#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct PacketPayload {
    uint8_t* data;
    size_t length;
} PacketPayload;

typedef struct PacketHeader {
    uint32_t timestamp;
    PacketPayload payload;
    struct PacketHeader* next;
} PacketHeader;

PacketHeader* process_packet_headers(uint32_t timestamps[], uint8_t** payloads, size_t payload_lengths[], size_t num_packets, size_t max_bytes) {
    if (num_packets == 0 || max_bytes == 0) {
        return NULL;
    }

    PacketHeader* head = NULL;
    PacketHeader* tail = NULL;

    for (size_t i = 0; i < num_packets; ++i) {
        if (payload_lengths[i] > max_bytes - sizeof(PacketPayload)) {
            printf("Error: Payload too large for available memory.\n");
            return head; // Return current list on error
        }

        PacketHeader* new_packet = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (!new_packet) {
            printf("Memory allocation failed.\n");
            return head; // Return current list on error
        }
        new_packet->timestamp = timestamps[i];
        new_packet->payload.data = (uint8_t*)malloc(payload_lengths[i]);
        if (!new_packet->payload.data) {
            printf("Memory allocation for payload failed.\n");
            free(new_packet);
            return head; // Return current list on error
        }
        new_packet->payload.length = payload_lengths[i];
        memcpy(new_packet->payload.data, payloads[i], payload_lengths[i]);
        new_packet->next = NULL;

        if (!head) {
            head = tail = new_packet;
        } else {
            tail->next = new_packet;
            tail = new_packet;
        }
    }

    return head;
}

// Example usage
int main() {
    uint32_t timestamps[] = {1, 2, 3};
    uint8_t* payloads[] = {(uint8_t*)"A", (uint8_t*)"BCD", (uint8_t*)"EFGH"};
    size_t payload_lengths[] = {1, 3, 4};
    size_t num_packets = sizeof(payloads) / sizeof(payloads[0]);
    size_t max_bytes = 20;

    PacketHeader* packet_list = process_packet_headers(timestamps, payloads, payload_lengths, num_packets, max_bytes);

    // Free allocated memory
    PacketHeader* current = packet_list;
    while (current) {
        free(current->payload.data);
        PacketHeader* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
