#define MAX_LINE_LENGTH 2048
#define FIELD_DELIMITER ','

void resolve_dns(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; 
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        strncpy(ip_address, "", sizeof(ip_address));
    } else {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
        freeaddrinfo(res); 
    }
}

char* calculate_average(char *line) {
    char *token = strtok(line, FIELD_DELIMITER);
    int count = 0;
    float sum = 0;

    while (token != NULL) {
        if (count >= 2) break;
        sum += atof(token);
        count++;
        token = strtok(NULL, FIELD_DELIMITER);
    }

    if (count < 2) return line; // Not enough fields to calculate average

    float average = sum / count;
    char *new_line = realloc(line, strlen(line) + 25); // Assuming max field length is 10
    sprintf(new_line + strlen(line), "%c%.2f", FIELD_DELIMITER, average);
    return new_line;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <hostname> <file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char ip_address[INET_ADDRSTRLEN];
    resolve_dns(argv[1], ip_address);

    FILE *file = fopen(argv[2], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        char *updated_line = calculate_average(line);
        printf("%s", updated_line);
        free(updated_line);
    }

    fclose(file);
    return EXIT_SUCCESS;
}
