#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NUMS 100
#define INT_MIN -2147483648
#define INT_MAX 2147483647

// Function to find and print the largest integer in the array
void print_largest(int* nums, int count) {
    if (count == 0) {
        printf("No valid integers found.\n");
        return;
    }
    int largest = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (nums[i] > largest) {
            largest = nums[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

// Function to read integers from a file and return an array of them
int* read_integers(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        *count = 0;
        return NULL;
    }

    int* nums = (int*)malloc(MAX_NUMS * sizeof(int));
    if (!nums) {
        perror("Memory allocation failed");
        fclose(file);
        *count = 0;
        return NULL;
    }

    char line[256];
    int num_count = 0;
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, " \t\n");
        while (token) {
            long val = strtol(token, NULL, 10);
            if (val >= INT_MIN && val <= INT_MAX) {
                nums[num_count++] = (int)val;
            }
            if (num_count == MAX_NUMS) break; // Stop reading if array is full
            token = strtok(NULL, " \t\n");
        }
    }

    fclose(file);
    *count = num_count;
    return nums;
}

// Main function to handle file input and process integers
int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int count;
    int* nums = read_integers(argv[1], &count);
    if (!nums || count == 0) {
        free(nums); // Free allocated memory in case of failure
        return EXIT_FAILURE;
    }

    print_largest(nums, count);
    free(nums); // Clean up dynamically allocated memory

    return EXIT_SUCCESS;
}
