#define MAX_IP_LENGTH 16

typedef struct {
    uint32_t ip;
} IPAddress;

int validate_ip(const char *ip_str, uint32_t *ip_out) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip_str, &addr) == 1) {
        *ip_out = addr.s_addr;
        return 0; // Valid IP
    } else {
        return -1; // Invalid IP
    }
}

IPAddress* process_ip_list(const char **ip_list, size_t count, size_t *valid_count, size_t *invalid_count) {
    IPAddress *result = (IPAddress *)malloc(count * sizeof(IPAddress));
    if (!result) {
        perror("Failed to allocate memory for IP list");
        return NULL;
    }

    *valid_count = 0;
    *invalid_count = 0;

    for (size_t i = 0; i < count; ++i) {
        uint32_t ip;
        int status = validate_ip(ip_list[i], &ip);
        if (status == 0) {
            result[*valid_count].ip = ip;
            (*valid_count)++;
        } else {
            fprintf(stderr, "Invalid IP address: %s\n", ip_list[i]);
            (*invalid_count)++;
        }
    }

    return result;
}

void free_ip_list(IPAddress *list, size_t count) {
    if (list) {
        free(list);
    }
}

int main() {
    const char *ip_list[] = {
        "192.168.1.1",
        "256.0.0.1",  // Invalid IP
        "10.0.0.1",
        "172.16.0.1"
    };
    size_t count = sizeof(ip_list) / sizeof(ip_list[0]);
    size_t valid_count, invalid_count;

    IPAddress *processed_ips = process_ip_list(ip_list, count, &valid_count, &invalid_count);
    if (processed_ips) {
        printf("Valid IPs: %zu\n", valid_count);
        for (size_t i = 0; i < valid_count; ++i) {
            char buffer[MAX_IP_LENGTH];
            inet_ntop(AF_INET, &(processed_ips[i].ip), buffer, MAX_IP_LENGTH);
            printf("%s\n", buffer);
        }
        free_ip_list(processed_ips, count);
    }

    return 0;
}
