public class DynamicClassLoader extends ClassLoader {
    private Map<String, byte[]> classCache = new HashMap<>();
    private PublicKey publicKey;

    public DynamicClassLoader(PublicKey publicKey) {
        this.publicKey = publicKey;
    }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        if (!classCache.containsKey(name)) {
            try {
                byte[] bytecode = loadBytecodeFromDisk(name);
                verifyIntegrity(bytecode, publicKey);
                Class<?> clazz = defineClass(name, bytecode, 0, bytecode.length);
                classCache.put(name, bytecode);
                return clazz;
            } catch (Exception e) {
                throw new ClassNotFoundException("Failed to load class: " + name, e);
            }
        } else {
            return findLoadedClass(name);
        }
    }

    private byte[] loadBytecodeFromDisk(String className) throws Exception {
        File file = new File(className.replace('.', '/') + ".class");
        try (FileInputStream fis = new FileInputStream(file)) {
            return fis.readAllBytes();
        }
    }

    private void verifyIntegrity(byte[] bytecode, PublicKey publicKey) throws Exception {
        Signature signature = Signature.getInstance("SHA256withRSA");
        signature.initVerify(publicKey);
        signature.update(bytecode);
        // Assume a method loadSignature() is implemented to fetch the signature from disk
        byte[] receivedSignature = loadSignature();
        if (!signature.verify(receivedSignature)) {
            throw new SecurityException("Integrity check failed for class: " + className);
        }
    }

