def validate_payload(payload):
    """Validate the user input payload"""
    if 'type' not in payload or 'data' not in payload:
        raise ValueError("Invalid payload structure")

    payload_type = payload['type']
    data = payload['data']

    if payload_type == 'create':
        required_fields = ['username', 'email', 'role']
    elif payload_type == 'update':
        required_fields = ['user_id', 'new_role']
    else:
        raise ValueError("Unsupported operation type")

    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    return payload_type, data

def construct_api_url(service_id, endpoint):
    """Construct the API URL using service configuration"""
    base_url = service_configurations[service_id]['base_url']
    return f"{base_url}/{endpoint}"

def construct_request_body(payload_type, data):
    """Construct the HTTP request body based on payload type and data"""
    if payload_type == 'create':
        return {
            "username": data['username'],
            "email": data['email'],
            "role": data['role']
        }
    elif payload_type == 'update':
        return {
            "user_id": data['user_id'],
            "new_role": data['new_role']
        }

