    """Make an HTTP request to the API"""
    try:
        if method.lower() == 'get':
            response = requests.get(api_url, headers=headers)
        elif method.lower() == 'post':
            response = requests.post(api_url, headers=headers, json=body)
        else:
            raise ValueError("Unsupported HTTP method")

        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        logger.error(f"API request failed: {e}")
        return None

def execute_user_management_command(payload):
    """Execute the user management command based on the payload"""
    try:
        payload_type, data = validate_payload(payload)

        service_id = data.get('service_id', 'default_service')
        endpoint = data['endpoint']
        headers = {
            "Authorization": f"Bearer {service_configurations[service_id]['token']}",
            "Content-Type": "application/json"
        }
        api_url = construct_api_url(service_id, endpoint)
        body = construct_request_body(payload_type, data)

        response = make_api_request(api_url, 'POST', headers, body)

        if response:
            logger.info(f"Operation successful: {response}")
        else:
            raise Exception("API request failed")

    except (ValueError, KeyError) as e:
        logger.error(f"Payload validation or processing error: {e}")

