import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;
import org.json.JSONObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class PokemonWeaknessesFetcher {
    private static final Logger logger = LoggerFactory.getLogger(PokemonWeaknessesFetcher.class);
    private static final String API_URL = "https://api.pokemontcg.io/v2/pokemon/{pokemonName}";
    private static final int CACHE_EXPIRATION_TIME = 3600; // 1 hour in seconds
    private static ConcurrentHashMap<String, WeaknessesCacheEntry> cache = new ConcurrentHashMap<>();

    public static String getPokemonWeaknesses(String pokemonName) {
        try {
            WeaknessesCacheEntry entry = cache.get(pokemonName);
            if (entry == null || isCacheExpired(entry)) {
                entry = fetchWeaknessesFromAPI(pokemonName);
                cache.put(pokemonName, entry);
            }
            return entry.getWeaknesses();
        } catch (IOException e) {
            logger.error("Error fetching Pokemon weaknesses", e);
            return getDefaultWeaknesses();
        }
    }

    private static boolean isCacheExpired(WeaknessesCacheEntry entry) {
        long currentTime = System.currentTimeMillis() / 1000;
        return currentTime - entry.getTimestamp() > CACHE_EXPIRATION_TIME;
    }

    private static WeaknessesCacheEntry fetchWeaknessesFromAPI(String pokemonName) throws IOException {
        String url = API_URL.replace("{pokemonName}", pokemonName);
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        try {
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                String jsonResponse = readResponse(connection.getInputStream());
                JSONObject jsonObject = new JSONObject(jsonResponse);
                return new WeaknessesCacheEntry(jsonObject.toString(), System.currentTimeMillis() / 1000);
            } else {
                logger.warn("API response code: {}", responseCode);
                throw new IOException("Failed to fetch data from API");
            }
        } finally {
            connection.disconnect();
        }
    }

    private static String readResponse(java.io.InputStream inputStream) throws IOException {
        java.util.Scanner scanner = new java.util.Scanner(inputStream).useDelimiter("\\A");
        return scanner.hasNext() ? scanner.next() : "";
    }

    private static String getDefaultWeaknesses() {
        // Return default or alternative data here
        return "[{\"type\":\"Normal\",\"damageMultiplier\":1}]";
    }

    private static class WeaknessesCacheEntry {
        private String weaknesses;
        private long timestamp;

        public WeaknessesCacheEntry(String weaknesses, long timestamp) {
            this.weaknesses = weaknesses;
            this.timestamp = timestamp;
        }

        public String getWeaknesses() {
            return weaknesses;
        }

        public long getTimestamp() {
            return timestamp;
        }
    }
}
