#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to generate secure random data using OpenSSL's DRBG
void generate_secure_random(void *buf, size_t num) {
    if (!RAND_bytes(buf, num)) {
        fprintf(stderr, "Error generating secure random bytes\n");
        exit(EXIT_FAILURE);
    }
}

// Function to encrypt data based on the specified encryption mode and key
int encrypt_data(const char *data, size_t length, const EVP_CIPHER *cipher,
                 unsigned char *key, unsigned char *iv, unsigned char *encrypted) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return -1;
    }

    int len, ciphertext_len;
    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Encryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, encrypted, &len, (unsigned char *)data, length)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, encrypted + len, &len)) {
        fprintf(stderr, "Final encryption failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to compute HMAC-SHA256 for the encrypted data
void compute_hmac(unsigned char *data, size_t length, unsigned char *key,
                   unsigned char *hmac) {
    HMAC(EVP_sha256(), key, 32, data, length, hmac, NULL);
}

// Example usage of the encryption and HMAC functions
int main(int argc, char **argv) {
    // Parse command line arguments for encryption mode and seed
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    unsigned char key[32], iv[16];
    generate_secure_random(key, sizeof(key));
    generate_secure_random(iv, sizeof(iv));

    // Encrypt data
    const char *plaintext = "Hello, World!";
    size_t plaintext_len = strlen(plaintext);
    unsigned char encrypted[plaintext_len + EVP_CIPHER_block_size(cipher)];
    int ciphertext_len = encrypt_data(plaintext, plaintext_len, cipher,
                                       key, iv, encrypted);

    if (ciphertext_len == -1) {
        fprintf(stderr, "Encryption failed\n");
        return EXIT_FAILURE;
    }

    // Compute HMAC
    unsigned char hmac[32];
    compute_hmac(encrypted, ciphertext_len, key, hmac);

    // Output results
    printf("Encrypted data: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", encrypted[i]);
    }
    printf("\n");

    printf("HMAC: ");
    for (int i = 0; i < sizeof(hmac); i++) {
        printf("%02x", hmac[i]);
    }
    printf("\n");

    return EXIT_SUCCESS;
}
```

