#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <semaphore.h>

#define SEM_DIR "/tmp/sems"
#define LOG_FILE "/var/log/sem_log.log"

typedef struct {
    sem_t *sem;
    char *temp_file_path;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    // Create semaphore directory
    if (access(SEM_DIR, F_OK) == -1) {
        mkdir(SEM_DIR, 0755);
    }

    // Generate unique temporary file for state tracking
    char temp_file[256];
    snprintf(temp_file, sizeof(temp_file), "%s/sem.%d", SEM_DIR, getpid());

    // Create and lock semaphore
    sem_t *sem = sem_open(temp_file, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    // Open log file for writing
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        sem_close(sem);
        sem_unlink(temp_file);
        return NULL;
    }

    Semaphore *semaphore = (Semaphore *)malloc(sizeof(Semaphore));
    semaphore->sem = sem;
    semaphore->temp_file_path = strdup(temp_file);

    // Log creation of semaphore
    fprintf(log, "Created semaphore %s with initial value %d\n", temp_file, initial_value);
    fclose(log);

    return semaphore;
}

void destroy_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return;
    }

    // Open log file for writing
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    // Log deletion of semaphore
    fprintf(log, "Deleting semaphore %s\n", sem->temp_file_path);

    // Close and unlink semaphore
    sem_close(sem->sem);
    sem_unlink(sem->temp_file_path);

    // Remove temporary file
    remove(sem->temp_file_path);
    free(sem->temp_file_path);
    free(sem);

    fclose(log);
}

void increment_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return;
    }

    // Increment semaphore
    sem_post(sem->sem);

    // Open log file for writing
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    // Log increment of semaphore
    fprintf(log, "Incremented semaphore %s\n", sem->temp_file_path);

    fclose(log);
}

void decrement_semaphore(Semaphore *sem) {
    if (sem == NULL) {
        return;
    }

    // Decrement semaphore
    sem_wait(sem->sem);

    // Open log file for writing
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    // Log decrement of semaphore
    fprintf(log, "Decremented semaphore %s\n", sem->temp_file_path);

    fclose(log);
}
