#include <iostream>
#include <string>
#include <mutex>

struct Node {
    std::string data;
    int value;
    Node* next;

    Node(const std::string& str, int val) : data(str), value(val), next(nullptr) {}
};

class LinkedList {
private:
    Node* head;
    std::mutex mtx;

public:
    LinkedList() : head(nullptr) {}

    ~LinkedList() {
        clear();
    }

    void insertAfterFirstOccurrence(const std::string& target, const std::string& newData, int newValue) {
        std::lock_guard<std::mutex> lock(mtx);
        Node* current = head;
        while (current != nullptr && current->data != target) {
            current = current->next;
        }
        if (current == nullptr) {
            append(newData, newValue);
        } else {
            Node* newNode = new Node(newData, newValue);
            newNode->next = current->next;
            current->next = newNode;
        }
    }

    void append(const std::string& newData, int newValue) {
        std::lock_guard<std::mutex> lock(mtx);
        Node* newNode = new Node(newData, newValue);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mtx);
        Node* current = head;
        while (current != nullptr) {
            Node* next = current->next;
            delete current;
            current = next;
        }
        head = nullptr;
    }

    class Iterator {
    private:
        Node* current;

    public:
        Iterator(Node* node) : current(node) {}

        bool hasNext() const {
            return current != nullptr;
        }

        void next() {
            if (current != nullptr) {
                current = current->next;
            }
        }

        std::string getData() const {
            return current == nullptr ? "" : current->data;
        }

        int getValue() const {
            return current == nullptr ? 0 : current->value;
        }
    };

    Iterator begin() {
        return Iterator(head);
    }

    Iterator end() {
        return Iterator(nullptr);
    }
};
