import java.security.SecureRandom;

public class SessionIdGenerator {
    private final SecureRandom secureRandom;
    private byte[] seed;

    public SessionIdGenerator() {
        this.seed = generateSeed();
        this.secureRandom = new SecureRandom(seed);
    }

    private byte[] generateSeed() {
        SecureRandom entropySource = new SecureRandom();
        byte[] seed = new byte[20];
        entropySource.nextBytes(seed);
        return seed;
    }

    public String generateSessionId(int length) {
        byte[] sessionIdBytes = new byte[length];
        secureRandom.nextBytes(sessionIdBytes);
        return bytesToHex(sessionIdBytes);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        SessionIdGenerator generator = new SessionIdGenerator();
        String sessionId = generator.generateSessionId(16);
        System.out.println("Generated Session ID: " + sessionId);
    }
}
```

