using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class UserService
{
    public List<UserDetails> GetUserDetails(List<int> userIds, SqlConnection connection, SqlCommand command, bool paginate = false, int pageSize = 1000, string orderByColumn = null, string orderDirection = "ASC")
    {
        List<UserDetails> userDetailsList = new List<UserDetails>();

        try
        {
            if (userIds.Count > 0)
            {
                int pageNumber = 1;
                while ((paginate && userIds.Count > (pageNumber - 1) * pageSize) || !paginate)
                {
                    int endIndex = Math.Min(pageNumber * pageSize, userIds.Count);
                    List<int> pageUserIds = userIds.GetRange((pageNumber - 1) * pageSize, endIndex - (pageNumber - 1) * pageSize);

                    command.CommandText = GenerateSqlQuery(pageUserIds, orderByColumn, orderDirection);
                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            userDetailsList.Add(new UserDetails
                            {
                                UserId = Convert.ToInt32(reader["UserId"]),
                                UserName = reader["UserName"].ToString(),
                                Email = reader["Email"].ToString()
                            });
                        }
                    }

                    if (!paginate || endIndex == userIds.Count)
                    {
                        break;
                    }

                    pageNumber++;
                }
            }
        }
        catch (SqlException ex)
        {
            // Handle SQL exceptions, e.g., timeouts, connection failures
            Console.WriteLine($"Database error: {ex.Message}");
        }
        catch (Exception ex)
        {
            // Handle other exceptions gracefully
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }

        return userDetailsList;
    }

    private string GenerateSqlQuery(List<int> userIds, string orderByColumn, string orderDirection)
    {
        string userIdsString = string.Join(",", userIds.Select(id => $"@UserId{id}"));
        string sqlQuery = $"SELECT * FROM Users WHERE UserId IN ({userIdsString})";

        if (!string.IsNullOrEmpty(orderByColumn))
        {
            sqlQuery += $" ORDER BY {orderByColumn} {orderDirection}";
        }

        return sqlQuery;
    }
}

public class UserDetails
{
    public int UserId { get; set; }
    public string UserName { get; set; }
    public string Email { get; set; }
}
