from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_httpauth import HTTPBasicAuth
import logging

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///resources.db'
app.config['SECRET_KEY'] = 'your_secret_key'
db = SQLAlchemy(app)
auth = HTTPBasicAuth()

# Define the resource model
class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    data = db.Column(db.String(500), nullable=False)

# In-memory cache for resources
resource_cache = {}

# External authentication service integration
def authenticate(username, password):
    # Simulate external authentication
    return username == 'admin' and password == 'password'

@auth.verify_password
def verify_password(username, password):
    if authenticate(username, password):
        return username

@app.route('/resources/<int:resource_id>', methods=['PUT'])
@auth.login_required
def update_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)
    updated_data = request.json.get('data', '')
    if updated_data:
        resource.data = updated_data
        db.session.commit()
        resource_cache[resource_id] = resource  # Update cache
        logging.info(f"Resource {resource_id} updated by {auth.current_user()}")
        return jsonify({'message': 'Resource updated successfully'}), 200
    else:
        return jsonify({'error': 'No data provided'}), 400

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
@auth.login_required
def delete_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)
    resource.data = ''  # Reset to default values
    db.session.commit()
    del resource_cache[resource_id]  # Remove from cache
    logging.info(f"Resource {resource_id} deleted by {auth.current_user()}")
    return jsonify({'message': 'Resource deleted successfully'}), 200

if __name__ == '__main__':
