<?php

class UserManager {
    private $config;
    private $db;

    public function __construct($config, $db) {
        $this->config = $config;
        $this->db = $db;
    }

    public function manageUserRequest() {
        if (empty($_REQUEST)) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = isset($_REQUEST['name']) ? trim($_REQUEST['name']) : '';
        $email = isset($_REQUEST['email']) ? trim($_REQUEST['email']) : '';
        $password = isset($_REQUEST['password']) ? $_REQUEST['password'] : '';
        $action = isset($_REQUEST['action']) ? trim($_REQUEST['action']) : '';
        $sub_action = isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'redirect' ? true : false;
        $redirect_url = isset($_REQUEST['redirect_url']) ? trim($_REQUEST['redirect_url']) : '';

        $validationResult = $this->Validate($name, $email, $password, $action);
        if ($validationResult !== true) {
            return json_encode(['message' => 'error', 'data' => ['validation_errors' => $validationResult]]);
        }

        $user_data = [
            'name' => $name,
            'email' => $email,
            'password' => password_hash($password, PASSWORD_DEFAULT)
        ];

        if ($action === 'create') {
            $this->Save($user_data);
        } elseif ($action === 'update') {
            $this->Save($user_data, $id);
        }

        if ($sub_action) {
            $trusted_domains = $this->config['trusted_domains'];
            if (!in_array(parse_url($redirect_url, PHP_URL_HOST), $trusted_domains)) {
                $redirect_url = $this->config['default_landing_page'];
            }
            return json_encode(['message' => 'success', 'data' => ['redirect_url' => $redirect_url]]);
        }

        if ($action === 'view') {
            $user_data = $this->Get($id);
            return json_encode(['message' => 'success', 'data' => $user_data]);
        }

        return json_encode(['message' => 'error', 'data' => []]);
    }

    private function Validate($name, $email, $password, $action) {
        if ($action === 'create') {
            if (empty($name) || empty($email) || empty($password)) {
                return ['name' => 'Name is required.', 'email' => 'Email is required.', 'password' => 'Password is required.'];
            }
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                return ['email' => 'Invalid email format.'];
            }
        } elseif ($action === 'update') {
            if (empty($name) || empty($email)) {
                return ['name' => 'Name is required.', 'email' => 'Email is required.'];
            }
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                return ['email' => 'Invalid email format.'];
            }
        }

        return true;
    }

    private function Save($user_data, $id = null) {
        if ($id === null) {
            $this->db->insert('users', $user_data);
        } else {
            $this->db->update('users', $user_data, ['id' => $id]);
        }
    }

    private function Get($id) {
        return $this->db->select('users', '*', ['id' => $id]);
    }
}
?>
