            // bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static <T extends Serializable> T loadStateObject(File stateFile, List<Class<? extends Serializable>> supportedClasses) {
        try (FileInputStream fis = new FileInputStream(stateFile);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

            T obj = (T) ois.readObject();
            if (supportedClasses.contains(obj.getClass())) {
                return obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return null;
    }
}
