["```typescript
import * as fs from 'fs';
import * as path from 'path';
import { Mutex } from 'async-mutex';

interface CacheEntry {
  path: string;
  files: string[];
  timestamp: number;
}

class ImageFileProcessor {
  private cache: Map<string, CacheEntry> = new Map();
  private mutex: Mutex = new Mutex();

  async getFilenames(userDirectory: string): Promise<string[]> {
    const lockRelease = await this.mutex.acquire();
    try {
      if (this.isCacheValid(userDirectory)) {
        return this.cache.get(userDirectory)!.files;
      }

      const absolutePath = path.resolve(__dirname, userDirectory);
      if (!fs.existsSync(absolutePath) || !fs.lstatSync(absolutePath).isDirectory()) {
        throw new Error('Invalid directory path');
      }

      const files = await fs.promises.readdir(absolutePath);
      this.cache.set(userDirectory, { path: absolutePath, files, timestamp: Date.now() });
      return files;
    } finally {
      lockRelease();
    }
  }

  private isCacheValid(directory: string): boolean {
    const cacheEntry = this.cache.get(directory);
    if (!cacheEntry) {
      return false;
    }

    const maxAge = 3600 * 1000; // Cache for 1 hour
    return Date.now() - cacheEntry.timestamp < maxAge;
  }
}

const processor = new ImageFileProcessor();

// Example usage:
async function processUserImages(userDirectory: string) {
  try {
    const filenames = await processor.getFilenames(userDirectory);
    console.log('Filenames:', filenames);
  } catch (error) {
    console.error('Error processing images:', error.message);
  }
}

processUserImages('users/username/images');
```"]

