function generateFooterScripts(configUrl) {
    return new Promise((resolve, reject) => {
        fetch(configUrl)
            .then(response => response.json())
            .then(data => {
                const scripts = data.scripts.map(script => {
                    return `<script key="${script.key}" src="data:text/javascript;base64,${btoa(unescape encodeURIComponent(script.code))}" async defer></script>`;
                });
                resolve(scripts.join(''));
            })
            .catch(error => reject(error));
    });
}

async function renderFooter(configUrl) {
    try {
        const scripts = await generateFooterScripts(configUrl);
        document.getElementById('footer').innerHTML = scripts;
    } catch (error) {
        console.error('Error fetching or rendering footer scripts:', error);
    }
}
```

