const EventEmitter = require('events');
const { Queue } = require('p-queue');

class DataProcessor extends EventEmitter {
  constructor(options) {
    super();
    this.queue = new Queue({ concurrency: options.concurrency });
    this.intervalId = null;
    this.isPaused = false;
  }

  start() {
    this.intervalId = setInterval(() => {
      if (!this.isPaused && !this.queue.size()) {
        this.processData();
      }
    }, options.delay);
  }

  stop() {
    clearInterval(this.intervalId);
    this.queue.clear();
    this.emit('stopped');
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }

  async processData() {
    try {
      const dataPoint = await fetchDataFromSources(); // Assume this function exists
      this.queue.add(() => this.storeData(dataPoint));
    } catch (error) {
      console.error('Error processing data:', error);
    }
  }

  async storeData(dataPoint) {
    // Store the data point in a managed data store
    try {
      await storeInDatabase(dataPoint); // Assume this function exists
    } catch (error) {
      console.error('Error storing data:', error);
    }
  }
}

module.exports = DataProcessor;
