// Import necessary libraries and dependencies
const { exec } = require('child_process');
const fs = require('fs');

// Function to dynamically generate and execute C code
function modifyFileExtension(filePath, digits, fileType) {
    try {
        // Check if the file exists
        if (!fs.existsSync(filePath)) {
            throw new Error(`File not found: ${filePath}`);
        }

        // Generate C code using sprintf and strcat
        const cCode = `
#include <stdio.h>
int main() {
    char filename[256];
    sprintf(filename, "%s%d.%s", "${filePath.split('.').slice(0, -1).join('.')}", ${digits}, "${fileType}");
    printf("New filename: %s\\n", filename);
    return 0;
}
`;

        // Write the C code to a temporary file
        const tempCFile = 'temp.c';
        fs.writeFileSync(tempCFile, cCode);

        // Compile and execute the C code using exec
        const compileCommand = `gcc ${tempCFile} -o temp`;
        exec(compileCommand, (error, stdout, stderr) => {
            if (error) {
                throw new Error(`Compilation failed: ${stderr}`);
            }

            exec('./temp', (error, stdout, stderr) => {
                if (error) {
                    throw new Error(`Execution failed: ${stderr}`);
                }

                console.log(stdout);
                fs.unlinkSync(tempCFile); // Clean up temporary files
                fs.unlinkSync('temp');   // Clean up temporary executable
            });
        });
    } catch (error) {
        console.error(error.message);
    }
}

// Example usage
modifyFileExtension('example.js', 123, 'txt');
