['```java
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class SessionIDGenerator {
    private static final SecureRandom secureRandom = new SecureRandom();
    private static ConcurrentHashMap<String, Boolean> usedIDs = new ConcurrentHashMap<>();
    private static long startTime = System.currentTimeMillis();
    private static int totalGenerations = 0;
    private static long totalTimeTaken = 0;

    public static String generateSessionID() {
        long start = System.nanoTime();
        while (true) {
            byte[] bytes = new byte[16];
            secureRandom.nextBytes(bytes);
            String id = bytesToHex(bytes);
            if (usedIDs.putIfAbsent(id, true) == null) {
                updateStatistics(start);
                return id;
            }
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void updateStatistics(long start) {
        long end = System.nanoTime();
        long duration = end - start;
        totalGenerations++;
        totalTimeTaken += duration;
        if (totalGenerations % 1000 == 0) {
            double averageTime = ((double) totalTimeTaken) / totalGenerations * 1e-9;
            double elapsedTime = (System.currentTimeMillis() - startTime) / 1e3;
            System.out.printf("Average ID generation time: %.6f ms, Elapsed time: %.2f s%n", averageTime, elapsedTime);
        }
    }

    public static void main(String[] args) {
        try {
            for (int i = 0; i < 1000; i++) {
                String id = generateSessionID();
                System.out.println("Generated ID " + (i + 1) + ": " + id);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
