import java.net.URL;
import java.net.HttpURLConnection;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class URLProcessor {

    public static String processURL(String urlString) {
        try {
            // Validate and sanitize the URL
            URL url = new URL(urlString);
            if (!isSafeURL(url)) {
                throw new SecurityException("Invalid or unsafe URL");
            }

            // Open connection and handle potential state changes
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new IOException("Failed to retrieve content, HTTP response code: " + responseCode);
            }

            // Read and return the content
            StringBuilder contentBuilder = new StringBuilder();
            try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    contentBuilder.append(inputLine);
                }
            }
            return contentBuilder.toString();

        } catch (IOException | SecurityException e) {
            // Handle exceptions gracefully
            System.err.println("Error processing URL: " + e.getMessage());
            return null;
        }
    }

    private static boolean isSafeURL(URL url) {
        try {
            String host = url.getHost();
            // Add your own validation logic to check if the host is safe
            // For example, exclude internal network resources or specific domains
            return !host.startsWith("localhost") && !host.contains("internal-network");
        } catch (Exception e) {
            return false;
        }
    }

    public static void main(String[] args) {
        String url = "https://example.com";
        String content = processURL(url);
        if (content != null) {
            System.out.println("Content retrieved: " + content);
        } else {
            System.out.println("Failed to retrieve content.");
        }
    }
}
