package com.example.themecaching;

import android.content.Context;
import android.graphics.Bitmap;
import android.os.Environment;
import android.util.Log;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;

public class ThemeCacheManager {
    private static final String TAG = "ThemeCacheManager";
    private Context context;
    private File cacheDir;

    public ThemeCacheManager(Context context) {
        this.context = context;
        initializeCacheDir();
    }

    private void initializeCacheDir() {
        if (!isDefaultThemeDirectoryExists()) {
            createDefaultThemeDirectory();
        }
        cacheDir = getThemeCacheDirectory();
    }

    private boolean isDefaultThemeDirectoryExists() {
        File dir = new File(context.getExternalFilesDir(null), "themes");
        return dir.exists();
    }

    private void createDefaultThemeDirectory() {
        context.getExternalFilesDir(null).mkdirs();
        new File(context.getExternalFilesDir(null), "themes").mkdirs();
    }

    public Bitmap getThemeBitmap(String themeName) {
        try {
            FileInputStream fis = new FileInputStream(new File(cacheDir, themeName + ".png"));
            Bitmap bitmap = BitmapFactory.decodeStream(fis);
            fis.close();
            return bitmap;
        } catch (IOException e) {
            Log.e(TAG, "Error loading theme bitmap", e);
            return null;
        }
    }

    public void saveThemeBitmap(String themeName, Bitmap bitmap) {
        try {
            FileOutputStream fos = new FileOutputStream(new File(cacheDir, themeName + ".png"));
            bitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);
            fos.close();
            Log.d(TAG, "Theme bitmap saved: " + themeName);
        } catch (IOException e) {
            Log.e(TAG, "Error saving theme bitmap", e);
        }
    }

    private File getThemeCacheDirectory() {
        return new File(context.getExternalFilesDir(null), "themes");
    }

    public void clearUnusedBitmaps() {
        File[] files = cacheDir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isFile()) {
                    Bitmap bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
                    if (bitmap == null) {
                        file.delete();
                        Log.d(TAG, "Unused bitmap removed: " + file.getName());
                    }
                }
            }
        }
    }

    public void setDefaultFilePermissions() {
        cacheDir.setExecutable(false, false);
        cacheDir.setReadable(true, true);
        cacheDir.setWritable(true, true);
        File[] files = cacheDir.listFiles();
        if (files != null) {
            for (File file : files) {
                file.setExecutable(false, false);
                file.setReadable(true, true);
                file.setWritable(true, true);
            }
        }
    }

    public void logCacheEvent(String event) {
        Log.d(TAG, "Cache Event: " + event);
    }
}
