import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class BackgroundServiceManager {

    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final long STARTUP_INTERVAL = Long.parseLong(System.getenv("STARTUP_INTERVAL"));
    private static final long SHUTDOWN_INTERVAL = Long.parseLong(System.getenv("SHUTDOWN_INTERVAL"));
    private static final long HEALTH_CHECK_INTERVAL = Long.parseLong(System.getenv("HEALTH_CHECK_INTERVAL"));
    private static final int TIMEOUT = Integer.parseInt(System.getenv("TIMEOUT"));
    private static boolean isServiceRunning = false;

    public static void main(String[] args) {
        startMonitoring();
    }

    private static void startMonitoring() {
        Runnable serviceTask = () -> {
            if (!isServiceRunning) {
                try {
                    startService();
                } catch (Exception e) {
                    logError("Failed to start service: " + e.getMessage());
                }
            } else {
                try {
                    stopService();
                } catch (Exception e) {
                    logError("Failed to stop service: " + e.getMessage());
                }
            }
        };

        scheduler.scheduleAtFixedRate(serviceTask, 0, STARTUP_INTERVAL, TimeUnit.MILLISECONDS);
    }

    private static void startService() throws Exception {
        // Simulate service startup
        isServiceRunning = true;
        logInfo("Service started");
    }

    private static void stopService() throws Exception {
        // Simulate service shutdown
        isServiceRunning = false;
        logInfo("Service stopped");
    }

    private static void monitorHealth() {
        Runnable healthCheckTask = () -> {
            if (isServiceRunning) {
                long startTime = System.currentTimeMillis();
                try {
                    checkServiceHealth();
                    logInfo("Service health check passed in " + (System.currentTimeMillis() - startTime) + "ms");
                } catch (Exception e) {
                    logError("Service health check failed: " + e.getMessage());
                }
            }
        };

        scheduler.scheduleAtFixedRate(healthCheckTask, 0, HEALTH_CHECK_INTERVAL, TimeUnit.MILLISECONDS);
    }

    private static void checkServiceHealth() throws Exception {
        // Simulate service health check
        if (Math.random() < 0.1) {
            throw new Exception("Simulated health issue");
        }
    }

    private static void logInfo(String message) {
        System.out.println("[INFO] " + message);
    }

    private static void logError(String message) {
        System.err.println("[ERROR] " + message);
    }
}
```

### Explanation of the Code:
1. **Environment Variables**: The program reads configuration parameters such as `STARTUP_INTERVAL`, `SHUTDOWN_INTERVAL`, `HEALTH_CHECK_INTERVAL`, and `TIMEOUT` from environment variables.
2. **Scheduled Executor Service**: It uses a scheduled executor to run tasks at fixed intervals.
3. **Service Management**: The `startMonitoring` method schedules tasks to start or stop the service based on its current state.
4. **Health Monitoring**: A separate task is scheduled to monitor the health of the service periodically.
5. **Logging**: Basic logging is implemented using `System.out.println` and `System.err.println`.

### How to Run:
1. Set environment variables:
   ```sh
   export STARTUP_INTERVAL=60000
   export SHUTDOWN_INTERVAL=30000
   export HEALTH_CHECK_INTERVAL=10000
   export TIMEOUT=5000
   ```
2. Compile and run the Java program.

This code provides a basic structure for managing a background service with dynamic intervals, error handling, and health monitoring. You can extend it further to include more sophisticated logic as needed.']

