use hyper::{Client, Uri};
use hyper_tls::HttpsConnector;
use tokio::sync::{Mutex, RwLock};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, SystemTime};

type CacheKey = String;

struct Config {
    disable_certificate_validation: bool,
    cache_expiration_policy: Duration,
}

struct HttpClient {
    client: Client<HttpsConnector>,
    config: Arc<Config>,
    cache: Arc<Mutex<HashMap<CacheKey, (SystemTime, Vec<u8>)>>>,
}

impl HttpClient {
    fn new(config: Config) -> Self {
        let https = HttpsConnector::new();
        let client = Client::builder().build::<_, hyper::Body>(https);
        let cache = Arc::new(Mutex::new(HashMap::new()));
        HttpClient { client, config: Arc::new(config), cache }
    }

    async fn send_request(&self, url: &str) -> Result<String, Box<dyn std::error::Error>> {
        if self.config.disable_certificate_validation {
            // Disable certificate validation for non-production environments
        }

        let uri = Uri::from_str(url)?;
        let response = self.client.get(uri).await?;
        let body = hyper::body::to_bytes(response.into_body()).await?;

        if self.config.cache_expiration_policy > Duration::ZERO {
            let now = SystemTime::now();
            self.cache.lock().await.insert(url.to_string(), (now, body.clone()));
        }

        String::from_utf8(body)?
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use hyper::body::to_bytes;
    use hyper::{Body, Request};
    use std::sync::atomic::{AtomicUsize, Ordering};
    use tokio::time;

    struct MockClient {
        request_count: Arc<AtomicUsize>,
    }

    impl MockClient {
        fn new() -> Self {
            MockClient {
                request_count: Arc::new(AtomicUsize::new(0)),
            }
        }
    }

    impl hyper::client::connect::Connect for MockClient {
        type Connecting = futures_util::future::Ready<Result<hyper::client::HttpConnector, hyper::Error>>;
        type Connected = hyper::client::HttpConnector;
        type Error = hyper::Error;

        fn connect(&self, _dest: hyper::uri::Uri) -> Self::Connecting {
            self.request_count.fetch_add(1, Ordering::SeqCst);
            futures_util::future::ready(Ok(hyper::client::HttpConnector::new()))
        }
    }

    #[tokio::test]
    async fn test_send_request() {
        let mock_client = MockClient::new();
        let config = Config {
            disable_certificate_validation: true,
            cache_expiration_policy: Duration::from_secs(60),
        };
        let client = HttpClient::new(config);

        let uri = Uri::from_str("https://example.com").unwrap();
        let request = Request::builder()
            .uri(uri)
            .body(Body::empty())
            .unwrap();

        // First request should hit the network
        assert_eq!(mock_client.request_count.load(Ordering::SeqCst), 0);
        client.send_request("https://example.com").await.unwrap();
        assert_eq!(mock_client.request_count.load(Ordering::SeqCst), 1);

        // Second request with the same URL should use cache
        mock_client.request_count.store(0, Ordering::SeqCst);
        client.send_request("https://example.com").await.unwrap();
        assert_eq!(mock_client.request_count.load(Ordering::SeqCst), 0);
    }
}
