<?php

function isTrustedNetwork($userIP) {
    // Define a list of trusted IP ranges or networks
    $trustedRanges = [
        '192.168.0.0/16',
        '172.16.0.0/12',
        '10.0.0.0/8',
        // Add more ranges as needed
    ];

    foreach ($trustedRanges as $range) {
        if (ipInRange($userIP, $range)) {
            return true;
        }
    }

    return false;
}

function ipInRange($ip, $range) {
    list($address, $netmask) = explode('/', $range, 2);
    $ipDecimal = ip2long($ip);
    $addressDecimal = ip2long($address);
    $wildcardDecimal = pow(2, (32 - $netmask)) - 1;
    $networkDecimal = $addressDecimal & ~$wildcardDecimal;

    return ($ipDecimal & ~$wildcardDecimal) == $networkDecimal;
}

function updateProfile($userID, $email, $phone, $address) {
    if (!isTrustedNetwork($_SERVER['REMOTE_ADDR'])) {
        logAttempt(false, 'IP_NOT_TRUSTED', $_SERVER['REMOTE_ADDR']);
        return false;
    }

    $db = connectToDatabase();
    $stmt = $db->prepare("UPDATE users SET email=?, phone=?, address=? WHERE id=?");

    if ($stmt === false) {
        logAttempt(false, 'DB_PREPARE_ERROR');
        return false;
    }

    try {
        $stmt->execute([$email, $phone, $address, $userID]);

        // Log successful update
        logAttempt(true, $_SERVER['REMOTE_ADDR'], $_SERVER['HTTP_USER_AGENT']);

        return true;
    } catch (PDOException $e) {
        logAttempt(false, 'DB_EXECUTE_ERROR', $e->getMessage());
        return false;
    }
}

function connectToDatabase() {
    // Replace with your database connection code
    $dsn = 'mysql:host=localhost;dbname=your_database';
    $username = 'your_username';
    $password = 'your_password';

    try {
        return new PDO($dsn, $username, $password);
    } catch (PDOException $e) {
        logAttempt(false, 'DB_CONNECTION_ERROR', $e->getMessage());
        exit('Database connection failed: ' . $e->getMessage());
    }
}

function logAttempt($success, $ip = null, $userAgent = null) {
    // Replace with your logging code
    file_put_contents('log.txt', date('Y-m-d H:i:s') . " - " . ($success ? 'SUCCESS' : 'FAIL') . " - IP: $ip - User-Agent: $userAgent\n", FILE_APPEND);
}

?>
