<?php

// Define a class to encapsulate all functionalities
class SecureOperations {
    private $logFile = 'operations.log';

    // Function to generate a random string with no repeating characters
    public function generateRandomString($length, $characterSet) {
        $result = '';
        $chars = str_split($characterSet);
        shuffle($chars);
        for ($i = 0; $i < $length && !empty($chars); $i++) {
            $result .= array_shift($chars);
        }
        if (strlen($result) !== $length) {
            throw new Exception('Unable to generate string with unique characters');
        }
        return $result;
    }

    // Function to hash a password securely
    public function hashPassword($password) {
        $salt = openssl_random_pseudo_bytes(16);
        $hashed = hash_pbkdf2("sha256", $password, $salt, 10000, 32, true);
        return [
            'hash' => base64_encode($hashed),
            'salt' => bin2hex($salt)
        ];
    }

    // Function to read a file synchronously
    public function readFileSynchronously($filePath) {
        $allowedDirectory = '/path/to/allowed/directory/';

        if (strpos($filePath, $allowedDirectory) !== 0 || !is_file($filePath)) {
            throw new Exception('Invalid file path');
        }

        try {
            return file_get_contents($filePath);
        } catch (Exception $e) {
            $this->logError("Failed to read file: " . $filePath . "\n" . $e->getMessage());
            return false;
        }
    }

    // Function to validate and sanitize the file path
    private function validateFilePath($filePath, $allowedDirectory) {
        if (strpos($filePath, $allowedDirectory) !== 0 || !is_file($filePath)) {
            throw new Exception('Invalid file path');
        }
    }

    // Function to log errors
    private function logError($message) {
        file_put_contents($this->logFile, date('Y-m-d H:i:s') . ' - Error: ' . $message, FILE_APPEND);
    }
}

// Example usage:
$operations = new SecureOperations();
try {
    $randomString = $operations->generateRandomString(10, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
    print_r($randomString);

    $hashedPassword = $operations->hashPassword('myPassword123');
    print_r($hashedPassword);

    $fileContent = $operations->readFileSynchronously('/path/to/allowed/directory/example.txt');
    if ($fileContent !== false) {
        echo $fileContent;
    }
} catch (Exception $e) {
    echo 'Error: ' . $e->getMessage();
}
?>
