import axios from 'axios';
import { createReadStream, promises as fs } from 'fs';
import crypto from 'crypto';

const PRIVATE_KEY_REPO = 'https://api.privatekeyrepo.com/key';
const CERTIFICATE_REPO = 'https://api.certificaterepo.com/cert';
const CACHE_EXPIRY = 3600; // 1 hour in seconds

let privateKeyCache = null;
let certificateCache = null;

async function fetchResource(url, cacheKey) {
    if (cacheKey && cacheExpires(cacheKey)) {
        return getFromCache(cacheKey);
    }
    try {
        const response = await axios.get(url, { responseType: 'stream' });
        const tempFilePath = `/tmp/${crypto.randomBytes(8).toString('hex')}`;
        const writeStream = fs.createWriteStream(tempFilePath);
        response.data.pipe(writeStream);
        await new Promise((resolve, reject) => {
            writeStream.on('finish', resolve);
            writeStream.on('error', reject);
        });
