u_char* authenticate_user(const char* access_token, const char* hostname) {
    u_char ip[MAX_IP_LENGTH];
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    // Check DNS cache for the IP address
    time_t current_time = time(NULL);
    for (int i = 0; i < cache_index; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && dns_cache[i].expiration_time > current_time) {
            memcpy(ip, &dns_cache[i].ip, MAX_IP_LENGTH);
            return ip;
        }
    }

    // Perform DNS resolution
    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL; // Placeholder for error handling
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), MAX_IP_LENGTH);

    // Store the resolved IP in the cache with an expiration time
    if (cache_index < DNS_CACHE_SIZE) {
        dns_cache[cache_index].hostname[0] = '\0';
        strcpy(dns_cache[cache_index].hostname, hostname);
        memcpy(&dns_cache[cache_index].ip, ip, MAX_IP_LENGTH);
        dns_cache[cache_index].expiration_time = current_time + 3600; // Cache for 1 hour
        cache_index++;
    }

    freeaddrinfo(res); // Free the linked list

    return ip;
}

int main() {
