import os
import re
from collections import defaultdict

def read_and_sort_log_files(log_file_paths):
    log_data = []
    for file_path in log_file_paths:
        if not os.path.isfile(file_path):
            print(f"Error: File '{file_path}' does not exist.")
            continue

        try:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                if lines:
                    last_line = lines[-1]
                    sequence_number_match = re.search(r'sequence_number=(\d+)', last_line)
                    if sequence_number_match:
                        sequence_number = int(sequence_number_match.group(1))
                        log_data.append((sequence_number, file_path))
        except Exception as e:
            print(f"Error reading file '{file_path}': {e}")

    return sorted(log_data, key=lambda x: x[0])

def generate_summary_report(log_files):
    summary = {}
    for _, file_path in log_files:
        if file_path not in summary:
            summary[file_path] = {'count': 1}
        else:
            summary[file_path]['count'] += 1
    return summary

# Example usage:
log_file_paths = ['log1.txt', 'log2.txt', 'log3.txt']
sorted_logs = read_and_sort_log_files(log_file_paths)
report = generate_summary_report(sorted_logs)
print(report)
