#include <iostream>
#include <vector>

struct OctreeNode {
    std::vector<OctreeNode*> children;
    // Other data members as needed

    OctreeNode() : children(8, nullptr) {}
    ~OctreeNode() {
        for (auto& child : children) {
            delete child;
        }
    }
};

OctTreeNode* initializeOctree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity, size_t maxMemoryLimit) {
    // Validate input parameters
    if (featureSize == 0 || numLeafNodes == 0 || dataCapacity == 0 || maxMemoryLimit == 0) {
        std::cerr << "Invalid input parameters. All values must be greater than zero." << std::endl;
        return nullptr;
    }

    // Calculate memory requirements
    size_t nodeSize = sizeof(OctTreeNode);
    size_t prefixLeafsSize = numLeafNodes * (featureSize * featureSize * featureSize * sizeof(float));
    size_t dataArraySize = dataCapacity * (sizeof(int) + 3 * sizeof(float)); // Assuming int and 3 floats for data

    size_t totalMemoryRequired = nodeSize + prefixLeafsSize + dataArraySize;
    if (totalMemoryRequired > maxMemoryLimit) {
        std::cerr << "Out of memory. Required: " << totalMemoryRequired << ", Limit: " << maxMemoryLimit << std::endl;
        return nullptr;
    }

    // Allocate memory
    try {
        OctTreeNode* root = new OctTreeNode();
        float* prefixLeafs = new float[numLeafNodes * (featureSize * featureSize * featureSize)];
        int* dataArray = new int[dataCapacity];

        // Initialize data structures
        for (size_t i = 0; i < numLeafNodes; ++i) {
            size_t index = i * (featureSize * featureSize * featureSize);
            for (size_t j = 0; j < featureSize * featureSize * featureSize; ++j) {
                prefixLeafs[index + j] = static_cast<float>(i + j); // Example initialization
            }
        }

        for (size_t i = 0; i < dataCapacity; ++i) {
            dataArray[i] = static_cast<int>(i); // Example initialization
        }

        // Clean up in case of failure
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        return nullptr;
    }

    return root;
}

int main() {
    size_t featureSize = 10;
    size_t numLeafNodes = 1000;
    size_t dataCapacity = 10000;
    size_t maxMemoryLimit = 1024 * 1024 * 1024; // 1 GB

    OctTreeNode* root = initializeOctree(featureSize, numLeafNodes, dataCapacity, maxMemoryLimit);
    if (root) {
        std::cout << "Octree initialized successfully." << std::endl;
        delete root;
    }

    return 0;
}
```

