#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define MAX_SESSIONS 1000

typedef struct {
    unsigned long id;
    time_t expiry_time;
} Session;

Session session_pool[MAX_SESSIONS];
int next_id = 0;
int active_sessions = 0;
bool refresh_in_progress = false;

unsigned long generate_session_id() {
    return rand();
}

void create_session(time_t duration) {
    if (active_sessions >= MAX_SESSIONS) {
        printf("Session pool is full!\n");
        return;
    }
    session_pool[next_id].id = generate_session_id();
    time_t current_time = time(NULL);
    session_pool[next_id].expiry_time = current_time + duration;
    active_sessions++;
    next_id = (next_id + 1) % MAX_SESSIONS;
}

bool validate_session(unsigned long id) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_pool[i].id == id && time(NULL) < session_pool[i].expiry_time) {
            return true;
        }
    }
    return false;
}

void clean_up_sessions() {
    int new_active_sessions = 0;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (time(NULL) >= session_pool[i].expiry_time) {
            continue;
        }
        session_pool[new_active_sessions++] = session_pool[i];
    }
    active_sessions = new_active_sessions;
}

void refresh_session_id(unsigned long old_id, time_t duration) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_pool[i].id == old_id && time(NULL) < session_pool[i].expiry_time) {
            unsigned long new_id = generate_session_id();
            session_pool[i].id = new_id;
            session_pool[i].expiry_time = time(NULL) + duration;
            break;
        }
    }
}

int main() {
    srand(time(NULL));
    create_session(3600);
    create_session(1800);
    printf("Session 1 valid: %d\n", validate_session(session_pool[0].id));
    clean_up_sessions();
    refresh_session_id(session_pool[1].id, 7200);
    return 0;
}
