using System;
using System.Security.Cryptography;

public class PerformanceCriticalValueGenerator
{
    private int _minValue;
    private int _maxValue;
    private Random _random;

    public PerformanceCriticalValueGenerator(int minValue, int maxValue)
    {
        SetRange(minValue, maxValue);
        _random = new Random();
    }

    public void SetRange(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("MinValue must be less than MaxValue.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
