    if (!response.ok) throw new Error('Network response was not ok');
    return await response.json();
  } catch (error) {
    console.error('Failed to fetch random number:', error);
    return Math.random(); // Fallback to a cryptographically secure random number
  }
};

const memoizedRandomNumber = () => {
  let cache = null;
  let lastFetchTime = 0;
  const cacheDuration = 60 * 1000; // Cache for 1 minute

  return async () => {
    if (!cache || Date.now() - lastFetchTime > cacheDuration) {
      cache = await fetchRandomNumber();
      lastFetchTime = Date.now();
    }
    return cache;
  };
};

const efficientAsyncReduce = async (array, initialValue, asyncCallback) => {
  const getRandomNumber = memoizedRandomNumber();

  for (let i = 0; i < array.length; i++) {
    const randomNumber = await getRandomNumber();
    if (randomNumber > 0.5) continue; // Filter based on pseudo-random number
    initialValue = await asyncCallback(initialValue, array[i]);
  }

  return initialValue;
};

