#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

int count_log_entries(const char *file_path) {
    FILE *log_file = fopen(file_path, "r");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    int entry_count = 0;
    char *line_buffer = malloc(MAX_LINE_LENGTH);
    if (line_buffer == NULL) {
        perror("Memory allocation failed for line buffer");
        fclose(log_file);
        return -1;
    }

    while (fgets(line_buffer, MAX_LINE_LENGTH, log_file) != NULL) {
        // Trim leading and trailing whitespace
        size_t len = strlen(line_buffer);
        while (len > 0 && isspace((unsigned char)line_buffer[len-1])) {
            line_buffer[--len] = '\0';
        }
        if (len > 0) {
            entry_count++;
        }
    }

    free(line_buffer);
    fclose(log_file);
    return entry_count;
}
```

This C function `count_log_entries` takes a file path as input and returns the total number of entries in the log file. It reads the file line by line, dynamically allocating memory for each line to ensure safety against stack-based buffer overflow. The function handles large files efficiently by minimizing memory usage and ensuring that incomplete lines are not counted towards the total entry count. It also includes error handling for file opening and memory allocation failures.']

