#define MAX_FILENAME_LENGTH 500
#define MAX_PATH_LENGTH 1024

int count_vowels(const char *filename) {
    int count = 0;
    while (*filename) {
        switch (tolower(*filename)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                count++;
                break;
        }
        filename++;
    }
    return count;
}

void modify_filename(const char *input, char *output) {
    if (strlen(input) > MAX_FILENAME_LENGTH) {
        input = input + strlen(input) - MAX_FILENAME_LENGTH;
    }

    int vowel_count = count_vowels(input);
    snprintf(output, MAX_PATH_LENGTH, "%s%.*d", input, vowel_count, 123456789); // Replace '123456789' with predefined file type

    if (strlen(output) > MAX_FILENAME_LENGTH) {
