void initialize_aes_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    // Derive key using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);

    // Copy the first 32 bytes of the hash as key
    *key = (unsigned char *)malloc(32);
    memcpy(*key, hash, 32);

    // Generate a random IV of 16 bytes
    *iv = (unsigned char *)malloc(16);
    if (!RAND_bytes(*iv, 16)) {
        fprintf(stderr, "Error generating random IV\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

