#include <uuid/uuid.h>

#define MAX_COMMANDS 100
#define TIMEOUT_SECONDS 3600
#define LOG_FILE "command_logs.txt"
#define LOG_ROTATION_INTERVAL 86400

typedef struct {
    uuid_t id;
    char command[256];
    pid_t pid;
    int status;
} Command;

Command commands[MAX_COMMANDS] = {0};
int active_commands = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void log_command(const char *command, const char *output) {
    fprintf(log_file, "%s\n%s\n", command, output);
}

void rotate_log() {
    fclose(log_file);
    rename(LOG_FILE, "old_command_logs.txt");
    log_file = fopen(LOG_FILE, "w");
}

void signal_handler(int signum) {
    if (signum == SIGTERM) {
        for (int i = 0; i < active_commands; i++) {
            kill(commands[i].pid, SIGTERM);
        }
        exit(0);
    }
}

void *execute_command(void *arg) {
    Command *cmd = (Command *)arg;
    int status = system(cmd->command);
    cmd->status = WEXITSTATUS(status);
    pthread_mutex_lock(&mutex);
    commands[active_commands++] = *cmd;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int run_command(const char *command) {
    pthread_t thread_id;
    Command cmd;
    uuid_generate(cmd.id);
    snprintf(cmd.command, sizeof(cmd.command), "%s", command);

    if (pthread_create(&thread_id, NULL, execute_command, &cmd) != 0) {
        return -1;
    }

    // Add code to handle timeout and signal handling

    pthread_join(thread_id, NULL);
    return cmd.status;
}

int get_command_status(uuid_t id) {
    for (int i = 0; i < active_commands; i++) {
        if (memcmp(commands[i].id, id, sizeof(uuid_t)) == 0) {
            return commands[i].status;
        }
    }
    return -1;
}

int main() {
    signal(SIGTERM, signal_handler);
    log_file = fopen(LOG_FILE, "w");

    while (1) {
        // Add code to dynamically generate and run commands

        sleep(1);
        if (time(NULL) % LOG_ROTATION_INTERVAL == 0) {
            rotate_log();
        }
    }

    fclose(log_file);
    return 0;
}
