import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

public class FileBackup {
    private static final int AGE_THRESHOLD = 30; // days

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter source directory path:");
        Path sourceDir = Paths.get(scanner.nextLine());
        System.out.println("Enter backup directory path:");
        Path backupDir = Paths.get(scanner.nextLine());

        if (!Files.exists(sourceDir)) {
            System.err.println("Source directory does not exist.");
            return;
        }

        if (!Files.isDirectory(sourceDir)) {
            System.err.println("Source is not a directory.");
            return;
        }

        if (!Files.isWritable(backupDir)) {
            System.out.println("Backup directory is not writable. Create or change permissions?");
            boolean create = scanner.nextLine().equalsIgnoreCase("yes");
            if (create) {
                try {
                    Files.createDirectories(backupDir);
                } catch (IOException e) {
                    System.err.println("Failed to create backup directory.");
                    return;
                }
            } else {
                System.out.println("Operation cancelled.");
                return;
            }
        }

        try {
            List<Path> filesToCopy = findFilesOlderThan(sourceDir, AGE_THRESHOLD);
            if (!filesToCopy.isEmpty()) {
                generateAndExecuteCopyCommand(filesToCopy, sourceDir, backupDir);
            } else {
                System.out.println("No files older than " + AGE_THRESHOLD + " days to copy.");
            }
        } catch (IOException e) {
            System.err.println("Error processing file operations: " + e.getMessage());
        }
    }

    private static List<Path> findFilesOlderThan(Path directory, int ageThreshold) throws IOException {
        List<Path> filesToCopy = new ArrayList<>();
        Files.walkFileTree(directory, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (System.currentTimeMillis() - attrs.lastModifiedTime().toMillis() > ageThreshold * 24 * 60 * 60 * 1000) {
                    filesToCopy.add(file);
                }
                return FileVisitResult.CONTINUE;
            }
        });
        return filesToCopy;
    }

    private static void generateAndExecuteCopyCommand(List<Path> files, Path sourceDir, Path backupDir) throws IOException {
        List<String> commands = new ArrayList<>();
        for (Path file : files) {
            Path targetFile = backupDir.resolve(sourceDir.relativize(file));
            commands.add("cp -r " + file.toAbsolutePath() + " " + targetFile.toAbsolutePath());
        }

        ProcessBuilder pb = new ProcessBuilder("bash", "-c", String.join("\n", commands));
        try (Process process = pb.start()) {
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.err.println("Copy operation failed with exit code: " + exitCode);
            } else {
                System.out.println("Files copied successfully.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Operation interrupted.");
        }
    }
}
