import java.io.FileInputStream;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class DatabaseConnector {

    private static Properties config = new Properties();
    private static final int MAX_RETRIES = 3;
    private static final long[] RETRY_DELAYS = {100, 500, 2000};

    static {
        loadConfig("db.properties");
    }

    public static boolean connectToDatabase() {
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                String url = config.getProperty("database.url");
                String username = config.getProperty("database.username");
                String password = config.getProperty("database.password");

                if (url == null || username == null || password == null) {
                    logError("Missing configuration values: " + 
                             (url == null ? "url, " : "") +
                             (username == null ? "username, " : "") +
                             (password == null ? "password" : ""));
                    return false;
                }

                Connection connection = DriverManager.getConnection(url, username, password);
                if (connection != null) {
                    logInfo("Database connection established successfully.");
                    return true;
                }
            } catch (SQLException e) {
                if (i < MAX_RETRIES - 1) {
                    long delay = RETRY_DELAYS[i];
                    logWarning("Connection attempt failed. Retrying in " + delay + "ms...");
                    try {
                        TimeUnit.MILLISECONDS.sleep(delay);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return false;
                    }
                } else {
                    logError("Failed to establish database connection after " + MAX_RETRIES + " attempts.");
                    return false;
                }
            }
        }
        return false;
    }

    private static void loadConfig(String filename) {
        try (FileInputStream fis = new FileInputStream(filename)) {
            config.load(fis);
        } catch (IOException e) {
            logError("Failed to load configuration file: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }

    private static void logInfo(String message) {
        System.out.println("[INFO] " + message);
    }

    private static void logWarning(String message) {
        System.err.println("[WARNING] " + message);
    }

    private static void logError(String message) {
        System.err.println("[ERROR] " + message);
    }
}
