    private string modify_filename(string filename)
    {
        if (filename.Length > 255)
        {
            filename = filename.Substring(0, 255);
        }

        int vowelCount = Regex.Matches(filename.ToLower(), "[aeiou]").Count;
        string newExtension = $"{vowelCount:D}{new Random().Next(100):D2}.txt"; // Example extension
        string newFilename = Path.GetFileNameWithoutExtension(filename) + newExtension;

        if (newFilename.Length > 500)
        {
            newFilename = newFilename.Substring(0, 500);
        }

        return newFilename;
    }
