public class MessageDecryptor
{
    private byte[] key;
    private byte[] iv;
    private string logFilePath;

    public MessageDecryptor(string keyHex, string ivHex, string logFilePath)
    {
        if (string.IsNullOrEmpty(keyHex) || string.IsNullOrEmpty(ivHex) || string.IsNullOrEmpty(logFilePath))
        {
            throw new ArgumentException("Key, IV, and log file path cannot be null or empty.");
        }

        this.key = Convert.FromHexString(keyHex);
        this.iv = Convert.FromHexString(ivHex);
        this.logFilePath = logFilePath;
    }

    public string Decrypt(string base64EncodedMessage)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage))
        {
            LogError("Invalid input: Base64 encoded message cannot be null or empty.");
            return "Error: Invalid input.";
        }

        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
                using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError("Decryption failed: " + ex.Message);
            return "Error: Decryption failed.";
        }
    }

    private void LogError(string message)
    {
        try
        {
            using (StreamWriter sw = new StreamWriter(logFilePath, true))
