using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class MessageProcessor
{
    private readonly ConcurrentBag<Message> _messages = new ConcurrentBag<Message>();
    private readonly int _maxParallelDecryptions = 100;
    private readonly int _memoryFootprintLimitPerCore = 10 * 1024 * 1024; // 10 MB
    private readonly ILogger _logger;

    public MessageProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public void EnqueueMessage(Message message)
    {
        _messages.Add(message);
    }

    public async Task ProcessMessagesAsync()
    {
        while (_messages.Any())
        {
            var tasks = _messages.Take(_maxParallelDecryptions).Select(ProcessMessageAsync);
            await Task.WhenAll(tasks);

            // Remove processed messages from the queue
            foreach (var message in tasks.Select(task => task.Result))
            {
                _messages.Remove(message);
            }
        }
    }

    private async Task<Message> ProcessMessageAsync(Message message)
    {
        try
        {
            var decryptedData = await DecryptAsync(message.EncryptedData, message.Key, message.IV);
            if (message.Checksum != null && !VerifyChecksum(decryptedData, message.Checksum))
            {
                _logger.LogError("HMAC-SHA256 verification failed for message.");
                return message;
            }

            // Process the decrypted data
