import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInput;
import java.io.ObjectInputStream;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DeserializationService {

    private static final Logger logger = Logger.getLogger(DeserializationService.class.getName());

    public <T> T deserialize(byte[] data, Class<T> expectedClass) {
        if (data == null || data.length == 0) {
            throw new IllegalArgumentException("Data cannot be null or empty");
        }

        try (ObjectInput in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Object obj = in.readObject();
            if (!expectedClass.isInstance(obj)) {
                throw new RuntimeException("Deserialized object does not match the expected class type");
            }
            return expectedClass.cast(obj);
        } catch (IOException | ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Deserialization failed", e);
            throw new RuntimeException("Failed to deserialize data", e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        byte[] serializedData = ...; // Assume this is the byte array received from an external source
        DeserializationService service = new DeserializationService();
        try {
            MyClass deserializedObject = service.deserialize(serializedData, MyClass.class);
            // Use the deserialized object
        } catch (RuntimeException e) {
            System.err.println(e.getMessage());
        }
    }
}
```

