// Initialize Redis client for configuration caching
const redisClient = redis.createClient();

// Function to fetch updated configuration from a remote service
async function fetchConfig() {
  try {
    const response = await axios.get('https://api.configservice.com/settings');
    return response.data;
  } catch (error) {
    console.error('Failed to fetch configuration:', error);
    throw error;
  }
}

// Function to apply the latest configuration
async function applyConfiguration(config) {
  // Update application settings based on config object
  // Example: app.set('maxSessions', config.maxSessions);
  console.log('Applying new configuration:', config);
}

// Route to update configuration via API
app.post('/updateConfig', async (req, res) => {
  try {
    const newConfig = await fetchConfig();
    await applyConfiguration(newConfig);
    // Cache the new configuration in Redis for quick access
    redisClient.set('config', JSON.stringify(newConfig));
    res.status(200).json({ message: 'Configuration updated successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to update configuration' });
  }
});

// Middleware to load and apply configuration from Redis
app.use(async (req, res, next) => {
  try {
    const cachedConfig = await redisClient.get('config');
    if (cachedConfig) {
      req.config = JSON.parse(cachedConfig);
    } else {
      const config = await fetchConfig();
      req.config = config;
      // Cache the fetched configuration
      redisClient.set('config', JSON.stringify(config));
    }
    next();
  } catch (error) {
    next(error);
  }
});

// Example route using configuration
