use std::fs;
use std::env;
use std::time::{Duration, Instant};
use std::sync::Mutex;
use log::{info, warn, error};
use crossbeam_channel::{self, Receiver, Sender};

// Define a safe character set for directory names
const SAFE_CHARS: &[char] = &['a'..='z', 'A'..='Z', '0'..='9', '_', '-'];

fn validate_directory_name(name: &str) -> bool {
    name.chars().all(|c| SAFE_CHARS.iter().any(|range| range.contains(&c)))
}

fn create_directory_with_lock(name: &str, lock_channel: &Sender<String>, max_retries: u32, timeout_ms: u64) -> Result<(), String> {
    let now = Instant::now();
    loop {
        if now.elapsed() > Duration::from_millis(timeout_ms) {
            return Err("Operation timed out".to_string());
        }

        let lock_message = format!("lock_{}", name);
        match lock_channel.send(lock_message.clone()) {
            Ok(_) => {
                if fs::create_dir_all(name).is_err() && !fs::metadata(name).is_ok() {
                    warn!("Failed to create directory: {}", name);
                    return Err("Directory creation failed".to_string());
                }
                env::set_var(format!("DIRECTORY_PATH_{}", name), name);
                info!("Created directory and set environment variable for: {}", name);
                lock_channel.send(format!("unlock_{}", name)).unwrap();
                return Ok(());
            },
            Err(_) => {
                std::thread::sleep(Duration::from_millis(10));
            }
        }

        if max_retries > 0 && now.elapsed() > Duration::from_millis(timeout_ms / 2) {
            error!("Max retries exceeded for directory creation: {}", name);
            return Err("Max retries exceeded".to_string());
        }
    }
}

fn main() {
    // Setup logging configuration
    log4rs::init_file("log4rs.yaml", Default::default()).unwrap();

    let (lock_sender, lock_receiver): (Sender<String>, Receiver<String>) = crossbeam_channel::bounded(1);

    let directory_name = "safe_directory_123";
    if validate_directory_name(directory_name) {
        match create_directory_with_lock(directory_name, &lock_sender, 5, 150) {
            Ok(_) => info!("Successfully created and locked directory: {}", directory_name),
            Err(e) => error!("Failed to create or lock directory: {}", e),
        }
    } else {
        warn!("Invalid directory name provided: {}", directory_name);
    }

    // Simulate service degradation by handling retries
    for _ in 0..3 {
        if let Err(_) = create_directory_with_lock(directory_name, &lock_sender, 5, 150) {
            info!("Retrying directory creation...");
        } else {
            break;
        }
    }
}
