import json
import inspect
import os

class JSONSerializer:
    _registry = {}

    @classmethod
    def register(cls, type_id, factory):
        cls._registry[type_id] = factory

    @classmethod
    def deserialize(cls, json_str):
        data = json.loads(json_str)
        if 'type' not in data or data['type'] not in cls._registry:
            raise ValueError("Invalid JSON format")

        factory = cls._registry[data['type']]
        return factory(data.get('data', {}))

    def serialize(self):
        type_id = self.__class__.__name__
        if type_id not in JSONSerializer._registry:
            raise ValueError(f"Type {self.__class__.__name__} not registered")

        data = {
            'type': type_id,
            'data': vars(self)
        }
        return json.dumps(data)

def load_config(config_service):
    types_metadata = config_service.get_types_metadata()

    for metadata in types_metadata:
        class_name = metadata['type_name']
        factory_id = metadata['factory_id']

        # Dynamically create the custom type and its corresponding factory function
        module_path, class_name = class_name.rsplit('.', 1)
        module = __import__(module_path, fromlist=[class_name])
        cls = getattr(module, class_name)

        def factory(data):
            return cls(**data)

        JSONSerializer.register(factory_id, factory)

def register_types_from_directories(directories):
    for directory in directories:
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    module_path = os.path.relpath(os.path.join(root, file), start=os.getcwd()).replace(os.sep, '.').rstrip('.py')
                    __import__(module_path)

# Example usage
class MyCustomType:
    def __init__(self, value):
        self.value = value

def my_custom_type_factory(data):
    return MyCustomType(**data)

JSONSerializer.register('my_custom_type', my_custom_type_factory)

serializer = JSONSerializer()
json_str = serializer.serialize()
new_instance = JSONSerializer.deserialize(json_str)
print(new_instance.value)  # Output: <value_of_the_instance>

config_service = SomeConfigService()  # Replace with actual config service
load_config(config_service)

register_types_from_directories(['path/to/custom/types'])
