    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Requested more records than the maximum allowed.\n");
        return NULL;
    }

    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < count; i++) {
