    if (size <= 0) {
        fprintf(stderr, "Error: Array is empty.\n");
        return -1; // Return an invalid value or handle error appropriately
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

