#define INITIAL_SIZE 1024
#define CACHE_LINE_SIZE 64

typedef struct {
    int value;
} record;

long* allocate_long_array(size_t size) {
    long* array = aligned_alloc(CACHE_LINE_SIZE, size * sizeof(long));
    if (!array) {
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = i; // Initialize with offset
    }
    return array;
}

int* allocate_int_array(size_t size) {
    int* array = aligned_alloc(CACHE_LINE_SIZE, size * sizeof(int));
    if (!array) {
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = rand() % 1000; // Initialize with random key
    }
    return array;
}

record* allocate_record_array(size_t size, unsigned seed) {
    record* array = aligned_alloc(CACHE_LINE_SIZE, size * sizeof(record));
    if (!array) {
        return NULL;
    }
    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        array[i].value = rand() % 1000; // Initialize with random value
    }
    return array;
}

void free_all(long* offsets, int* keys, record* records) {
    if (offsets) {
        aligned_free(offsets);
    }
    if (keys) {
        aligned_free(keys);
    }
    if (records) {
        aligned_free(records);
    }
}

record* resize_record_array(record* old_records, size_t old_size, size_t new_size, unsigned seed) {
    record* new_records = allocate_record_array(new_size, seed);
    if (!new_records) {
        return NULL;
    }
    for (size_t i = 0; i < old_size && i < new_size; ++i) {
        new_records[i].value = old_records[i].value;
    }
    free_all(NULL, NULL, old_records);
    return new_records;
}

void reset_prng_seed(unsigned seed) {
    srand(seed);
}

// Example usage
int main() {
    unsigned seed = time(NULL);
    long* offsets = allocate_long_array(INITIAL_SIZE);
    int* keys = allocate_int_array(INITIAL_SIZE);
    record* records = allocate_record_array(INITIAL_SIZE, seed);

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        free_all(offsets, keys, records);
        return 1;
    }

    // Simulate usage
    size_t new_size = INITIAL_SIZE * 2;
    record* resized_records = resize_record_array(records, INITIAL_SIZE, new_size, seed);

    if (!resized_records) {
        // Handle memory allocation failure
        free_all(offsets, keys, records);
        return 1;
    }

    free_all(offsets, keys, resized_records);

    reset_prng_seed(seed);

    return 0;
}
