#include <iostream>
#include <vector>
#include <random>
#include <memory>

namespace random_namespace {
    class MersenneTwisterPRNG {
    public:
        static std::mt19937* mt;

        MersenneTwisterPRNG() {
            if (mt == nullptr) {
                mt = new std::mt19937(std::random_device{}());
            }
        }

        ~MersenneTwisterPRNG() {
            delete mt;
            mt = nullptr;
        }

        static int generateRandomInt(int min, int max) {
            if (mt == nullptr) throw std::runtime_error("PRNG not initialized.");
            return std::uniform_int_distribution<>(min, max)(*mt);
        }
    };

    std::mt19937* MersenneTwisterPRNG::mt = nullptr;
}

struct record {
    int value;
};

extern "C" void allocate_and_initialize_records(long* offsets, int* keys, size_t count) {
    try {
        std::vector<record> records(count);
        for (size_t i = 0; i < count; ++i) {
            keys[i] = random_namespace::MersenneTwisterPRNG::generateRandomInt(1, 100);
            records[i].value = keys[i];
        }

        offsets[0] = reinterpret_cast<long>(&records[0]);
        for (size_t i = 1; i < count; ++i) {
            offsets[i] = offsets[i - 1] + sizeof(record);
        }
    } catch (const std::exception& e) {
        // Log the error
        std::cerr << "Error: " << e.what() << std::endl;
    }
}

int main() {
    size_t count = 1000000; // Example size
    long* offsets = new long[count];
    int* keys = new int[count];

    allocate_and_initialize_records(offsets, keys, count);

    delete[] offsets;
    delete[] keys;

    return 0;
}
