int runCommandWithLogging(const char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0; // Command execution failed
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp"); // Should not reach here
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}

void generateSensorData(long* timestamps, int* keyIndices, double* sensorReadings, size_t count) {
