    const size_t id_length = 32;
    *id = (char *)malloc(id_length);
    if (*id == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    if (!RAND_bytes((unsigned char *)*id, id_length)) {
        fprintf(stderr, "Failed to generate random bytes\n");
        free(*id);
        exit(EXIT_FAILURE);
    }
    (*id)[id_length - 1] = '\0'; // Null-terminate the string
}

record *initialize_records(int count) {
    record *records = (record *)malloc(count * sizeof(record));
    if (records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; ++i) {
        records[i].value = -1;
        records[i].id = NULL;
        generate_random_id(&records[i].id);
    }
    return records;
}

void process_records(record *records, int count) {
