        fprintf(stderr, "Failed to initialize CSPRNG\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; ++i) {
        records[i].value = (int)rand(); // CSPRNG-generated random number
    }
}

void print_max_value(record *records, int count) {
    if (count == 0) {
        printf("No records to process\n");
        return;
    }
    int max_value = records[0].value;
    for (int i = 1; i < count; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    printf("Maximum value: %d\n", max_value);
}

void free_records(record *records, int count) {
    for (int i = 0; i < count; ++i) {
        if (records[i].id != NULL) {
            free(records[i].id);
        }
    }
    free(records);
}

int main() {
    record *records = initialize_records(MAX_RECORDS);
    process_records(records, MAX_RECORDS);
    print_max_value(records, MAX_RECORDS);
    free_records(records, MAX_RECORDS);
    return 0;
}
