#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h>

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_SUSPENDED
} Status;

typedef struct Node {
    int id;
    Status status;
    time_t timestamp;
    struct Node* next;
} Node;

Node* create_node(int min_id, int max_id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure
        return NULL;
    }

    if (!RAND_bytes((unsigned char*)&new_node->id, sizeof(new_node->id))) {
        // Handle CSPRNG failure
        free(new_node);
        return NULL;
    }

    new_node->id = (int)(rand() % (max_id - min_id + 1)) + min_id;
    new_node->status = STATUS_ACTIVE;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    return new_node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL || new_node->id < (*head)->id) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->id < new_node->id) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_node(Node** head, int id) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return; // Node not found
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

void free_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
