        keys[i] = (int)(i + 1); // Example key initialization
        status_flags[i] = 0x0000; // Initial status flag value
    }

    return 0;
}

// Function to release all allocated resources
void free_pipeline(record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
            records[i] = NULL;
        }
    }
}

