#define MAX_EVENT_COUNT 10000000
#define EVENT_DESC_MAX_LEN 256

typedef struct {
    long timestamp;
    int event_type;
    char* description;
} event;

typedef struct {
    size_t capacity;
    size_t count;
    event* events;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_capacity) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->events = (event*)malloc(initial_capacity * sizeof(event));
    if (!pool->events) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->events[i].description);
    }
    free(pool->events);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

event* allocate_event(memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        event* new_events = (event*)realloc(pool->events, new_capacity * sizeof(event));
        if (!new_events) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->events = new_events;
        pool->capacity = new_capacity;
    }

    event* new_event = &pool->events[pool->count++];
    new_event->description = (char*)malloc(EVENT_DESC_MAX_LEN * sizeof(char));
    if (!new_event->description) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pthread_mutex_unlock(&pool->lock);
    return new_event;
}

int main() {
    memory_pool* pool = create_memory_pool(1000);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

