        // Simulate setting up the event
        new_event->timestamp = i * 1000; // Example timestamp
        new_event->event_type = i % 5;   // Example event type

        // Generate a pseudo-random event description
        snprintf(new_event->description, EVENT_DESC_MAX_LEN, "Event %zu", i);
    }

    destroy_memory_pool(pool);
    return 0;
}
