#include <stdlib.h>
#include <pthread.h>

typedef struct Event {
    double timestamp;
    int key;
    long offset;
} Event;

typedef struct MemoryPool {
    Event *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity < 0) {
        fprintf(stderr, "Invalid initial capacity: %zu\n", initial_capacity);
        return NULL;
    }

    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory for memory pool");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    if (pthread_mutex_init(&pool->mutex, &attr) != 0) {
        perror("Failed to initialize mutex for memory pool");
        free(pool);
        return NULL;
    }

    pool->events = (Event*)malloc(initial_capacity * sizeof(Event));
    if (!pool->events) {
        perror("Failed to allocate memory for events in memory pool");
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool == NULL) {
        fprintf(stderr, "Invalid memory pool pointer\n");
        return;
    }

    pthread_mutex_lock(&pool->mutex);

    free(pool->events);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int add_event(MemoryPool *pool, int key, long offset) {
    if (pool == NULL) {
        fprintf(stderr, "Invalid memory pool pointer\n");
        return -1;
    }

    pthread_mutex_lock(&pool->mutex);

    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Event *new_events = (Event*)realloc(pool->events, new_capacity * sizeof(Event));
        if (!new_events) {
            perror("Failed to resize memory for events in memory pool");
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }

        pool->events = new_events;
        pool->capacity = new_capacity;
    }

    double timestamp = ((double)rand()) / RAND_MAX * 86400 + 1577836800; // Generate a random timestamp within a specific range
    Event event = {timestamp, key, offset};
    pool->events[pool->size++] = event;

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void* prng_thread(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;

    while (1) {
        // Simulate adding events to the memory pool
        add_event(pool, rand() % 1000000, rand());
        sleep(1); // Adjust the frequency as needed
    }

    return NULL;
}

int main() {
    MemoryPool *pool = create_memory_pool(50000000);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    pthread_t prng_tid;
    if (pthread_create(&prng_tid, NULL, prng_thread, (void*)pool) != 0) {
        perror("Failed to create PRNG thread");
        destroy_memory_pool(pool);
        return 1;
    }

    // Simulate other operations and management
    pthread_join(prng_tid, NULL);

    destroy_memory_pool(pool);
    return 0;
}
```

