    // Allocate memory for 'record' structures array
    record *records = (record *)malloc(numEdges * sizeof(record));

    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");

        // Free previously allocated arrays on failure
        free(offsets);
        free(keys);
