void generate_random_string(char* buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        buffer[i] = charset[rand() % sizeof(charset)];
    }
    buffer[length - 1] = '\0';
}

void initialize_logging_system(log_entry** log_entries, long* timestamps, int* event_ids, char** messages) {
    srand(time(NULL)); // Seed the random number generator

    *log_entries = (log_entry*)malloc(NUM_LOG_ENTRIES * sizeof(log_entry));
    *timestamps = (long*)malloc(NUM_LOG_ENTRIES * sizeof(long));
    *event_ids = (int*)malloc(NUM_LOG_ENTRIES * sizeof(int));
    *messages = (char**)malloc(NUM_LOG_ENTRIES * sizeof(char*));

    for (size_t i = 0; i < NUM_LOG_ENTRIES; ++i) {
        (*log_entries)[i].timestamp = time(NULL);
        (*log_entries)[i].event_id = rand() % 100 + 1; // Random event ID between 1 and 100
        (*messages)[i] = (char*)malloc(MAX_MESSAGE_LENGTH * sizeof(char));
        generate_random_string((*messages)[i], MAX_MESSAGE_LENGTH);
    }
}

void cleanup_logging_system(log_entry* log_entries, long* timestamps, int* event_ids, char** messages) {
    for (size_t i = 0; i < NUM_LOG_ENTRIES; ++i) {
        free(messages[i]);
    }
    free(messages);
    free(event_ids);
    free(timestamps);
    free(log_entries);
}

int main() {
    log_entry* log_entries;
    long* timestamps;
    int* event_ids;
    char** messages;

    initialize_logging_system(&log_entries, &timestamps, &event_ids, &messages);

    // Simulate logging some events
    for (size_t i = 0; i < NUM_LOG_ENTRIES; ++i) {
        printf("Timestamp: %ld, Event ID: %d, Message: %s\n", 
               log_entries[i].timestamp, log_entries[i].event_id, log_entries[i].message);
    }

    cleanup_logging_system(log_entries, timestamps, event_ids, messages);

    return 0;
}
