void findAndPrintLargest(int* array, size_t size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

