        void* ptr = malloc(size);
        if (!ptr) {
            std::cerr << "Memory allocation failed" << std::endl;
            exit(EXIT_FAILURE);
        }
        return ptr;
    }

    static void deallocate(void* ptr, size_t size) {
        free(ptr);
    }
};

record* initializeArray(int count, int minVal, int maxVal) {
    record* array = static_cast<record*>(MemoryManager::allocate(count * sizeof(record)));
    for (int i = 0; i < count; ++i) {
        array[i].value = rand() % (maxVal - minVal + 1) + minVal;
    }
    return array;
}

void freeArray(record* array, int count) {
    MemoryManager::deallocate(array, count * sizeof(record));
}

int findLargest(const std::vector<int>& vec) {
    if (vec.empty()) {
        throw std::invalid_argument("Vector is empty");
    }
    int maxVal = vec[0];
    for (int num : vec) {
        if (num > maxVal) {
            maxVal = num;
        }
    }
    return maxVal;
}

void insertAfterString(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            it++;
            list.insert_after(it, insertion);
            return;
        }
        ++it;
    }
    list.push_back(insertion);
}

int main() {
    // Example usage
    srand(static_cast<unsigned int>(time(nullptr)));

    std::vector<long> offsets(1000); // Example size for demonstration
    std::vector<int> keys(500);     // Example size for demonstration

    record* records = initializeArray(offsets.size(), 1, 1000);
    try {
        int largestValue = findLargest(keys);
        std::cout << "Largest value: " << largestValue << std::endl;

        std::forward_list<std::string> stringList = {"apple", "banana", "cherry"};
        insertAfterString(stringList, "banana", "grape");

        for (const auto& str : stringList) {
            std::cout << str << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    freeArray(records, offsets.size());
    return 0;
}
