#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    long* offsets;
    int* keys;
    double* timestamps;
} record;

record* create_records(int num_records, unsigned long seed) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Too many records requested\n");
        return NULL;
    }

    record* rec = malloc(sizeof(record));
    if (!rec) {
        perror("Failed to allocate memory for record structure");
        return NULL;
    }

    rec->offsets = malloc(num_records * sizeof(long));
    rec->keys = malloc(num_records * sizeof(int));
    rec->timestamps = malloc(num_records * sizeof(double));

    if (!rec->offsets || !rec->keys || !rec->timestamps) {
        perror("Failed to allocate memory for arrays");
        free(rec);
        return NULL;
    }

    pthread_mutex_t* lock = malloc(sizeof(pthread_mutex_t));
    if (!lock) {
        perror("Failed to allocate memory for mutex");
        free(rec->offsets);
        free(rec->keys);
        free(rec->timestamps);
        free(rec);
        return NULL;
    }

    pthread_mutex_init(lock, NULL);

    unsigned int* state = malloc(num_records * sizeof(unsigned int));
    if (!state) {
        perror("Failed to allocate memory for PRNG state");
        pthread_mutex_destroy(lock);
        free(lock);
        free(rec->offsets);
        free(rec->keys);
        free(rec->timestamps);
        free(rec);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        unsigned int init_state = seed + i;
        state[i] = init_state;

        rec->offsets[i] = rand_r(&state[i]);
        rec->keys[i] = rand_r(&state[i]);
        rec->timestamps[i] = (double)time(NULL);
    }

    rec->lock = lock;
    rec->num_records = num_records;
    return rec;
}

void destroy_records(record* rec) {
    pthread_mutex_lock(rec->lock);
    free(rec->offsets);
    free(rec->keys);
    free(rec->timestamps);
    pthread_mutex_unlock(rec->lock);

    pthread_mutex_destroy(rec->lock);
    free(rec->lock);
    free(rec);
}
