#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    char* buffer;
    int priority;
} Message;

typedef struct {
    Message** messages;
    size_t capacity;
    size_t size;
} MessageManager;

// Pseudo-random number generator (PRNG) function
unsigned int prng(unsigned int seed) {
    return seed * 1103515245 + 12345; // Simple linear congruential generator
}

// Initialize the message manager
void init_message_manager(MessageManager* mm) {
    mm->messages = (Message**)malloc(INITIAL_CAPACITY * sizeof(Message*));
    mm->capacity = INITIAL_CAPACITY;
    mm->size = 0;
}

// Resize the buffer for messages
void resize_buffer(MessageManager* mm, size_t new_capacity) {
    Message** temp = (Message**)realloc(mm->messages, new_capacity * sizeof(Message*));
    if (temp == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    mm->messages = temp;
    mm->capacity = new_capacity;
}

// Add a new message to the manager
void add_message(MessageManager* mm, int key, const char* buffer, int priority) {
    if (mm->size >= mm->capacity) {
        resize_buffer(mm, mm->capacity * GROWTH_FACTOR);
    }
    Message* msg = (Message*)malloc(sizeof(Message));
    msg->buffer = strdup(buffer); // Duplicate the string
    msg->priority = priority;
    mm->messages[mm->size++] = msg;
}

// Verify integrity and size of allocated memory blocks
void verify_memory_integrity(MessageManager* mm) {
    for (size_t i = 0; i < mm->size; ++i) {
        if (mm->messages[i] == NULL || mm->messages[i]->buffer == NULL) {
            fprintf(stderr, "Memory corruption detected\n");
            exit(EXIT_FAILURE);
        }
        // Optionally check buffer size and other integrity conditions
    }
}

// Clean up resources
void free_message_manager(MessageManager* mm) {
    for (size_t i = 0; i < mm->size; ++i) {
        free(mm->messages[i]->buffer);
        free(mm->messages[i]);
    }
    free(mm->messages);
}

int main() {
    srand(time(NULL)); // Seed the PRNG
    MessageManager manager;
    init_message_manager(&manager);

    add_message(&manager, 1, "Hello, World!", 5);
    add_message(&manager, 2, "This is a test.", 3);

    verify_memory_integrity(&manager);

    free_message_manager(&manager);
    return 0;
}
```

