    if (offset_array == NULL || key_array == NULL || records == NULL || count <= 0) {
        return;
    }

    *offset_array = (long*)malloc(count * sizeof(long));
    *key_array = (int*)malloc(count * sizeof(int));
    *records = (record*)malloc(count * sizeof(record));

    if (*offset_array == NULL || *key_array == NULL || *records == NULL) {
        free(*offset_array);
        free(*key_array);
        return;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        (*offset_array)[i] = rand() % 1000L;
        (*key_array)[i] = rand() % 100;
        (*records)[i].value = rand() % 1000;
        snprintf((*records)[i].id, sizeof((*records)[i].id), "ID%04d", i);
        time(&(*records)[i].timestamp);
    }
}

