// Custom memory pool implementation for record structures
typedef struct memory_pool {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t capacity) {
    pool->records = malloc(capacity * sizeof(Record));
    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
}

MemoryPool* get_record(MemoryPool* pool) {
    MemoryPool* result = malloc(sizeof(MemoryPool));
    if (result == NULL) {
        return NULL;
    }
    *result = *pool;
    result->records = &result->records[result->count++];
    return result;
}

void release_record(MemoryPool* pool, MemoryPool* record) {
    pthread_mutex_lock(&pool->lock);
    pool->records[--record->count] = *record;
    pthread_mutex_unlock(&pool->lock);
}

// Non-cryptographic PRNG for performance reasons
unsigned int prng(unsigned int seed) {
    return seed * 1103515245 + 12345;
}

void init_records(MemoryPool* pool, size_t count, unsigned int* seed) {
    if (count <= 0) {
        printf("Error: Record count must be positive.\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        MemoryPool* record = get_record(pool);
        if (record == NULL) {
            printf("Warning: Failed to allocate memory for record %zu.\n", i);
            continue;
        }
        record->records->value = prng(*seed++);
    }

    // Validate randomness using a statistical distribution
    // ...
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 10000000);

    unsigned int seed = time(NULL);
    init_records(&pool, 10000000, &seed);

    destroy_memory_pool(&pool);
    return 0;
}
