    // Allocate memory for the offset array
    *offsets = (long*)malloc(count * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the key array
    *keys = (int*)malloc(count * sizeof(int));
    if (*keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the random numbers array
    *random_numbers = (uint64_t*)malloc(count * sizeof(uint64_t));
    if (*random_numbers == NULL) {
        perror("Failed to allocate memory for random numbers");
        free(*keys);
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the transactions array
    *transactions = (Transaction*)malloc(count * sizeof(Transaction));
    if (*transactions == NULL) {
        perror("Failed to allocate memory for transactions");
        free(*random_numbers);
        free(*keys);
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize PRNG state and generate pseudo-random values
    srand(time(NULL)); // Seed the PRNG with the current time
    for (size_t i = 0; i < count; ++i) {
        (*transactions)[i].timestamp = time(NULL); // Example timestamp generation
        (*transactions)[i].key = keys[i];
        (*transactions)[i].random_number = ((uint64_t)rand() * RAND_MAX + rand()) % UINT64_MAX;
    }
}

// Function to free allocated memory
void free_memory(long* offsets, int* keys, uint64_t* random_numbers, Transaction* transactions) {
