#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>

typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    uint64_t random_number;
} RandomNumber;

typedef struct {
    double transaction_amount;
} TransactionAmount;

typedef struct {
    int timestamp;
    int key;
    uint64_t random_number;
    double transaction_amount;
} Transaction;

typedef struct {
    Offset* offsets;
    Key* keys;
    RandomNumber* random_numbers;
    TransactionAmount* transaction_amounts;
    Transaction* transactions;
    size_t capacity;
    size_t size;
} TransactionManager;

void initialize_transaction_manager(TransactionManager* manager, size_t initial_capacity) {
    manager->offsets = (Offset*)malloc(initial_capacity * sizeof(Offset));
    manager->keys = (Key*)malloc(initial_capacity * sizeof(Key));
    manager->random_numbers = (RandomNumber*)malloc(initial_capacity * sizeof(RandomNumber));
    manager->transaction_amounts = (TransactionAmount*)malloc(initial_capacity * sizeof(TransactionAmount));
    manager->transactions = (Transaction*)malloc(initial_capacity * sizeof(Transaction));
    manager->capacity = initial_capacity;
    manager->size = 0;
}

void free_transaction_manager(TransactionManager* manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->random_numbers);
    free(manager->transaction_amounts);
    free(manager->transactions);
}

void generate_random_number(RandomNumber* rn, uint64_t min, uint64_t max) {
    // Use a non-cryptographically secure PRNG with entropy from time and random device
    srand(time(NULL) ^ getpid());
    rn->random_number = (uint64_t)(min + rand() % (max - min + 1));
}

void add_transaction(TransactionManager* manager, int timestamp, int key, double transaction_amount) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->offsets = (Offset*)realloc(manager->offsets, new_capacity * sizeof(Offset));
        manager->keys = (Key*)realloc(manager->keys, new_capacity * sizeof(Key));
        manager->random_numbers = (RandomNumber*)realloc(manager->random_numbers, new_capacity * sizeof(RandomNumber));
        manager->transaction_amounts = (TransactionAmount*)realloc(manager->transaction_amounts, new_capacity * sizeof(TransactionAmount));
        manager->transactions = (Transaction*)realloc(manager->transactions, new_capacity * sizeof(Transaction));
        manager->capacity = new_capacity;
    }

    Transaction* transaction = &manager->transactions[manager->size];
    transaction->timestamp = timestamp;
    transaction->key = key;
    generate_random_number(&transaction->random_number, 1000000000ULL, 9999999999ULL);
    transaction->transaction_amount = transaction_amount;

    manager->offsets[manager->size].offset = (long)(manager->size * sizeof(Transaction));
    manager->keys[manager->size].key = key;
    manager->transaction_amounts[manager->size].transaction_amount = transaction_amount;

    manager->size++;
}

int main() {
    TransactionManager manager;
    initialize_transaction_manager(&manager, 1024);

    add_transaction(&manager, time(NULL), 12345, 100.75);
    add_transaction(&manager, time(NULL) + 1, 67890, 250.50);

    free_transaction_manager(&manager);

    return 0;
}
