#include "logger.h"

typedef struct {
    time_t timestamp;
    int statusCode;
    float sensorReading;
} sensorRecord;

sensorRecord* allocateSensorRecords(size_t count, int minReading, int maxReading) {
    if (count == 0 || minReading > maxReading) {
        logError("Invalid input parameters.");
        return NULL;
    }

    sensorRecord* records = malloc(count * sizeof(sensorRecord));
    if (records == NULL) {
        logMemoryAllocationWarning();
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < count; ++i) {
        records[i].timestamp = time(NULL);
        records[i].statusCode = rand() % 100 + 1; // Simulate status code
        records[i].sensorReading = ((float)(rand()) / RAND_MAX) * (maxReading - minReading) + minReading;
    }

    logInfo("Sensor records allocated successfully.");
    return records;
}

void freeSensorRecords(sensorRecord* records, size_t count) {
    if (records != NULL) {
        free(records);
        logInfo("Sensor records freed successfully.");
    } else {
        logError("Attempted to free null sensor record pointer.");
    }
}
