void find_max_integer(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Array is empty.\n");
        return;
    }

    int max_value = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    printf("Largest integer in the array: %d\n", max_value);
}

