void* readInputList(void* arg) {
    int** list = (int**)arg;
    char buffer[256];
    if (fgets(buffer, sizeof(buffer), stdin)) {
        *list = (int*)malloc((strlen(buffer) / 3 + 1) * sizeof(int));
        int count = 0, num;
        sscanf(buffer, "%d %d %d", &num, list[0]++, &num);
        while (sscanf(buffer + strlen(buffer) - 2, " %d", &num) == 1) {
            list[0][count++] = num;
        }
    } else {
        *list = NULL;
    }
    return NULL;
}

int find(union find* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void unionFind(union find* uf, int x, int y) {
    int rootX = find(uf, x), rootY = find(uf, y);
    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootX].parent = rootY;
            uf[rootY].rank++;
        }
    }
}

