// Function to allocate memory and initialize arrays with random values
void allocateAndInitialize(int numRecords, long *offsets, int *keys, record **records) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for offsets and keys arrays
    offsets = (long *)malloc(numRecords * sizeof(long));
    if (offsets == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    keys = (int *)malloc(numRecords * sizeof(int));
    if (keys == NULL) {
        // Free previously allocated memory and handle failure
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return;
    }

    // Allocate memory for records array
    *records = (record *)malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        // Free previously allocated memory and handle failure
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return;
    }

    // Initialize arrays with random values
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand(); // Using rand() for simplicity
        keys[i] = rand();
        (*records)[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }
}

// Example usage
int main() {
    int numRecords = 5;
    long *offsets;
    int *keys;
    record *records;

    allocateAndInitialize(numRecords, offsets, keys, &records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
