#define MAX_RECORDS 1000

bool initialize_arrays(const char *json_str, long **offsets, int **keys) {
    json_object *parsed_json;
    json_object *access_token, *expires_in, *token_type, *refresh_token = NULL;

    parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        return false;
    }

    json_object_object_get_ex(parsed_json, "access_token", &access_token);
    json_object_object_get_ex(parsed_json, "expires_in", &expires_in);
    json_object_object_get_ex(parsed_json, "token_type", &token_type);

    if (!json_object_is_type(access_token, json_type_string) ||
        !json_object_is_type(expires_in, json_type_int) ||
        !json_object_is_type(token_type, json_type_string)) {
        json_object_put(parsed_json);
        return false;
    }

    const char *token_type_str = json_object_get_string(token_type);
    int expires_in_val = json_object_get_int(expires_in);

    if (strcmp(token_type_str, "Bearer") != 0 || expires_in_val <= 0) {
        json_object_put(parsed_json);
        return false;
    }

    json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    if (!*offsets) {
        json_object_put(parsed_json);
        return false;
    }

    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    if (!*keys) {
        free(*offsets);
        json_object_put(parsed_json);
        return false;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        (*offsets)[i] = rand() % 1000000L; // Example offset calculation
        if (!RAND_bytes((unsigned char *)&(*keys)[i], sizeof(int))) {
            free(*offsets);
            free(*keys);
            json_object_put(parsed_json);
            return false;
        }
    }

    json_object_put(parsed_json);
    return true;
}

int main() {
    const char *json_str = "{\"access_token\":\"token123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    long *offsets;
    int *keys;

    if (initialize_arrays(json_str, &offsets, &keys)) {
        // Use offsets and keys
        free(offsets);
        free(keys);
    } else {
        // Handle error
    }

    return 0;
}
