#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MIN_KEY 10
#define MAX_KEY 100

typedef struct {
    long offset;
    int key;
    double probability;
} record;

record* allocate_records(int n, int seed) {
    record* arr = (record*)malloc(n * sizeof(record));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed);
    double total_probability = 0.0;
    for (int i = 0; i < n - 1; ++i) {
        arr[i].key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY + 1);
        arr[i].probability = ((double)rand() / RAND_MAX);
        total_probability += arr[i].probability;
    }

    // Normalize the last probability to ensure sum is exactly 1.0
    arr[n - 1].key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY + 1);
    arr[n - 1].probability = 1.0 - total_probability;

    return arr;
}

void log_init(int n, int seed) {
    printf("Initializing records with %d elements and seed %d\n", n, seed);
}

int read_integers(int* arr, int max_size) {
    int count = 0;
    while (scanf("%d", &arr[count]) == 1 && count < max_size) {
        ++count;
    }
    return count;
}

void find_and_print_largest(const int* arr, int size) {
    if (size > 0) {
        int largest = arr[0];
        for (int i = 1; i < size; ++i) {
            if (arr[i] > largest) {
                largest = arr[i];
            }
        }
        printf("Largest integer: %d\n", largest);
    } else {
        printf("No integers read.\n");
    }
}

void save_records(const record* arr, int n, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(arr, sizeof(record), n, file);
    fclose(file);
}

int load_records(record** arr, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return 0;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(record);
    fseek(file, 0, SEEK_SET);

    *arr = (record*)malloc(*size * sizeof(record));
    if (!*arr) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return 0;
    }

    size_t read_count = fread(*arr, sizeof(record), *size, file);
    fclose(file);

    if (read_count != *size) {
        fprintf(stderr, "Failed to read all records from file\n");
        free(*arr);
        *arr = NULL;
        *size = 0;
    }

    return 1;
}

int main() {
    int n, seed;
    printf("Enter the number of records and seed: ");
    scanf("%d %d", &n, &seed);

    log_init(n, seed);
    record* arr = allocate_records(n, seed);
    if (arr) {
        int integers[MAX_SIZE];
        int count = read_integers(integers, MAX_SIZE);
        find_and_print_largest(integers, count);

        save_records(arr, n, "records.dat");

        record* loaded_arr;
        int loaded_size;
        if (load_records(&loaded_arr, &loaded_size, "records.dat")) {
            // Process loaded records
            free(loaded_arr);
        }

        free(arr);
    }

    return 0;
}
