#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1024
#define RANDOM_STRING_LEN 64

typedef struct {
    int value;
    char buffer[RANDOM_STRING_LEN];
} record;

record records[MAX_RECORDS];

long offsets[MAX_RECORDS];
int keys[MAX_RECORDS];

pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t offsets_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long xorshift128plus() {
    static unsigned long s[4] = {0x68d39150, 0x2a19b8c7, 0xe3e70241, 0x8755f4ac};
    unsigned long t = s[3];
    unsigned long const r = t * 2654435769U;
    s[3] = s[2]; s[2] = s[1]; s[1] = s[0];
    s[0] = (s[0] ^ (t >> 18)) + r;
    return s[0] + (r << 9);
}

void generate_random_string(char *buf, size_t len) {
    for (size_t i = 0; i < len - 1; ++i) {
        buf[i] = 'a' + xorshift128plus() % ('z' - 'a' + 1);
    }
    buf[len - 1] = '\0';
}

void initialize_records(size_t num_records, int range_start, int range_end) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        return;
    }

    pthread_mutex_lock(&records_mutex);
    pthread_mutex_lock(&offsets_mutex);
    pthread_mutex_lock(&keys_mutex);

    for (size_t i = 0; i < num_records; ++i) {
        int random_value = range_start + xorshift128plus() % (range_end - range_start + 1);
        records[i].value = random_value;
        generate_random_string(records[i].buffer, RANDOM_STRING_LEN);

        offsets[i] = rand();
        keys[i] = i;
    }

    pthread_mutex_unlock(&records_mutex);
    pthread_mutex_unlock(&offsets_mutex);
    pthread_mutex_unlock(&keys_mutex);
}

int main() {
    srand(time(NULL));
    initialize_records(10, 0, 100);
    return 0;
}
```

