#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1000

typedef struct {
    long timestamp;
    int event_id;
    char message[256];
} log_entry;

typedef struct {
    pthread_mutex_t mutex;
    log_entry logs[MAX_LOG_SIZE];
    int count;
} logging_system;

void initialize_logging_system(logging_system *sys) {
    if (pthread_mutex_init(&sys->mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        exit(EXIT_FAILURE);
    }
    memset(sys->logs, 0, sizeof(sys->logs));
    sys->count = 0;
}

void add_log_entry(logging_system *sys, long timestamp, int event_id, const char *message) {
    pthread_mutex_lock(&sys->mutex);
    if (sys->count < MAX_LOG_SIZE) {
        sys->logs[sys->count].timestamp = timestamp;
        sys->logs[sys->count].event_id = event_id;
        strncpy(sys->logs[sys->count].message, message, sizeof(sys->logs[sys->count].message) - 1);
        sys->count++;
    } else {
        printf("Log buffer full, dropping new entry.\n");
    }
    pthread_mutex_unlock(&sys->mutex);
}

void* log_task(void *arg) {
    logging_system *sys = (logging_system*) arg;
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        long timestamp = time(NULL);
        int event_id = rand() % 100;
        char message[256];
        snprintf(message, sizeof(message), "Event %d at %ld", event_id, timestamp);
        add_log_entry(sys, timestamp, event_id, message);
    }
    return NULL;
}

void read_integers_from_input(int *array, int *count) {
    printf("Enter integers (end with -1):\n");
    while (*count < MAX_LOG_SIZE) {
        scanf("%d", &array[*count]);
        if (array[*count] == -1) break;
        (*count)++;
    }
}

void print_largest_integer(int array[], int count) {
    if (count > 0) {
        int largest = array[0];
        for (int i = 1; i < count; i++) {
            if (array[i] > largest) {
                largest = array[i];
            }
        }
        printf("Largest integer: %d\n", largest);
    } else {
        printf("No integers entered.\n");
    }
}

int main() {
    logging_system sys;
    initialize_logging_system(&sys);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, log_task, &sys) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    int integers[MAX_LOG_SIZE];
    int count = 0;
    read_integers_from_input(integers, &count);
    print_largest_integer(integers, count);

    pthread_mutex_destroy(&sys.mutex);
    return 0;
}
