#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for record collection.\n");
        exit(EXIT_FAILURE);
    }
    collection->head = NULL;
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(collection);
}

Node* create_node(int key, long offset) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for record node.\n");
        exit(EXIT_FAILURE);
    }
    node->data.key = key;
    node->data.offset = offset;
    node->next = NULL;
    return node;
}

void insert_record(RecordCollection* collection, int key, long offset) {
    Node* new_node = create_node(key, offset);
    if (collection->head == NULL) {
        collection->head = new_node;
    } else {
        Node* current = collection->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

Record* retrieve_record(RecordCollection* collection, int key) {
    Node* current = collection->head;
    while (current) {
        if (current->data.key == key) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void remove_record(RecordCollection* collection, int key) {
    Node* current = collection->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                collection->head = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

int main() {
    srand(time(NULL)); // Seed the PRNG with the current time for non-deterministic behavior
    RecordCollection* collection = create_record_collection();

    insert_record(collection, 1, rand());
    insert_record(collection, 2, rand());
    insert_record(collection, 3, rand());

    Record* record = retrieve_record(collection, 2);
    if (record) {
        printf("Record found: Key=%d, Offset=%ld\n", record->key, record->offset);
    }

    remove_record(collection, 1);

    destroy_record_collection(collection);

    return 0;
}
```

