    char buffer[256];
} Data;

typedef struct {
    long *offsets;
    int *keys;
    Data *data;
    size_t capacity;
    size_t count;
    unsigned long seed;
    int use_high_quality_prng;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity, int use_high_quality_prng) {
    ArrayManager *manager = malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->data = malloc(initial_capacity * sizeof(Data));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->seed = time(NULL);
    manager->use_high_quality_prng = use_high_quality_prng;

    if (!manager->offsets || !manager->keys || !manager->data) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->data);
        free(manager);
        return NULL;
    }

    srand(manager->seed);

    return manager;
}

void destroy_array_manager(ArrayManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->data);
    free(manager);
}

void reset_prng_state(ArrayManager *manager, unsigned long new_seed) {
    manager->seed = new_seed;
    srand(new_seed);
}

void add_element(ArrayManager *manager, int key, const char *value) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));
        Data *new_data = realloc(manager->data, new_capacity * sizeof(Data));

        if (!new_offsets || !new_keys || !new_data) {
            return;
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->data = new_data;
        manager->capacity = new_capacity;
    }

    manager->keys[manager->count] = key;
    snprintf(manager->data[manager->count].buffer, sizeof(manager->data[manager->count].buffer), "%s", value);
    manager->data[manager->count].value = rand() % 100; // Example range
    manager->count++;
}
