#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>

#define MAX_RECORDS 1000

typedef struct {
    int id;
    int value;
} Record;

typedef struct {
    int* offsets;
    int* keys;
    Record** records;
    int size;
    int* parent;
    int* rank;
} DisjointSet;

DisjointSet* create_disjoint_set(int n) {
    DisjointSet* ds = (DisjointSet*)malloc(sizeof(DisjointSet));
    if (!ds) return NULL;

    ds->offsets = (int*)malloc(n * sizeof(int));
    ds->keys = (int*)malloc(n * sizeof(int));
    ds->records = (Record**)malloc(n * sizeof(Record*));
    ds->parent = (int*)malloc(n * sizeof(int));
    ds->rank = (int*)malloc(n * sizeof(int));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->parent || !ds->rank) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->parent);
        free(ds->rank);
        free(ds);
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        ds->offsets[i] = 0;
        ds->keys[i] = rand() % n; // Initialize with random keys
        ds->records[i] = (Record*)malloc(sizeof(Record));
        ds->records[i]->id = i;
        ds->records[i]->value = rand() % 100; // Random value within range
        ds->parent[i] = i;
        ds->rank[i] = 0;
    }

    return ds;
}

int find(int x, DisjointSet* ds) {
    if (ds->parent[x] != x)
        ds->parent[x] = find(ds->parent[x], ds);
    return ds->parent[x];
}

void union_sets(int x, int y, DisjointSet* ds) {
    int rootX = find(x, ds);
    int rootY = find(y, ds);

    if (rootX != rootY) {
        if (ds->rank[rootX] > ds->rank[rootY])
            ds->parent[rootY] = rootX;
        else if (ds->rank[rootX] < ds->rank[rootY])
            ds->parent[rootX] = rootY;
        else {
            ds->parent[rootY] = rootX;
            ds->rank[rootX]++;
        }
    }
}

int count_disjoint_pairs(DisjointSet* ds) {
    int count = 0;
    for (int i = 0; i < ds->size - 1; i++) {
        if (find(i, ds) != find(i + 1, ds)) {
            count++;
            union_sets(i, i + 1, ds);
        }
    }
    return count;
}

void free_disjoint_set(DisjointSet* ds) {
    for (int i = 0; i < ds->size; i++) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->parent);
    free(ds->rank);
    free(ds);
}

int main() {
    srand(time(NULL));

    DisjointSet* ds = create_disjoint_set(MAX_RECORDS);
    if (!ds) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    clock_t start_time = clock();
    int disjoint_pairs_count = count_disjoint_pairs(ds);
    clock_t end_time = clock();

    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC * 1000;

    printf("Disjoint pairs count: %d\n", disjoint_pairs_count);
    printf("Time taken for operations: %.2f ms\n", time_taken);

    free_disjoint_set(ds);

    return 0;
}
