typedef struct {
    long timestamp;
    int ID;
    float amount;
} transaction;

void log_message(const char *message) {
    printf("%s\n", message);
}

long **allocate_timestamp_array(size_t size, const char **error_msg) {
    long **array = (long **)malloc(size * sizeof(long *));
    if (!array) {
        *error_msg = "Failed to allocate memory for timestamp array";
        return NULL;
    }
    return array;
}

int **allocate_id_array(size_t size, const char **error_msg) {
    int **array = (int **)malloc(size * sizeof(int *));
    if (!array) {
        *error_msg = "Failed to allocate memory for ID array";
        return NULL;
    }
    return array;
}

transaction **allocate_transaction_array(size_t size, const char **error_msg) {
    transaction **array = (transaction **)malloc(size * sizeof(transaction *));
    if (!array) {
        *error_msg = "Failed to allocate memory for transaction array";
        return NULL;
    }
    return array;
}

void initialize_transactions(transaction **transactions, size_t size, long start_timestamp, long end_timestamp, int min_id, int max_id, float min_amount, float max_amount) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        transactions[i] = (transaction *)malloc(sizeof(transaction));
        if (!transactions[i]) {
            log_message("Failed to allocate memory for transaction");
            return;
        }
        transactions[i]->timestamp = start_timestamp + rand() % (end_timestamp - start_timestamp);
        transactions[i]->ID = min_id + rand() % (max_id - min_id);
        transactions[i]->amount = min_amount + ((float)rand() / RAND_MAX) * (max_amount - min_amount);
    }
}

void free_transactions(transaction **transactions, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (transactions[i]) {
            free(transactions[i]);
        }
    }
    free(transactions);
}

float calculate_average_transaction_amount(transaction **transactions, size_t size) {
    float sum = 0.0;
    for (size_t i = 0; i < size; ++i) {
        sum += transactions[i]->amount;
    }
    return size > 0 ? sum / size : 0.0;
}

int main() {
    size_t num_transactions = 1000000; // Example size
    long start_timestamp = 1633072800L;
    long end_timestamp = 1633159200L;
    int min_id = 100;
    int max_id = 999;
    float min_amount = 1.0f;
    float max_amount = 1000.0f;

    const char *error_msg = NULL;
    long **timestamps = allocate_timestamp_array(num_transactions, &error_msg);
    if (error_msg) {
        log_message(error_msg);
        return 1;
    }
    int **ids = allocate_id_array(num_transactions, &error_msg);
    if (error_msg) {
        log_message(error_msg);
        free(timestamps);
        return 1;
    }
    transaction **transactions = allocate_transaction_array(num_transactions, &error_msg);
    if (error_msg) {
        log_message(error_msg);
        free(timestamps);
        free(ids);
        return 1;
    }

    initialize_transactions(transactions, num_transactions, start_timestamp, end_timestamp, min_id, max_id, min_amount, max_amount);

    float average_amount = calculate_average_transaction_amount(transactions, num_transactions);
    printf("Average transaction amount: %.2f\n", average_amount);

    free_transactions(transactions, num_transactions);
    free(timestamps);
    free(ids);

    return 0;
}
