typedef struct {
    char* field;
} record;

long generate_random_offset(int max) {
    return rand() % (max + 1);
}

int generate_random_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_records(long** offsets, int** keys, record** records, int size, PRNG prng, const char* charSet, int minLength, int maxLength) {
    if (size <= 0 || minLength < 0 || maxLength > 10 || strlen(charSet) == 0 || minLength > maxLength) {
        return;
    }

    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *records = malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        free(*offsets);
        free(*keys);
        free(*records);
        return;
    }

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = generate_random_offset(maxLength);
        (*keys)[i] = generate_random_key(minLength, maxLength);

        int fieldLength = prng() % (maxLength - minLength + 1) + minLength;
        (*records)[i].field = malloc((fieldLength + 1) * sizeof(char));
        if ((*records)[i].field == NULL) {
            // Handle memory allocation failure for record field
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++) {
                free((*records)[j].field);
            }
            free(*records);
            return;
        }

        for (int j = 0; j < fieldLength; j++) {
            (*records)[i].field[j] = charSet[prng() % strlen(charSet)];
        }
        (*records)[i].field[fieldLength] = '\0';
    }
}

void free_records(long* offsets, int* keys, record* records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i].field != NULL) {
            free(records[i].field);
        }
    }
    free(offsets);
    free(keys);
    free(records);
}

