        records[i].data[0] = '\0';
        for (int j = 0; j < length; ++j) {
            int index = prng() % strlen(charSet);
            strncat(records[i].data, &charSet[index], 1);
        }
    }

    pthread_mutex_destroy(&mutex);
    return records;
