public class EventLogFramework
{
    private ConcurrentQueue<Event> _eventQueue = new ConcurrentQueue<Event>();
    private Random _randomGenerator = new Random();
    private int _logSize = 1024; // Initial log size
    private readonly object _lock = new object();

    public void StartLogging()
    {
        var timer = new Timer(LogEvent, null, TimeSpan.Zero, TimeSpan.FromSeconds(1));
    }

    private void LogEvent(object state)
    {
        Event eventToLog = new Event
        {
            Timestamp = DateTime.Now,
            UniqueId = Guid.NewGuid(),
            EventCode = _randomGenerator.Next(1000, 9999) // Simulating random event codes
        };

        if (_eventQueue.Count >= _logSize)
        {
            ResizeLog();
        }

        _eventQueue.Enqueue(eventToLog);
    }

    private void ResizeLog()
    {
        lock (_lock)
        {
            if (_eventQueue.Count < _logSize * 2) // Double the log size if it's less than twice the current size
            {
                return;
            }

            _logSize *= 2;

            // Implement logic to optimize memory usage and cache utilization here
        }
    }

    public void ProcessEvents()
    {
        while (_eventQueue.TryDequeue(out Event eventToProcess))
        {
            // Process the event (e.g., log it, store it in a database)
        }
    }

    public void MonitorPerformance()
    {
        lock (_lock)
        {
            Console.WriteLine($"Current log size: {_logSize}");
            Console.WriteLine($"Event queue count: {_eventQueue.Count}");
        }
    }
}

public class Event
{
    public DateTime Timestamp { get; set; }
    public Guid UniqueId { get; set; }
    public int EventCode { get; set; }
}
