    // Simplified Union-Find implementation
    int* parent = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; ++i) {
        parent[i] = i;
    }
    for (int i = 1; i < size; ++i) {
        if (array[i - 1] == array[i]) {
            int x = i - 1, y = i;
            while (x != parent[x]) x = parent[x];
            while (y != parent[y]) y = parent[y];
            parent[x] = y;
