#include <stdlib.h>
#include <time.h>
#include <stdio.h>

typedef struct {
    int value;
} record;

typedef struct union_find_node {
    int parent;
    int rank;
} union_find_node;

void init_arrays(long** offsets, int** keys, record** records, union_find_node** nodes, size_t size) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));
    *nodes = (union_find_node*)malloc(size * sizeof(union_find_node));

    if (!*offsets || !*keys || !*records || !*nodes) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = rand() % 1000; // Random value in the range [0, 999]
        (*nodes)[i].parent = i;
        (*nodes)[i].rank = 0;
    }
}

void free_arrays(long* offsets, int* keys, record* records, union_find_node* nodes) {
    free(offsets);
    free(keys);
    free(records);
    free(nodes);
}

int find(union_find_node* nodes, int x) {
    if (nodes[x].parent != x)
        nodes[x].parent = find(nodes, nodes[x].parent);
    return nodes[x].parent;
}

void union_sets(union_find_node* nodes, int x, int y) {
    int rootX = find(nodes, x);
    int rootY = find(nodes, y);

    if (rootX != rootY) {
        if (nodes[rootX].rank < nodes[rootY].rank)
            nodes[rootX].parent = rootY;
        else if (nodes[rootX].rank > nodes[rootY].rank)
            nodes[rootY].parent = rootX;
        else {
            nodes[rootY].parent = rootX;
            nodes[rootX].rank++;
        }
    }
}

int main() {
    size_t size = 1000; // Example size
    long* offsets;
    int* keys;
    record* records;
    union_find_node* nodes;

    init_arrays(&offsets, &keys, &records, &nodes, size);

    for (size_t i = 0; i < size - 1; ++i) {
        union_sets(nodes, keys[i], keys[i + 1]);
    }

    free_arrays(offsets, keys, records, nodes);

    return 0;
}
