#include <stdlib.h>
#include <time.h>

typedef struct {
    long value;
    char status;
} record;

long customPRNG(long seed) {
    return (seed * 214013 + 2531011) & 0xFFFFFFFFL;
}

void initializeArrays(long *offsets, int *keys, record *records, size_t count, long seed, time_t timeout) {
    clock_t start = clock();
    long prngSeed = seed;

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = customPRNG(prngSeed);
        keys[i] = (int)(customPRNG(prngSeed) % INT_MAX);

        record *currentRecord = &records[i];
        currentRecord->value = customPRNG(prngSeed) % 1000L;
        currentRecord->status = (char)(customPRNG(prngSeed) % 26 + 'A');

        prngSeed = customPRNG(prngSeed);

        if ((clock() - start) / CLOCKS_PER_SEC > timeout) {
            // Fallback mechanism to another PRNG
            prngSeed = seed;
        }
    }

    // Memory allocation check
    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Reset PRNG state for testing
    void resetPRNG() {
        prngSeed = seed;
    }
}
