    record* records = (record*)calloc(size, sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for record array\n");
    }
    return records;
}

void initialize_records(record* records, int count, int min_value, int max_value) {
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < count; ++i) {
        int random_value;
        do {
            random_value = rand() % (max_value - min_value + 1) + min_value;
        } while (!is_valid_random_value(random_value, min_value, max_value));
        records[i].value = random_value;
    }
}

int is_valid_random_value(int value, int min_value, int max_value) {
    return value >= min_value && value <= max_value;
}

void find_and_print_largest(const int* array, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer in the array: %d\n", largest);
}

void free_memory(long* offset, int* keys, record* records, int count) {
    free(offset);
    free(keys);
    free(records);
}

