void initializeRecords(record* records, size_t count, int minVal, int maxVal) {
    srand(time(NULL)); // Seed the PRNG
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
        records[i].str = NULL;
        records[i].length = 0;
    }
}

void initializeString(record* record, const char* str) {
    record->str = strdup(str);
    record->length = strlen(str);
}

int findLargestInt(const int* array, size_t count) {
    if (count == 0) return INT_MIN;
    int maxVal = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > maxVal) maxVal = array[i];
    }
    return maxVal;
}

const char* findLongestString(const record* records, size_t count) {
    if (count == 0) return NULL;
    const char* longestStr = records[0].str;
    for (size_t i = 1; i < count; ++i) {
        if (records[i].length > strlen(longestStr)) longestStr = records[i].str;
    }
    return longestStr;
}

void freeRecords(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].str);
