Record* create_records(int size, int min_value, int max_value) {
    if (size <= 0 || min_value > max_value) {
        return NULL;
    }

    Record* records = malloc(size * sizeof(Record));
    if (!records) {
        return NULL; // Handle out-of-memory condition
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; ++i) {
        records[i].key = i;
        records[i].offset = rand() % 1000000L; // Example offset generation
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    return records;
}

void free_records(Record* records, int size) {
    if (records) {
        free(records);
    }
}

// Example usage
int main() {
    int num_records = 1000;
    int min_val = 1;
    int max_val = 100;

    Record* records = create_records(num_records, min_val, max_val);
    if (records) {
        // Use the records
        free_records(records, num_records);
    }

    return 0;
}
