#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include "libwebsockets.h"

#define MAX_NODES 1000
#define MAX_RECORDS 1000

typedef struct {
    float value;
} record;

int union_find[MAX_NODES];
int union_size[MAX_NODES];

void init_union_find(int n) {
    for (int i = 0; i < n; i++) {
        union_find[i] = i;
        union_size[i] = 1;
    }
}

int find(int x) {
    if (union_find[x] != x)
        union_find[x] = find(union_find[x]);
    return union_find[x];
}

void union_sets(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);

    if (rootX != rootY) {
        if (union_size[rootX] > union_size[rootY]) {
            union_find[rootY] = rootX;
            union_size[rootX] += union_size[rootY];
        } else {
            union_find[rootX] = rootY;
            union_size[rootY] += union_size[rootX];
        }
    }
}

double calculate_average(float *numbers, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++)
        sum += numbers[i];
    return sum / size;
}

void log_message(const char *message) {
    printf("%s\n", message);
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int *keys = (int *)malloc(n * sizeof(int));
    record *records = (record *)malloc(m * sizeof(record));

    if (!keys || !records) {
        log_message("Memory allocation failed");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        records[i].value = ((float)(rand() % 100)) / 10.0f;
    }

    init_union_find(n);

    float *numbers = (float *)malloc(m * sizeof(float));
    if (!numbers) {
        log_message("Memory allocation failed");
        free(keys);
        free(records);
        return 1;
    }

    for (int i = 0; i < m; i++) {
        scanf("%f", &numbers[i]);
        union_sets(i % n, numbers[i] > 50 ? (i + 1) % n : i % n);
    }

    double average = calculate_average(numbers, m);

    log_message("Average: %.2f\n", average);

    free(keys);
    free(records);
    free(numbers);

    return 0;
}
