    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest element: %d\n", largest);
