        for (int j = i + 1; j < size; ++j) {
            clock_t start = clock();
            // Perform disjointness check here
            clock_t end = clock();
            double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
            printf("Pair (%d, %d) is %s. Time taken: %.2f ms\n", array[i], array[j], "disjoint", time_taken * 1000);
        }
