#define MAX_TRANSACTION_TYPE 10
#define MAX_TRANSACTION_AMOUNT 9223372036854775807L

typedef struct {
    char type[MAX_TRANSACTION_TYPE];
    long amount;
} transaction;

long generate_random_amount() {
    return rand() % (MAX_TRANSACTION_AMOUNT + 1);
}

transaction* allocate_transactions(int num_transactions, int* error_code) {
    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (!transactions) {
        *error_code = -1;
        return NULL;
    }

    for (int i = 0; i < num_transactions; i++) {
        strcpy(transactions[i].type, "DEBIT"); // Simplified type assignment
        transactions[i].amount = generate_random_amount();
    }

    *error_code = 0;
    return transactions;
}

void log_event(const char* message) {
    printf("LOG: %s\n", message);
}

int read_transactions_from_file(transaction** transactions, const char* filename, int* error_code) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        *error_code = -1;
        return 0;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int num_transactions = (int)(file_size / sizeof(transaction));
    *transactions = allocate_transactions(num_transactions, error_code);
    if (*error_code != 0) {
        fclose(file);
        return 0;
    }

    fread(*transactions, sizeof(transaction), num_transactions, file);
    fclose(file);
    return num_transactions;
}

void compute_total_amount(transaction* transactions, int num_transactions) {
    long total_amount = 0;
    for (int i = 0; i < num_transactions; i++) {
        total_amount += transactions[i].amount;
    }
    printf("Total transaction amount: %ld\n", total_amount);
}

int main() {
    srand(time(0));

    int error_code = 0;
    transaction* transactions;
    int num_transactions = read_transactions_from_file(&transactions, "transactions.txt", &error_code);
    if (num_transactions <= 0) {
        log_event("Error reading transactions from file.");
        return -1;
    }

    compute_total_amount(transactions, num_transactions);

    free(transactions);
    return 0;
}
