        records[i].value = rand() % INT_MAX;
        if (records[i].value == INT_MIN) {
            log_message("Warning: Pseudo-random number is at the minimum limit");
        }
    }

    return records;
}

void free_record_array(record* records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        // No need to clean up individual record values as they are primitive types
    }
    free(records);
}

int find_largest_integer(const int* array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    size_t size = 1000000; // Example size
    long* offsets = allocate_offset_array(size);
    int* keys = allocate_key_array(size);
    record* records = allocate_record_array(size, stdout);

    int input_size;
    scanf("%d", &input_size);
    if (input_size > size) {
        log_message("Error: Input size exceeds array capacity");
        free_record_array(records, size);
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    int* input_array = (int*)malloc(input_size * sizeof(int));
    for (size_t i = 0; i < input_size; ++i) {
        scanf("%d", &input_array[i]);
    }

    int largest = find_largest_integer(input_array, input_size);
    printf("Largest integer: %d\n", largest);

    free(input_array);
    free_record_array(records, size);
    free(keys);
    free(offsets);

    return EXIT_SUCCESS;
}
