Record* allocate_records(int num_records, int seed, int range_start, int range_end) {
    if (num_records <= 0 || range_start > range_end) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand(seed);
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return records;
}

void free_records(Record* records, int num_records) {
    if (!records || num_records <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    free(records);
}
