#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 100

typedef struct {
    int value;
} Record;

unsigned long xorshift(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return *state = x;
}

void reseed_prng(unsigned long *state, int input) {
    *state += (unsigned long)time(NULL) + (unsigned long)input;
}

int generate_unique_value(int range, unsigned long *prng_state, Record *records, int *record_count) {
    while (*record_count < ARRAY_SIZE) {
        unsigned long value = xorshift(prng_state);
        if (value >= 0 && value < range) {
            int found = 0;
            for (int i = 0; i < *record_count; i++) {
                if (records[i].value == value) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                records[*record_count].value = value;
                (*record_count)++;
                return value;
            }
        }
    }
    return -1; // Error: No unique value available
}

void manage_memory(long **offsets, int **keys, Record **records) {
    *offsets = (long *)malloc(ARRAY_SIZE * sizeof(long));
    *keys = (int *)malloc(ARRAY_SIZE * sizeof(int));
    *records = (Record *)malloc(ARRAY_SIZE * sizeof(Record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    unsigned long prng_state = time(NULL);
    int record_count = 0;

    for (int i = 0; i < ARRAY_SIZE; i++) {
        reseed_prng(&prng_state, rand());
        int key = generate_unique_value(1000, &prng_state, *records, &record_count);
        if (key == -1) break;
        (*offsets)[i] = rand() % 1000000L; // Example offset
        (*keys)[i] = key;
    }

    printf("Generated %d unique records\n", record_count);
}

int main() {
    long *offsets;
    int *keys;
    Record *records;

    manage_memory(&offsets, &keys, &records);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
