#include <stdlib.h>
#include <stdint.h>

#define MAX_THRESHOLD (1024 * 1024) // Maximum threshold of 1MB

typedef struct {
    int value;
} record;

long* offsets;
int* keys;
record* records;
size_t capacity;
size_t size;

uint32_t xorshift(uint32_t *state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

void init_arrays(size_t initial_capacity, size_t max_threshold) {
    size_t total_size = sizeof(long) + sizeof(int) + initial_capacity * sizeof(record);
    if (total_size > max_threshold) {
        fprintf(stderr, "Exceeded maximum threshold\n");
        exit(EXIT_FAILURE);
    }

    offsets = malloc(sizeof(long));
    keys = (int*)(offsets + 1);
    records = (record*)(keys + capacity);

    capacity = initial_capacity;
    size = 0;

    *offsets = 0;
}

void resize_records(size_t new_capacity) {
    record* new_records = realloc(records, new_capacity * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    records = new_records;
    capacity = new_capacity;
}

int generate_random(uint32_t *state, int min, int max) {
    return (xorshift(state) % (max - min + 1)) + min;
}

void set_records_random(int min, int max, uint32_t *state) {
    while (size < capacity) {
        records[size].value = generate_random(state, min, max);
        size++;
    }

    if (size == capacity) {
        resize_records(capacity * 2);
        set_records_random(min, max, state);
    }
}

void free_arrays() {
    free(records - size);
}

int main() {
    uint32_t prng_state = 12345;
    init_arrays(100, MAX_THRESHOLD);
    set_records_random(1, 1000, &prng_state);
    free_arrays();
    return 0;
}
