#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} memory_pool;

void init_memory_pool(memory_pool *pool, size_t initial_capacity) {
    pool->offsets = (long *)malloc(initial_capacity * sizeof(long));
    pool->keys = (int *)malloc(initial_capacity * sizeof(int));
    pool->records = (record *)malloc(initial_capacity * sizeof(record));
    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
}

void resize_memory_pool(memory_pool *pool) {
    size_t new_capacity = pool->capacity * 2;
    long *new_offsets = (long *)realloc(pool->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(pool->keys, new_capacity * sizeof(int));
    record *new_records = (record *)realloc(pool->records, new_capacity * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;
    pool->capacity = new_capacity;
}

void add_record(memory_pool *pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        resize_memory_pool(pool);
    }
    pool->offsets[pool->size] = offset;
    pool->keys[pool->size] = key;
    pool->records[pool->size].value = rand() % 100; // Custom PRNG for example
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
}

void free_memory_pool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    pthread_mutex_unlock(&pool->lock);
}
