#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_ARRAYS 5
#define ARRAY_SIZE 1024

typedef struct {
    float value;
} data_t;

union FindUnion {
    int parent;
    int rank;
};

void unionFindMakeSet(union FindUnion *uf, int n) {
    for (int i = 0; i < n; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

int unionFindFind(union FindUnion *uf, int x) {
    if (uf[x].parent != x)
        uf[x].parent = unionFindFind(uf, uf[x].parent);
    return uf[x].parent;
}

void unionFindUnion(union FindUnion *uf, int x, int y) {
    int rootX = unionFindFind(uf, x);
    int rootY = unionFindFind(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

void *allocateMemory(int size, const char *arrayName) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error allocating memory for %s\n", arrayName);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int main() {
    srand(time(NULL));

    long *timestamps = allocateMemory(ARRAY_SIZE * sizeof(long), "timestamps");
    int *eventIDs = allocateMemory(ARRAY_SIZE * sizeof(int), "eventIDs");
    double *sensorReadings = allocateMemory(ARRAY_SIZE * sizeof(double), "sensorReadings");
    char *statusIndicators = allocateMemory(ARRAY_SIZE * sizeof(char), "statusIndicators");
    data_t *dataStructures = allocateMemory(ARRAY_SIZE * sizeof(data_t), "dataStructures");

    union FindUnion *uf = allocateMemory(ARRAY_SIZE * sizeof(union FindUnion), "uf");

    unionFindMakeSet(uf, ARRAY_SIZE);

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        timestamps[i] = rand() % 1000000L;
        eventIDs[i] = rand() % 100;
        sensorReadings[i] = ((double)rand() / RAND_MAX) * 100.0;
        statusIndicators[i] = (char)(rand() % 26 + 'A');
        dataStructures[i].value = ((float)rand() / RAND_MAX) * 100.0;

        int set1 = rand() % ARRAY_SIZE;
        int set2 = rand() % ARRAY_SIZE;
        if (set1 != set2)
            unionFindUnion(uf, set1, set2);
    }

    start = clock();
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        int root = unionFindFind(uf, i);
        // Perform disjointness checks and measure time
    }
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;

    printf("Time taken for disjointness checks: %.2f ms\n", cpu_time_used);

    free(timestamps);
    free(eventIDs);
    free(sensorReadings);
    free(statusIndicators);
    free(dataStructures);
    free(uf);

    return 0;
}
