record* init_records(int initial_capacity, long* offsets, int* keys, char* tags) {
    // Initialize arrays for offsets, keys, and tags
    offsets = (long*)malloc(initial_capacity * sizeof(long));
    keys = (int*)malloc(initial_capacity * sizeof(int));
    tags = (char*)malloc(initial_capacity * sizeof(char));

    if (!offsets || !keys || !tags) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize records array
    record* records = (record*)malloc(initial_capacity * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        free(tags);
        return NULL;
    }

    // Populate records with pseudo-random values and timestamps
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < initial_capacity; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 1000; // Assuming keys range from 0 to 999
        tags[i] = 'A' + rand() % 26; // Assuming tags are uppercase letters
        records[i].value = rand() % 1000;
        records[i].tag = tags[i];
        records[i].timestamp = (double)rand() / RAND_MAX;
    }

    return records;
}

void free_records(record* records, long* offsets, int* keys, char* tags) {
    free(records);
    free(offsets);
    free(keys);
    free(tags);
}

record* query_record(record* records, int key, char tag, int* found_index) {
    for (int i = 0; i < *found_index; i++) {
        if (records[i].key == key && records[i].tag == tag) {
            return &records[i];
        }
    }
    return NULL;
}

int main() {
    int initial_capacity = 1000000;
    long* offsets;
    int* keys;
    char* tags;

    record* records = init_records(initial_capacity, &offsets, &keys, &tags);
    if (!records) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }

    // Example query
    int found_index = initial_capacity;
    record* result = query_record(records, 123, 'A', &found_index);
    if (result) {
        printf("Found record: value=%d, tag='%c', timestamp=%.6f\n", result->value, result->tag, result->timestamp);
    } else {
        printf("Record not found\n");
    }

    free_records(records, offsets, keys, tags);
    return EXIT_SUCCESS;
}
