unsigned long prng(unsigned long state) {
    return (state * 25214903917ULL + 11) % 4294967291ULL;
}

void initialize_records(record** records, size_t* offsets, int* keys, unsigned char* flags, const char* input, size_t len) {
    if (len == 0 || input == NULL) {
        fprintf(stderr, "Invalid input string.\n");
        return;
    }

    *records = malloc(MAX_RECORDS * sizeof(record));
    offsets = malloc(MAX_RECORDS * sizeof(size_t));
    keys = malloc(MAX_RECORDS * sizeof(int));
    flags = malloc(MAX_RECORDS * sizeof(unsigned char));

    if (*records == NULL || offsets == NULL || keys == NULL || flags == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(*records);
        free(offsets);
        free(keys);
        free(flags);
        return;
    }

    unsigned long state = 123456789ULL; // Seed for PRNG

    for (size_t i = 0; i < MAX_RECORDS && i * 10 < len; ++i) {
        offsets[i] = rand() % (len - i * 10);
        keys[i] = prng(state++) % (len - offsets[i]);
        flags[i] = (unsigned char)(prng(state++) & 1);

        (*records)[i].value = keys[i];
        (*records)[i].str = malloc(11); // Assuming each substring is up to 10 characters long
        strncpy((*records)[i].str, input + offsets[i], 10);
        (*records)[i].str[10] = '\0';
    }
}

void free_records(record** records, size_t* offsets, int* keys, unsigned char* flags) {
    for (size_t i = 0; i < MAX_RECORDS && offsets[i] != 0; ++i) {
        free((*records)[i].str);
    }

    free(*records);
    free(offsets);
    free(keys);
    free(flags);
}

int main() {
    const char* input = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    size_t len = strlen(input);

    record* records;
    size_t* offsets;
    int* keys;
    unsigned char* flags;

    initialize_records(&records, &offsets, &keys, &flags, input, len);

    // Use records here

    free_records(&records, &offsets, &keys, &flags);

    return 0;
}
