        return;
    }

    while (1) {
        double num;
        int result = scanf("%lf", &num);
        if (result == EOF) break;
        if (result != 1) {
            printf("Invalid input. Please enter a floating-point number.\n");
            continue;
        }
        count++;
        floatArray = realloc(floatArray, count * sizeof(double));
        if (!floatArray) {
            for (int i = 0; i < 50; i++) {
                free(dataStructs[i]->message);
                free(dataStructs[i]);
                free(prngIntLists[i]);
                free(timestamps[i]);
                free(complexGraphOps[i]);
