    // Clean up
    for (int i = 0; i < 50; i++) {
        free(dataStructs[i]->message);
        free(dataStructs[i]);
        free(prngIntLists[i]);
        free(timestamps[i]);
        free(complexGraphOps[i]);
    }
    free(seeds);
    free(indices);
    free(dataStructs);
    free(floatArray);
}

int main() {
    processArrays();
    return 0;
}
