#define MAX_THREADS 10

typedef struct {
    int value;
} record;

union find_set {
    int parent;
    int rank;
};

int find(union find_set *set, int i) {
    if (set[i].parent != i)
        set[i].parent = find(set, set[i].parent);
    return set[i].parent;
}

void union_sets(union find_set *set, int x, int y) {
    int xroot = find(set, x);
    int yroot = find(set, y);

    if (set[xroot].rank < set[yroot].rank)
        set[xroot].parent = yroot;
    else if (set[xroot].rank > set[yroot].rank)
        set[yroot].parent = xroot;
    else {
        set[yroot].parent = xroot;
        set[xroot].rank++;
    }
}

