        perror("Connection failed");
        close(sock);
        free(offsets); free(keys); free(records); free(input_list); free(commands); free(set);
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
