#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    unsigned long id;
    double timestamp;
    char tag[10];
} event;

unsigned long generate_random_id() {
    // Non-cryptographic PRNG for performance
    static unsigned long seed = 42;
    return seed = seed * 636900167 + 123456789;
}

double generate_random_timestamp(double start, double end) {
    return start + (end - start) * ((double)rand() / RAND_MAX);
}

char* generate_random_tag() {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    static char tag[10];
    for (int i = 0; i < 9; ++i)
        tag[i] = charset[rand() % sizeof(charset)];
    tag[9] = '\0';
    return tag;
}

