    if (!events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL)); // Seed for PRNG
    for (int i = 0; i < num_events; ++i) {
        events[i].id = generate_random_id();
        events[i].timestamp = generate_random_timestamp(0.0, 1000.0);
        strcpy(events[i].tag, generate_random_tag());
    }
    return events;
}

void free_events(event* events, int num_events) {
    free(events);
}

int main() {
    const int num_events = 1000;
    event* events = initialize_events(num_events);

    // Simulate network connection and data exchange
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        free_events(events, num_events);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);
    serv_addr.sin_port = htons(8080);

    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Failed to connect to server");
        close(sockfd);
        free_events(events, num_events);
        exit(EXIT_FAILURE);
    }

    // Perform operations and handle connection state changes
