#include <unistd.h>
#include <arpa/inet.h>

#define MAX_RETRIES 5
#define INITIAL_DELAY_US 1000

typedef struct {
    int value;
} record;

u_char* resolve_hostname(const char* hostname, int* ip_size) {
    u_char* ip_address = NULL;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    while (1) {
        status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                if (p->ai_family == AF_INET) { // Check for IPv4
                    struct sockaddr_in* h = (struct sockaddr_in *)p->ai_addr;
                    *ip_size = sizeof(h->sin_addr);
                    ip_address = malloc(*ip_size);
                    if (ip_address != NULL) {
                        memcpy(ip_address, &(h->sin_addr), *ip_size);
                        break;
                    } else {
                        fprintf(stderr, "Memory allocation failed for IP address\n");
                        freeaddrinfo(res);
                        return NULL;
                    }
                }
            }
            freeaddrinfo(res);
            if (ip_address != NULL) {
                break;
            } else {
                fprintf(stderr, "No IPv4 address found for hostname\n");
                return NULL;
            }
        } else {
            fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
            usleep(INITIAL_DELAY_US);
            INITIAL_DELAY_US *= 2; // Exponential backoff
            if (INITIAL_DELAY_US > MAX_RETRIES * 1000) {
                break;
            }
        }
    }

    return ip_address;
}

long* allocate_offsets(int size, long max_offset) {
    long* offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % max_offset;
    }
    return offsets;
}

record* initialize_records(int size) {
    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand();
    }
    return records;
}

void free_resources(long* offsets, record* records, u_char* ip_address) {
    free(offsets);
    free(records);
    if (ip_address != NULL) {
        free(ip_address);
    }
}
