#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

typedef struct {
    int *records;
    size_t capacity;
    size_t count;
} RecordArray;

void initRecordArray(RecordArray *array, int minVal, int maxVal) {
    array->capacity = INITIAL_SIZE;
    array->count = 0;
    array->records = (int *)malloc(array->capacity * sizeof(int));
    if (array->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL)); // Seed PRNG
    for (size_t i = 0; i < INITIAL_SIZE; ++i) {
        array->records[i] = minVal + rand() % (maxVal - minVal + 1);
    }
}

void addRecord(RecordArray *array, int value) {
    if (array->count == array->capacity) {
        array->capacity *= GROWTH_FACTOR;
        array->records = realloc(array->records, array->capacity * sizeof(int));
        if (array->records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    array->records[array->count++] = value;
}

void updateRecord(RecordArray *array, size_t index, int value) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    array->records[index] = value;
}

void removeRecord(RecordArray *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->records[i] = array->records[i + 1];
    }
    array->count--;
}

void resizeRecordArray(RecordArray *array, size_t newSize) {
    if (newSize > array->capacity) {
        while (array->capacity < newSize) {
            array->capacity *= GROWTH_FACTOR;
        }
        array->records = realloc(array->records, array->capacity * sizeof(int));
        if (array->records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        for (size_t i = array->count; i < newSize; ++i) {
            array->records[i] = 0; // Initialize new records
        }
    } else if (newSize < array->capacity) {
        array->capacity = newSize;
        array->records = realloc(array->records, array->capacity * sizeof(int));
        if (array->records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

void freeRecordArray(RecordArray *array) {
    free(array->records);
    array->records = NULL;
    array->count = 0;
    array->capacity = 0;
}

int main() {
    RecordArray myArray;
    initRecordArray(&myArray, 1, 100);

    addRecord(&myArray, 42);
    updateRecord(&myArray, 0, 99);
    removeRecord(&myArray, 1);

    resizeRecordArray(&myArray, 20);

    freeRecordArray(&myArray);

    return 0;
}
