typedef struct {
    int id;
    float value;
} Vertex;

typedef struct {
    int source;
    int destination;
    float weight;
} Edge;

typedef struct {
    Vertex* vertices;
    Edge* edges;
    int numVertices;
    int numEdges;
} Graph;

Graph* createGraph(int numVertices, int numEdges) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->vertices = (Vertex*)malloc(numVertices * sizeof(Vertex));
    graph->edges = (Edge*)malloc(numEdges * sizeof(Edge));
    if (!graph->vertices || !graph->edges) {
        free(graph);
        return NULL;
    }

    for (int i = 0; i < numVertices; ++i) {
        graph->vertices[i].id = i;
        graph->vertices[i].value = ((float)rand()) / RAND_MAX * 100.0;
    }

    for (int i = 0; i < numEdges; ++i) {
        graph->edges[i].source = rand() % numVertices;
        graph->edges[i].destination = rand() % numVertices;
        graph->edges[i].weight = ((float)rand()) / RAND_MAX * 100.0;
    }

    graph->numVertices = numVertices;
    graph->numEdges = numEdges;

    return graph;
}

void freeGraph(Graph* graph) {
    if (graph) {
        free(graph->vertices);
        free(graph->edges);
        free(graph);
    }
}
