// Define record structure
typedef struct {
    int value;
} Record;

// Define timestamp structure
typedef struct {
    time_t time;
} Timestamp;

// Union-Find data structure
typedef struct {
    int* parent;
    int* rank;
    int size;
} UFSet;

// Initialize Union-Find structure
void uf_init(UFSet* uf, int n) {
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->rank = (int*)calloc(n, sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
    }
}

// Find with path compression
int uf_find(UFSet* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = uf_find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

// Union by rank
void uf_union(UFSet* uf, int x, int y) {
    int rootX = uf_find(uf, x);
    int rootY = uf_find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

// Helper function to find minimum value in array
double find_min(double* arr, int n) {
    double min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// Main function
