    long* offsets = (long*)malloc(10 * sizeof(long));
    int* keys = (int*)malloc(10 * sizeof(int));
    Record* records = (Record*)malloc(10 * sizeof(Record));
    Timestamp* timestamps2 = (Timestamp*)malloc(10 * sizeof(Timestamp));

    if (seed_values == NULL || indices == NULL || data == NULL ||
        input_numbers == NULL || random_integers == NULL || timestamps == NULL ||
        offsets == NULL || keys == NULL || records == NULL || timestamps2 == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    // Initialize seed values and PRNG
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        seed_values[i] = rand();
        random_integers[i] = rand() % 100;
    }

    // Create Union-Find structure
    UFSet uf;
    uf_init(&uf, 10);

    // Generate graph data
    for (int i = 0; i < 10; i++) {
        int x = keys[i];
        int y = keys[(i + 1) % 10];
        long offset = offsets[i];
        uf_union(&uf, x, y);
