['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORD_SIZE sizeof(record)
#define INITIAL_CAPACITY 1024
#define MAX_LOAD_FACTOR 0.75

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_array;

typedef struct {
    dynamic_array* array;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool() {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->array = (dynamic_array*)malloc(sizeof(dynamic_array));
    if (!pool->array) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    pool->array->records = (record*)malloc(INITIAL_CAPACITY * RECORD_SIZE);
    if (!pool->array->records) {
        free(pool->array);
        free(pool);
        return NULL;
    }

    pool->array->capacity = INITIAL_CAPACITY;
    pool->array->size = 0;

    pthread_mutex_init(&pool->array->lock, NULL);

    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->array->lock);
    free(pool->array->records);
    pthread_mutex_unlock(&pool->array->lock);

    free(pool->array);
    pthread_mutex_destroy(&pool->array->lock);

    free(pool);
    pthread_mutex_destroy(&pool->lock);
}

void resize_memory_pool(memory_pool* pool) {
    pthread_mutex_lock(&pool->array->lock);

    if (pool->array->size <= (MAX_LOAD_FACTOR * pool->array->capacity)) {
        pthread_mutex_unlock(&pool->array->lock);
        return;
    }

    size_t new_capacity = pool->array->capacity * 2;
    record* new_records = (record*)realloc(pool->array->records, new_capacity * RECORD_SIZE);
    if (!new_records) {
        pthread_mutex_unlock(&pool->array->lock);
        return;
    }

    pool->array->records = new_records;
    pool->array->capacity = new_capacity;

    pthread_mutex_unlock(&pool->array->lock);
}

void insert_record(memory_pool* pool, long offset, int key) {
    pthread_mutex_lock(&pool->array->lock);

    if (pool->array->size == pool->array->capacity) {
        resize_memory_pool(pool);
    }

    pool->array->records[pool->array->size].offset = offset;
    pool->array->records[pool->array->size].key = key;
    pool->array->size++;

    pthread_mutex_unlock(&pool->array->lock);
}

record* lookup_record(memory_pool* pool, int key) {
    pthread_mutex_lock(&pool->array->lock);

    for (size_t i = 0; i < pool->array->size; i++) {
        if (pool->array->records[i].key == key) {
            pthread_mutex_unlock(&pool->array->lock);
            return &pool->array->records[i];
        }
    }

    pthread_mutex_unlock(&pool->array->lock);
    return NULL;
}
```

This code provides a basic implementation of a dynamic array with a memory pool manager for efficient memory allocation and deallocation. It includes functions to create, destroy, resize, insert records, and lookup records. The code uses pthread mutexes for thread-safe access to shared data structures. Note that this is a simplified version and does not include advanced features such as hash tables, alignment padding, or error handling mechanisms mentioned in the question.']

