#define RECORD_SIZE 1

typedef struct {
    int value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

record* create_records(long size, int min_val, int max_val) {
    record* records = (record*)malloc(size * RECORD_SIZE * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }
    srand(time(NULL));
    for (long i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    return records;
}

int find_largest(int* array, long size) {
    int largest = array[0];
    for (long i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void union_find_check(long* offsets, int* keys, record* records, long size) {
    struct timeval start, end;
    gettimeofday(&start, NULL);
