const crypto = require('crypto');
const fs = require('fs');
const http = require('http');
const https = require('https');
const net = require('net');
const url = require('url');

const CACHE_SIZE = 1024 * 1024; // 1 MB cache size
const MAX_CONCURRENCY = 10;
const WORKER_POOL_SIZE = 5;

let resourceCache = new Map();
let workerPool = [];
let pendingTasks = [];

function processPageResources(descriptors) {
    return new Promise((resolve, reject) => {
        descriptors.forEach(descriptor => {
            enqueueTask({ descriptor, resolve, reject });
        });

        startWorkerPool();
    });
}

function enqueueTask(task) {
    if (workerPool.length > 0) {
        let worker = workerPool.shift();
        worker.task = task;
        worker.process();
    } else {
        pendingTasks.push(task);
    }
}

function startWorkerPool() {
    for (let i = 0; i < WORKER_POOL_SIZE; i++) {
        let worker = { process };
        workerPool.push(worker);
        worker.process();
    }

    function process() {
        if (pendingTasks.length > 0) {
            let task = pendingTasks.shift();
            this.task = task;
            this.executeTask(task);
        }
    }
}

function executeTask(task) {
    try {
        let result = processResource(this.task.descriptor);
        resourceCache.set(cacheKey(this.task.descriptor), result);
        task.resolve(result);
        this.process();
    } catch (error) {
        task.reject(error);
        this.process();
    }
}

function cacheKey(descriptor) {
    return crypto.createHash('sha256').update(JSON.stringify(descriptor)).digest('hex');
}

function processResource(descriptor) {
    let key = cacheKey(descriptor);
    if (resourceCache.has(key)) {
        return resourceCache.get(key);
    }

    let { type, source, contentType } = descriptor;
    switch (type) {
        case 'script':
            return fetchScript(source, contentType);
        case 'style':
            return fetchStyle(source, contentType);
        default:
            throw new Error(`Unsupported resource type: ${type}`);
    }
}

function fetchScript(source, contentType) {
    let request = https.get(source, response => {
        if (response.statusCode === 200 && response.headers['content-type'].startsWith(contentType)) {
            let data = [];
            response.on('data', chunk => data.push(chunk));
            response.on('end', () => {
                let scriptContent = Buffer.concat(data).toString();
                return `<script type="${contentType}">${scriptContent}</script>`;
            });
        } else {
            throw new Error(`Failed to fetch resource: ${response.statusCode}`);
        }
    });

    request.on('error', error => {
        throw error;
    });
}

function fetchStyle(source, contentType) {
    let request = https.get(source, response => {
        if (response.statusCode === 200 && response.headers['content-type'].startsWith(contentType)) {
            let data = [];
            response.on('data', chunk => data.push(chunk));
            response.on('end', () => {
                let styleContent = Buffer.concat(data).toString();
                return `<style type="${contentType}">${styleContent}</style>`;
            });
        } else {
            throw new Error(`Failed to fetch resource: ${response.statusCode}`);
        }
    });

    request.on('error', error => {
        throw error;
    });
}
