#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
} record;

record* init_records(int num_records, unsigned long seed) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    return records;
}

void free_records(record* records) {
    if (records) {
        free(records);
        printf("Records memory freed\n");
    }
}

int find_largest(int* arr, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size for finding largest value\n");
        return -1;
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

void* read_and_find_largest(void* arg) {
    int num_records = *(int*)arg;
    record* records = init_records(num_records, time(NULL));
    if (!records) {
        pthread_exit(NULL);
    }

    int* input_array = (int*)malloc(num_records * sizeof(int));
    if (!input_array) {
        perror("Failed to allocate memory for input array");
        free_records(records);
        pthread_exit(NULL);
    }

    printf("Enter %d integers:\n", num_records);
    for (int i = 0; i < num_records; i++) {
        scanf("%d", &input_array[i]);
    }

    int largest_value = find_largest(input_array, num_records);
    if (largest_value != -1) {
        printf("Largest value: %d\n", largest_value);
    } else {
        fprintf(stderr, "Error finding largest value\n");
    }

    free(input_array);
    free_records(records);
    pthread_exit(NULL);
}

int main() {
    int num_threads = 2;
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = MAX_RECORDS / num_threads * (i + 1);
        if (pthread_create(&threads[i], NULL, read_and_find_largest, &thread_args[i]) != 0) {
            perror("Failed to create thread");
            exit(1);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
