            populateRecords(minValue, maxValue);
        }

        void addRecord(int key, long offset) {
            if (key >= 0 && key < records.size()) {
                records[key].offset = offset;
            }
        }

        long getOffset(int key) const {
            if (key >= 0 && key < records.size()) {
                return records[key].offset;
            }
            throw std::out_of_range("Key out of range");
        }

    private:
        struct Record {
            int key;
            long offset;
        };

        std::vector<Record> records;
        std::mt19937 randomEngine;

        static unsigned seedGenerator() {
            std::ifstream urandom("/dev/urandom"); // For system-specific seeding
            unsigned seed;
            urandom.read(reinterpret_cast<char*>(&seed), sizeof(seed));
            return seed;
        }

        void populateRecords(size_t minValue, size_t maxValue) {
            std::uniform_int_distribution<long> distribution(minValue, maxValue);
            for (auto& record : records) {
                record.key = static_cast<int>(records.size() - 1);
                record.offset = distribution(randomEngine);
            }
        }
    };
}
```

This code snippet defines a class `DataStore` within the `RecordManager` namespace that manages a collection of records. Each record stores a unique integer key and a corresponding long offset value. The class uses the Mersenne Twister algorithm for generating pseudo-random integers to initialize the offsets. The constructor initializes the random number generator with a seed obtained from an external data source, and populates the records with random offset values within a specified range. The `addRecord` method allows adding new records to the store, while the `getOffset` method retrieves the offset value for a given key.']

