// Custom PRNG function using XORShift algorithm for good performance and low bias
unsigned long xorshift(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return (*state = x);
}

// Function to generate a random integer within a specified range using the PRNG
