typedef struct {
    size_t num_entries;
    size_t max_data_length;
    int *offsets;
    int *keys;
    Record *records;
} DatabaseIndex;

DatabaseIndex* create_database_index(size_t num_entries, size_t max_data_length) {
    DatabaseIndex *index = (DatabaseIndex*)malloc(sizeof(DatabaseIndex));
    if (!index) return NULL;

    index->num_entries = num_entries;
    index->max_data_length = max_data_length;

    index->offsets = (int*)malloc(num_entries * sizeof(int));
    index->keys = (int*)malloc(num_entries * sizeof(int));
    index->records = (Record*)malloc(num_entries * sizeof(Record));

    if (!index->offsets || !index->keys || !index->records) {
        free(index->offsets);
        free(index->keys);
        free(index->records);
        free(index);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_entries; ++i) {
        index->keys[i] = i + 1;

        int offset_value = rand() % (int)num_entries;
        index->offsets[i] = offset_value;

        index->records[i].value = rand() % 1000; // Random value between 0 and 999

        index->records[i].data = (char*)malloc(max_data_length * sizeof(char));
        if (!index->records[i].data) {
            for (size_t j = 0; j < i; ++j) {
                free(index->records[j].data);
            }
            free(index->offsets);
            free(index->keys);
            free(index->records);
            free(index);
            return NULL;
        }

        for (size_t j = 0; j < max_data_length - 1; ++j) {
            index->records[i].data[j] = 'a' + rand() % 26; // Random alphabetic character
        }
        index->records[i].data[max_data_length - 1] = '\0'; // Null-terminate the string
    }

    return index;
}

void free_database_index(DatabaseIndex *index) {
    if (index) {
        for (size_t i = 0; i < index->num_entries; ++i) {
            free(index->records[i].data);
        }
        free(index->offsets);
        free(index->keys);
        free(index->records);
        free(index);
    }
}

Record* get_record_by_key(DatabaseIndex *index, int key) {
    for (size_t i = 0; i < index->num_entries; ++i) {
        if (index->keys[i] == key) {
            return &index->records[index->offsets[i]];
        }
    }
    return NULL;
}
