#define MAX_RECORDS 1000000
#define MIN_KEY -1000000
#define MAX_KEY 1000000

typedef struct {
    int value;
} record;

record* init_records(int count, int seed) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Count exceeds maximum allowed records.\n");
        return NULL;
    }

    record* recs = (record*)malloc(count * sizeof(record));
    if (!recs) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < count; ++i) {
        recs[i].value = MIN_KEY + rand() % (MAX_KEY - MIN_KEY + 1);
    }

    return recs;
}

int find_largest(int* arr, int size) {
    if (!arr || size <= 0) {
        fprintf(stderr, "Error: Invalid input array for finding largest value.\n");
        return INT_MIN;
    }

    int max_value = INT_MIN;
    for (int i = 0; i < size; ++i) {
        if (arr[i] > max_value) {
            max_value = arr[i];
        }
    }

    return max_value;
}

void serialize_records(record* recs, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for serialization.\n");
        return;
    }

    fwrite(recs, sizeof(record), count, file);
    fclose(file);
}

void deserialize_records(record** recs, int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for deserialization.\n");
        return;
    }

    fseek(file, 0L, SEEK_END);
    *count = ftell(file) / sizeof(record);
    fseek(file, 0L, SEEK_SET);

    *recs = (record*)malloc(*count * sizeof(record));
    if (!*recs) {
        fprintf(stderr, "Error: Failed to allocate memory for deserialized records.\n");
        fclose(file);
        return;
    }

    fread(*recs, sizeof(record), *count, file);
    fclose(file);
}

int main(int argc, char* argv[]) {
    int count = 1000000; // Example count
    int seed = time(NULL); // Use current time as seed for PRNG
    record* recs = init_records(count, seed);

    if (!recs) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Initialized records successfully.\n");

    // Example input reading and largest value finding
    int size = 10; // Example size
    int* arr = (int*)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Error: Failed to allocate memory for input array.\n");
        free(recs);
        return EXIT_FAILURE;
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; ++i) {
        scanf("%d", &arr[i]);
    }

    int largest_value = find_largest(arr, size);
    if (largest_value != INT_MIN) {
        printf("Largest value: %d\n", largest_value);
    }

    free(arr);
    free(recs);

    return EXIT_SUCCESS;
}
