void initializeMemoryPool(MemoryPool** pool, size_t initialCapacity) {
    *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    (*pool)->records = (Record*)calloc(initialCapacity, sizeof(Record));
    (*pool)->capacity = initialCapacity;
    (*pool)->used = 0;
}

void resizeMemoryPool(MemoryPool** pool, size_t newCapacity) {
    MemoryPool* oldPool = *pool;
    Record* newRecords = (Record*)realloc(oldPool->records, newCapacity * sizeof(Record));

    if (newRecords == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    (*pool)->records = newRecords;
    (*pool)->capacity = newCapacity;
}

void insertRecord(MemoryPool* pool, long offset, int key, double weight, char status) {
    if (pool->used == pool->capacity) {
        resizeMemoryPool(&pool, pool->capacity * 2);
    }
    pool->records[pool->used].offset = offset;
    pool->records[pool->used].key = key;
    pool->records[pool->used].weight = weight;
    pool->records[pool->used].status = status;
    pool->used++;
}

double calculateTotalWeight(MemoryPool* pool) {
    double totalWeight = 0.0;
    for (size_t i = 0; i < pool->used; i++) {
        totalWeight += pool->records[i].weight;
    }
    return totalWeight;
}

void logMemoryUsage(MemoryPool* pool, FILE* logFile) {
    fprintf(logFile, "Total records: %zu\n", pool->used);
    fprintf(logFile, "Total weight: %.2f\n", calculateTotalWeight(pool));
}

void freeMemoryPool(MemoryPool** pool) {
    if (*pool != NULL) {
        free((*pool)->records);
        free(*pool);
        *pool = NULL;
    }
}

int main() {
    srand(time(NULL)); // Seed the PRNG
    MemoryPool* pool = NULL;
    initializeMemoryPool(&pool, 10);

    for (size_t i = 0; i < 25; i++) {
        insertRecord(pool, i, rand() % 1000, 1.1 * i, 'V');
    }

    FILE* logFile = fopen("memory_usage.log", "w");
    if (logFile != NULL) {
        logMemoryUsage(pool, logFile);
        fclose(logFile);
    }

    freeMemoryPool(&pool);

    return 0;
}
