import java.util.HashSet;

public class UnionFind {
    private int[] parent;
    private int count;

    public UnionFind(int size) {
        parent = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
        count = size;
    }

    public int find(int p) {
        while (p != parent[p]) {
            parent[p] = parent[parent[p]]; // Path compression
            p = parent[p];
        }
        return p;
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP == rootQ) return;

        parent[rootP] = rootQ; // Union by rank can be added for optimization
        count--;
    }

    public boolean isConnected(int p, int q) {
        return find(p) == find(q);
    }
}

public class DisjointPairsCalculator {
    public static int countDisjointPairs(int[] array) {
        HashSet<Integer> elements = new HashSet<>();
        UnionFind uf = new UnionFind(array.length);

        for (int i = 0; i < array.length - 1; i++) {
            if (!elements.contains(array[i])) {
                elements.add(array[i]);
            }
            if (i + 1 < array.length && !elements.contains(array[i + 1])) {
                elements.add(array[i + 1]);
                uf.union(i, i + 1);
            } else if (uf.isConnected(i, i + 1)) {
                return -1; // Not disjoint
            }
        }

        return elements.size() - uf.count;
    }
}
