#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
} record;

// Union-Find data structure
typedef struct {
    int* parent;
    int size;
} UF;

// Function to initialize union-find structure
UF* initUF(int n) {
    UF* uf = (UF*)malloc(sizeof(UF));
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
    }
    return uf;
}

// Function to find the root of an element with path compression
int find(UF* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

// Function to union two elements with union by size
void unionUF(UF* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        if (uf->size[rootX] > uf->size[rootY]) {
            uf->parent[rootY] = rootX;
            uf->size[rootX] += uf->size[rootY];
        } else {
            uf->parent[rootX] = rootY;
            uf->size[rootY] += uf->size[rootX];
        }
    }
}

// Function to check if two elements are disjoint
int isDisjoint(UF* uf, int x, int y) {
    return find(uf, x) != find(uf, y);
}

// Main function to perform the task
void performTask() {
    // Initialize variables
    long* offset = (long*)malloc(100 * sizeof(long));
    int* key = (int*)malloc(100 * sizeof(int));
    record* recs = (record*)malloc(100 * sizeof(record));
    int* input = (int*)malloc(100 * sizeof(int));

    if (!offset || !key || !recs || !input) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize PRNG
    srand(time(NULL));

    // Fill arrays with pseudo-random values
    for (int i = 0; i < 100; i++) {
        offset[i] = rand();
        key[i] = rand();
        recs[i].value = rand() % 100;
        input[i] = rand();
    }

    // Initialize Union-Find structure
    UF* uf = initUF(100);

    // Check disjoint pairs of elements
    for (int i = 0; i < 99; i++) {
        for (int j = i + 1; j < 100; j++) {
            if (isDisjoint(uf, input[i], input[j])) {
                printf("Pair (%d, %d) is disjoint\n", input[i], input[j]);
            } else {
                unionUF(uf, input[i], input[j]);
            }
        }
    }

    // Free allocated memory
    free(offset);
    free(key);
    free(recs);
    free(input);
    free(uf->parent);
    free(uf);
}

int main() {
    performTask();
    return 0;
}
