transaction* initialize_transactions(int count, int range_start, int range_end) {
    if (count <= 0 || range_start >= range_end) {
        log_message("Invalid input values for transaction initialization.");
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG
    transaction* transactions = malloc(count * sizeof(transaction));
    if (!transactions) {
        log_message("Memory allocation failed for transactions.");
        return NULL;
    }

    double scale = (double)(range_end - range_start) / RAND_MAX;
    for (int i = 0; i < count; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].ID = i + 1;
        transactions[i].random = range_start + rand() * scale;
    }

    return transactions;
}

void process_input_and_print_average() {
    int size;
    log_message("Enter the number of integers:");
    scanf("%d", &size);

    int* array = malloc(size * sizeof(int));
    if (!array) {
        log_message("Memory allocation failed for input array.");
        return;
    }

    log_message("Enter the integers:");
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    double average = calculate_average(array, size);
    printf("Average: %.2f\n", average);

    free(array);
}

