        (*records)[i] = (record*)malloc(sizeof(record));
        if (!(*records)[i]) {
            log_error("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        // Set random value within range
        (*records)[i]->value = rand();
    }

    // Initialize OpenSSL library
    SSL_library_init();
    OpenSSL_add_all_algorithms();

    // Set default digest algorithm
    const EVP_MD* md = EVP_get_digestbyname(default_digest);
    if (!md) {
        log_warning("Digest algorithm not supported, falling back to MD5");
        md = EVP_md5();
    }

    // Validate cryptographic function versions
    if (EVP_CIPHER_get_flags(EVP_aes_256_cbc()) != EVP_CIPHER_VARIABLE_LENGTH) {
        log_warning("AES-256-CBC version is deprecated, using fallback algorithm");
    }
}

// Function to clean up allocated memory
void cleanup(long* offsets, int* keys, record** records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    // Clean up OpenSSL library
