const fetch = require('node-fetch');
const FormData = require('form-data');

async function uploadFileFromURL(url) {
    const response = await fetch(url);
    if (!response.ok) {
        throw new Error(`Failed to fetch file: ${url}`);
    }

    const blob = await response.blob();
    const formData = new FormData();
    formData.append('file', blob, 'filename');

    let retries = 3;
    while (retries > 0) {
        try {
            const uploadResponse = await fetch('https://upload.example.com/upload', {
                method: 'POST',
                body: formData
            });

            if (!uploadResponse.ok) {
                throw new Error(`Failed to upload file: ${url}`);
            }

            return `https://example.com/files/${await uploadResponse.text()}`;
        } catch (error) {
            retries--;
            console.warn(`Upload attempt failed, retrying... (${retries} attempts left)`);
        }
    }

    throw new Error('Max upload attempts reached');
}
