        rec->data[i] = 'a' + rand() % ('z' - 'a' + 1);
    }
}

record* create_record(int key, int data_length) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        log_message("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    new_record->key = key;
    generate_random_data(new_record, data_length);
    return new_record;
}

void connect_to_server() {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT_NO);

    if (connect(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to connect to server");
        exit(EXIT_FAILURE);
    }
}

void perform_operations() {
    pthread_create(&worker_thread, NULL, worker_function, NULL);
    // Enqueue and process commands as needed
}

void* thread_function(void* arg) {
    while (1) {
        sem_wait(&thread_pool_sem);
        command_t cmd = dequeue_command();
        if (!cmd) break;
        process_command(cmd);
        sem_post(&thread_pool_sem);
    }
    return NULL;
}

void process_command(command_t cmd) {
    // Process the given command
}

void enqueue_command(command_t cmd) {
    pthread_mutex_lock(&queue_mutex);
    // Add the command to the queue
    pthread_mutex_unlock(&queue_mutex);
}

command_t dequeue_command() {
    pthread_mutex_lock(&queue_mutex);
    // Remove and return a command from the queue
    pthread_mutex_unlock(&queue_mutex);
    return NULL;
}
