int* read_input_list(int* size) {
    *size = 0;
    int capacity = 10;
    int* list = (int*)malloc(capacity * sizeof(int));
    if (!list) {
        log_message("Memory allocation failed for input list");
        return NULL;
    }

    int value;
    while (scanf("%d", &value) != EOF) {
        if (*size >= capacity) {
            capacity *= 2;
            int* new_list = (int*)realloc(list, capacity * sizeof(int));
            if (!new_list) {
                log_message("Memory reallocation failed for input list");
                free(list);
                return NULL;
            }
            list = new_list;
        }
        list[*size] = value;
        (*size)++;
    }

    return list;
}

int find_largest(const int* list, int size) {
    if (size == 0) {
        log_message("No values provided to find largest");
        return -1; // Assuming -1 as an error code
    }
    int max = list[0];
    for (int i = 1; i < size; i++) {
        if (list[i] > max) {
            max = list[i];
        }
    }
    return max;
}

