    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        log_message("Memory allocation failed for arrays");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand(); // Generate random long value
        keys[i] = i % 100; // Generate random int key
        records[i].value = range_start + rand() % (range_end - range_start + 1); // Random record value within specified range
    }

    return records;
}

void cleanup(void* records, long* offsets, int* keys) {
    free(records);
    free(offsets);
    free(keys);
}

int main() {
