    int range_start = 1;
    int range_end = 1000;

    void* records_ptr = initialize_arrays(num_records, range_start, range_end);
    if (!records_ptr) {
        return 1;
    }

    record* records = (record*)records_ptr;

    int size;
    int* input_list = read_input_list(&size);
    if (!input_list) {
        cleanup(records_ptr, NULL, NULL);
        return 1;
    }

    int largest_value = find_largest(input_list, size);
    printf("Largest value in input list: %d\n", largest_value);

    free(input_list);
    cleanup(records_ptr, NULL, NULL);

    return 0;
}
