typedef struct {
    int* data;
    size_t size;
} DisjointSet;

DisjointSet* createDisjointSet(int* data, size_t size) {
    DisjointSet* ds = (DisjointSet*)malloc(sizeof(DisjointSet));
    ds->data = (int*)malloc(size * sizeof(int));
    ds->size = size;
    for (size_t i = 0; i < size; ++i) {
        ds->data[i] = i;
    }
    return ds;
}

void destroyDisjointSet(DisjointSet* ds) {
    free(ds->data);
    free(ds);
}

int findRoot(int* data, int x) {
    if (data[x] != x) {
        data[x] = findRoot(data, data[x]); // Path compression
    }
    return data[x];
}

void unionSets(DisjointSet* ds, int x, int y) {
    int rootX = findRoot(ds->data, x);
    int rootY = findRoot(ds->data, y);
    if (rootX != rootY) {
        ds->data[rootY] = rootX;
    }
}

int main() {
    int* data = (int*)malloc(100 * sizeof(int)); // Example array
    DisjointSet* ds = createDisjointSet(data, 100);

    // Union operations here

    destroyDisjointSet(ds);
    free(data);

    return 0;
}
