#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILENAME_LEN 256
#define MAX_METADATA_LEN 501

// Function to count consonants in a string
int count_consonants(const char *str) {
    int count = 0;
    for (const char *p = str; *p != '\0'; p++) {
        if (*p >= 'a' && *p <= 'z') {
            if (*p != 'a' && *p != 'e' && *p != 'i' && *p != 'o' && *p != 'u') {
                count++;
            }
        } else if (*p >= 'A' && *p <= 'Z') {
            if (*p != 'A' && *p != 'E' && *p != 'I' && *p != 'O' && *p != 'U') {
                count++;
            }
        }
    }
    return count;
}

// Function to adjust file metadata
void adjust_file_metadata(const char *filename, off_t size) {
    if (strlen(filename) > MAX_FILENAME_LEN - 1) {
        filename = strndup(filename, MAX_FILENAME_LEN - 1);
    }

    int consonant_count = count_consonants(filename);
    char new_extension[consonant_count + 5]; // Consonant count + ".txt\0"
    snprintf(new_extension, sizeof(new_extension), "_%d.txt", consonant_count);

    char new_filename[MAX_METADATA_LEN];
    snprintf(new_filename, sizeof(new_filename), "%.*s%s", MAX_FILENAME_LEN - strlen(new_extension) - 1, filename, new_extension);

    // Simulate file metadata adjustment
    printf("New filename: %s\n", new_filename);
}

// Helper function to find the largest integer in an array
int find_largest(int arr[], int size) {
    if (size <= 0) return INT_MIN;
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from standard input and find the largest
void read_and_find_largest() {
    int arr[1000]; // Adjust size as needed
    int count = 0;

    while (scanf("%d", &arr[count]) == 1) {
        count++;
        if (count >= 1000) break; // Prevent buffer overflow
    }

    int largest = find_largest(arr, count);
    printf("Largest integer: %d\n", largest);
}

int main() {
    // Example usage of adjust_file_metadata function
    const char *filename = "example.txt";
    off_t size = 1024;
    adjust_file_metadata(filename, size);

    // Example usage of read_and_find_largest function
    printf("Enter integers (press Ctrl+D to stop):\n");
    read_and_find_largest();

    return 0;
