void generate_random_id(char *id, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        id[i] = charset[rand() % sizeof(charset)];
    }
    id[length - 1] = '\0';
}

transaction* initialize_transactions(size_t num_transactions, size_t id_length, int *error_code) {
    transaction *trans = (transaction *)malloc(num_transactions * sizeof(transaction));
    if (!trans) {
        *error_code = -1; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG for this run

    for (size_t i = 0; i < num_transactions; ++i) {
        generate_random_id(trans[i].id, id_length);
        trans[i].amount = rand() % 10000; // Random amount between 0 and 9999
    }

    *error_code = 0; // Success
    return trans;
}

double calculate_average(transaction *trans, size_t num_transactions) {
    int total_amount = 0;
    for (size_t i = 0; i < num_transactions; ++i) {
        total_amount += trans[i].amount;
    }
    return (double)total_amount / num_transactions;
}

void free_transactions(transaction *trans, size_t num_transactions) {
    free(trans);
}
