    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % 100000; // Efficient random value generation
    }

    return records;
}

void readAndFindMax(int *array, int size) {
    if (size <= 0) {
        logWarning("No input provided");
        return;
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

