#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 100000

typedef struct {
    int key;
    double weight;
    char* value;
} record;

// Non-cryptographic PRNG function
int prng(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Helper function to log messages
void log_message(const char* message) {
    printf("%s\n", message);
}

// Function to initialize records with random values and strings
record* init_records(int num_records) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = prng(1, 100);
        records[i].weight = ((double)prng(1, 1000)) / 10.0;
        records[i].value = malloc(20 * sizeof(char));
        if (!records[i].value) {
            log_message("Memory allocation failed for record value");
            free(records);
            return NULL;
        }
        sprintf(records[i].value, "Value%d", i);
    }

    return records;
}

// Function to find and print the largest integer along with its string
void find_largest(record* records, int num_records) {
    int max_key = 0;
    char* max_value = NULL;

    for (int i = 0; i < num_records; i++) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
            max_value = records[i].value;
        }
    }

    printf("Largest key: %d, Value: %s\n", max_key, max_value);
}

// Function to sort records based on double values in descending order
void sort_records(record* records, int num_records) {
    // Choose quicksort for simplicity and better performance for smaller datasets
    qsort(records, num_records, sizeof(record), 
          (int (*)(const void *, const void *))compare_records);
}

// Compare function for qsort
int compare_records(const void *a, const void *b) {
    record *recordA = (record *)a;
    record *recordB = (record *)b;

    if (recordA->weight < recordB->weight)
        return 1;
    else if (recordA->weight > recordB->weight)
        return -1;
    else
        return 0;
}

// Main function to demonstrate the above functionalities
int main() {
    record* records = init_records(MAX_RECORDS);
    if (!records) {
        log_message("Initialization failed");
        return EXIT_FAILURE;
    }

    find_largest(records, MAX_RECORDS);

    sort_records(records, MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("Key: %d, Weight: %.2f, Value: %s\n", 
               records[i].key, records[i].weight, records[i].value);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i].value);
    }
    free(records);

    return EXIT_SUCCESS;
}
