// Define the struct for a transaction
typedef struct {
    int transactionID;
    double amount;
    time_t timestamp;
} Transaction;

// Function to initialize transactions with pseudo-random values
void initTransactions(Transaction* transactions, int count) {
    // Initialize PRNG seed
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        transactions[i].transactionID = rand() % 10000 + 1; // Random transaction ID between 1 and 10000
        transactions[i].amount = ((double)(rand() % 100)) / 10.0; // Random amount between 0 and 99.9
        transactions[i].timestamp = time(NULL) - (rand() % 365 * 24 * 60 * 60); // Random timestamp within the last year
    }
}

// Function to free allocated memory for transactions
void freeTransactions(Transaction* transactions, int count) {
    if (transactions != NULL) {
        free(transactions);
    }
}

// Function to calculate total transaction amount for a specific period
double calculateTotalAmount(Transaction* transactions, int count, time_t start, time_t end) {
    double total = 0.0;
    for (int i = 0; i < count; ++i) {
        if (transactions[i].timestamp >= start && transactions[i].timestamp <= end) {
            total += transactions[i].amount;
        }
    }
    return total;
}

// Function to print the number of milliseconds taken for a grouping operation
void printTimeTaken(clock_t start, clock_t end) {
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000.0;
    printf("Time taken for grouping: %.2f ms\n", time_taken);
}

// Main function to handle transactions and perform calculations
int main() {
    int count;
    printf("Enter the number of transactions: ");
    scanf("%d", &count);

    // Dynamically allocate memory for transactions
    Transaction* transactions = (Transaction*)malloc(count * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Initialize transactions with pseudo-random values
    initTransactions(transactions, count);

    // Example usage: Calculate total amount for the last month
    time_t now = time(NULL);
    time_t one_month_ago = now - (30 * 24 * 60 * 60); // Simplified calculation for demonstration
    double totalAmount = calculateTotalAmount(transactions, count, one_month_ago, now);

    printf("Total transaction amount for the last month: %.2f\n", totalAmount);

    // Free allocated memory
    freeTransactions(transactions, count);

    return 0;
}
