#include <time.h>

typedef struct {
    double value;
} record;

void initialize_data_structures(long size, long *offsets, int *keys, record **records) {
    clock_t start_time, end_time;
    double cpu_time_used;

    // Initialize offsets array
    start_time = clock();
    for (long i = 0; i < size; i++) {
        offsets[i] = i * sizeof(long);
    }
    end_time = clock();
    cpu_time_used = ((double) (end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Time to initialize offsets: %f seconds\n", cpu_time_used);

    // Initialize keys array
    start_time = clock();
    for (long i = 0; i < size; i++) {
        keys[i] = rand() % size;
    }
    end_time = clock();
    cpu_time_used = ((double) (end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Time to initialize keys: %f seconds\n", cpu_time_used);

    // Initialize records array
    start_time = clock();
    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (long i = 0; i < size; i++) {
        (*records)[i].value = ((double) rand()) / RAND_MAX;
    }
    end_time = clock();
    cpu_time_used = ((double) (end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Time to initialize records: %f seconds\n", cpu_time_used);
}

int main() {
    long size = 1000000; // Example size
    long *offsets;
    int *keys;
    record *records;

    srand(time(NULL)); // Seed for PRNG

    offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    initialize_data_structures(size, offsets, keys, &records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
