typedef struct {
    int value;
    int access_count;
} record;

// Pseudo-random number generator function
unsigned long prng(unsigned long seed, unsigned long range) {
    seed = seed * 1103515245 + 12345; // Simple LCG (Linear Congruential Generator)
    return seed % range;
}

record* initialize_records(int num_records, unsigned long seed) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < num_records; i++) {
        records[i].value = prng(seed + i, 100); // Generate random value within range [0, 99]
        records[i].access_count = 0;
    }

    return records;
}

void free_records(record* records, int num_records) {
    free(records);
}

int increment_access(record* record) {
    if (record != NULL) {
        record->access_count++;
        return record->access_count;
    }
    return -1; // Return error code for null pointer
}

int main() {
    srand(time(0)); // Seed the PRNG with current time
    int num_records = 1000;
    record* records = initialize_records(num_records, rand());

    printf("Initial values and access counts:\n");
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Value=%d, Access Count=%d\n", i, records[i].value, records[i].access_count);
    }

    // Increment access count for the first record
    int new_access_count = increment_access(&records[0]);
    printf("Updated Access Count for Record 0: %d\n", new_access_count);

    free_records(records, num_records);
    return 0;
}
