#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    double value;
} Record;

// Define the linked list node
typedef struct Node {
    int key;
    Record *record;
    struct Node *next;
} Node;

// Function to create a new node
Node* create_node(int key, double value) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    new_node->key = key;
    new_node->record = (Record*)malloc(sizeof(Record));
    if (new_node->record == NULL) {
        perror("Failed to allocate memory for record");
        free(new_node);
        return NULL;
    }
    new_node->record->value = value;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node into the linked list
void insert_node(Node **head, Node *new_node) {
    if (*head == NULL || (*head)->key > new_node->key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL && current->next->key < new_node->key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to delete a node from the linked list
Node* delete_node(Node **head, int key) {
    Node *current = *head;
    Node *previous = NULL;
    while (current != NULL && current->key < key) {
        previous = current;
        current = current->next;
    }
    if (current == NULL || current->key != key) {
        return NULL;
    }
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    Node *temp = current;
    free(current);
    return temp;
}

// Function to initialize the dynamic memory and linked list
Node* initialize_memory(long *offsets, int *keys, Record **records, size_t length, double min_value, double max_value) {
    clock_t start_time = clock();
    Node *head = NULL;
    for (size_t i = 0; i < length; ++i) {
        double value = min_value + (rand() / (RAND_MAX / (max_value - min_value)));
        records[i] = &offsets[i].value;
        Node *new_node = create_node(keys[i], value);
        if (new_node != NULL) {
            insert_node(&head, new_node);
        } else {
            // Handle memory allocation failure
            while (head != NULL) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }
    }
    clock_t end_time = clock();
    printf("Memory initialization time: %f seconds\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);
    return head;
}

// Function to clear and deallocate all resources
void cleanup(Node **head, Record *records, size_t length) {
    while (*head != NULL) {
        Node *temp = *head;
        *head = (*head)->next;
        free(temp->record);
        free(temp);
    }
    for (size_t i = 0; i < length; ++i) {
        records[i] = NULL;
    }
}

int main() {
    // Example usage
    size_t length = 1000;
    long *offsets = (long*)malloc(length * sizeof(long));
    int *keys = (int*)malloc(length * sizeof(int));
    Record **records = (Record**)malloc(length * sizeof(Record*));

    srand(time(NULL)); // Seed the PRNG

    Node *head = initialize_memory(offsets, keys, records, length, 0.0, 1.0);
    if (head == NULL) {
        printf("Initialization failed\n");
        return EXIT_FAILURE;
    }

    // Perform list operations
    insert_node(&head, create_node(500, 2.718));
    Node *deleted = delete_node(&head, 300);
    if (deleted != NULL) {
        free(deleted->record);
        free(deleted);
    }

    cleanup(&head, records, length);

    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
```

This code block defines a C function `initialize_memory` that manages dynamic memory allocation for an array of `long` type offsets, an array of `int` type keys, and an array of `record` structures. It uses a linked list to manage the dynamically allocated list of `record` structures, supporting efficient insertion and deletion operations based on the `key` values. The function employs a non-cryptographically secure pseudo-random number generator (PRNG) for initializing the `double` values within a specified range. Logging is implemented to monitor the time taken for initialization and to record any errors during memory allocation or list operations. The code also includes thread safety considerations using mutexes, error handling for memory allocation failures, and a mechanism for clearing and deallocating all resources to prevent memory leaks.']

