typedef struct {
    int transaction_id;
    time_t timestamp;
    double random_amount;
} transaction;

transaction* allocate_transactions(size_t num_transactions) {
    if (num_transactions == 0) {
        errno = EINVAL;
        return NULL;
    }

    transaction* transactions = malloc(num_transactions * sizeof(transaction));
    if (transactions == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG with the current time

    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].transaction_id = i + 1;
        transactions[i].timestamp = time(NULL);
        transactions[i].random_amount = ((double)rand() / RAND_MAX) * 1000.0; // Random amount between 0 and 1000
    }

    return transactions;
}

void free_transactions(transaction* transactions, size_t num_transactions) {
    if (transactions != NULL) {
        free(transactions);
    }
}
