// Function to find maximum in array
int findMax(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to perform union-find operations
void unionFind(int* arr, int n) {
    int parent[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    clock_t start_time = clock();
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) {
                int x = parent[i];
                int y = parent[j];
                while (x != parent[x]) {
                    x = parent[x];
                }
                while (y != parent[y]) {
                    y = parent[y];
                }
                if (x != y) {
                    parent[x] = y;
                    printf("Pair (%d, %d) is not disjoint. Time taken: %f ms\n", arr[i], arr[j], ((double)(clock() - start_time)) / CLOCKS_PER_SEC * 1000);
                } else {
                    printf("Pair (%d, %d) is disjoint. Time taken: %f ms\n", arr[i], arr[j], ((double)(clock() - start_time)) / CLOCKS_PER_SEC * 1000);
                }
            }
        }
    }
}

// Main function
int main() {
    int n = 5;
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    Record* records = (Record*)malloc(n * sizeof(Record));
    int* unionFindResults = (int*)malloc(n * sizeof(int));
