    if (!inputArray) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        free(unionFindResults);
        return 1;
    }

    printf("Enter integers (end with -1): ");
    int num = scanf("%d", &inputArray[0]);
    while (num == 1 && inputArray[num - 1] != -1) {
        num++;
        if (num > 256) {
            fprintf(stderr, "Input size exceeds limit\n");
            break;
        }
        num = scanf("%d", &inputArray[num - 1]);
