typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    time_t* timestamps;
    size_t count;
} data_store;

data_store* create_data_store(size_t size, unsigned int seed) {
    if (size == 0 || seed == 0) {
        return NULL;
    }

    data_store* store = malloc(sizeof(data_store));
    if (!store) {
        return NULL;
    }

    store->count = size;

    store->offsets = calloc(size, sizeof(long));
    if (!store->offsets) {
        goto cleanup;
    }

    store->keys = calloc(size, sizeof(int));
    if (!store->keys) {
        goto cleanup;
    }

    store->records = calloc(size, sizeof(record*));
    if (!store->records) {
        goto cleanup;
    }

    store->timestamps = calloc(size, sizeof(time_t));
    if (!store->timestamps) {
        goto cleanup;
    }

    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        store->offsets[i] = rand();
        store->keys[i] = rand();
        store->records[i] = malloc(sizeof(record));
        if (!store->records[i]) {
            goto cleanup;
        }
        store->records[i]->value = rand();
        store->timestamps[i] = time(NULL);
    }

    return store;

cleanup:
    free(store->offsets);
    free(store->keys);
    for (size_t i = 0; i < size; ++i) {
        free(store->records[i]);
    }
    free(store->records);
    free(store->timestamps);
    free(store);

    return NULL;
}
