// Function to seed the PRNG with a combination of environment variables and user-provided seed
std::mt19937 seedPRNG(int customSeed) {
    unsigned seed = std::hash<std::string>{}(std::to_string(customSeed) + std::to_string(std::time(nullptr))) ^
                     (customSeed * 123456789);
    return std::mt19937(seed);
}

// Function to select an attack with a cooldown of 9 seconds
void selectAttack(int customSeed = 0) {
    static std::mt19937 prng = seedPRNG(customSeed);
    static std::uniform_int_distribution<int> dist(1, 5); // Assuming there are 5 attacks
    static std::chrono::time_point<std::chrono::system_clock> lastAttackTime = std::chrono::system_clock::now();

    auto now = std::chrono::system_clock::now();
    if (now - lastAttackTime < std::chrono::seconds(9)) {
        return; // Cooldown period not yet over
    }

    int attackNumber = dist(prng);
    std::cout << "Selected Attack: " << attackNumber << std::endl;

    lastAttackTime = now;
}

int main() {
    selectAttack(); // Using default seed based on current time and user input
    return 0;
}
