void initializeRandomValues(int* sizes, void** arrays, int minVal, int maxVal) {
    srand(time(NULL));
    for (int i = 0; i < numArrays; i++) {
        switch (i) {
            case 0: // Seeds
                for (int j = 0; j < sizes[i]; j++) {
                    ((int*)arrays[i])[j] = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
            case 1: // Indices
                for (int j = 0; j < sizes[i]; j++) {
                    ((int*)arrays[i])[j] = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
            case 2: // Double data structures
                for (int j = 0; j < sizes[i]; j++) {
                    ((double*)arrays[i])[j] = (double)rand() / RAND_MAX * (maxVal - minVal) + minVal;
                }
                break;
            case 3: // Floating-point number lists
                for (int j = 0; j < sizes[i]; j++) {
                    ((float*)arrays[i])[j] = (float)rand() / RAND_MAX * (maxVal - minVal) + minVal;
                }
                break;
            case 4: // Integer lists
                for (int j = 0; j < sizes[i]; j++) {
                    ((int*)arrays[i])[j] = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
            case 5: // Long offset values
                for (int j = 0; j < sizes[i]; j++) {
                    ((long*)arrays[i])[j] = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
            case 6: // Keys
                for (int j = 0; j < sizes[i]; j++) {
                    ((int*)arrays[i])[j] = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
            case 7: // Record structures
                for (int j = 0; j < sizes[i]; j++) {
                    ((Record*)arrays[i])[j].value = (double)rand() / RAND_MAX * (maxVal - minVal) + minVal;
                    ((Record*)arrays[i])[j].key = rand() % (maxVal - minVal + 1) + minVal;
                }
                break;
        }
    }
}

void freeArrays(int numArrays, void** arrays) {
    for (int i = 0; i < numArrays; i++) {
        free(arrays[i]);
    }
}
