        offsets[i] = rand();
        keys[i] = rand() % 1000; // Adjust range as needed
        (*records)[i].value = rand() % 1000;
        (*records)[i].status = 'U';
    }
}

void find_and_print_largest(int *array, size_t count) {
    if (count == 0) {
        printf("No elements to compare.\n");
        return;
    }
    int largest = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void process_records(int *keys, record **records, size_t count, int *input_array, size_t input_count) {
    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < input_count; ++j) {
            if ((*records)[i].value == input_array[j]) {
                (*records)[i].status = 'P';
                break;
            }
        }
    }
}

int main() {
    size_t count = 1000000; // Example size
    long *offsets = (long *)malloc(count * sizeof(long));
    int *keys = (int *)malloc(count * sizeof(int));
