#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void generate_random_records(record *records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 1000; // Pseudo-random values between 0 and 999
    }
}

record* find_largest_record(record *records, int count) {
    record *largest = &records[0];
    for (int i = 1; i < count; i++) {
        if (records[i].value > largest->value) {
            largest = &records[i];
        }
    }
    return largest;
}

void log_memory_usage(int bytes_allocated, int bytes_freed) {
    static int total_bytes_allocated = 0;
    static int total_bytes_freed = 0;
    total_bytes_allocated += bytes_allocated;
    total_bytes_freed += bytes_freed;
    printf("Memory usage: %d bytes allocated, %d bytes freed, net %d bytes\n",
           total_bytes_allocated, total_bytes_freed,
           total_bytes_allocated - total_bytes_freed);
}

int main() {
    int count;
    printf("Enter the number of records: ");
    scanf("%d", &count);

    long *offsets = (long *)malloc(count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return 1;
    }
    log_memory_usage(count * sizeof(long), 0);

    int *keys = (int *)malloc(count * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        log_memory_usage(0, count * sizeof(long));
        return 1;
    }
    log_memory_usage(count * sizeof(int), 0);

    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        log_memory_usage(0, count * sizeof(long) + count * sizeof(int));
        return 1;
    }
    log_memory_usage(count * sizeof(record), 0);

    generate_random_records(records, count);

    record *largest_record = find_largest_record(records, count);
    printf("Largest record value: %d\n", largest_record->value);

    free(offsets);
    free(keys);
    free(records);
    log_memory_usage(-count * sizeof(long) - count * sizeof(int) - count * sizeof(record), 0);

    return 0;
}
```

