    int value;
} record;

// Function to initialize arrays and structures
void initialize_arrays(long **offsets, int **keys, record ***records, int **int_list, char ***file_paths) {
    *offsets = (long *)malloc(5 * sizeof(long));
    *keys = (int *)malloc(5 * sizeof(int));
    *records = (record **)malloc(5 * sizeof(record *));
    *int_list = (int *)malloc(5 * sizeof(int));
    *file_paths = (char **)malloc(5 * sizeof(char *));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *int_list == NULL || *file_paths == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize PRNG
    srand(time(NULL));
    for (int i = 0; i < 5; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100;
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record\n");
            exit(EXIT_FAILURE);
        }
        (*records)[i]->value = rand() % 1000;
    }

    // Read integers from standard input
    for (int i = 0; i < 5; i++) {
        scanf("%d", &(*int_list)[i]);
    }

    // Read file paths from standard input
    for (int i = 0; i < 5; i++) {
        (*file_paths)[i] = (char *)malloc(256 * sizeof(char));
        scanf("%s", (*file_paths)[i]);
    }
}

// Helper function to find the largest integer in an array
int find_largest(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function
int main() {
    long *offsets;
    int *keys, **records, *int_list, **file_paths;

    initialize_arrays(&offsets, &keys, &records, &int_list, &file_paths);

    // Print the largest integer in the array
    printf("Largest integer: %d\n", find_largest(int_list, 5));

    // Free allocated memory
    for (int i = 0; i < 5; i++) {
        free(records[i]);
        free(file_paths[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(int_list);
    free(file_paths);

    return 0;
}
