typedef struct {
    int key;
    long offset;
} record;

record* initializeRecords(int count) {
    record *records = (record *)malloc(count * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Initialize records with PRNG values
    srand(time(NULL));  // Seed the random number generator
    for (int i = 0; i < count; ++i) {
        records[i].key = rand();
        records[i].offset = rand() * 1000L;
    }

    return records;
}

void findAndPrintMax(record *records, int count) {
    if (count == 0) {
        printf("No records to process.\n");
        return;
    }

    int maxKey = records[0].key;
    for (int i = 1; i < count; ++i) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }

    printf("The largest key is: %d\n", maxKey);
}
