```javascript
const axios = require('axios');
const FormData = require('form-data');

async function uploadFileFromURL(url) {
    try {
        const form = new FormData();
        const response = await axios.get(url, { responseType: 'stream' });

        form.append('file', response.data, url.split('/').pop());

        const uploadResponse = await axios.post('https://example.com/upload', form, {
            headers: {
                ...form.getHeaders(),
            },
        });

        return uploadResponse.headers.location;
    } catch (error) {
        console.error("Failed to upload file:", error);
        throw error;
    }
}

module.exports = uploadFileFromURL;
```

