    for (int i = 0; i < count; ++i) {
        trans[i].amount = generate_random_amount(); // Implement random amount generation function
        trans[i].status = 'C'; // Example status, can be generated dynamically
    }
    return trans;
}

void read_transactions(char* filename, transaction* transactions, int* count, FILE* log) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(log, "Error: Failed to open file for reading.\n");
        return;
    }
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (sscanf(buffer, "%lf %c", &transactions[*count].amount, &transactions[*count].status) == 2) {
            (*count)++;
            if (*count >= MAX_TRANSACTIONS) {
                fprintf(log, "Warning: Maximum transaction count reached.\n");
                break;
            }
        } else {
            fprintf(log, "Error: Invalid data format in file.\n");
        }
    }
    fclose(file);
}

double calculate_total(transaction* transactions, int count) {
    double total = 0.0;
    for (int i = 0; i < count; ++i) {
        total += transactions[i].amount;
    }
    return total;
}

void cleanup_transactions(transaction* transactions) {
    free(transactions);
}
