void initializeTransactions(long* offsets, int* keys, Transaction** transactions, int numTransactions, long minAmount, long maxAmount, time_t startTime) {
    srand(time(0)); // Seed for pseudo-random number generator
    long seed = rand();

    for (int i = 0; i < numTransactions; i++) {
        offsets[i] = pseudoRandom(seed);
        keys[i] = pseudoRandom(seed) % 1000 + 1; // Assuming key range from 1 to 1000
        seed = pseudoRandom(seed);

        (*transactions)[i].transactionID = i;
        (*transactions)[i].amount = (pseudoRandom(seed) % (maxAmount - minAmount + 1)) + minAmount;
        if ((*transactions)[i].amount < minAmount || (*transactions)[i].amount > maxAmount) {
            (*transactions)[i].amount = minAmount + pseudoRandom(seed) % (maxAmount - minAmount + 1);
        }
        seed = pseudoRandom(seed);

        (*transactions)[i].timestamp = startTime + i * 60; // Assuming one minute interval
    }
}

int main() {
