typedef struct {
    int value;
} Record;

void manage_records(long *offsets, int *keys, Record **records, long offset_size) {
    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Invalid input pointers.\n");
        return;
    }

    // Allocate memory for offsets and keys
    if ((offsets = realloc(offsets, sizeof(long) * offset_size)) == NULL) {
        perror("Failed to allocate memory for offsets.");
        return;
    }
    if ((keys = realloc(keys, sizeof(int) * offset_size)) == NULL) {
        perror("Failed to allocate memory for keys.");
        free(offsets);
        return;
    }

    // Initialize PRNG with current time as seed
    srand(time(NULL));

    // Allocate and populate records
    Record *new_records = malloc(sizeof(Record) * offset_size);
    if (new_records == NULL) {
        perror("Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        return;
    }

    for (long i = 0; i < offset_size; ++i) {
        new_records[i].value = rand() % 1000000; // Pseudo-random number between 0 and 999,999
    }

    *records = new_records;

    printf("Records managed successfully.\n");
}

int main() {
    long initial_size = 10;
    long *offsets = NULL;
    int *keys = NULL;
    Record **records_ptr = NULL;

    manage_records(offsets, keys, records_ptr, initial_size);

    if (records_ptr != NULL && *records_ptr != NULL) {
        // Perform operations on records
        for (long i = 0; i < initial_size; ++i) {
            printf("Record %ld: %d\n", i, (*records_ptr)[i].value);
        }
        free(*records_ptr);
    }

    if (keys != NULL) {
        free(keys);
    }
    if (offsets != NULL) {
        free(offsets);
    }

    return 0;
}
