#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    int value;
    char* id;
    time_t timestamp;
} record;

record** create_records(int size, int min_value, int max_value, time_t min_time, time_t max_time) {
    record** records = (record**) malloc(size * sizeof(record*));
    if (!records) return NULL;

    for (int i = 0; i < size; i++) {
        records[i] = (record*) malloc(sizeof(record));
        if (!records[i]) {
            // Clean up previously allocated memory on failure
            for (int j = 0; j < i; j++) free(records[j]);
            free(records);
            return NULL;
        }

        // Initialize record fields using CSPRNG and timestamp
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        records[i]->id = (char*) malloc(20 * sizeof(char));
        sprintf(records[i]->id, "ID_%d", i);
        records[i]->timestamp = min_time + (rand() % ((long)(max_time - min_time) + 1));

    }

    return records;
}

void free_records(record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]->id);
        free(records[i]);
    }
    free(records);
}

int main() {
    srand(time(NULL)); // Seed CSPRNG

    int size = 10;
    record** records = create_records(size, 0, 100, time(NULL) - 3600, time(NULL));
    if (records) {
        for (int i = 0; i < size; i++) {
            printf("Record %d: Value=%d, ID=%s, Timestamp=%ld\n", i, records[i]->value, records[i]->id, records[i]->timestamp);
        }
        free_records(records, size);
    } else {
        fprintf(stderr, "Failed to allocate memory for records.\n");
    }

    return 0;
}
```

