#include <stdio.h>

typedef struct {
    int value;
} record;

int allocate_records(record** records, long* offsets, int* keys, int max_records, size_t memory_limit) {
    time_t current_time = time(NULL);
    unsigned int seed = (unsigned int)current_time;
    srand(seed);

    *records = malloc(max_records * sizeof(record));
    if (*records == NULL) {
        log_error("Failed to allocate records");
        return -1;
    }

    offsets = malloc(max_records * sizeof(long));
    if (offsets == NULL) {
        log_error("Failed to allocate offsets");
        free(*records);
        return -1;
    }

    keys = malloc(max_records * sizeof(int));
    if (keys == NULL) {
        log_error("Failed to allocate keys");
        free(*records);
        free(offsets);
        return -1;
    }

    size_t total_memory = max_records * sizeof(record) + max_records * sizeof(long) + max_records * sizeof(int);
    if (total_memory > memory_limit) {
        log_warning("Memory limit exceeded");
        free(*records);
        free(offsets);
        free(keys);
        return -1;
    }

    for (int i = 0; i < max_records; i++) {
        (*records)[i].value = rand_r(&seed) % 100; // Random value between 0 and 99
        offsets[i] = i * sizeof(record); // Simplified offset calculation
        keys[i] = seed % 1000; // Random key between 0 and 999
    }

    log_info("Records initialized with seed: %u, total records: %d", seed, max_records);

    return max_records;
}

void free_records(record* records, long* offsets, int* keys) {
    if (records != NULL) {
        free(records);
    }
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
}

void log_info(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

void log_warning(const char* format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "WARNING: ");
    vprintf(format, args);
    va_end(args);
}

void log_error(const char* format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "ERROR: ");
    vprintf(format, args);
    va_end(args);
}
