    *records1 = allocate_memory(count * sizeof(record));
    *records2 = allocate_memory(count * sizeof(record));
    *inputs = allocate_memory(count * sizeof(int));

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand() % range;
        (*keys)[i] = rand() % range;
        (*records1)[i].value = rand() % range;
        (*records2)[i].value = rand() % range;
        (*inputs)[i] = rand() % range;

