    *timestamps = (long*)malloc(array_size * sizeof(long));
    *sensor_readings = (float*)malloc(array_size * sizeof(float));

    if (*timestamps == NULL || *sensor_readings == NULL) {
        log_message("Memory allocation failed.");
        exit(1);
    }

    srand(time(NULL));
    for (int i = 0; i < array_size; i++) {
        (*timestamps)[i] = start_time + i * time_increment;
        (*sensor_readings)[i] = ((float)rand() / RAND_MAX) * 100.0 - 50.0; // Pseudo-random value between -50 and 50
    }
}

void read_and_calculate(float* sensor_readings, int array_size) {
    float sum = 0;
    float sum_of_squares = 0;

    for (int i = 0; i < array_size; i++) {
        scanf("%f", &sensor_readings[i]);
        sum += sensor_readings[i];
        sum_of_squares += sensor_readings[i] * sensor_readings[i];
    }

    float average = sum / array_size;
    float variance = sum_of_squares / array_size - average * average;
    float standard_deviation = sqrt(variance);

    printf("Average: %.2f\n", average);
    printf("Standard Deviation: %.2f\n", standard_deviation);
}

void moving_average_filter(float* sensor_readings, int array_size, int window_size) {
    float sum = 0;
    for (int i = 0; i < window_size; i++) {
        sum += sensor_readings[i];
    }

    printf("Moving Average: %.2f\n", sum / window_size);

    for (int i = window_size; i < array_size; i++) {
        sum -= sensor_readings[i - window_size];
        sum += sensor_readings[i];
        printf("Moving Average at time %d: %.2f\n", i * 10, sum / window_size);
    }
}

void network_protocol(float* sensor_readings, int array_size) {
    // Custom network protocol implementation
}

int main() {
    int array_size = 1000;
    float* timestamps;
    float* sensor_readings;

    initialize_arrays(1633072800L, 10L, array_size, &timestamps, &sensor_readings);

    read_and_calculate(sensor_readings, array_size);

    moving_average_filter(sensor_readings, array_size, 50);

    network_protocol(sensor_readings, array_size);

    free(timestamps);
    free(sensor_readings);

    return 0;
}
