    for (int i = 0; i < 100; i++) {
        timestamp[i] = rand();
    }

    // Log initialization process
    printf("Timestamps initialized successfully\n");

    // Free allocated memory
    free(timestamp);
    free(uniqueID);
    free(inputList);
}

// Helper function to calculate the median of an array
double findMedian(int* arr, int size) {
    // Sort the array
    qsort(arr, size, sizeof(int), (int(*)(const void*, const void*))strcmp);

    // Calculate and return the median
    if (size % 2 != 0) {
        return (double)arr[size / 2];
    } else {
        return ((double)(arr[(size - 1) / 2] + arr[size / 2])) / 2.0;
    }
}

// Main function to execute the task
int main() {
    // Initialize arrays with pseudo-random timestamps
    initializeArrays();

    // Read integers from standard input and find the median
    int input, count = 0;
    while (scanf("%d", &input) != EOF) {
        inputList[count++] = input;
    }

    double median = findMedian(inputList, count);
    printf("Median value: %f\n", median);

    return 0;
}
