BatchData* createBatchData(size_t max_batches, size_t batch_size) {
    BatchData* data = (BatchData*)malloc(sizeof(BatchData));
    if (!data) return NULL;

    data->offsets = (long*)malloc(max_batches * batch_size * sizeof(long));
    data->keys = (int*)malloc(max_batches * batch_size * sizeof(int));
    data->records = (Record*)malloc(max_batches * batch_size * sizeof(Record));
    data->identifiers = (char**)malloc(max_batches * batch_size * sizeof(char*));

    if (!data->offsets || !data->keys || !data->records || !data->identifiers) {
        free(data);
        return NULL;
    }

    data->total_records = max_batches * batch_size;
    data->current_index = 0;

    srand(time(NULL)); // Initialize PRNG seed

    for (size_t i = 0; i < data->total_records; ++i) {
        data->offsets[i] = i;
        data->keys[i] = (int)i;

        Record* rec = &data->records[i];
        rec->value = rand() % 1000; // Random value between 0 and 999
        snprintf(rec->buffer, sizeof(rec->buffer), "prefix_%d", data->keys[i]);
        rec->identifier = rec->buffer;

        char* identifier = (char*)malloc(20); // Allocate memory for identifier
        if (!identifier) {
            freeBatchData(data);
            return NULL;
        }
        snprintf(identifier, 20, "prefix_%d", data->keys[i]);
        data->identifiers[i] = identifier;
    }

    return data;
}

void freeBatchData(BatchData* data) {
    for (size_t i = 0; i < data->total_records; ++i) {
        free((char*)data->records[i].buffer); // Free buffer
        free((char*)data->identifiers[i]); // Free identifier
    }

    free(data->offsets);
    free(data->keys);
    free(data->records);
    free(data->identifiers);
    free(data);
}
