#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    char* identifier;
} record;

void init_random() {
    srand(time(NULL));
}

long* create_offset_array(int size) {
    return (long*)calloc(size, sizeof(long));
}

int* create_key_array(int size) {
    return (int*)calloc(size, sizeof(int));
}

record* create_record_array(int size) {
    record* records = (record*)calloc(size, sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i].value = rand();
        records[i].identifier = NULL;
    }
    return records;
}

char** create_identifier_pool(int size) {
    char** pool = (char**)malloc(size * sizeof(char*));
    for (int i = 0; i < size; i++) {
        pool[i] = (char*)malloc(16 * sizeof(char)); // Example fixed-size buffer
    }
    return pool;
}

void fill_arrays(long* offsets, int* keys, record* records, char** identifiers, int size) {
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = i;
        records[i].value = rand() % MAX_RECORDS; // Random value within range
        if (identifiers[i]) {
            sprintf(records[i].identifier, "ID_%d", i);
        }
    }
}

data_struct* allocate_data_structure(int size) {
    data_struct* ds = (data_struct*)malloc(sizeof(data_struct));
    ds->offsets = create_offset_array(size);
    ds->keys = create_key_array(size);
    ds->records = create_record_array(size);
    ds->identifiers = create_identifier_pool(size);
    return ds;
}

void deallocate_data_structure(data_struct* ds, int size) {
    for (int i = 0; i < size; i++) {
        free(ds->records[i].identifier);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->identifiers);
    free(ds);
}

// Thread-safe function to handle concurrent calls
data_struct* allocate_data_structure_thread_safe(int size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    data_struct* ds = allocate_data_structure(size);
    if (!ds) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    fill_arrays(ds->offsets, ds->keys, ds->records, ds->identifiers, size);
    pthread_mutex_unlock(&mutex);
    return ds;
}

void log_performance_metrics(data_struct* ds, int size) {
    // Placeholder for performance logging
    printf("Memory usage: %ld bytes\n", sizeof(*ds) + size * (sizeof(long) + sizeof(int) + sizeof(record) + 16));
}

// Example usage
int main() {
    init_random();
    data_struct* ds = allocate_data_structure_thread_safe(MAX_RECORDS);
    if (ds) {
        log_performance_metrics(ds, MAX_RECORDS);
        deallocate_data_structure(ds, MAX_RECORDS);
    }
    return 0;
}
