#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MIN_DESCRIPTION_LENGTH 10
#define MAX_DESCRIPTION_LENGTH 256

typedef struct {
    unsigned long id;
    int status_code;
    char* description;
} transaction;

void log_message(const char* message) {
    // External logging mechanism integration here
    printf("Log: %s\n", message);
}

char* generate_description(int length) {
    const char characters[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    char* description = (char*)malloc(length * sizeof(char));
    if (!description) {
        log_message("Failed to allocate memory for transaction description.");
        return NULL;
    }
    for (int i = 0; i < length - 1; i++) {
        description[i] = characters[rand() % (sizeof(characters) - 1)];
    }
    description[length - 1] = '\0';
    return description;
}

void initialize_transactions(transaction** transactions, int count, int min_length, int max_length) {
    srand(time(NULL));
    *transactions = (transaction*)malloc(count * sizeof(transaction));
    if (!*transactions) {
        log_message("Failed to allocate memory for transaction array.");
        return;
    }
    for (int i = 0; i < count; i++) {
        (*transactions)[i].id = rand();
        (*transactions)[i].status_code = rand() % 256;
        int length = min_length + rand() % (max_length - min_length + 1);
        (*transactions)[i].description = generate_description(length);
        if (!(*transactions)[i].description) {
            for (int j = 0; j < i; j++) {
                free((*transactions)[j].description);
            }
            free(*transactions);
            *transactions = NULL;
            return;
        }
    }
}

void clean_transactions(transaction* transactions, int count) {
    if (!transactions) return;
    for (int i = 0; i < count; i++) {
        free(transactions[i].description);
    }
    free(transactions);
}

// Example usage
int main() {
    transaction* my_transactions = NULL;
    initialize_transactions(&my_transactions, 10, MIN_DESCRIPTION_LENGTH, MAX_DESCRIPTION_LENGTH);
    if (my_transactions) {
        // Use the transactions...
        clean_transactions(my_transactions, 10);
    }
    return 0;
}
