// Define the sensorData structure
typedef struct {
    int seed;
    long timestamp;
    double measurement;
} sensorData;

// Function to initialize sensor data
void initializeSensorData(sensorData** data, int size) {
    // Allocate memory for seed values
    (*data)->seed = malloc(size * sizeof(int));
    if ((*data)->seed == NULL) {
        fprintf(stderr, "Failed to allocate memory for seed values\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for timestamps
    (*data)->timestamp = malloc(size * sizeof(long));
    if ((*data)->timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamps\n");
        free((*data)->seed);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for sensor measurements
    (*data)->measurement = malloc(size * sizeof(double));
    if ((*data)->measurement == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensor measurements\n");
        free((*data)->seed);
        free((*data)->timestamp);
        exit(EXIT_FAILURE);
    }

    // Initialize seed values using a non-cryptographic PRNG
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*data)->seed[i] = rand();
    }

    // Populate timestamps with current timestamps
    for (int i = 0; i < size; i++) {
        (*data)->timestamp[i] = time(NULL);
    }
}

// Function to calculate average and standard deviation of sensor readings
void calculateStats(sensorData* data, int size) {
    double sum = 0.0;
    double variance = 0.0;

    for (int i = 0; i < size; i++) {
        sum += data[i].measurement;
    }

    double average = sum / size;

    for (int i = 0; i < size; i++) {
        variance += pow(data[i].measurement - average, 2);
    }

    variance /= size;

    printf("Average: %f\n", average);
    printf("Standard Deviation: %f\n", sqrt(variance));
}

int main() {
    int size = 10; // Example size
    sensorData* data;
    data = malloc(sizeof(sensorData) * size);

    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensorData structure\n");
        exit(EXIT_FAILURE);
    }

    initializeSensorData(&data, size);

    // Read sensor measurements from a file
    FILE* file = fopen("sensor_data.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open sensor_data.txt\n");
        free(data->seed);
        free(data->timestamp);
        free(data->measurement);
        free(data);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; i++) {
        fscanf(file, "%lf", &data[i].measurement);
    }

    fclose(file);

    calculateStats(data, size);

    // Free allocated memory
    free(data->seed);
    free(data->timestamp);
    free(data->measurement);
    free(data);

    return 0;
}
