    }
    clock_t start_time, end_time;
    start_time = clock();
    for(int i = 0; i < size - 1; ++i) {
        int x = rand() % size;
        int y = rand() % size;
        while(x == y) y = rand() % size;
        if(find(parent, x) != find(parent, y)) {
            union_sets(parent, x, y);
        }
    }
    end_time = clock();
    printf("Time taken for Union-Find: %ld milliseconds\n", (end_time - start_time) * 1000 / CLOCKS_PER_SEC);

    // Concurrent write operation to persistent storage
    // This part requires handling file I/O and synchronization, not shown here

    free_memory(records);
    free_memory(numbers);
    free_memory(parent);
    return 0;
}

int find(int parent[], int i) {
    if(parent[i] != i)
        parent[i] = find(parent, parent[i]);
    return parent[i];
}

void union_sets(int parent[], int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);
    if(rootX != rootY)
        parent[rootX] = rootY;
