int initialize_data_structures(long* offsets, int* keys, Record** records, int size) {
    if (size > MAX_SIZE) {
        printf("Error: Size exceeds maximum limit.\n");
        return -1; // Insufficient memory
    }

    srand(time(NULL)); // Initialize PRNG with current time for randomness

    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));
    records = malloc(size * sizeof(Record*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Memory allocation failed.\n");
        return -1; // Insufficient memory
    }

    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 100 + 1;
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Error: Memory allocation failed.\n");
            return -1; // Insufficient memory
        }
        records[i]->value = rand() % 256;
        records[i]->identifier = 'A' + rand() % 26;
    }

    printf("Data structures initialized successfully.\n");
    return 0; // Success
}

int main() {
    long* offsets;
    int* keys;
    Record** records;

