int resolveHostname(const char* hostname, u_char** ipAddress) {
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    p = res;
    struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
    *ipAddress = malloc(INET_ADDRSTRLEN);
    inet_ntop(p->ai_family, ipv4->sin_addr, (char*)*ipAddress, INET_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

long* getOffsetArray(int length) {
    long* offsets = (long*)malloc(length * sizeof(long));
    for (int i = 0; i < length; i++) {
        offsets[i] = i * 8; // Example offset calculation
    }
    return offsets;
}

int* getKeyArray(int length, int minValue, int maxValue) {
    int* keys = (int*)malloc(length * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
    }
    return keys;
}

record* getRecordArray(int length, int rangeMin, int rangeMax) {
