        indices[i] = rand() % MAX_SIZE;
        data_structures[i].value = ((double)rand() / RAND_MAX) * 100.0;
        float_list = realloc(float_list, (i + 1) * sizeof(double));
        float_list[i] = ((double)rand() / RAND_MAX) * 100.0;
        prng_list = realloc(prng_list, (i + 1) * sizeof(int));
        prng_list[i] = rand();
        timestamps[i] = time(NULL);
        offset_values[i] = rand() % MAX_SIZE;
        key_values[i] = rand() % MAX_SIZE;
        records[i].key = key_values[i];
        records[i].id = 'A' + (rand() % 26);
        timestamp_list = realloc(timestamp_list, (i + 1) * sizeof(timestamp));
        timestamp_list[i].timestamp = time(NULL);
    }

    // Free allocated memory
    free(seed_values);
    free(indices);
    free(data_structures);
    free(float_list);
    free(prng_list);
    free(timestamps);
    free(offset_values);
    free(key_values);
    free(records);
    free(timestamp_list);

    return 0;
}
