int initialize_records(int num_records, int seed, int **records_ptr) {
    // Allocate memory for records
    record *records = (record *)malloc(num_records * RECORD_SIZE);
    if (!records) {
        perror("Failed to allocate memory");
        return -1;
    }

    // Seed the PRNG
