        records[i].value = rand();
        records[i].weight = (float)rand() / RAND_MAX;
        records[i].offset = NULL; // Initialize offset to NULL
        records[i].key = i;

        // Log record initialization
        printf("Record %d: value=%d, weight=%.2f, key=%d\n", i, records[i].value, records[i].weight, records[i].key);
    }

    *records_ptr = records;
    return 0;
}

void free_records(record *records, int num_records) {
    // Free the allocated memory for each record
    for (int i = 0; i < num_records; ++i) {
        if (records[i].offset != NULL) {
            free(records[i].offset);
        }
    }

    // Free the records array itself
    free(records);
}

void *process_chunk(void *arg) {
    chunk_data *chunk_info = (chunk_data *)arg;
    record *records = chunk_info->records;
    int start_index = chunk_info->start_index;
    int end_index = chunk_info->end_index;

    // Process each record in the chunk
    for (int i = start_index; i < end_index; ++i) {
        // Example processing: calculate checksum of value and weight
        int checksum = records[i].value + (int)(records[i].weight * 100);

        // Log processing result
        printf("Processed record %d, checksum=%d\n", i, checksum);
    }

    return NULL;
}

int main() {
    int num_records = 10000;
    int seed = time(NULL);
    record *records;

    // Initialize records
    if (initialize_records(num_records, seed, &records) != 0) {
        fprintf(stderr, "Failed to initialize records\n");
        return 1;
    }

    // Example chunked processing with 4 threads
    pthread_t threads[4];
    int chunk_size = num_records / 4;

    for (int i = 0; i < 4; ++i) {
        chunk_data chunk_info = {records, i * chunk_size, (i + 1) * chunk_size};
        if (pthread_create(&threads[i], NULL, process_chunk, &chunk_info) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free records
    free_records(records, num_records);

    return 0;
}
