void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long find_min(double* array, int size) {
    long min_val = (long)array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] < min_val) {
            min_val = (long)array[i];
        }
    }
    return min_val;
}

void union_find(int* parent, int n) {
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
    }

    for (int i = 1; i < n; ++i) {
        int x = parent[i];
        int y = parent[i - 1];

        while (x != parent[x]) {
            x = parent[x];
        }
        while (y != parent[y]) {
            y = parent[y];
        }

        if (x == y) continue;

        parent[x] = y;
    }
}

void log_init() {
