#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define data structures and types
typedef struct {
    double value;
} Data;

typedef struct {
    int key;
} Record;

void logMessage(const char* message) {
    // Simulate logging mechanism
    printf("Log: %s\n", message);
}

double findSmallestNumber(double* array, size_t size) {
    if (size == 0) return -1.0; // Handle empty array case
    double smallest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] < smallest) smallest = array[i];
    }
    return smallest;
}

void initializeArrays(int numVertices, int numEdges) {
    if (numVertices > 1000 || numEdges > 5000) {
        logMessage("Error: Exceeds maximum number of vertices or edges.");
        return;
    }

    // Dynamically allocate memory for arrays
    long* seedValues = malloc(numVertices * sizeof(long));
    int* indices = malloc(numVertices * sizeof(int));
    Data* dataStructures = malloc(numVertices * sizeof(Data));
    double* floatArray = (double*)malloc(5000 * sizeof(double)); // Fixed size for simplicity

    if (!seedValues || !indices || !dataStructures || !floatArray) {
        logMessage("Error: Memory allocation failed.");
        return;
    }

    // Initialize data structures with pseudo-random values
    srand(time(NULL));
    for (int i = 0; i < numVertices; ++i) {
        seedValues[i] = rand();
        indices[i] = i;
        dataStructures[i].value = ((double)(rand()) / RAND_MAX) * (10.0 - (-10.0)) + (-10.0);
    }

    // Read floating-point numbers from standard input
    for (int i = 0; i < 5000; ++i) {
        if (!scanf("%lf", &floatArray[i])) {
            logMessage("Error: Failed to read float values from input.");
            free(seedValues);
            free(indices);
            free(dataStructures);
            free(floatArray);
            return;
        }
    }

    // Find and print the smallest floating-point number
    double smallestNumber = findSmallestNumber(floatArray, 5000);
    printf("Smallest Number: %f\n", smallestNumber);

    // Free allocated memory
    free(seedValues);
    free(indices);
    free(dataStructures);
    free(floatArray);
}

int main() {
    int numVertices, numEdges;
    printf("Enter number of vertices and edges: ");
    if (scanf("%d %d", &numVertices, &numEdges) != 2) {
        logMessage("Error: Invalid input for vertices and edges.");
        return 1;
    }

    initializeArrays(numVertices, numEdges);
    return 0;
}
```

