#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    time_t timestamp;
    int id;
} record;

long* offset_array;
int* key_array;
record** record_array;
size_t array_size = 1024; // Initial size
size_t current_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void expand_arrays() {
    array_size *= 2;
    long* new_offset = realloc(offset_array, array_size * sizeof(long));
    int* new_key = realloc(key_array, array_size * sizeof(int));
    record** new_record = realloc(record_array, array_size * sizeof(record*));

    if (!new_offset || !new_key || !new_record) {
        perror("Failed to expand arrays");
        exit(EXIT_FAILURE);
    }

    offset_array = new_offset;
    key_array = new_key;
    record_array = new_record;
}

void initialize_arrays() {
    offset_array = malloc(array_size * sizeof(long));
    key_array = malloc(array_size * sizeof(int));
    record_array = malloc(array_size * sizeof(record*));

    if (!offset_array || !key_array || !record_array) {
        perror("Failed to allocate initial arrays");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed PRNG
}

void add_record(long offset, int key, time_t timestamp, int id) {
    pthread_mutex_lock(&lock);

    if (current_size == array_size) {
        expand_arrays();
    }

    offset_array[current_size] = offset;
    key_array[current_size] = key;

    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    new_record->value = id; // Example value, modify as needed
    new_record->timestamp = timestamp;
    new_record->id = id;

    record_array[current_size] = new_record;
    current_size++;

    pthread_mutex_unlock(&lock);
}

void free_memory() {
    for (size_t i = 0; i < current_size; i++) {
        free(record_array[i]);
    }

    free(offset_array);
    free(key_array);
    free(record_array);

    pthread_mutex_destroy(&lock);
}
