    // Allocate memory for arrays
    *timestamps = (long *)malloc(num_records * sizeof(long));
    *status_codes = (int *)malloc(num_records * sizeof(int));
    *records = (Record *)malloc(num_records * sizeof(Record));
    *keys = (char **)malloc(num_records * sizeof(char *));

    if (*timestamps == NULL || *status_codes == NULL || *records == NULL || *keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and records
    for (int i = 0; i < num_records; ++i) {
        (*timestamps)[i] = generate_timestamp_id();
        (*status_codes)[i] = rand() % 100; // Example status code
        (*records)[i].data = NULL;
        (*records)[i].key = NULL;

        // Allocate memory for record data and key
        (*records)[i].data = (char *)malloc(256 * sizeof(char)); // Assume maximum string length of 255 characters + null terminator
        (*keys)[i] = (char *)malloc(33 * sizeof(char)); // Assume key length of 32 bytes + null terminator

        if ((*records)[i].data == NULL || (*keys)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Populate record data with a unique string
        sprintf((*records)[i].data, "Record_%ld", (*timestamps)[i]);

        // Initialize key using secure random number generator (example)
        for (int j = 0; j < 32; ++j) {
            (*keys)[i][j] = 'a' + rand() % ('z' - 'a' + 1); // Simple ASCII character generation
        }
        (*keys)[i][32] = '\0';
    }
}

// Function to free allocated memory
void free_memory(long *timestamps, int *status_codes, Record *records, char **keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].data != NULL) {
            free(records[i].data);
        }
        if (keys[i] != NULL) {
            free(keys[i]);
        }
    }
    free(timestamps);
    free(status_codes);
    free(records);
    free(keys);
}

int main() {
    int num_records = 5;
    long *timestamps = NULL;
    int *status_codes = NULL;
    Record *records = NULL;
    char **keys = NULL;

    // Initialize arrays and records
    init_arrays(&timestamps, &status_codes, &records, &keys, num_records);

    // Print results (for demonstration purposes)
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Timestamp=%ld, Status=%d, Data=%s, Key=%s\n", 
               i, timestamps[i], status_codes[i], records[i].data, keys[i]);
    }

    // Free allocated memory
    free_memory(timestamps, status_codes, records, keys, num_records);

    return 0;
}
