        offsets[i] = (long *)malloc(sizeof(long));
        keys[i] = (int *)malloc(sizeof(int));

        if (!timestamps[i] || !statusCodes[i] || !records[i] || !offsets[i] || !keys[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }

        // Initialize arrays
        *timestamps[i] = time(NULL);
        *statusCodes[i] = rand() % 256; // Random status code between 0 and 255
        records[i]->data = (char *)malloc(32); // Allocate memory for char buffer
        if (!records[i]->data) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }
        sprintf(records[i]->data, "%d", rand()); // Generate unique string using PRNG
        *offsets[i] = (long)(rand() % 100); // Random offset value between 0 and 99
        *keys[i] = rand() % 100; // Random key value between 0 and 99
    }
}

// Function to clean up allocated memory
void cleanup(long **timestamps, int **statusCodes, Record **records, long **offsets, int **keys, int count) {
    for (int i = 0; i < count; i++) {
        free(timestamps[i]);
        free(statusCodes[i]);
        if (records[i] && records[i]->data) {
            free(records[i]->data);
        }
        free(offsets[i]);
        free(keys[i]);
    }
}

