    int *statusCodes[count];
    Record *records[count];
    long *offsets[count];
    int *keys[count];

    initArrays(timestamps, statusCodes, records, offsets, keys, count);

    // Use the arrays...

    cleanup(timestamps, statusCodes, records, offsets, keys, count);
    return 0;
}
