#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/time.h>

typedef struct {
    time_t timestamp;
    int id;
    long offset;
} record;

record* create_records(int num_records, int min_timestamp, int max_timestamp) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));
    int* used_timestamps = (int*)calloc(max_timestamp - min_timestamp + 1, sizeof(int));
    if (!used_timestamps) {
        perror("Failed to allocate memory for timestamp tracker");
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        time_t timestamp;
        do {
            timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp + 1);
        } while (used_timestamps[timestamp - min_timestamp]);
        used_timestamps[timestamp - min_timestamp] = 1;

        records[i].timestamp = timestamp;
        records[i].id = i; // Using index as unique identifier for simplicity
        records[i].offset = rand() % 1000L; // Generating random offset
    }

    free(used_timestamps);
    return records;
}

void print_largest(int* arr, int size) {
    if (size == 0) {
        printf("Empty array.\n");
        return;
    }

    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void simulate_network_latency(int num_records, int latency_factor) {
    struct timeval delay;
    delay.tv_sec = 0;
    delay.tv_usec = num_records * latency_factor * 1000; // Convert to microseconds
    select(0, NULL, NULL, NULL, &delay);
}

int main(int argc, char* argv[]) {
    int num_records = 1000;
    int min_timestamp = 1630456800; // Example start timestamp (January 1, 2022)
    int max_timestamp = 1664739200; // Example end timestamp (December 31, 2022)

    record* records = create_records(num_records, min_timestamp, max_timestamp);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Simulate network latency
    int latency_factor = 1000; // microseconds per record
    simulate_network_latency(num_records, latency_factor);

    int* input_array = (int*)malloc(num_records * sizeof(int));
    if (!input_array) {
        perror("Failed to allocate memory for input array");
        free(records);
        return EXIT_FAILURE;
    }

    // Read integers from standard input and validate
    int valid_count = 0;
    printf("Enter integers within the range [%d, %d]:\n", min_timestamp, max_timestamp);
    while (valid_count < num_records) {
        int value;
        if (scanf("%d", &value) != 1 || value < min_timestamp || value > max_timestamp) {
            printf("Invalid input. Please enter a valid integer within the specified range.\n");
            continue;
        }
        input_array[valid_count++] = value;
    }

    print_largest(input_array, valid_count);

    free(records);
    free(input_array);

    return EXIT_SUCCESS;
}
