    int i;
    long* seeds = allocateSeeds(NUM_SEEDS);
    int* indices = allocateIndices(NUM_INDICES);
    Data* dataStructs = allocateDataStructures(NUM_INDICES, 0.0, 1.0);
    float* floats = readFloatsFromStdin(NULL);
    int* randomIntegers = generateRandomIntegers(5, time(NULL));

    // Example usage of the allocated arrays
    for (i = 0; i < NUM_INDICES; i++) {
        printf("Data Struct %d: Value = %f\n", i, dataStructs[i].value);
    }

    // Free allocated memory
    free(seeds);
    free(indices);
    free(dataStructs);
    free(floats);
    free(randomIntegers);

    return 0;
}

// Helper functions
long* allocateSeeds(int count) {
    long* array = (long*)malloc(count * sizeof(long));
    if (!array) {
        logInitializationWarning("Failed to allocate memory for seeds");
    }
    return array;
}

int* allocateIndices(int count) {
    int* array = (int*)calloc(count, sizeof(int));
    if (!array) {
        logInitializationWarning("Failed to allocate memory for indices");
    }
    return array;
}

Data* allocateDataStructures(int count, double minVal, double maxVal) {
    Data* array = (Data*)malloc(count * sizeof(Data));
    if (!array) {
        logInitializationWarning("Failed to allocate memory for data structures");
    } else {
        srand(time(NULL)); // Seed the random number generator
        for (int i = 0; i < count; i++) {
            array[i].value = minVal + (double)rand() / RAND_MAX * (maxVal - minVal);
        }
    }
    return array;
}

float* readFloatsFromStdin(int *count) {
    printf("Enter the number of floating-point numbers: ");
    scanf("%d", count);
    float* array = (float*)malloc(*count * sizeof(float));
    if (!array) {
        logInitializationWarning("Failed to allocate memory for floats");
    } else {
        printf("Enter %d floating-point numbers:\n", *count);
        for (int i = 0; i < *count; i++) {
            scanf("%f", &array[i]);
        }
    }
    return array;
}

int* generateRandomIntegers(int count, long seed) {
    srand(seed); // Seed the random number generator
    int* array = (int*)malloc(count * sizeof(int));
    if (!array) {
        logInitializationWarning("Failed to allocate memory for random integers");
    } else {
        for (int i = 0; i < count; i++) {
            array[i] = rand();
        }
    }
    return array;
}

void logInitializationWarning(const char* message) {
    fprintf(stderr, "WARNING: %s\n", message);
}
