typedef struct {
    long interval;
    int identifier;
    EventRecord records[MAX_EVENTS];
    int count;
} MemoryManager;

uint32_t custom_prng(uint32_t state) {
    return (state * 1664525 + 1013904223) % UINT32_MAX;
}

void init_memory_manager(MemoryManager *mm, long interval, int identifier) {
    mm->interval = interval;
    mm->identifier = identifier;
    mm->count = 0;
    srand(time(NULL));
}

void add_event(MemoryManager *mm, time_t timestamp, int event_type) {
    if (mm->count < MAX_EVENTS) {
        mm->records[mm->count].timestamp = timestamp;
        mm->records[mm->count].event_type = event_type;
        mm->count++;
    }
}

void populate_random_events(MemoryManager *mm, int num_events) {
    uint32_t state = time(NULL);
    for (int i = 0; i < num_events; i++) {
        time_t timestamp = custom_prng(state);
        int event_type = rand() % 100;
        add_event(mm, timestamp, event_type);
    }
}

int get_event_count(MemoryManager *mm) {
    return mm->count;
}
