// PRNG functions
unsigned int prng_seed = 0;

void seed_prng() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    prng_seed = (unsigned int)(ts.tv_sec ^ ts.tv_nsec);
}

int next_random(int min, int max) {
    prng_seed = prng_seed * 1664525 + 1013904223;
    return min + (prng_seed >> 16) % (max - min + 1);
}

// Event generation and memory management
void generate_event(EventRecord* record, Metadata* metadata) {
    time_t current_time = time(NULL);
    record->timestamp = current_time;
    metadata->event_type = next_random(1, 5); // Assuming 5 event types
}

void log_memory_operation(const char* operation, size_t size) {
    printf("%s: %zu bytes\n", operation, size);
}

// Data export functions
void export_data_to_file(const EventRecord* records, Metadata* metadata, int count, const char* filename, const char* format) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    if (format[0] == 'b') {
        // Binary format
        fwrite(records, sizeof(EventRecord), count, file);
        fwrite(metadata, sizeof(Metadata), count, file);
    } else if (format[0] == 'c') {
        // CSV format
        for (int i = 0; i < count; i++) {
            fprintf(file, "%ld,%d\n", records[i].timestamp, metadata[i].event_type);
