#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double amount;
    char status;
} transaction;

transaction* init_transactions(int count, int min_amount, int max_amount, time_t* timestamps) {
    transaction* trans = (transaction*)malloc(count * sizeof(transaction));
    if (!trans) {
        fprintf(stderr, "Memory allocation failed for transactions\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < count; ++i) {
        trans[i].amount = min_amount + ((double)rand() / RAND_MAX * (max_amount - min_amount));
        trans[i].status = 'A'; // Initialize status to 'Active'
        timestamps[i] = time(NULL); // Record the current time as timestamp
    }

    return trans;
}

int check_transactions(transaction* trans, int count, int* input_amounts) {
    for (int i = 0; i < count; ++i) {
        if (trans[i].amount == input_amounts[i]) {
            printf("Match\n");
        } else {
            printf("No Match\n");
        }
    }

    return 0;
}

void validate_timestamps(time_t* timestamps, int count, time_t current_time) {
    for (int i = 0; i < count; ++i) {
        if (timestamps[i] > current_time) {
            printf("Inconsistent\n");
            return;
        }
    }

    printf("Consistent\n");
}

int main() {
    int count, min_amount, max_amount;
    printf("Enter the number of transactions: ");
    scanf("%d", &count);

    printf("Enter the minimum and maximum amount range: ");
    scanf("%d %d", &min_amount, &max_amount);

    time_t* timestamps = (time_t*)malloc(count * sizeof(time_t));
    if (!timestamps) {
        fprintf(stderr, "Memory allocation failed for timestamps\n");
        return 1;
    }

    transaction* trans = init_transactions(count, min_amount, max_amount, timestamps);
    if (!trans) {
        free(timestamps);
        return 1;
    }

    int* input_amounts = (int*)malloc(count * sizeof(int));
    printf("Enter %d transaction amounts:\n", count);
    for (int i = 0; i < count; ++i) {
        scanf("%d", &input_amounts[i]);
    }

    check_transactions(trans, count, input_amounts);

    time_t current_time = time(NULL);
    validate_timestamps(timestamps, count, current_time);

    free(trans);
    free(input_amounts);
    free(timestamps);

    return 0;
}
