    char string[256];
};

void* allocate_memory(int type, size_t count) {
    void* memory = malloc(type * count);
    if (memory == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return memory;
}

void initialize_record(struct record* record, int min, int max) {
    srand(time(NULL));
    record->value = rand() % (max - min + 1) + min;
}

void initialize_item(struct item* item, float min, float max) {
    srand(time(NULL));
    item->number = ((float)rand() / RAND_MAX) * (max - min) + min;
    strcpy(item->string, "example");
}

void* init_arrays(int types[], int counts[]) {
    void** arrays = allocate_memory(void*, MAX_ARRAYS);
    for (int i = 0; i < MAX_ARRAYS; i++) {
        if (types[i] == 1) { // int key
            arrays[i] = allocate_memory(int, counts[i]);
        } else if (types[i] == 2) { // record structure with a single int value
            arrays[i] = allocate_memory(struct record, counts[i]);
            struct record* records = (struct record*)arrays[i];
            for (int j = 0; j < counts[i]; j++) {
                initialize_record(&records[j], 0, 100);
            }
        } else if (types[i] == 3) { // float value
            arrays[i] = allocate_memory(float, counts[i]);
        } else if (types[i] == 4) { // char string
            arrays[i] = allocate_memory(char*, counts[i]);
            for (int j = 0; j < counts[i]; j++) {
                arrays[i][j] = allocate_memory(char, 256);
                strcpy((char*)arrays[i][j], "example");
            }
        } else if (types[i] == 5) { // struct item containing a float and a char string
            arrays[i] = allocate_memory(struct item, counts[i]);
            struct item* items = (struct item*)arrays[i];
            for (int j = 0; j < counts[i]; j++) {
                initialize_item(&items[j], 0.0, 100.0);
            }
        } else if (types[i] == 6) { // metadata pointer
            arrays[i] = allocate_memory(void*, counts[i]);
        }
    }
    return arrays;
}

int main() {
    int types[MAX_ARRAYS] = {1, 2, 3, 4, 5, 6};
    int counts[MAX_ARRAYS] = {1000, 1000, 1000, 1000, 1000, 1000};
    void** arrays = init_arrays(types, counts);
    // Additional code to use the initialized arrays
    for (int i = 0; i < MAX_ARRAYS; i++) {
        free(arrays[i]);
    }
    free(arrays);
    return 0;
}
