typedef enum {
    RECORD_STATUS_OK,
    RECORD_STATUS_ERROR
} RecordStatus;

typedef struct {
    int value;
    time_t timestamp;
    RecordStatus status;
} record;

void* initialize_records(void* arg) {
    long num_records = (long)arg;
    long* offset_array = NULL;
    int* key_array = NULL;
    record** record_array = NULL;
    time_t seed = time(NULL);

    // Initialize PRNG
    srand(seed);

    // Allocate memory for arrays
    offset_array = malloc(num_records * sizeof(long));
    if (offset_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        return (void*)-1;
    }

    key_array = malloc(num_records * sizeof(int));
    if (key_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        free(offset_array);
        return (void*)-1;
    }

    record_array = malloc(num_records * sizeof(record*));
    if (record_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return (void*)-1;
    }

    // Initialize records
    for (long i = 0; i < num_records; ++i) {
        record_array[i] = malloc(sizeof(record));
        if (record_array[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for record at index %ld\n", i);
            for (long j = 0; j < i; ++j) {
                free(record_array[j]);
            }
            free(offset_array);
            free(key_array);
            free(record_array);
            return (void*)-1;
        }

        // Initialize record with pseudo-random values
        record_array[i]->value = rand() % 1000;
        record_array[i]->timestamp = time(NULL);
        if (rand() % 2 == 0) {
            record_array[i]->status = RECORD_STATUS_OK;
        } else {
            record_array[i]->status = RECORD_STATUS_ERROR;
        }
    }

    // Assign offsets and keys
    for (long i = 0; i < num_records; ++i) {
        offset_array[i] = i * sizeof(record);
        key_array[i] = rand() % 1000;
    }

    // Return pointers to arrays
    return record_array;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <num_records>\n", argv[0]);
        return 1;
    }

    long num_records = atol(argv[1]);

    pthread_t thread_id;
    record** records;

    if (pthread_create(&thread_id, NULL, initialize_records, (void*)num_records) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    if (pthread_join(thread_id, (void**)&records) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return 1;
    }

    // Use records...

