void initialize_arrays(long **offsets, int **keys, record ***records, size_t length, int min_val, int max_val) {
    if (length == 0 || min_val > max_val) {
        return; // Handle invalid input
    }

    // Securely seed PRNG
    srand(time(NULL));

    *offsets = (long *)malloc(length * sizeof(long));
    *keys = (int *)malloc(length * sizeof(int));
    *records = (record **)malloc(length * sizeof(record *));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        return;
    }

    for (size_t i = 0; i < length; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % (max_val - min_val + 1) + min_val;

        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return;
        }

        (*records)[i]->value = rand() % (max_val - min_val + 1) + min_val;
    }
}

