['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define data structures
typedef struct {
    int value;
    time_t timestamp;
} Record;

// Global variables
long *offsets;
int *keys;
Record **records;
time_t *timestamps;
char *status_flags;
size_t capacity, size;
pthread_mutex_t mutex;

// Function prototypes
void init_arrays(size_t initial_capacity);
void free_arrays();
void resize_arrays(size_t new_capacity);
int init_prng();
int generate_random_value(int min, int max);

// Initialize arrays with specified initial capacity
void init_arrays(size_t initial_capacity) {
    pthread_mutex_lock(&mutex);
    capacity = size = initial_capacity;
    offsets = (long *)malloc(capacity * sizeof(long));
    keys = (int *)malloc(capacity * sizeof(int));
    records = (Record **)malloc(capacity * sizeof(Record *));
    timestamps = (time_t *)malloc(capacity * sizeof(time_t));
    status_flags = (char *)malloc(capacity * sizeof(char));

    if (!offsets || !keys || !records || !timestamps || !status_flags) {
        perror("Memory allocation failed");
        free_arrays();
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize records with random values and timestamps
    for (size_t i = 0; i < size; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->value = generate_random_value(0, 100);
        records[i]->timestamp = time(NULL) + rand() % 86400; // Random timestamp within a day
    }

    pthread_mutex_unlock(&mutex);
}

// Free allocated memory
void free_arrays() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
    free(status_flags);
    capacity = size = 0;
    pthread_mutex_unlock(&mutex);
}

// Resize arrays to new capacity
void resize_arrays(size_t new_capacity) {
    pthread_mutex_lock(&mutex);
    if (new_capacity <= capacity) {
        pthread_mutex_unlock(&mutex);
        return; // No need to resize
    }

    long *new_offsets = (long *)realloc(offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(keys, new_capacity * sizeof(int));
    Record **new_records = (Record **)realloc(records, new_capacity * sizeof(Record *));
    time_t *new_timestamps = (time_t *)realloc(timestamps, new_capacity * sizeof(time_t));
    char *new_status_flags = (char *)realloc(status_flags, new_capacity * sizeof(char));

    if (!new_offsets || !new_keys || !new_records || !new_timestamps || !new_status_flags) {
        perror("Memory reallocation failed");
        free_arrays();
        pthread_mutex_unlock(&mutex);
        return;
    }

    offsets = new_offsets;
    keys = new_keys;
    records = new_records;
    timestamps = new_timestamps;
    status_flags = new_status_flags;
    capacity = new_capacity;

    // Initialize newly allocated records with random values and timestamps
    for (size_t i = size; i < capacity; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->value = generate_random_value(0, 100);
        records[i]->timestamp = time(NULL) + rand() % 86400;
    }

    size = capacity;
    pthread_mutex_unlock(&mutex);
}

// Initialize PRNG with high-quality randomness
int init_prng() {
    srand(time(NULL) ^ getpid());
    return 0; // Success
}

// Generate a random value within the specified range
int generate_random_value(int min, int max) {
    return min + rand() % (max - min + 1);
}
