// Define union-find data structure
typedef struct UFSet {
    int *parent;
    int *rank;
    int size;
} UFSet;

// Initialize Union-Find structure
void initUF(UFSet *uf, int n) {
    uf->parent = (int *)malloc(n * sizeof(int));
    uf->rank = (int *)malloc(n * sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

// Find function with path compression
int find(UFSet *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

// Union function by rank
void unionUF(UFSet *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY])
            uf->parent[rootY] = rootX;
        else if (uf->rank[rootX] < uf->rank[rootY])
            uf->parent[rootX] = rootY;
        else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

// Function to check disjoint pairs
void checkDisjointPairs(int *array, int n) {
    UFSet uf;
    initUF(&uf, n);

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            start = clock();
            if (find(&uf, array[i]) != find(&uf, array[j])) {
                unionUF(&uf, array[i], array[j]);
                printf("Disjoint pair: %d and %d\n", array[i], array[j]);
            }
            end = clock();
            cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
            printf("Time taken: %.2f milliseconds\n", cpu_time_used);
        }
    }

    free(uf.parent);
    free(uf.rank);
}

// Function to handle network connection
void* handleConnection(void* arg) {
