} record;

long* allocate_long_array(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for long array\n");
        exit(1);
    }
    return array;
}

int* allocate_int_array(int size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for int array\n");
        exit(1);
    }
    return array;
}

record* allocate_record_array(int size) {
    record* array = (record*)malloc(size * sizeof(record));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        exit(1);
    }
    return array;
}

void initialize_record_array(record* records, int size, int min_val, int max_val) {
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < size; ++i) {
        int value;
        do {
            value = rand() % (max_val - min_val + 1) + min_val;
        } while (value == INT_MAX); // Avoid overflow
        records[i].value = value;
    }
}

void log_init_info(int range_min, int range_max) {
    printf("Initializing with PRNG range: [%d, %d]\n", range_min, range_max);
}

int find_largest_int(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Array is empty\n");
        return INT_MIN;
    }
    int max_val = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_val) {
            max_val = array[i];
        }
    }
    return max_val;
}

void read_integers(int** int_array, int* count) {
    *count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        (*count)++;
        *int_array = realloc(*int_array, (*count) * sizeof(int));
        if (!*int_array) {
            fprintf(stderr, "Failed to reallocate memory for int array\n");
            exit(1);
        }
        (*int_array)[*count - 1] = atoi(buffer);
    }
}

void main_function() {
    const int num_records = 1000;
    int range_min = -1000;
    int range_max = 1000;

    long* offsets = allocate_long_array(num_records);
    int* keys = allocate_int_array(num_records);
    record* records = allocate_record_array(num_records);

    initialize_record_array(records, num_records, range_min, range_max);
    log_init_info(range_min, range_max);

    int* integers = NULL;
    int count;

    printf("Enter a list of integers (one per line, end with Ctrl+D):\n");
    read_integers(&integers, &count);

    int largest = find_largest_int(integers, count);
    if (largest != INT_MIN) {
        printf("Largest integer: %d\n", largest);
    }

    free(offsets);
    free(keys);
    free(records);
    free(integers);
}
