['```c
#include <stdio.h>
#include <stdlib.h>

#define OFFSET_ARRAY_SIZE 1000
#define KEY_ARRAY_SIZE 500
#define RECORD_ARRAY_SIZE 500

typedef struct record {
    int value;
} Record;

long* offsets;
int* keys;
Record* records;

// Function to generate unique pseudo-random numbers
int gen_unique_key(int max) {
    static unsigned long seed = 123456789; // Seed for PRNG
    return (seed = seed * 1103515245 + 12345) % max;
}

// Function to fill records with random values
void fill_records(int range) {
    for (int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        records[i].value = gen_unique_key(range);
    }
}

// Function to initialize arrays and populate records
Record* init_arrays(size_t offset_size, size_t key_size, size_t record_size, int max_range) {
    offsets = (long*)calloc(offset_size, sizeof(long));
    keys = (int*)calloc(key_size, sizeof(int));
    records = (Record*)malloc(record_size * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }

    int key_set[KEY_ARRAY_SIZE * 2]; // Buffer to store generated keys
    size_t key_index = 0;

    while (key_index < KEY_ARRAY_SIZE) {
        int new_key = gen_unique_key(max_range);
        int is_duplicate = 0;
        for (size_t j = 0; j < key_index; j++) {
            if (new_key == key_set[j]) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            keys[key_index++] = new_key;
            key_set[key_index - 1] = new_key;
        }
    }

    fill_records(max_range);

    return records;
}

// Function to free allocated memory
void free_memory() {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    Record* result = init_arrays(OFFSET_ARRAY_SIZE, KEY_ARRAY_SIZE, RECORD_ARRAY_SIZE, 10000);
    // Process the records array...
    free_memory();
    return 0;
}
