long* allocate_long_array(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (array == NULL) {
        log_message("Error: Memory allocation failed for long array");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* allocate_int_array(int size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (array == NULL) {
        log_message("Error: Memory allocation failed for int array");
        exit(EXIT_FAILURE);
    }
    return array;
}

Record* allocate_record_array(int size) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (records == NULL) {
        log_message("Error: Memory allocation failed for record array");
        exit(EXIT_FAILURE);
    }
    return records;
}

char** allocate_string_array(int size, const char* prefix, int count) {
    char** strings = (char**)malloc(size * sizeof(char*));
    if (strings == NULL) {
        log_message("Error: Memory allocation failed for string array");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        strings[i] = (char*)malloc((strlen(prefix) + count + 1) * sizeof(char));
        if (strings[i] == NULL) {
            log_message("Error: Memory allocation failed for string element");
            exit(EXIT_FAILURE);
        }
        snprintf(strings[i], strlen(prefix) + count + 1, "%s%d", prefix, i);
    }
    return strings;
}

void initialize_random_records(Record* records, int size, int range_min, int range_max) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }
}

void log_message(const char* message) {
    printf("%s\n", message);
}

void release_memory(long* longs, int* ints, Record* records, char** strings) {
    free(longs);
    free(ints);
    for (int i = 0; i < size; i++) {
        free(strings[i]);
    }
    free(records);
    free(strings);
}
