#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NUM_OFFSETS 10
#define NUM_DOUBLES 5
#define NUM_STRINGS 2
#define NUM_RECORDS 4
#define NUM_DATA_ENTRIES 2

typedef struct {
    int value;
} record;

typedef struct {
    long timestamp;
    int counter;
} data_entry;

union find {
    int *parent;
    double *value;
};

void init_memory(union find *uf, long offsets[NUM_OFFSETS], double doubles[NUM_DOUBLES],
                 char strings[NUM_STRINGS][256], record records[NUM_RECORDS],
                 data_entry entries[NUM_DATA_ENTRIES]) {
    srand(time(NULL));

    for (int i = 0; i < NUM_OFFSETS; i++) {
        offsets[i] = rand();
    }

    for (int i = 0; i < NUM_DOUBLES; i++) {
        doubles[i] = (double)rand() / RAND_MAX;
    }

    for (int i = 0; i < NUM_STRINGS; i++) {
        snprintf(strings[i], sizeof(strings[i]), "String%d", i);
    }

    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].value = rand();
    }

    for (int i = 0; i < NUM_DATA_ENTRIES; i++) {
        entries[i].timestamp = time(NULL);
        entries[i].counter = rand();
    }
}

void union_find_init(union find *uf, int size) {
    uf->parent = malloc(size * sizeof(int));
    if (!uf->parent) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        uf->parent[i] = i;
    }
}

void union_find_init_double(union find *uf, int size) {
    uf->value = malloc(size * sizeof(double));
    if (!uf->value) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        uf->value[i] = i / (double)size;
    }
}

int find(union find *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_find(int *x, int *y, union find *uf) {
    int rootX = find(uf, *x);
    int rootY = find(uf, *y);

    if (rootX != rootY) {
        uf->parent[rootY] = rootX;
    }
}

void process_queue() {
    // Implement queue processing logic here
}

int main() {
    long offsets[NUM_OFFSETS];
    double doubles[NUM_DOUBLES];
    char strings[NUM_STRINGS][256];
    record records[NUM_RECORDS];
    data_entry entries[NUM_DATA_ENTRIES];

    union find uf_int;
    union_find_init(&uf_int, NUM_RECORDS);

    union find uf_double;
    union_find_init_double(&uf_double, NUM_RECORDS);

    init_memory(NULL, offsets, doubles, strings, records, entries);

    for (int i = 0; i < NUM_RECORDS - 1; i++) {
        union_find(&(records[i].value), &(records[i + 1].value), &uf_int);
    }

    clock_t start = clock();
    for (int i = 0; i < NUM_RECORDS / 2; i++) {
        union_find(&(entries[i].timestamp), &(entries[i + 1].timestamp), &uf_double);
    }
    clock_t end = clock();

    printf("Time taken to perform checks: %f milliseconds\n", ((double)(end - start)) * 1000 / CLOCKS_PER_SEC);

    free(uf_int.parent);
    free(uf_double.value);

    return 0;
}
