    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for transactions
    *trans_ptr = (transaction*)malloc(NUM_TRANSACTIONS * sizeof(transaction));
    if (*trans_ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for timestamps and identifiers
    timestamps = (long*)malloc(NUM_TRANSACTIONS * sizeof(long));
