    if (timestamps == NULL || identifiers == NULL) {
        perror("Memory allocation failed");
        free(*trans_ptr);
        exit(EXIT_FAILURE);
    }

    // Initialize transactions with pseudo-random values
    double min_amount = 0.0, max_amount = 1000.0;
    for (int i = 0; i < NUM_TRANSACTIONS; i++) {
        (*trans_ptr)[i].timestamp = time(NULL) + i * 60; // Incremental timestamp for demonstration
        (*trans_ptr)[i].identifier = i % 100 + 1; // Unique identifier within a small range
        double random_amount = min_amount + (double)(rand() / (RAND_MAX / (max_amount - min_amount)));
        (*trans_ptr)[i].amount = random_amount;

        if (i == 0 || random_amount < min_amount) {
            min_amount = random_amount;
        }
        if (i == 0 || random_amount > max_amount) {
            max_amount = random_amount;
        }
    }

    // Log initialization details
    printf("Min transaction amount: %.2f\n", min_amount);
    printf("Max transaction amount: %.2f\n", max_amount);

    // Free allocated memory for timestamps and identifiers if not needed further
    free(timestamps);
    free(identifiers);
}

int main() {
