#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    int event_id;
    double probability;
} Event;

Event* create_event_array(int size, int seed) {
    srand(seed);
    Event *events = (Event*)malloc(size * sizeof(Event));
    if (!events) return NULL;

    double total_probability = 0.0;
    for (int i = 0; i < size - 1; ++i) {
        events[i].timestamp = time(NULL) + i;
        events[i].event_id = rand() % 100; // Example event ID range
        events[i].probability = (double)rand() / RAND_MAX;
        total_probability += events[i].probability;
    }

    // Adjust the last event's probability to ensure sum is exactly 1.0
    events[size - 1].timestamp = time(NULL) + size - 1;
    events[size - 1].event_id = rand() % 100; // Example event ID range
    events[size - 1].probability = 1.0 - total_probability;

    return events;
}

void print_events(Event *events, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Event %d: Timestamp=%ld, Event ID=%d, Probability=%.4f\n",
               i, events[i].timestamp, events[i].event_id, events[i].probability);
    }
}

void free_event_array(Event *events) {
    if (events) {
        free(events);
    }
}

int main() {
    int size = 10;
    Event *events = create_event_array(size, time(NULL));
    if (events) {
        print_events(events, size);
        free_event_array(events);
    } else {
        printf("Failed to allocate memory for events.\n");
    }
    return 0;
}
