#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MIN_PROBABILITY 0.0
#define MAX_PROBABILITY 1.0

typedef struct {
    long timestamp;
    int identifier;
    double probability;
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t count;
} EventArray;

EventArray* create_event_array() {
    EventArray* array = (EventArray*)malloc(sizeof(EventArray));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for EventArray\n");
        return NULL;
    }
    array->events = (Event*)calloc(INITIAL_CAPACITY, sizeof(Event));
    if (!array->events) {
        free(array);
        fprintf(stderr, "Failed to allocate memory for events\n");
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    srand(time(NULL)); // Seed PRNG
    return array;
}

void resize_event_array(EventArray* array) {
    size_t new_capacity = array->capacity * 2;
    Event* new_events = (Event*)realloc(array->events, new_capacity * sizeof(Event));
    if (!new_events) {
        fprintf(stderr, "Failed to reallocate memory for events\n");
        return;
    }
    array->events = new_events;
    array->capacity = new_capacity;
}

void add_event(EventArray* array, long timestamp, int identifier) {
    if (array->count == array->capacity) {
        resize_event_array(array);
    }
    array->events[array->count].timestamp = timestamp;
    array->events[array->count].identifier = identifier;
    array->events[array->count].probability = (double)rand() / RAND_MAX * (MAX_PROBABILITY - MIN_PROBABILITY) + MIN_PROBABILITY;
    array->count++;
}

void update_event(EventArray* array, int identifier, long new_timestamp, double new_probability) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].identifier == identifier) {
            array->events[i].timestamp = new_timestamp;
            array->events[i].probability = new_probability;
            break;
        }
    }
}

void remove_event(EventArray* array, int identifier) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].identifier == identifier) {
            while (i + 1 < array->count) {
                array->events[i] = array->events[i + 1];
                i++;
            }
            array->count--;
            break;
        }
    }
}

void normalize_probabilities(EventArray* array) {
    double sum = 0.0;
    for (size_t i = 0; i < array->count; ++i) {
        sum += array->events[i].probability;
