#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int id;
    double probability;
} event;

typedef struct {
    event* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} event_manager;

void init_event_manager(event_manager* manager, size_t initial_capacity) {
    manager->events = (event*)malloc(initial_capacity * sizeof(event));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroy_event_manager(event_manager* manager) {
    free(manager->events);
    pthread_mutex_destroy(&manager->mutex);
}

int add_event(event_manager* manager, long timestamp, int id, double probability) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        event* new_events = (event*)realloc(manager->events, new_capacity * sizeof(event));

        if (!new_events) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }

        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    event* e = &manager->events[manager->size++];
    e->timestamp = timestamp;
    e->id = id;
    e->probability = probability;

    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

void adjust_probabilities(event_manager* manager) {
    pthread_mutex_lock(&manager->mutex);

    double sum = 0.0;
    for (size_t i = 0; i < manager->size; ++i) {
        sum += manager->events[i].probability;
    }

    if (sum == 1.0) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    double factor = 1.0 / sum;
    for (size_t i = 0; i < manager->size; ++i) {
        manager->events[i].probability *= factor;
    }

    pthread_mutex_unlock(&manager->mutex);
}

int generate_events(event_manager* manager, size_t count) {
    srand(time(NULL));

    double remaining_probability = 1.0;
    for (size_t i = 0; i < count && remaining_probability > 0; ++i) {
        long timestamp = rand();
        int id = rand() % 1000 + 1; // Simulating event ID generation
        double probability = (double)(rand()) / RAND_MAX;

        if ((remaining_probability - probability) >= 0) {
            add_event(manager, timestamp, id, probability);
            remaining_probability -= probability;
        } else {
            // Adjust probabilities to ensure sum is exactly 1.0
            adjust_probabilities(manager);
            break;
        }
    }

    return 0; // Success
}
