    srand(time(NULL));
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));
    *metadataStructs = (metadata *)malloc(size * sizeof(metadata));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *metadataStructs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();
        (*records)[i].value = rand();
        (*metadataStructs)[i].identifier = (char *)malloc(20 * sizeof(char));
        snprintf((*metadataStructs)[i].identifier, 20, "id_%d", i);
    }
}

int findLargest(int *array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

