        free(metadataStructs[i]->identifier);
    }
    free(offsets);
    free(keys);
    free(records);
    free(metadataStructs);
}

void serializeData(record *records, metadata **metadataStructs, int size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        exit(1);
    }

    fwrite(records, sizeof(record), size, file);
    fwrite(metadataStructs, sizeof(metadata *), size, file);

    fclose(file);
}

