    printf("Enter integers (end with -1):\n");
    for (int i = 0; i < MAX_RECORDS; i++) {
        scanf("%d", &inputArray[i]);
        if (inputArray[i] == -1) {
            break;
        }
    }

    int largest = findLargest(inputArray, i);
    printf("Largest number: %d\n", largest);

    freeMemory(offsets, keys, records, metadataStructs, MAX_RECORDS);

    serializeData(records, metadataStructs, i, "data.bin");

    return 0;
}
