void generateEvents(long *timestamps, int *eventIDs, Event **events, int numEvents, int minOutcome, int maxOutcome) {
    srand(time(NULL)); // Seed the random number generator with current time
    for (int i = 0; i < numEvents; i++) {
        timestamps[i] = time(NULL); // Assign current timestamp to each event
        eventIDs[i] = i + 1; // Assign sequential IDs to events
        (*events)[i].timestamp = timestamps[i];
        (*events)[i].eventID = eventIDs[i];
        (*events)[i].outcome = minOutcome + rand() % (maxOutcome - minOutcome + 1); // Random outcome within the specified range
    }
}

void validateRandomness(Event *events, int numEvents) {
    static Event *previousEvents = NULL;
    static int previousCount = 0;

    if (numEvents < previousCount) { // Check for potential repetitions or patterns
        printf("Potential randomness issues detected.\n");
    }

    for (int i = 0; i < numEvents; i++) {
        for (int j = 0; j < previousCount; j++) {
            if (events[i].outcome == previousEvents[j].outcome) { // Compare current outcomes with previously generated ones
                printf("Potential randomness issues detected.\n");
                return;
            }
        }
    }

    previousCount = numEvents;
    free(previousEvents); // Free the memory allocated for the previous events
    previousEvents = (Event *)malloc(numEvents * sizeof(Event)); // Allocate memory for the new events
    memcpy(previousEvents, events, numEvents * sizeof(Event)); // Copy the current events to the previous events array
}

int main() {
    int numEvents = 10;
    long *timestamps = (long *)malloc(numEvents * sizeof(long));
    int *eventIDs = (int *)malloc(numEvents * sizeof(int));
    Event *events = (Event *)malloc(numEvents * sizeof(Event));

    generateEvents(timestamps, eventIDs, &events, numEvents, 1, 100);
    validateRandomness(events, numEvents);

    free(timestamps);
    free(eventIDs);
    free(events);

    return 0;
}
