// Union-Find data structure for disjoint set operations
typedef struct {
    int *parent;
    int *rank;
    size_t size;
} UFSet;

UFSet* createUFSet(size_t size) {
    UFSet *set = malloc(sizeof(UFSet));
    set->parent = malloc(size * sizeof(int));
    set->rank = malloc(size * sizeof(int));
    for (size_t i = 0; i < size; ++i) {
        set->parent[i] = i;
        set->rank[i] = 0;
    }
    set->size = size;
    return set;
}

int find(UFSet *set, int i) {
    if (set->parent[i] != i)
        set->parent[i] = find(set, set->parent[i]);
    return set->parent[i];
}

void unionSets(UFSet *set, int x, int y) {
    int rootX = find(set, x);
    int rootY = find(set, y);

    if (rootX != rootY) {
        if (set->rank[rootX] > set->rank[rootY]) {
            set->parent[rootY] = rootX;
        } else if (set->rank[rootX] < set->rank[rootY]) {
            set->parent[rootX] = rootY;
        } else {
            set->parent[rootY] = rootX;
            set->rank[rootX]++;
        }
    }
}

// Concurrent read operation from a shared queue
typedef struct {
    Event *events;
    size_t capacity;
    size_t front, rear;
    pthread_mutex_t mutex;
} SharedQueue;

SharedQueue* createQueue(size_t capacity) {
    SharedQueue *queue = malloc(sizeof(SharedQueue));
    queue->events = malloc(capacity * sizeof(Event));
    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = -1;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

void enqueue(SharedQueue *queue, Event event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == queue->capacity - 1)
        // Handle full queue condition
    else if (queue->front == -1)
        queue->front = 0;
    queue->rear++;
    queue->events[queue->rear] = event;
    pthread_mutex_unlock(&queue->mutex);
}

Event dequeue(SharedQueue *queue) {
    Event event;
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == -1)
        // Handle empty queue condition
    else {
        event = queue->events[queue->front];
        if (queue->front == queue->rear)
            queue->front = queue->rear = -1;
        else
            queue->front++;
    }
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

