#define NUM_STRUCTS 100

typedef struct {
    long timestamp;
    int index;
    float measurement;
} sensorData;

unsigned long xorshift32(void) {
    static unsigned long x = 123456789;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

float calculateAverage(float *array, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return sum / size;
}

void logMessage(const char *message) {
    printf("LOG: %s\n", message);
}

sensorData* initializeSensorData(int count, int *indices, float *measurements) {
    sensorData *data = (sensorData *)malloc(count * sizeof(sensorData));
    if (data == NULL) {
        logMessage("Error allocating memory for sensor data");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        data[i].timestamp = xorshift32();
        data[i].index = indices[i];
        data[i].measurement = measurements[i];
    }

    return data;
}

void processInput() {
    int size;
    float *measurements;

    logMessage("Reading input size");
    scanf("%d", &size);
    if (size <= 0) {
        logMessage("Invalid input size");
        return;
    }

    measurements = (float *)malloc(size * sizeof(float));
    if (measurements == NULL) {
        logMessage("Error allocating memory for measurements");
        return;
    }

    logMessage("Reading measurements");
    for (int i = 0; i < size; i++) {
        scanf("%f", &measurements[i]);
    }

    float average = calculateAverage(measurements, size);
    printf("Average measurement: %.2f\n", average);

    free(measurements);
}

void establishTCPConnection(const char *ip, int port) {
    int sockfd;
    struct sockaddr_in server_addr;

    logMessage("Creating socket");
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        logMessage("Error creating socket");
        return;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        logMessage("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    logMessage("Connecting to server");
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        logMessage("Connection failed");
        close(sockfd);
        return;
    }

    logMessage("Connected to server");

    // Simulate sending and receiving data
    char buffer[1024];
    int n = read(sockfd, buffer, sizeof(buffer));
    if (n <= 0) {
        logMessage("Error reading from socket");
    } else {
        buffer[n] = '\0';
        printf("Received: %s\n", buffer);
    }

    close(sockfd);
}

void cleanUp(sensorData *data, int count) {
    free(data);
}

int main() {
    sensorData *sensorDataArray;
    int indices[NUM_STRUCTS];
    float measurements[NUM_STRUCTS];

    // Initialize indices and measurements with random values
    for (int i = 0; i < NUM_STRUCTS; i++) {
        indices[i] = xorshift32();
        measurements[i] = (float)xorshift32() / 1000.0f;
    }

    sensorDataArray = initializeSensorData(NUM_STRUCTS, indices, measurements);
    if (sensorDataArray == NULL) {
        logMessage("Failed to initialize sensor data");
        return 1;
    }

    processInput();

    establishTCPConnection("127.0.0.1", 8080);

    cleanUp(sensorDataArray, NUM_STRUCTS);

    return 0;
}
