#define MAX_LOG_RECORDS 10000

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} log_record;

int initialize_log_records(log_record **records, size_t *count) {
    srand(time(NULL));
    *count = 0;

    while (*count < MAX_LOG_RECORDS) {
        int new_key = rand() % (MAX_LOG_RECORDS * 2); // Non-cryptographic PRNG
        int key_exists = 0;
        for (size_t i = 0; i < *count; ++i) {
            if ((*records)[i].key == new_key) {
                key_exists = 1;
                break;
            }
        }
        if (!key_exists) {
            (*records)[*count].key = new_key;
            (*records)[*count].offset = rand() % (MAX_LOG_RECORDS * 10);
            (*records)[*count].timestamp = time(NULL);
            (*count)++;
        } else {
            // Collision, retry
        }
    }

    return 0; // Success
}

void validate_log_records(log_record *records, size_t count) {
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (records[i].key == records[j].key) {
                fprintf(stderr, "Key collision detected: key %d\n", records[i].key);
                exit(1);
            }
        }
    }
}

int main() {
    log_record *log_records;
    size_t record_count;

