#include <time.h>

typedef struct {
    char id;
    unsigned long amount;
} TransactionRecord;

typedef struct {
    TransactionRecord* records;
    size_t count;
    size_t capacity;
    unsigned int seed;
} TransactionManager;

unsigned long custom_prng(unsigned int* seed) {
    *seed = (*seed * 1103515245 + 12345) % ((unsigned int)-1);
    return *seed;
}

TransactionManager* create_transaction_manager(size_t count) {
    if (count == 0) {
        fprintf(stderr, "Error: Invalid record count.\n");
        return NULL;
    }

    TransactionManager* manager = (TransactionManager*)malloc(sizeof(TransactionManager));
    if (!manager) {
        fprintf(stderr, "Error: Memory allocation failed for TransactionManager.\n");
        return NULL;
    }

    manager->records = (TransactionRecord*)calloc(count, sizeof(TransactionRecord));
    if (!manager->records) {
        fprintf(stderr, "Error: Memory allocation failed for transaction records.\n");
        free(manager);
        return NULL;
    }

    manager->count = count;
    manager->capacity = count;
    manager->seed = time(NULL); // Initialize seed with current time

    for (size_t i = 0; i < count; ++i) {
        manager->records[i].id = 'A' + (i % 26);
        manager->records[i].amount = custom_prng(&manager->seed);
    }

    return manager;
}

void reset_prng(TransactionManager* manager) {
    if (!manager) {
        fprintf(stderr, "Error: Manager is NULL.\n");
        return;
    }
    manager->seed = time(NULL); // Reset seed with current time
}

void free_transaction_manager(TransactionManager* manager) {
    if (manager) {
        free(manager->records);
        free(manager);
    }
}
