#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection *record_collection_init(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) {
        return NULL; // Handle memory allocation failure
    }
    collection->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL; // Handle memory allocation failure
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void record_collection_free(RecordCollection *collection) {
    if (collection->records) {
        free(collection->records);
    }
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int record_collection_add(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Handle memory allocation failure
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

Record *record_collection_get(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            Record *result = &collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL; // Key not found
}

// Add more functions as needed for concurrent updates and queries
