typedef struct unionFindNode {
    struct unionFindNode* parent;
    int rank;
} unionFindNode;

void initializeArrays(long** offset, int** keys, record** records, unionFindNode** nodes) {
    *offset = (long*)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    *records = (record*)malloc(MAX_RECORDS * sizeof(record));
    *nodes = (unionFindNode*)malloc(MAX_RECORDS * sizeof(unionFindNode));

    if (*offset == NULL || *keys == NULL || *records == NULL || *nodes == NULL) {
        // Log error
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*offset)[i] = rand();
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 1000;
        (*nodes)[i].parent = &(*nodes)[i];
        (*nodes)[i].rank = 0;
    }
}

int find(unionFindNode* node) {
    if (node->parent != node) {
        node->parent = find(node->parent);
    }
    return node->parent;
}

void unionNodes(unionFindNode* node1, unionFindNode* node2) {
    int root1 = find(node1);
    int root2 = find(node2);

    if (root1 != root2) {
        if (node1->rank > node2->rank) {
            node2->parent = node1;
        } else if (node1->rank < node2->rank) {
            node1->parent = node2;
        } else {
            node2->parent = node1;
            node1->rank++;
        }
    }
}

void findAndPrintMax() {
    int max = INT_MIN;
    int num;

    while (scanf("%d", &num) == 1) {
        if (num > max) {
            max = num;
        }
    }

    printf("Largest integer: %d\n", max);
}

int main() {
    long* offset;
    int* keys;
    record* records;
    unionFindNode* nodes;

    initializeArrays(&offset, &keys, &records, &nodes);

    findAndPrintMax();

    free(offset);
    free(keys);
    free(records);
    free(nodes);

    return 0;
}
