#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    int timestamp;
    int key;
    uint64_t random_number;
    double transaction_amount;
} Transaction;

Transaction* transactions = NULL;
int* long_offsets = NULL;
int* keys = NULL;
uint64_t* random_numbers = NULL;
double* transaction_amounts = NULL;
int transaction_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void generate_random_number(uint64_t* number) {
    *number = (uint64_t)rand();
}

void* worker_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (transaction_count == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        if (transactions[transaction_count - 1].timestamp == -1) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        // Process transaction
        transaction_count--;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    transactions = malloc(sizeof(Transaction) * MAX_TRANSACTIONS);
    long_offsets = malloc(sizeof(long) * 4);
    keys = malloc(sizeof(int) * 4);
    random_numbers = malloc(sizeof(uint64_t) * 4);
    transaction_amounts = malloc(sizeof(double) * 4);

    if (transactions == NULL || long_offsets == NULL || keys == NULL || random_numbers == NULL || transaction_amounts == NULL) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        generate_random_number(&random_numbers[i]);
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Process transactions
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        pthread_mutex_lock(&mutex);
        while (transaction_count >= MAX_TRANSACTIONS) {
            pthread_cond_wait(&cond, &mutex);
        }
        transactions[transaction_count].timestamp = time(NULL);
        generate_random_number(&transactions[transaction_count].random_number);
        transaction_count++;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free(transactions);
    free(long_offsets);
    free(keys);
    free(random_numbers);
    free(transaction_amounts);

    return EXIT_SUCCESS;
}
