#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2
#define MEMORY_THRESHOLD 0.8

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* allocate_records(int initial_capacity) {
    return (record*)malloc(initial_capacity * sizeof(record));
}

void free_records(record* records, int capacity) {
    free(records);
}

void resize_records(record** records, int* capacity) {
    int new_capacity = *capacity * GROWTH_FACTOR;
    record* new_records = allocate_records(new_capacity);
    for (int i = 0; i < *capacity; i++) {
        new_records[i] = (*records)[i];
    }
    free(*records);
    *records = new_records;
    *capacity = new_capacity;
}

record* add_record(record** records, int* capacity, long offset, int key, int value) {
    if ((*records)->offset == *capacity - 1) {
        resize_records(records, capacity);
    }
    record* rec = &(*records)[(*records)->offset++];
    rec->offset = offset;
    rec->key = key;
    rec->value = value;
    return rec;
}

int find_max_value(record* records, int size) {
    if (size == 0) return -1; // Assuming the array is not empty
    int max_value = records[0].value;
    for (int i = 1; i < size; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

void* prng_task(void* arg) {
    // Implement non-cryptographic PRNG algorithm
    return NULL;
}

int main() {
    record* records = allocate_records(INITIAL_CAPACITY);
    int capacity = INITIAL_CAPACITY;
    int size = 0;

    long offset = 0;
    while (1) {
        int key, value;
        if (scanf("%d %d", &key, &value) != 2) break;
        add_record(&records, &capacity, offset++, key, value);
        size++;
        if ((double)size / capacity > MEMORY_THRESHOLD) {
            // Log memory usage warning
        }
    }

    int max_value = find_max_value(records, size);
    printf("Max value: %d\n", max_value);

    free_records(records, capacity);

    pthread_t prng_thread;
    pthread_create(&prng_thread, NULL, prng_task, NULL);
    pthread_join(prng_thread, NULL);

    return 0;
}
