} node;

void* generateData(void* arg) {
    int size = *(int*)arg;
    if (size > MAX_SIZE || size <= 0) {
        fprintf(stderr, "Invalid size. Size must be between 1 and %d.\n", MAX_SIZE);
        return NULL;
    }

    long *seed_values = (long *)calloc(size, sizeof(long));
