#include <time.h>

typedef struct {
    int userID;
    long timestamp;
    float expirationTime;
} Session;

Session* createSessions(int initialCapacity) {
    Session* sessions = (Session*)malloc(initialCapacity * sizeof(Session));
    if (sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return sessions;
}

void addOrUpdateSession(Session* sessions, int userID, long timestamp, float expirationTime, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (sessions[i].userID == userID) {
            sessions[i] = (Session){userID, timestamp, expirationTime};
            return;
        }
    }
    fprintf(stderr, "No space to add session\n");
}

void generateExpirationTimes(Session* sessions, int count, float minTime, float maxTime, int capacity) {
    srand(time(0)); // Seed the random number generator
    for (int i = 0; i < count && i < capacity; i++) {
        float randomMultiplier = ((float)rand() / RAND_MAX);
        sessions[i].expirationTime = minTime + randomMultiplier * (maxTime - minTime);
    }
}

void printSessions(Session* sessions, int count) {
    for (int i = 0; i < count; i++) {
        printf("Session %d: UserID=%d, Timestamp=%ld, ExpirationTime=%.2f\n", i, sessions[i].userID, sessions[i].timestamp, sessions[i].expirationTime);
    }
}

int main() {
    const int initialCapacity = 100;
    Session* sessions = createSessions(initialCapacity);

    // Example usage
    addOrUpdateSession(sessions, 1, time(NULL), 0.0f, initialCapacity);
    generateExpirationTimes(sessions, 50, 10.0f, 60.0f, initialCapacity);
    printSessions(sessions, 50);

    free(sessions);
    return 0;
}
