int allocateMemory(long **offsets, int **keys, int size, long checksum) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size\n");
        return -1;
    }

    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));

    if (!*offsets || !*keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    Record *records = (Record *)malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    int sum = 0;
    for (int i = 0; i < size; i++) {
        (*keys)[i] = rand() % 1000; // Example key generation
        records[i].value = (*keys)[i];
        sum += records[i].value;
    }

    if (sum != checksum) {
        fprintf(stderr, "Checksum mismatch\n");
        free(*offsets);
        free(*keys);
        free(records);
        return -1;
    }

    *offsets = NULL; // Example assignment for demonstration
    *keys = NULL; // Example assignment for demonstration

    free(offsets); // Deallocate offsets array
    free(keys); // Deallocate keys array
    free(records); // Deallocate records array

    return size;
}

int main() {
    long *offsets;
    int *keys;
    long checksum = 1500; // Example checksum value

    int result = allocateMemory(&offsets, &keys, 10, checksum);
    if (result < 0) {
        printf("Failed to allocate memory\n");
    } else {
        printf("Successfully allocated memory for %d records\n", result);
        free(offsets); // Free offsets array
        free(keys); // Free keys array
    }

    return 0;
}
