        free(*timestamp_array);
        exit(EXIT_FAILURE);
    }

    *message_array = (Message*)malloc(num_entries * sizeof(Message));
    if (*message_array == NULL) {
        fprintf(stderr, "Memory allocation failed for message array.\n");
        free(*timestamp_array);
        free(*event_id_array);
        exit(EXIT_FAILURE);
    }

    *session_array = (Session*)malloc(num_entries * sizeof(Session));
    if (*session_array == NULL) {
        fprintf(stderr, "Memory allocation failed for session array.\n");
        free(*timestamp_array);
        free(*event_id_array);
        free(*message_array);
        exit(EXIT_FAILURE);
