        (*timestamp_array)[i] = time(NULL); // Current timestamp
        (*event_id_array)[i / 2] = rand() % 1000; // Random event ID

        int msg_len = rand() % (MAX_MSG_LENGTH - 1) + 1;
        (*message_array)[i].timestamp = (*timestamp_array)[i];
        (*message_array)[i].message = (char*)malloc(msg_len * sizeof(char));
        if ((*message_array)[i].message == NULL) {
