            free(*timestamp_array);
            free(*event_id_array);
            free(*message_array);
            free(*session_array);
            exit(EXIT_FAILURE);
        }
        for (int j = 0; j < msg_len - 1; ++j) {
            (*message_array)[i].message[j] = charset[rand() % strlen(charset)];
        }
        (*message_array)[i].message[msg_len - 1] = '\0';

        (*session_array)[i].session_id = rand() % 100000;
        (*session_array)[i].event_id = (*event_id_array)[i / 2];
    }
}

