// Safe memory allocation
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize records with pseudo-random values
Record* initialize_records(int count, long *offsets, int *keys, UF *uf) {
    Record *records = safe_malloc(count * sizeof(Record));
    populate_records(records, count, uf);
    return records;
}

// Initialize PRNG with a seed for consistent sequences
void initialize_prng() {
    srand(time(NULL));
}

// Generate random integer within a specified range
int generate_random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Generate random ASCII character based on frequency distribution
char generate_random_char() {
    // Implement frequency distribution logic here
    return 'A' + rand() % 26;
}

// Populate records with pseudo-random values and unique identifiers
void populate_records(Record *records, int count, UF *uf) {
    for (int i = 0; i < count; ++i) {
        records[i].value = generate_random_int(1, 100);
        records[i].identifier = generate_random_char();
        records[i].processed = false;
        // Initialize Union-Find elements
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

// Helper function to find and print the largest integer from input array
void find_and_print_largest(int *input, int size) {
    if (size == 0) {
        printf("No elements in input\n");
        return;
    }
    int largest = input[0];
    for (int i = 1; i < size; ++i) {
        if (input[i] > largest) {
            largest = input[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

// Close all resources and deallocate memory
void close_resources(long *offsets, int *keys, Record *records, UF *uf, int record_count) {
    free(offsets);
    free(keys);
    free(records);
    free(uf->parent);
    free(uf->rank);
}
