void initArrays(long **offsets, int **keys, Record **records, size_t initialSize) {
    *offsets = (long *)malloc(initialSize * sizeof(long));
    *keys = (int *)malloc(initialSize * sizeof(int));
    *records = (Record *)malloc(initialSize * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for pseudo-random number generation

    for (size_t i = 0; i < initialSize; ++i) {
        do {
            (*keys)[i] = rand() % INT_MAX; // Generate a random key
        } while (findKey(*records, i) != -1); // Ensure uniqueness

        (*offsets)[i] = i * sizeof(Record);
        (*records)[i].value = rand() % INT_MAX; // Initialize record value
    }
}

int findKey(Record *records, size_t index) {
    for (size_t i = 0; i < index; ++i) {
        if (records[i].value == records[index].value) {
            return i;
        }
    }
    return -1;
}

void resizeArrays(long **offsets, int **keys, Record **records, size_t newSize) {
    long *newOffsets = (long *)realloc(*offsets, newSize * sizeof(long));
    int *newKeys = (int *)realloc(*keys, newSize * sizeof(int));
    Record *newRecords = (Record *)realloc(*records, newSize * sizeof(Record));

    if (newOffsets == NULL || newKeys == NULL || newRecords == NULL) {
        // Handle memory reallocation failure
        free(newOffsets);
        free(newKeys);
        free(newRecords);
        exit(EXIT_FAILURE);
    }

    *offsets = newOffsets;
    *keys = newKeys;
    *records = newRecords;

    for (size_t i = 0; i < newSize; ++i) {
        do {
            (*keys)[i] = rand() % INT_MAX; // Generate a random key
        } while (findKey(*records, i) != -1); // Ensure uniqueness

        (*offsets)[i] = i * sizeof(Record);
        if (i < newSize) {
            (*records)[i].value = rand() % INT_MAX; // Initialize record value for new elements
        }
    }
}

void freeArrays(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}
