        (*records)[i].value = rand(); // Generate random values for records
    }

    return 0;
}

int is_key_duplicate(int *keys, int key, int index) {
    for (int i = 0; i < index; i++) {
        if (keys[i] == key) {
            return 1; // Key duplicate found
        }
    }
    return 0; // No duplicates
}
