    ds.offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    ds.keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    ds.records = (int **)malloc(MAX_RECORDS * sizeof(int *));
    for (int i = 0; i < MAX_RECORDS; i++) {
        ds.records[i] = NULL;
    }
}

void reseed_prng() {
    srand(time(NULL) ^ getpid());
}

int generate_random_key() {
    return rand();
}

