        printf("Collision threshold reached. Alerting system administrators.\n");
        // Implement alert logic here
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (ds.keys[i] == key) {
            collision_count++;
            return -1; // Key already exists, no collision allowed
        }
        if (ds.keys[i] == 0 && ds.records[i] == NULL) {
            ds.keys[i] = key;
            Record *new_record = (Record *)malloc(sizeof(Record));
            new_record->value = value;
            ds.records[i] = new_record;
            return 0; // Success
        }
    }

    printf("Records array full. Consider resizing.\n");
    // Implement resize logic here
