        sensorData[i].timestamp = timestamp;

        // Simulate data acquisition with a non-cryptographic PRNG
        sensorData[i].value = offsetValues[i] + rangeStart + rand() % (rangeEnd - rangeStart + 1);

        clock_t end = clock();
        double timeTaken = ((double)end - start) / CLOCKS_PER_SEC;
        valuesPerSecond = numSensors / timeTaken;

        if (valuesPerSecond < numSensors / 0.05) {
            fprintf(logFile, "Warning: PRNG might be too slow for data acquisition needs.\n");
            break;
        }
    }

