void calculate_statistics(double *data, int size, double *mean, double *std_dev) {
    *mean = 0.0;
    for (int i = 0; i < size; i++) {
        *mean += data[i];
    }
    *mean /= size;

    *std_dev = 0.0;
    for (int i = 0; i < size; i++) {
        double diff = data[i] - *mean;
        *std_dev += diff * diff;
    }
    *std_dev = sqrt(*std_dev / size);
}

void log_message(const char *message) {
    printf("%s\n", message);
}

int main() {
    Record **records = (Record **)malloc(NUM_RECORDS * sizeof(Record *));
    int *ids = (int *)malloc(NUM_RECORDS * sizeof(int));

    if (!records || !ids) {
        log_message("Memory allocation failed");
        return 1;
    }

    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            log_message("Memory allocation failed for record");
            return 1;
        }
    }

    initialize_records(records, ids, NUM_RECORDS);

    double *data = (double *)malloc(NUM_RECORDS * sizeof(double));
    if (!data) {
        log_message("Memory allocation failed for data array");
        return 1;
    }

    for (int i = 0; i < NUM_RECORDS; i++) {
        printf("Enter floating-point number: ");
        scanf("%lf", &data[i]);
    }

