    calculate_statistics(data, NUM_RECORDS, &mean, &std_dev);
    printf("Mean: %.2f\nStandard Deviation: %.2f\n", mean, std_dev);

    for (int i = 0; i < NUM_RECORDS; i++) {
        free(records[i]);
    }
    free(records);
    free(ids);
    free(data);

    return 0;
}
