#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void* initialize_arrays(void* arg) {
    long* offsets;
    int* keys;
    record** records;
    size_t num_records = *(size_t*)arg;
    pthread_mutex_t* lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!lock) {
        perror("Failed to allocate memory for mutex");
        return NULL;
    }
    if (pthread_mutex_init(lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        free(lock);
        return NULL;
    }

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record*));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        pthread_mutex_destroy(lock);
        free(lock);
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * 10; // Example offset calculation
        keys[i] = rand() % 100; // Random key within range [0, 99]

        record* rec = malloc(sizeof(record));
        if (!rec) {
            perror("Memory allocation failed for record");
            // Clean up previously allocated memory
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            pthread_mutex_destroy(lock);
            free(lock);
            return NULL;
        }

        rec->value = rand() % 1000; // Random value within range [0, 999]
        records[i] = rec;

        if (pthread_mutex_lock(lock) != 0) {
            perror("Failed to lock mutex");
            // Clean up previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            pthread_mutex_destroy(lock);
            free(lock);
            return NULL;
        }

        // External data source integration here
        // Ensure data integrity and consistency

        if (pthread_mutex_unlock(lock) != 0) {
            perror("Failed to unlock mutex");
            // Clean up previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            pthread_mutex_destroy(lock);
            free(lock);
            return NULL;
        }
    }

    *(long**)(arg + sizeof(size_t)) = offsets;
    *(int**)(arg + sizeof(size_t) + sizeof(long*)) = keys;
    *(record***)(arg + sizeof(size_t) + sizeof(long*) + sizeof(int*)) = records;

    pthread_mutex_destroy(lock);
    free(lock);

    return NULL;
}

int main() {
    size_t num_records = 500;
    long* offsets;
    int* keys;
    record** records;

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, initialize_arrays, &num_records) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    // Use offsets, keys, and records here

    // Clean up allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);

    return EXIT_SUCCESS;
}
