#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct {
    int value;
} record;

u_char* resolve_hostname(const char* hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("IP address: %s\n", ipstr);

        u_char* result = (u_char*)malloc(sizeof(u_char) * INET6_ADDRSTRLEN);
        if (!result) {
            fprintf(stderr, "Memory allocation failed\n");
            freeaddrinfo(res);
            return NULL;
        }
        strcpy((char*)result, ipstr);
        freeaddrinfo(res);
        return result;
    }

    return NULL; // No address found
}
```

This code provides a simple DNS resolver that converts a given hostname to its corresponding IP address. It uses the `getaddrinfo` function from `<arpa/inet.h>` to perform the resolution and handles both IPv4 and IPv6 addresses. The resolved IP is stored in a dynamically allocated buffer, which is returned to the caller.

