#include <time.h>

typedef struct {
    uint64_t amount;
} transaction;

transaction* create_transactions(size_t num_transactions, unsigned long max_amount) {
    srand(time(NULL)); // Seed PRNG for simplicity

    unsigned long* ids = malloc(num_transactions * sizeof(unsigned long));
    if (!ids) return NULL;

    uint32_t* timestamps = malloc(num_transactions * sizeof(uint32_t));
    if (!timestamps) {
        free(ids);
        return NULL;
    }

    transaction* txns = malloc(num_transactions * sizeof(transaction));
    if (!txns) {
        free(ids);
        free(timestamps);
        return NULL;
    }

    for (size_t i = 0; i < num_transactions; ++i) {
        ids[i] = rand(); // Generate random ID
        timestamps[i] = time(NULL); // Current timestamp

        uint64_t amount = (rand() % max_amount) + 1; // Random transaction amount within range
        txns[i].amount = amount;
    }

    return txns;
}

void free_transactions(transaction* txns, size_t num_transactions) {
    free(txns);
}
