#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define RECORD_SIZE sizeof(int)

typedef struct Record {
    int value;
} Record;

typedef struct HashNode {
    int key;
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    HashNode **buckets;
    int bucket_count;
} HashTable;

HashTable *create_hash_table(int size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->bucket_count = size;
    table->buckets = (HashNode **)calloc(size, sizeof(HashNode *));
    return table;
}

int hash_function(int key, int size) {
    return abs(key) % size;
}

void insert_hash_table(HashTable *table, int key, Record *record) {
    int index = hash_function(key, table->bucket_count);
    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    node->key = key;
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
}

Record *get_hash_table(HashTable *table, int key) {
    int index = hash_function(key, table->bucket_count);
    HashNode *node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->bucket_count; i++) {
        HashNode *node = table->buckets[i];
        while (node != NULL) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

Record *initialize_record_pool(int record_count, int value_range_min, int value_range_max) {
    Record *records = (Record *)malloc(record_count * RECORD_SIZE);
    if (!records) {
        return NULL;
    }

    HashTable *hash_table = create_hash_table(record_count);

    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        insert_hash_table(hash_table, records[i].value, &records[i]);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Additional thread safety and memory management logic can be added here

    return records;
}

int main() {
    Record *record_pool = initialize_record_pool(MAX_RECORDS, 1, 100);
    if (record_pool) {
        printf("Record pool initialized successfully.\n");
        free(record_pool);
    } else {
        printf("Failed to initialize record pool.\n");
    }
    return 0;
}
```

