#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

int initialize_data(long** offsets, int** keys, Record** records, int size) {
    *offsets = safe_malloc(sizeof(long) * size);
    *keys = safe_malloc(sizeof(int) * size);
    *records = safe_malloc(sizeof(Record) * size);

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % size;
        (*records)[i].value = rand() % size;
    }

    return 0;
}

void free_data(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int find_largest(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void union_find(int* array, int size) {
    int parent[size];
    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }

    for (int i = 0; i < size - 1; i++) {
        if (array[i] != array[i + 1]) {
            int root1 = find(parent, array[i]);
            int root2 = find(parent, array[i + 1]);
            if (root1 != root2) {
                parent[root1] = root2;
                printf("Pair %d and %d are disjoint\n", array[i], array[i + 1]);
                clock_t start = clock();
                // Perform Union-Find operation
                clock_t end = clock();
                double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;
                printf("Time taken: %f milliseconds\n", time_taken);
            }
        }
    }
}

int main() {
    int size = 1000000; // Example batch size
    long* offsets;
    int* keys;
    Record* records;

    if (initialize_data(&offsets, &keys, &records, size) != 0) {
        return 1;
    }

    int input_size;
    printf("Enter the number of integers: ");
    scanf("%d", &input_size);

    int* input_array = safe_malloc(sizeof(int) * input_size);
    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input_array[i]);
    }

    int largest = find_largest(input_array, input_size);
    printf("Largest integer: %d\n", largest);

    union_find(input_array, input_size);

    free_data(offsets, keys, records);
    free(input_array);

    return 0;
}
