#define MAX_TRANSACTION_ID_LENGTH 20

typedef struct {
    char* id;
    double amount;
} transaction;

char* generate_transaction_id(size_t index, time_t timestamp) {
    // Simple non-cryptographic PRNG for performance
    size_t seed = (timestamp * 13457 + index * 56897) % 98245;
    char* id = malloc(MAX_TRANSACTION_ID_LENGTH * sizeof(char));
    if (!id) {
        return NULL;
    }
    snprintf(id, MAX_TRANSACTION_ID_LENGTH, "TX-%zu-%06lu", seed, (unsigned long)index);
    return id;
}

transaction* create_transactions(size_t num_transactions, size_t* error_count) {
    transaction* transactions = malloc(num_transactions * sizeof(transaction));
    if (!transactions) {
        (*error_count)++;
        return NULL;
    }

    time_t now = time(NULL);
    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].id = generate_transaction_id(i, now + i);
        if (!transactions[i].id) {
            (*error_count)++;
            continue;
        }
        transactions[i].amount = 100.0 * rand() / RAND_MAX; // Simulated transaction amount
    }

    return transactions;
}

void free_transactions(transaction* transactions, size_t num_transactions) {
    for (size_t i = 0; i < num_transactions; ++i) {
        free(transactions[i].id);
    }
    free(transactions);
}

int main() {
    size_t num_transactions = 1000;
    size_t error_count = 0;

    transaction* transactions = create_transactions(num_transactions, &error_count);

    if (error_count > 0) {
        fprintf(stderr, "Failed to allocate memory for %zu transactions. Encountered %zu errors.\n", num_transactions, error_count);
    } else {
        // Process transactions
        printf("Successfully created %zu transactions.\n", num_transactions);
    }

    free_transactions(transactions, num_transactions);

    return 0;
}
