#define MAX_RECORDS 1000
#define MAX_ID_LENGTH 256
#define POOL_SIZE 4096

typedef struct Record {
    int value;
    char* id;
} Record;

typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t used;
} MemoryPool;

Record* records[MAX_RECORDS];
MemoryPool memory_pool;

void initialize_memory_pool() {
    memory_pool.pool = malloc(POOL_SIZE);
    if (memory_pool.pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.size = POOL_SIZE;
    memory_pool.used = 0;
}

void* allocate_from_pool(size_t size) {
    if (memory_pool.used + size > memory_pool.size) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    void* ptr = memory_pool.pool + memory_pool.used;
    memory_pool.used += size;
    return ptr;
}

char* generate_unique_id() {
    static char id[MAX_ID_LENGTH];
    time_t current_time = time(NULL);
    snprintf(id, sizeof(id), "%ld", (long)current_time);
    return strdup(id);
}

Record* create_record(int min_val, int max_val) {
    Record* record = (Record*)allocate_from_pool(sizeof(Record));
    if (record == NULL) {
        return NULL;
    }
    record->value = rand() % (max_val - min_val + 1) + min_val;
    record->id = generate_unique_id();
    if (record->id == NULL) {
        free(record);
        return NULL;
    }
    return record;
}

void initialize_records(int num_records, int min_val, int max_val) {
    for (int i = 0; i < num_records; i++) {
        Record* record = create_record(min_val, max_val);
        if (record == NULL) {
            fprintf(stderr, "Failed to create record\n");
            exit(EXIT_FAILURE);
        }
        records[i] = record;
    }
}

void free_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i] != NULL) {
            free(records[i]->id);
            free(records[i]);
        }
    }
    free(memory_pool.pool);
}

int main() {
    srand(time(NULL));
    initialize_memory_pool();
    initialize_records(MAX_RECORDS, 1, 100);
    free_records();
    return 0;
}
