// Define the record structure
typedef struct {
    long offset;
    int key;
    float weight;
    char* str;
} Record;

// Function to initialize a record with pseudo-random values and dynamically allocated string
Record* init_records(int num_records, long min_offset, long max_offset) {
    // Calculate memory requirements for the records array
    size_t records_size = num_records * sizeof(Record);

    // Allocate memory for the records array
    Record* records = (Record*)malloc(records_size);
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Seed PRNG and other necessary initialization code here

    for (int i = 0; i < num_records; ++i) {
        // Initialize each record with pseudo-random values
        records[i].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].key = rand(); // Non-cryptographic PRNG for key generation

        // Allocate memory for the string field in each record
        size_t str_size = 50 * sizeof(char); // Example: allocate enough space for a 50-char string
        records[i].str = (char*)malloc(str_size);
        if (!records[i].str) {
            perror("Failed to allocate memory for record strings");

            // Free previously allocated memory and return NULL on failure
            for (int j = 0; j < i; ++j) {
                free(records[j].str);
            }
            free(records);
            return NULL;
        }

        // Initialize the string field with a pseudo-random string
        sprintf(records[i].str, "Record %d", i + 1);

        // Log initialization details (pseudo-code for logging)
        printf("Initialized record %d: Offset=%ld, Key=%d, Weight=%.2f, Str=\"%s\"\n",
               i, records[i].offset, records[i].key, rand() * 200.0 - 100.0, records[i].str);
    }

    return records;
}

// Function to free the allocated memory for records and their string fields
void free_records(Record* records, int num_records) {
    if (records) {
        // Free each record's string field
        for (int i = 0; i < num_records; ++i) {
            if (records[i].str) {
                free(records[i].str);
            }
        }

        // Free the records array itself
        free(records);
    }
}
