#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000
#define SEED_VALUE 42

typedef struct record {
    int value;
} Record;

long prng(long seed) {
    return (seed * 1103515245 + 12345) % ((long)1 << 31);
}

void initialize_records(Record* records, long offset, int key, int size) {
    for (int i = 0; i < size; ++i) {
        records[i].value = prng(offset + i * key);
    }
}

void manage_memory() {
    Record* records = malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    long seed = SEED_VALUE;
    int offset = 1000;
    int key = 50;

    initialize_records(records, seed, offset, MAX_RECORDS);

    free(records);
}

int main() {
    clock_t start_time = clock();
    manage_memory();
    double time_taken = ((double)clock() - start_time) / CLOCKS_PER_SEC * 1000;
    printf("Time taken for memory management: %.2f ms\n", time_taken);
    return 0;
}
