    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % num_keys;
        records[keys[i]].id = generate_random_id(min_id, max_id);
        records[keys[i]].status_code = generate_random_status_code(min_status_code, max_status_code);
        records[keys[i]].description = generate_random_description(min_description_length, max_description_length);
