typedef struct NetworkConnection {
    time_t timestamp;
    char sourceIP[16];
    int destinationPort;
} NetworkConnection;

int allocateAndInitializeConnections(int numRecords, NetworkConnection **connections, int lowerBound, int upperBound) {
    if (numRecords <= 0 || connections == NULL || lowerBound < MIN_PORT || upperBound > MAX_PORT || lowerBound >= upperBound) {
        return -1; // Invalid input
    }

    *connections = (NetworkConnection *)malloc(numRecords * sizeof(NetworkConnection));
    if (*connections == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numRecords; ) {
        int port;
        do {
            port = lowerBound + rand() % (upperBound - lowerBound);
        } while (port == (*connections)[i].destinationPort); // Ensure uniqueness

        (*connections)[i].timestamp = time(NULL);
        snprintf((*connections)[i].sourceIP, sizeof((*connections)[i].sourceIP), "192.168.%d.%d", rand() % 256, rand() % 256);
        (*connections)[i].destinationPort = port;
        i++;
    }

    return 0; // Success
}

void freeConnections(NetworkConnection *connections, int numRecords) {
    if (connections != NULL) {
        free(connections);
    }
}
