#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_RECORDS 100

typedef struct {
    int value;
} record;

long* allocate_offsets(int num_records) {
    return (long*)malloc(num_records * sizeof(long));
}

int* allocate_keys(int num_records) {
    return (int*)malloc(num_records * sizeof(int));
}

record* allocate_records(int num_records) {
    return (record*)calloc(num_records, sizeof(record));
}

void initialize_records(record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
}

void print_largest(int* numbers, int size) {
    if (size == 0) return;
    int largest = numbers[0];
    for (int i = 1; i < size; i++) {
        if (numbers[i] > largest) largest = numbers[i];
    }
    printf("Largest number: %d\n", largest);
}

void* connection_handler(void* arg) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Binding the socket to localhost on port PORT
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    // Handle connection here

    close(new_socket);
    close(server_fd);
    return NULL;
}

int main() {
    int num_records = MAX_RECORDS;
    long* offsets = allocate_offsets(num_records);
    int* keys = allocate_keys(num_records);
    record* records = allocate_records(num_records);

    initialize_records(records, num_records, 1, 1000);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, connection_handler, NULL) != 0) {
        perror("Thread creation failed");
        return EXIT_FAILURE;
    }

    int input_numbers[MAX_RECORDS];
    int size = 0;

    printf("Enter integers separated by space:\n");
    while (scanf("%d", &input_numbers[size++]) == 1 && size < MAX_RECORDS);

    print_largest(input_numbers, size);

    pthread_join(thread_id, NULL);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
