    for (int i = 0; i < numSensors; i++) {
        data[i].timestamp = time(NULL);
        data[i].keyIdentifier = rand() % rangeMax + rangeMin;
        data[i].sensorReading = ((float)rand() / RAND_MAX) * (rangeMax - rangeMin) + rangeMin;
