#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t mutex;
    int log_level;
    void (*log)(int level, const char* message);
} logger;

void log_message(logger* l, int level, const char* format, ...) {
    va_list args;
    va_start(args, format);
    if (l->log_level >= level) {
        pthread_mutex_lock(&l->mutex);
        vprintf(format, args);
        printf("\n");
        pthread_mutex_unlock(&l->mutex);
    }
    va_end(args);
}

void* initialize_data(int initial_size, logger* logger) {
    record* records;
    long* offsets;
    int* keys;

    records = malloc(initial_size * sizeof(record));
    if (!records) {
        log_message(logger, LOG_LEVEL_ERROR, "Failed to allocate memory for records");
        return NULL;
    }

    offsets = malloc(initial_size * sizeof(long));
    if (!offsets) {
        log_message(logger, LOG_LEVEL_ERROR, "Failed to allocate memory for offsets");
        free(records);
        return NULL;
    }

    keys = malloc(initial_size * sizeof(int));
    if (!keys) {
        log_message(logger, LOG_LEVEL_ERROR, "Failed to allocate memory for keys");
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize PRNG and populate arrays
    srand(time(NULL));
    for (int i = 0; i < initial_size; ++i) {
        records[i].value = rand() % 100;
        offsets[i] = rand();
        keys[i] = rand() % 256;
    }

    log_message(logger, LOG_LEVEL_INFO, "Initialization complete");
    return records;
}

void destroy_data(record* records, long* offsets, int* keys) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
