    free(pool->pool);
}

void* allocate_from_pool(memory_pool* pool, size_t size) {
    if (pool->used + size > pool->total) {
        return NULL; // Pool is full
    }
    void* ptr = (char*)pool->pool + pool->used;
    pool->used += size;
    return ptr;
}

void initialize_arrays(long** offset_values, int** keys, record** records, memory_pool* pool, int num_records) {
    *offset_values = allocate_from_pool(pool, num_records * sizeof(long));
    *keys = allocate_from_pool(pool, num_records * sizeof(int));
    *records = allocate_from_pool(pool, num_records * sizeof(record));

    if (!*offset_values || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        (*offset_values)[i] = rand() % POOL_SIZE;
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 100000;
    }
}

void read_and_process_input(int* max_value, int* input_array, size_t* num_elements) {
    *max_value = INT_MIN;
    *num_elements = 0;

    while (scanf("%d", &input_array[*num_elements]) == 1) {
        if (*input_array[*num_elements] < 0 || *input_array[*num_elements] > 999) {
            fprintf(stderr, "Invalid input: %d\n", *input_array[*num_elements]);
            continue;
        }
        if (*num_elements >= 10000000) {
            fprintf(stderr, "Too many inputs\n");
            exit(EXIT_FAILURE);
        }
        *max_value = (*max_value > *input_array[*num_elements]) ? *max_value : *input_array[*num_elements];
        ++(*num_elements);
    }
}

void print_largest(int max_value) {
    printf("Largest value: %d\n", max_value);
}

int main() {
    const int num_records = 100000;
    long* offset_values;
    int* keys;
    record* records;
    memory_pool pool = create_memory_pool(POOL_SIZE * 3);

    initialize_arrays(&offset_values, &keys, &records, &pool, num_records);
    int input_array[10000000];
    size_t num_elements;

    read_and_process_input(&max_value, input_array, &num_elements);
    print_largest(max_value);

    destroy_memory_pool(&pool);
    return 0;
}
