#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_TRANSACTIONS 1000
#define PORT 8080

typedef struct {
    int transactionID;
    double amount;
    time_t timestamp;
} Transaction;

void log_message(const char *message) {
    printf("Log: %s\n", message);
}

int generate_random_transaction_id(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

Transaction* initialize_transactions(int num_transactions, int id_min, int id_max, time_t start_time, time_t end_time) {
    Transaction *transactions = malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        log_message("Error allocating memory for transactions");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_transactions; ++i) {
        transactions[i].transactionID = generate_random_transaction_id(id_min, id_max);
        transactions[i].amount = (double)(rand() % 1000) / 100.0;
        transactions[i].timestamp = rand() % (end_time - start_time + 1) + start_time;
    }

    return transactions;
}

void free_transactions(Transaction *transactions, int num_transactions) {
    free(transactions);
}

int main() {
    int num_transactions = MAX_TRANSACTIONS;
    int id_min = 1000;
    int id_max = 9999;
    time_t start_time = time(NULL) - 3600; // One hour ago
    time_t end_time = time(NULL);

    Transaction *transactions = initialize_transactions(num_transactions, id_min, id_max, start_time, end_time);
    if (!transactions) {
        log_message("Failed to initialize transactions");
        return EXIT_FAILURE;
    }

    free_transactions(transactions, num_transactions);

    int sockfd;
    struct sockaddr_in server_addr;

    // Initialize socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        log_message("Error creating socket");
        return EXIT_FAILURE;
    }

    memset(&server_addr, 0, sizeof(server_addr));

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        log_message("Invalid address/ Address not supported");
        close(sockfd);
        return EXIT_FAILURE;
    }

    // Send data
    char *message = "Hello from client";
    sendto(sockfd, (const char *)message, strlen(message), MSG_CONFIRM,
           (const struct sockaddr *)&server_addr, sizeof(server_addr));

    log_message("Message sent");

    close(sockfd);

    return EXIT_SUCCESS;
}
