// Union-Find data structure implementation
typedef struct {
    int *parent;
    int *rank;
} UF;

UF* createUnionFind(int size) {
    UF *uf = (UF *)malloc(sizeof(UF));
    uf->parent = (int *)calloc(size, sizeof(int));
    uf->rank = (int *)calloc(size, sizeof(int));
    for (int i = 0; i < size; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
    return uf;
}

int find(UF *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void unionSet(UF *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

void destroyUnionFind(UF *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int main() {
    initializeResources();

    double array[32];
    for (int i = 0; i < 32; i++) {
        scanf("%lf", &array[i]);
    }

    float average = calculateAverage(array, 32);
    printf("Average value: %f\n", average);

    UF *uf = createUnionFind(32);
    for (int i = 0; i < 31; i++) {
        unionSet(uf, i, i + 1);
    }
    destroyUnionFind(uf);

    processCommands();

    return 0;
}
