#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_MESSAGES 1000
#define MESSAGE_LENGTH 256

typedef struct {
    long *timestamps;
    char **messages;
    int count;
} MessageSet;

union FindResult {
    int parent;
    long rank;
};

void initMessageSet(MessageSet *ms, int limit) {
    ms->timestamps = (long *)malloc(limit * sizeof(long));
    ms->messages = (char **)malloc(limit * sizeof(char *));
    for (int i = 0; i < limit; ++i) {
        ms->messages[i] = (char *)malloc(MESSAGE_LENGTH);
        srand(time(NULL));
        int length = rand() % MESSAGE_LENGTH;
        for (int j = 0; j < length; ++j) {
            ms->messages[i][j] = 'a' + rand() % 26;
        }
        ms->messages[i][length] = '\0';
    }
    ms->count = limit;
}

void freeMessageSet(MessageSet *ms) {
    for (int i = 0; i < ms->count; ++i) {
        free(ms->messages[i]);
    }
    free(ms->timestamps);
    free(ms->messages);
}

int find(union FindResult *uf, int i) {
    if (uf[i].parent != i) {
        uf[i].parent = find(uf, uf[i].parent);
    }
    return uf[i].parent;
}

void unionSet(union FindResult *uf, int i, int j) {
    int rootI = find(uf, i);
    int rootJ = find(uf, j);
    if (rootI != rootJ) {
        if (uf[rootI].rank > uf[rootJ].rank) {
            uf[rootJ].parent = rootI;
        } else if (uf[rootI].rank < uf[rootJ].rank) {
            uf[rootI].parent = rootJ;
        } else {
            uf[rootJ].parent = rootI;
            ++uf[rootI].rank;
        }
    }
}

void checkDisjointness(MessageSet *ms, union FindResult *uf, int limit) {
    clock_t start = clock();
    for (int i = 0; i < limit; ++i) {
        for (int j = i + 1; j < limit; ++j) {
            if (find(uf, i) != find(uf, j)) {
                unionSet(uf, i, j);
            }
        }
    }
    clock_t end = clock();
    printf("Disjointness check took %f milliseconds\n", (double)(end - start) * 1000 / CLOCKS_PER_SEC);
}

int main() {
    MessageSet ms;
    union FindResult uf[MAX_MESSAGES];
    for (int i = 0; i < MAX_MESSAGES; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    initMessageSet(&ms, MAX_MESSAGES);
    checkDisjointness(&ms, uf, MAX_MESSAGES);
    freeMessageSet(&ms);
    return 0;
}
