typedef struct {
    int value;
} Record;

int allocateMemory(long* offsets, int* keys, Record** records, int numRecords, int minValue, int maxValue, unsigned seed) {
    const int MAX_OFFSETS = 100000;
    const int MAX_RECORDS = 1000;

    if (numRecords > MAX_RECORDS || (offsets + keys + records) > offsets + MAX_OFFSETS) {
        return -1; // Exceeds maximum allowed elements
    }

    *offsets = malloc(MAX_OFFSETS * sizeof(long));
    *keys = malloc(MAX_OFFSETS * sizeof(int));
    *records = malloc(numRecords * sizeof(Record));

    if (!*offsets || !*keys || !*records) {
        return -2; // Memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    return 0; // Success
}

int main() {
    long* offsets;
    int* keys;
    Record* records;
    int result;

    srand(time(NULL));
    result = allocateMemory(&offsets, &keys, &records, 500, 10, 100, time(NULL));

    if (result == -1) {
        printf("Error: Exceeds maximum allowed elements.\n");
    } else if (result == -2) {
        printf("Error: Memory allocation failed.\n");
    } else {
        // Use the allocated memory
        printf("Memory allocation successful.\n");
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
