void initialize_records(record* records, size_t size, int min_value, int max_value) {
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

int initialize_data(size_t num_records, long** offsets, int** keys, record** records, int min_value, int max_value) {
    *offsets = allocate_offset_array(num_records);
    *keys = allocate_key_array(num_records);
    *records = allocate_record_array(num_records);

    if (!*offsets || !*keys || !*records) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1; // Memory allocation failed
    }

    initialize_records(*records, num_records, min_value, max_value);

    return 0; // Initialization successful
}

void validate_randomness(record* records, size_t size) {
    int range = max_value - min_value + 1;
    int count[range] = {0};
    for (size_t i = 0; i < size; ++i) {
        count[records[i].value - min_value]++;
    }
    for (int i = 0; i < range; ++i) {
        if (count[i] == 0) {
            printf("Value %d not found in the records\n", min_value + i);
        }
    }
}

