void initialize_records(Record* records, int size, int value_range_start, int value_range_end) {
    if (records == NULL || size <= 0) {
        return; // Handle invalid input
    }
    srand(time(NULL)); // Seed the PRNG once for all records

    for (int i = 0; i < size; i++) {
        records[i].value = value_range_start + rand() % (value_range_end - value_range_start + 1);
        records[i].timestamp = time(NULL); // Initialize timestamp with current time
    }
}

void update_records(Record* records, int size, int new_value_range_start, int new_value_range_end) {
    if (records == NULL || size <= 0) {
        return; // Handle invalid input
    }

    srand(time(NULL)); // Re-seed the PRNG for each update to ensure different values

    for (int i = 0; i < size; i++) {
        records[i].value = new_value_range_start + rand() % (new_value_range_end - new_value_range_start + 1);
        records[i].timestamp = time(NULL); // Update timestamp with current time
    }
}

void free_records(Record* records) {
    if (records != NULL) {
        free(records); // Free the allocated memory
    }
}
