        (*records)[i].value = keys[i];
        (*records)[i].timestamp = time(NULL) + offsets[i];
        snprintf((*records)[i].identifier, sizeof((*records)[i].identifier), "%d", i);
    }
}

void update_records(Record *records, int num_records, long seconds_to_add) {
    if (num_records <= 0 || records == NULL) {
        return;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].timestamp += seconds_to_add;
        snprintf(records[i].identifier, sizeof(records[i].identifier), "%d", i + 1);
    }
}

void free_records(Record *records) {
    if (records != NULL) {
        free(records);
    }
}
