#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_TRANSACTION_ID_LENGTH 10

struct transaction {
    char id[MAX_TRANSACTION_ID_LENGTH];
    long amount;
};

typedef struct {
    size_t capacity;
    size_t size;
    struct transaction *data;
} transaction_array;

transaction_array* create_transaction_array(size_t initial_capacity) {
    transaction_array *array = (transaction_array *)malloc(sizeof(transaction_array));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for transaction array.\n");
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (struct transaction *)calloc(initial_capacity, sizeof(struct transaction));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed for transaction data.\n");
        free(array);
        return NULL;
    }
    return array;
}

void destroy_transaction_array(transaction_array *array) {
    free(array->data);
    free(array);
}

void add_transaction(transaction_array *array) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 16;
        struct transaction *new_data = realloc(array->data, new_capacity * sizeof(struct transaction));
        if (!new_data) {
            fprintf(stderr, "Memory reallocation failed for transaction data.\n");
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    // Generate a random ID and amount
    sprintf(array->data[array->size].id, "%zu", array->size);
    array->data[array->size].amount = rand() % 1001; // Random number between 0 and 1000
    array->size++;
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    transaction_array *array = create_transaction_array(10);
    if (!array) return 1;

    for (size_t i = 0; i < 20; i++) {
        add_transaction(array);
    }

    for (size_t i = 0; i < array->size; i++) {
        printf("Transaction %zu: ID=%s, Amount=%ld\n", i, array->data[i].id, array->data[i].amount);
    }

    destroy_transaction_array(array);
    return 0;
}
