typedef struct {
    int value;
} record;

record* create_records(int count, int min_value, int max_value) {
    if (count <= 0 || min_value > max_value) {
        return NULL;
    }

    long* offsets = (long*)malloc(count * sizeof(long));
    int* keys = (int*)malloc(count * sizeof(int));
    record* records = (record*)malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        offsets[i] = rand() % ULONG_MAX;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_records(record* records, int count) {
    if (!records) {
        return;
    }
    free(records);
}

int main() {
