record* create_record() {
    record* new_record = (record*)malloc(sizeof(record));
    if (new_record == NULL) {
        perror("Failed to allocate memory for record");
        return NULL;
    }
    // Initialize the CSPRNG
    // Generate a cryptographically secure random number
    // For simplicity, using rand() as an example here
    new_record->value = rand();
    return new_record;
}

void free_record(record* r) {
    if (r != NULL) {
        free(r);
    }
}

// Thread-safe function to update the record value with a CSPRNG
void update_record_value(record* r, pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);
    // Generate a new cryptographically secure random number
    r->value = rand();
    pthread_mutex_unlock(mutex);
}

// Function to write records to a file
int write_records_to_file(const char* filename, record** records, int count) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }
    for (int i = 0; i < count; ++i) {
        fprintf(file, "%d\n", records[i]->value);
    }
    fclose(file);
    return 0;
}

// Function to read records from a file
int read_records_from_file(const char* filename, record** records, int count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return -1;
    }
    for (int i = 0; i < count; ++i) {
        fscanf(file, "%d", &records[i]->value);
    }
    fclose(file);
    return 0;
}

// Example usage
