    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    record* records[10];
    for (int i = 0; i < 10; ++i) {
        records[i] = create_record();
    }

    // Update all records with a CSPRNG
    for (int i = 0; i < 10; ++i) {
        update_record_value(records[i], &mutex);
    }

    // Write records to file
    if (write_records_to_file("records.txt", records, 10) != 0) {
        fprintf(stderr, "Failed to write records to file\n");
        return -1;
    }

    // Free allocated memory
    for (int i = 0; i < 10; ++i) {
        free_record(records[i]);
