void validateRandomValues(record* records, int size, int minValue, int maxValue) {
    for (int i = 0; i < size; ++i) {
        if (records[i].value < minValue || records[i].value > maxValue) {
            fprintf(stderr, "Error: Random value out of bounds. Value: %d\n", records[i].value);
            exit(EXIT_FAILURE);
        }
    }
}

