} userSession;

userSession* createSessions(int count) {
    userSession* sessions = (userSession*)malloc(count * sizeof(userSession));
    if (sessions == NULL) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < count; i++) {
        sprintf(sessions[i].id, "session%d", i);
        srand(time(0)); // Seed the random number generator
        sessions[i].timeout = ((double)rand() / RAND_MAX) * 3600 + 1800; // 1.5 to 3 hours in seconds
    }
    return sessions;
}

void updateTimeouts(userSession* sessions, int count, double interval) {
    for (int i = 0; i < count; i++) {
        sessions[i].timeout += interval;
    }
}

void printSessions(userSession* sessions, int count) {
    printf("Session ID\tTimeout Duration\n");
    for (int i = 0; i < count; i++) {
        printf("%s\t%.2f seconds\n", sessions[i].id, sessions[i].timeout);
    }
}

void freeSessions(userSession* sessions) {
    free(sessions); // Free the allocated memory
}

// Example usage:
int main() {
    int numSessions = 10;
    userSession* sessions = createSessions(numSessions);
    if (sessions != NULL) {
        double updateInterval = 3600; // Update every hour
        updateTimeouts(sessions, numSessions, updateInterval);
        printSessions(sessions, numSessions);
        freeSessions(sessions);
    }
    return 0;
}
