public class AccountInitializer {

    public static List<Account> initializeAccounts(int numAccounts) {
        List<Account> accounts = new ArrayList<>(numAccounts);
        Random prng = new Random();

        for (int i = 0; i < numAccounts; i++) {
            String accountID = generateUniqueAccountID(prng, i);
            int balance = prng.nextInt(10001); // Generates a number between 0 and 10,000
            try {
                accounts.add(new Account(accountID, balance));
            } catch (Exception e) {
                System.err.println("Failed to initialize account " + i + ": " + e.getMessage());
                // Optionally, rethrow or handle the exception as needed
            }
        }

        return accounts;
    }

    private static String generateUniqueAccountID(Random prng, int index) {
        // Simple example of generating a unique alphanumeric ID
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < 12; j++) {
            char c = (char) ('A' + prng.nextInt(26));
            sb.append(c);
        }
        return sb.toString() + index;
    }

    public static class Account {
        private String accountID;
        private int balance;

        public Account(String accountID, int balance) throws Exception {
            if (accountID == null || accountID.isEmpty()) {
                throw new Exception("Invalid account ID");
            }
            this.accountID = accountID;
            this.balance = balance < 0 ? 0 : balance; // Ensure non-negative balance
        }

        // Getters and setters
    }
}
