// Custom PRNG function for performance
int custom_prng(int range, int seed) {
    return (seed * 1103515245 + 12345) % range;
}

Record* allocate_and_init_records(int count, int value_range, int seed) {
    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        // Log error
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < count; ++i) {
        records[i].value = custom_prng(value_range, seed + i);
        records[i].probability = ((double)rand() / RAND_MAX);
        records[i].events = NULL;

        // Log initialization of record
    }

    return records;
}

Event* create_event(int id, double value) {
    Event* new_event = malloc(sizeof(Event));
    if (!new_event) {
        // Log error
        return NULL;
    }
    new_event->id = id;
    new_event->value = value;
    new_event->next = NULL;
    return new_event;
}

void insert_event(Record* record, Event* event, int position) {
    if (position < 0) {
        // Log error
        return;
    }

    Event** current = &record->events;
    for (int i = 0; i < position && *current != NULL; ++i) {
        current = &(*current)->next;
    }

    event->next = *current;
    *current = event;

    // Log insertion
}

void remove_event(Record* record, int id) {
    Event** current = &record->events;
    while (*current != NULL) {
        if ((*current)->id == id) {
            Event* temp = *current;
            *current = (*current)->next;
            free(temp);
            // Log removal
            return;
        }
        current = &(*current)->next;
    }

    // Log error: event not found
}

void free_records(Record* records, int count) {
    for (int i = 0; i < count; ++i) {
        Event* events = records[i].events;
        while (events != NULL) {
            Event* temp = events;
            events = events->next;
            free(temp);
        }
    }
    free(records);

    // Log memory deallocation
}
