#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int value;
} record;

typedef struct {
    unsigned int id;
} session;

unsigned long xorshift64star(unsigned long *x) {
    *x ^= *x >> 12;
    *x ^= *x << 25;
    *x ^= *x >> 27;
    return (*x) * 0x1b3d1b3d1b3d1b3dULL;
}

void initialize_arrays(const char *config_file, unsigned long seed, unsigned int max_record_value, unsigned long memory_limit) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    unsigned long num_offsets, num_keys, num_sessions;
    fscanf(file, "%lu %lu %lu", &num_offsets, &num_keys, &num_sessions);

    unsigned long *offsets = (unsigned long *)malloc(num_offsets * sizeof(unsigned long));
    unsigned int *keys = (unsigned int *)malloc(num_keys * sizeof(unsigned int));
    record *records = (record *)malloc(num_records * sizeof(record));
    session *sessions = (session *)malloc(num_sessions * sizeof(session));

    if (!offsets || !keys || !records || !sessions) {
        perror("Memory allocation failed");
        goto cleanup;
    }

    unsigned long total_memory_used = num_offsets * sizeof(unsigned long) + 
                                      num_keys * sizeof(unsigned int) +
                                      num_records * sizeof(record) +
                                      num_sessions * sizeof(session);

    if (total_memory_used > memory_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        goto cleanup;
    }

    srand(seed);
    for (unsigned long i = 0; i < num_offsets; ++i) {
        offsets[i] = xorshift64star(&seed);
    }

    for (unsigned long i = 0; i < num_keys; ++i) {
        keys[i] = xorshift64star(&seed) % UINT_MAX;
    }

    for (unsigned long i = 0; i < num_records; ++i) {
        records[i].value = xorshift64star(&seed) % max_record_value;
    }

    unsigned int session_id = 0;
    while (session_id < num_sessions && total_memory_used + sizeof(session) <= memory_limit) {
        sessions[session_id].id = xorshift64star(&seed);
        ++session_id;
    }

cleanup:
    free(offsets);
    free(keys);
    free(records);
    free(sessions);
    fclose(file);
}

int main() {
    initialize_arrays("config.txt", time(NULL), 100, 1024 * 1024); // Example usage
    return 0;
}
