#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000000000
#define EVENT_DESC_MAX_LEN 256

typedef struct Event {
    long timestamp;
    int type;
    char* description;
} Event;

typedef struct MemoryPool {
    Event events[MAX_EVENTS];
    pthread_mutex_t lock;
    int next_index;
} MemoryPool;

MemoryPool event_pool;

void initialize_memory_pool() {
    memset(&event_pool, 0, sizeof(MemoryPool));
    pthread_mutex_init(&event_pool.lock, NULL);
}

Event* allocate_event(long timestamp, int type, const char* description) {
    pthread_mutex_lock(&event_pool.lock);
    if (event_pool.next_index >= MAX_EVENTS) {
        pthread_mutex_unlock(&event_pool.lock);
        return NULL;
    }
    Event* event = &event_pool.events[event_pool.next_index++];
    event->timestamp = timestamp;
    event->type = type;
    event->description = strdup(description);
    pthread_mutex_unlock(&event_pool.lock);
    return event;
}

void free_event(Event* event) {
    if (event->description) {
        free(event->description);
    }
}

int main() {
    initialize_memory_pool();

    // Example usage
    Event* event1 = allocate_event(1633072800, 1, "Event Description 1");
    Event* event2 = allocate_event(1633072900, 2, "Event Description 2");

    if (event1 && event2) {
        printf("Events allocated successfully.\n");
        free_event(event1);
        free_event(event2);
    } else {
        printf("Failed to allocate events.\n");
    }

    pthread_mutex_destroy(&event_pool.lock);
    return 0;
}
