    srand(time(NULL)); // Seed for random number generation

    long* offsets = (long*)calloc(1000, sizeof(long));
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    int* keys = (int*)malloc(1000 * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    record* records = (record*)calloc(1000, sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return;
    }

    for (int i = 0; i < 1000; i++) {
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Reset the random number generator
    srand(time(NULL));

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

