        fprintf(stderr, "Failed to generate random seed\n");
        exit(EXIT_FAILURE);
    }

    if (!RAND_seed(&seed, sizeof(seed))) {
        fprintf(stderr, "Failed to set seed for PRNG\n");
        exit(EXIT_FAILURE);
    }

    return (long)(((unsigned long)RAND_range(maxValue - minValue + 1)) + minValue);
}

