        return NULL;
    }
    // Initialize keys array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        keys[i] = lower_bound + rand() % (upper_bound - lower_bound + 1);
    }
    return keys;
}

Record* generate_records(int num_records, int lower_bound, int upper_bound, char* seed) {
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        free(generate_offsets(num_records)); // Clean up offsets on failure
        free(generate_keys(num_records, lower_bound, upper_bound)); // Clean up keys on failure
        return NULL;
    }
    srand(seed); // Seed the PRNG
    for (int i = 0; i < num_records; i++) {
        records[i].value = lower_bound + rand() % (upper_bound - lower_bound + 1);
        for (int j = 0; j < 16; j++) {
