    return (long*)malloc(size * sizeof(long));
}

int* allocateIntArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(int size) {
    return (record*)calloc(size, sizeof(record));
}

pair* allocatePairArray(int size) {
    return (pair*)malloc(size * sizeof(pair));
}

void initializeRecords(record* records, int count, int range) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % range;
    }
}

pair* unionFindInitialize(int n) {
    pair* uf = allocatePairArray(n);
    for (int i = 0; i < n; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int find(pair* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void unionPairs(pair* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

