    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void freeAllMemory(long* longArray, int* intArray, record* recordArray, pair* pairArray) {
    free(longArray);
    free(intArray);
    free(recordArray);
    free(pairArray);
}

