void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int generate_random(int min, int max) {
    return min + rand() % (max - min + 1);
}

void initialize_arrays(long* offsets, int* keys, record** records, disjoint_elements* disjoint_pairs, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = generate_random(0, 1000000);
        keys[i] = generate_random(0, RANGE);
        records[i] = safe_malloc(sizeof(record));
        records[i]->value = generate_random(0, RANGE);
        disjoint_pairs[i].a = generate_random(0, RANGE);
        disjoint_pairs[i].b = generate_random(0, RANGE);
    }
}

void find_max(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

void check_disjoint_pairs(disjoint_elements* disjoint_pairs, int size, record** records) {
    for (int i = 0; i < size; i++) {
        clock_t start = clock();
        // Union-Find logic here
        clock_t end = clock();
        double time_spent = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Pair %d and %d checked in %.3f milliseconds\n", disjoint_pairs[i].a, disjoint_pairs[i].b, time_spent * 1000);
    }
}

