    long* offsets = safe_malloc(size * sizeof(long));
    int* keys = safe_malloc(size * sizeof(int));
    record** records = safe_malloc(size * sizeof(record*));
    disjoint_elements* disjoint_pairs = safe_malloc(size * sizeof(disjoint_elements));

    initialize_arrays(offsets, keys, records, disjoint_pairs, size);

    int input_size;
    printf("Enter number of integers: ");
    scanf("%d", &input_size);
    int* input_arr = safe_malloc(input_size * sizeof(int));
    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input_arr[i]);
    }

    find_max(input_arr, input_size);

    check_disjoint_pairs(disjoint_pairs, size, records);

    // Cleanup
    free(offsets);
    free(keys);
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
    free(disjoint_pairs);
