typedef struct {
    double value;
    char* message;
} Data;

typedef struct {
    float* numbers;
    int* prng_values;
    Data* data;
    long* seeds;
    int* indices;
} GraphData;

typedef struct {
    GraphData** graphs;
} ComplexGraphOperations;

ComplexGraphOperations* initializeGraphs() {
    ComplexGraphOperations* operations = (ComplexGraphOperations*)malloc(sizeof(ComplexGraphOperations));
    if (!operations) return NULL;

    operations->graphs = (GraphData**)malloc(NUM_GRAPHS * sizeof(GraphData*));
    if (!operations->graphs) {
        free(operations);
        return NULL;
    }

    for (int i = 0; i < NUM_GRAPHS; ++i) {
        operations->graphs[i] = (GraphData*)malloc(sizeof(GraphData));
        if (!operations->graphs[i]) {
            for (int j = 0; j < i; ++j) free(operations->graphs[j]);
            free(operations->graphs);
            free(operations);
            return NULL;
        }

        operations->graphs[i]->seeds = (long*)malloc(75 * sizeof(long));
        operations->graphs[i]->indices = (int*)malloc(75 * sizeof(int));
        operations->graphs[i]->data = (Data*)malloc(75 * sizeof(Data));
        operations->graphs[i]->numbers = (float*)malloc(75 * sizeof(float));
        operations->graphs[i]->prng_values = (int*)malloc(75 * sizeof(int));

        if (!operations->graphs[i]->seeds || !operations->graphs[i]->indices || 
            !operations->graphs[i]->data || !operations->graphs[i]->numbers || 
            !operations->graphs[i]->prng_values) {
                for (int j = 0; j <= i; ++j) {
                    free(operations->graphs[j]->seeds);
                    free(operations->graphs[j]->indices);
                    free(operations->graphs[j]->data);
                    free(operations->graphs[j]->numbers);
                    free(operations->graphs[j]->prng_values);
                    free(operations->graphs[j]);
                }
                free(operations->graphs);
                free(operations);
                return NULL;
            }

        for (int j = 0; j < 75; ++j) {
            operations->graphs[i]->data[j].message = (char*)malloc(256 * sizeof(char));
            if (!operations->graphs[i]->data[j].message) {
                for (int k = 0; k <= j; ++k) free(operations->graphs[i]->data[k].message);
                operations->graphs[i]->data[j].value = 0.0;
                for (int k = 0; k < j; ++k) {
                    free(operations->graphs[i]->seeds[k]);
                    free(operations->graphs[i]->indices[k]);
                    free(operations->graphs[i]->data[k]);
                    free(operations->graphs[i]->numbers[k]);
                    free(operations->graphs[i]->prng_values[k]);
                }
                free(operations->graphs[i]->seeds);
                free(operations->graphs[i]->indices);
                free(operations->graphs[i]->data);
                free(operations->graphs[i]->numbers);
                free(operations->graphs[i]->prng_values);
                free(operations->graphs[i]);
                for (int k = 0; k < i; ++k) {
                    free(operations->graphs[k]->seeds);
                    free(operations->graphs[k]->indices);
                    free(operations->graphs[k]->data);
                    free(operations->graphs[k]->numbers);
                    free(operations->graphs[k]->prng_values);
                    free(operations->graphs[k]);
                }
                free(operations->graphs);
                free(operations);
                return NULL;
            }
        }
    }

    // Initialize PRNG (example: Linear Congruential Generator)
    unsigned long seed = 12345; // Example seed
    for (int i = 0; i < NUM_GRAPHS; ++i) {
        operations->graphs[i]->prng_values[0] = seed;
        for (int j = 1; j < 75; ++j) {
            operations->graphs[i]->prng_values[j] = (operations->graphs[i]->prng_values[j-1] * 1664525 + 1013904223) % 4294967296;
        }
    }

    return operations;
}

void freeGraphs(ComplexGraphOperations* operations) {
    for (int i = 0; i < NUM_GRAPHS; ++i) {
        free(operations->graphs[i]->seeds);
        free(operations->graphs[i]->indices);
        for (int j = 0; j < 75; ++j) free(operations->graphs[i]->data[j].message);
        free(operations->graphs[i]->data);
        free(operations->graphs[i]->numbers);
        free(operations->graphs[i]->prng_values);
        free(operations->graphs[i]);
    }
    free(operations->graphs);
    free(operations);
}

int main() {
    ComplexGraphOperations* operations = initializeGraphs();
    if (!operations) return 1;

    // Use the graph data...

    freeGraphs(operations);
    return 0;
}
