void initializeArrays(long **offsets, int **keys, record **records, char ***identifiers, int **status_flags, int size) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));
    *identifiers = (char **)malloc(size * sizeof(char *));
    *status_flags = (int *)malloc(size * sizeof(int));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *identifiers == NULL || *status_flags == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for PRNG

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100;
        (*records)[i].value = rand() % 1000;
        (*identifiers)[i] = (char *)malloc(20 * sizeof(char));
        sprintf((*identifiers)[i], "ID%d", i);
        (*status_flags)[i] = rand() % 2;
    }
}

// Helper functions to find largest integer and longest string
int findLargestInteger(int *keys, int size) {
    int max = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > max) {
            max = keys[i];
        }
    }
    return max;
}

char* findLongestString(char **identifiers, int size) {
    char *longest = identifiers[0];
    for (int i = 1; i < size; i++) {
        if (strlen(identifiers[i]) > strlen(longest)) {
            longest = identifiers[i];
        }
    }
    return longest;
}

// Main function to demonstrate the usage of the above functions
int main() {
    int size = 5;
    long *offsets;
    int *keys, *status_flags;
    record *records;
    char **identifiers;

    initializeArrays(&offsets, &keys, &records, &identifiers, &status_flags, size);

    // Reading from standard input and finding the largest integer and longest string
    printf("Enter list of integers and strings:\n");
    int num;
    char str[20];
    while (scanf("%d %s", &num, str) == 2) {
        // Store in respective arrays
    }

    int largestInteger = findLargestInteger(keys, size);
    char *longestString = findLongestString(identifiers, size);

    printf("Largest Integer: %d\n", largestInteger);
    printf("Longest String: %s\n", longestString);

    // Clean up memory
    free(offsets);
    free(keys);
    for (int i = 0; i < size; i++) {
        free(identifiers[i]);
    }
    free(status_flags);
    free(records);
    free(identifiers);

    return 0;
}
