#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <sys/socket.h>

#define ARRAY_SIZE 1000

typedef struct {
    int value;
} Record;

void log_message(const char *message) {
    printf("%s\n", message);
}

long generate_random_long() {
    return rand();
}

int generate_random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

Record *initialize_records(long offset, int key, int range) {
    Record *records = (Record *)malloc(ARRAY_SIZE * sizeof(Record));
    if (records == NULL) {
        log_message("Memory allocation failed for records");
        return NULL;
    }
    srand(time(NULL) + offset);
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        records[i].value = generate_random_int(key, range);
    }
    return records;
}

int *initialize_disjoint_elements(long offset, int range) {
    int *disjoint_elements = (int *)malloc(ARRAY_SIZE * sizeof(int));
    if (disjoint_elements == NULL) {
        log_message("Memory allocation failed for disjoint elements");
        return NULL;
    }
    srand(time(NULL) + offset);
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        disjoint_elements[i] = generate_random_int(range, 2 * range);
    }
    return disjoint_elements;
}

void close_connection(int *channel) {
    if (*channel != -1) {
        close(*channel);
        *channel = -1;
    }
}

int main() {
    long offset_values[4];
    int keys[4];
    Record *records[4];
    int disjoint_elements[ARRAY_SIZE];
    int channel = socket(AF_INET, SOCK_STREAM, 0);

    for (int i = 0; i < 4; ++i) {
        offset_values[i] = generate_random_long();
        keys[i] = generate_random_int(100, 200);
        records[i] = initialize_records(offset_values[i], keys[i], 10000);
    }

    if (channel == -1) {
        log_message("Failed to create socket");
        return 1;
    }

    // Simulate connection establishment
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(channel, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        log_message("Failed to connect to server");
        close_connection(&channel);
        return 1;
    }

    // Simulate data exchange
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        if (send(channel, &disjoint_elements[i], sizeof(int), 0) != sizeof(int)) {
            log_message("Failed to send data");
            close_connection(&channel);
            return 1;
        }
    }

    // Simulate Union-Find operations
    clock_t start_time = clock();
    for (int i = 0; i < ARRAY_SIZE - 1; ++i) {
        if (disjoint_elements[i] != disjoint_elements[i + 1]) {
            log_message("Disjoint elements found");
        }
    }
    clock_t end_time = clock();
    printf("Time taken for Union-Find operations: %f ms\n", ((double)(end_time - start_time)) / CLOCKS_PER_SEC * 1000);

    close_connection(&channel);
    for (int i = 0; i < 4; ++i) {
        free(records[i]);
    }
    free(disjoint_elements);

    return 0;
}
