#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTION_ID 1000
#define MIN_TRANSACTION_AMOUNT 50
#define MAX_TRANSACTION_AMOUNT 200

typedef struct {
    time_t timestamp;
    int id;
    double amount;
} Transaction;

Transaction* create_transactions(int num_records, FILE* log_file) {
    if (num_records <= 0) {
        fprintf(stderr, "Error: Number of records must be positive.\n");
        return NULL;
    }

    Transaction* transactions = malloc(num_records * sizeof(Transaction));
    if (!transactions) {
        fprintf(log_file, "Memory allocation failed for %d transactions.\n", num_records);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].id = rand() % MAX_TRANSACTION_ID + 1;

        double amount_range = MAX_TRANSACTION_AMOUNT - MIN_TRANSACTION_AMOUNT;
        double random_factor = ((double)rand()) / RAND_MAX;
        transactions[i].amount = MIN_TRANSACTION_AMOUNT + random_factor * amount_range;

        fprintf(log_file, "Transaction %d: ID=%d, Amount=%.2f\n", i + 1, transactions[i].id, transactions[i].amount);
    }

    return transactions;
}

void free_transactions(Transaction* transactions) {
    if (transactions) {
        free(transactions);
    }
}
