#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    int event_id;
    double probability;
} log_entry;

log_entry* initialize_log_entries(int num_entries, FILE* log_file) {
    log_entry* entries = malloc(num_entries * sizeof(log_entry));
    if (entries == NULL) {
        fprintf(log_file, "Error: Failed to allocate memory for log entries.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < num_entries; ++i) {
        entries[i].timestamp = time(NULL);
        entries[i].event_id = rand() % 100; // Example event ID generation
        entries[i].probability = ((double)rand()) / RAND_MAX;
    }

    fprintf(log_file, "Log entries initialized with %d entries.\n", num_entries);
    return entries;
}

void read_events_from_stdin(log_entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        if (scanf("%ld %d", &entries[i].timestamp, &entries[i].event_id) != 2) {
            fprintf(stderr, "Error: Invalid input format.\n");
            exit(EXIT_FAILURE);
        }
    }
}

double calculate_average_probability(log_entry* entries, int num_entries) {
    double sum = 0;
    for (int i = 0; i < num_entries; ++i) {
        sum += entries[i].probability;
    }
    return sum / num_entries;
}

void free_log_entries(log_entry* entries) {
    free(entries);
}

int main() {
    FILE* log_file = fopen("log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    int num_entries;
    printf("Enter the number of log entries: ");
    if (scanf("%d", &num_entries) != 1 || num_entries <= 0) {
        fprintf(stderr, "Error: Invalid number of entries.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_entry* entries = initialize_log_entries(num_entries, log_file);
    if (entries == NULL) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    read_events_from_stdin(entries, num_entries);

    double average_prob = calculate_average_probability(entries, num_entries);
    printf("Average event probability: %f\n", average_prob);

    free_log_entries(entries);
    fclose(log_file);

    return EXIT_SUCCESS;
}
