typedef struct UF {
    int *parent, *rank;
    int n;
} UF;

// Function to create a new union-find data structure
UF* make_set(int n) {
    UF *uf = (UF*)malloc(sizeof(UF));
    uf->n = n;
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->rank = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
    return uf;
}

// Function to find the root of a set
int find_set(UF *uf, int v) {
    if (uf->parent[v] != v)
        uf->parent[v] = find_set(uf, uf->parent[v]);
    return uf->parent[v];
}

// Function to union two sets
void union_sets(UF *uf, int a, int b) {
    int root_a = find_set(uf, a);
    int root_b = find_set(uf, b);
    if (root_a != root_b) {
        if (uf->rank[root_a] > uf->rank[root_b])
            uf->parent[root_b] = root_a;
        else if (uf->rank[root_a] < uf->rank[root_b])
            uf->parent[root_a] = root_b;
        else {
            uf->parent[root_b] = root_a;
            uf->rank[root_a]++;
        }
    }
}

