    void *(*allocator)(size_t);
    void (*deallocator)(void*);
    pthread_mutex_t mutex;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_size, size_t increment, void *(*alloc_func)(size_t), void (*dealloc_func)(void*)) {
    memory_pool *pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->offsets = (long*)alloc_func(initial_size * sizeof(long));
    pool->keys = (int*)alloc_func(initial_size * sizeof(int));
    pool->records = (record**)alloc_func(initial_size * sizeof(record*));
    for (size_t i = 0; i < initial_size; ++i) {
        pool->records[i] = (record*)alloc_func(sizeof(record));
        pool->records[i]->value = rand() % 100; // Non-cryptographic PRNG
    }
    pool->num_elements = initial_size;
    pool->pool_size = initial_size + increment;
    pool->allocator = alloc_func;
    pool->deallocator = dealloc_func;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    for (size_t i = 0; i < pool->num_elements; ++i) {
        free(pool->records[i]);
    }
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

