void generateRandomRecords(long* offsets, int* keys, record** records, size_t size, int minRange, int maxRange, size_t maxMemory) {
    if (size <= 0 || minRange >= maxRange || maxMemory <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    size_t requiredMemory = sizeof(long) * size + sizeof(int) * size + sizeof(record) * size;
    if (requiredMemory > maxMemory) {
        fprintf(stderr, "Memory allocation exceeds the specified limit.\n");
        return;
    }

    offsets = (long*)malloc(requiredMemory);
    keys = (int*)(offsets + size);
    records = (record**)(keys + size);

    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % (maxRange - minRange) + minRange;
        keys[i] = rand() % (maxRange - minRange) + minRange;
        records[i] = (record*)malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record structure.\n");
            return;
        }
        records[i]->value = rand() % (maxRange - minRange) + minRange;
    }

    // Simulate processing of the records
    for (size_t i = 0; i < size; ++i) {
        printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i]->value);
    }

    // Free allocated memory
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(offsets);
}

