// Function to generate a pseudo-random integer between -1000 and 1000 using the Mersenne Twister algorithm
int mt_rand(int seed) {
    static unsigned long mt[624] = {0};
    static int index = 635;
    if (index == 635) {
        srand(seed);
        for (index = 0; index < 624; ++index) {
            mt[index] = rand();
        }
        index = 0;
    }
    unsigned long y = (mt[index++] & 0x80000000UL) + (mt[(index - 1) % 624] & 0x7FFFFFFFUL);
    if ((y & 0x10000000UL) != 0) {
        y = (y ^ (y >> 11)) & 0xFFFFFFFFUL;
        y = (y ^ (y << 7) & 0x9D2C5680UL) & 0xFFFFFFFFUL;
        y = (y ^ (y << 15) & 0xEFC60000UL) & 0xFFFFFFFFUL;
    } else {
        y = (y ^ (y >> 11)) & 0xFFFFFFFFUL;
    }
    return (int)((long long)y * -203873495L >> 32);
}

// Function to initialize records and arrays
Record** init_records(int seed, size_t* status) {
    Record** records = (Record**)malloc(10000 * sizeof(Record*));
    if (!records) {
        status[0] = -1;
        return NULL;
    }

    long* offsets = (long*)calloc(10000, sizeof(long));
    if (!offsets) {
        free(records);
        status[0] = -2;
        return NULL;
    }

    int* keys = (int*)malloc(10000 * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        status[0] = -3;
        return NULL;
    }

    int i, key;
    for (i = 0; i < 10000; ++i) {
        keys[i] = i + 1;
    }

    // Shuffle keys to ensure uniqueness
    srand(seed);
    for (i = 9999; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
    }

    status[0] = 1;
    for (i = 0; i < 10000; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(keys);
            free(offsets);
            status[0] = -4;
            return NULL;
        }
        records[i]->value = mt_rand(seed + i) % 2001 - 1000;
        offsets[i] = i;
    }

    status[1] = 1;
    for (i = 0; i < 9999; ++i) {
        if (keys[i] == keys[i + 1]) {
            // Duplicate key found, clean up and return
            for (int j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(keys);
            free(offsets);
            status[0] = -5;
            status[1] = 0;
            return NULL;
        }
    }

    status[2] = 1;
    for (i = 0; i < 9999; ++i) {
        if (offsets[i] != offsets[i + 1]) {
            // Non-sequential offset found, clean up and return
            for (int j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(keys);
            free(offsets);
            status[0] = -6;
            status[2] = 0;
            return NULL;
        }
    }

    free(offsets);
    free(keys);
    return records;
}
