        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < size; ++i) {
        records[i].value = prng(NULL, sizeof(int));

        int length = minLength + prng(NULL, maxLength - minLength + 1);
        records[i].data = (char*)malloc(length * sizeof(char));
        if (!records[i].data) {
            // Free previously allocated memory and return NULL
            for (int j = 0; j < i; ++j) {
                free(records[j].data);
            }
            free(records);
            return NULL;
