        for (int j = 0; j < length - 1; ++j) { // -1 to avoid null terminator overwrite
            records[i].data[j] = charSet[prng(NULL, strlen(charSet))];
        }
        records[i].data[length - 1] = '\0'; // Null-terminate the string
    }

    return records;
}

// Example PRNG function (not cryptographically secure)
void examplePRNG(void* state, size_t length) {
    static unsigned long seed = time(NULL);
    for (size_t i = 0; i < length; ++i) {
        *((unsigned char*)state + i) = (unsigned char)(seed = seed * 1103515245 + 12345);
    }
}

