int compare_ints(const void *a, const void *b) {
    return (*(int*)b - *(int*)a);
}

void find_largest(int arr[], int n) {
    qsort(arr, n, sizeof(int), compare_ints);
    printf("Largest integer: %d\n", arr[0]);
}

record* initialize_records(long num_records, int seed, char** descriptions, size_t max_description_len) {
