        return NULL;
    }

    srand(seed);
    long offset = 0;
    for (long i = 0; i < num_records; ++i) {
        records[i].id = offset++;
        records[i].status_code = rand() % 2001 - 1000; // Random between -1000 and 1000
        records[i].description = (char*)malloc(max_description_len * sizeof(char));
        if (!records[i].description) {
            fprintf(stderr, "Memory allocation failed for description.\n");
