        while ((int*)bsearch(&key, keys, i-1, sizeof(int), compare_ints)) {
            key = rand() % 1000 + 1;
        }
        keys[i-1] = key;
    }

    for (long i = 0; i < num_records; ++i) {
        records[keys[i]-1].id = offset++;
        records[keys[i]-1].status_code = rand() % 2001 - 1000; // Random between -1000 and 1000
        records[keys[i]-1].description = (char*)malloc(max_description_len * sizeof(char));
