    return (long*)malloc(count * sizeof(long));
}

int* allocateIntIndices(int count) {
    return (int*)malloc(count * sizeof(int));
}

Data* allocateAndInitializeData(int count, unsigned char minByte, unsigned char maxByte) {
    Data* dataStructures = (Data*)malloc(count * sizeof(Data));
    if (!dataStructures) {
        perror("Memory allocation failed for data structures");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; ++i) {
        dataStructures[i].buffer = (unsigned char*)malloc(BUFFER_SIZE);
        if (!dataStructures[i].buffer) {
            perror("Memory allocation failed for buffer");
            exit(EXIT_FAILURE);
        }
        dataStructures[i].length = BUFFER_SIZE;

        // Fill buffer with random bytes
        srand(time(NULL));
        for (size_t j = 0; j < BUFFER_SIZE; ++j) {
            dataStructures[i].buffer[j] = minByte + rand() % (maxByte - minByte + 1);
        }
    }

    return dataStructures;
}

Config* allocateAndInitializeConfig(int count, int defaultSetting, const char* defaultString) {
    Config* configStructures = (Config*)malloc(count * sizeof(Config));
    if (!configStructures) {
        perror("Memory allocation failed for config structures");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; ++i) {
        configStructures[i].setting = defaultSetting;
        configStructures[i].string = strdup(defaultString);
        if (!configStructures[i].string) {
            perror("Memory allocation failed for string");
            exit(EXIT_FAILURE);
        }
    }

    return configStructures;
}

void freeAllocatedResources(long* longOffsets, int* intIndices, Data* dataStructures, Config* configStructures, int count) {
    if (longOffsets) free(longOffsets);
    if (intIndices) free(intIndices);
    if (dataStructures) {
        for (int i = 0; i < count; ++i) {
            if (dataStructures[i].buffer) free(dataStructures[i].buffer);
        }
        free(dataStructures);
    }
    if (configStructures) {
        for (int i = 0; i < count; ++i) {
            if (configStructures[i].string) free(configStructures[i].string);
        }
        free(configStructures);
    }
}

int main() {
    const int count = 4;
    long* longOffsets = allocateLongOffsets(count);
    int* intIndices = allocateIntIndices(count);
    Data* dataStructures = allocateAndInitializeData(count, 0, 255);
    Config* configStructures = allocateAndInitializeConfig(count, 100, "default");

    // Use the allocated resources...

    freeAllocatedResources(longOffsets, intIndices, dataStructures, configStructures, count);

    return 0;
}
