#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Database;

Database* db_create() {
    Database* db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;
    db->records = (Record*)malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!db->records) {
        free(db);
        return NULL;
    }
    db->capacity = INITIAL_CAPACITY;
    db->size = 0;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void db_destroy(Database* db) {
    pthread_mutex_lock(&db->lock);
    free(db->records);
    pthread_mutex_unlock(&db->lock);
    free(db);
}

int db_insert(Database* db, int key, long offset) {
    if (db->size >= db->capacity) {
        size_t new_capacity = db->capacity * 2;
        Record* new_records = (Record*)realloc(db->records, new_capacity * sizeof(Record));
        if (!new_records) return -1;
        db->records = new_records;
        db->capacity = new_capacity;
    }
    pthread_mutex_lock(&db->lock);
    db->records[db->size].key = key;
    db->records[db->size].offset = offset;
    db->size++;
    pthread_mutex_unlock(&db->lock);
    return 0;
}

long* db_retrieve(Database* db, int key) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->size; i++) {
        if (db->records[i].key == key) {
            long* result = &db->records[i].offset;
            pthread_mutex_unlock(&db->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return NULL;
}

int db_update(Database* db, int key, long new_offset) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->size; i++) {
        if (db->records[i].key == key) {
            db->records[i].offset = new_offset;
            pthread_mutex_unlock(&db->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return -1;
}

void db_set_seed(Database* db, unsigned int seed) {
    srand(seed);
}

int main() {
    Database* db = db_create();
    if (!db) {
        fprintf(stderr, "Failed to create database\n");
        return 1;
    }

    db_set_seed(db, time(NULL));

    // Example usage
    for (int i = 0; i < 20; i++) {
        int key = rand(); // Pseudo-random number generator used
        long offset = i * 100;
        if (db_insert(db, key, offset) != 0) {
            fprintf(stderr, "Failed to insert record with key %d\n", key);
        }
    }

    for (int i = 0; i < 20; i++) {
        int key = rand();
        long* offset = db_retrieve(db, key);
        if (offset) {
            printf("Retrieved offset for key %d: %ld\n", key, *offset);
        } else {
            printf("Key %d not found\n", key);
        }
    }

    db_destroy(db);

    return 0;
}
```

This code provides a basic implementation of a thread-safe database with dynamic memory management and concurrent access control. The `Database` structure manages a resizable array of records, each containing a unique 'int' key and a 'long' offset value. The `db_insert`, `db_retrieve`, and `db_update` functions handle insertion, retrieval, and update operations, respectively, ensuring thread safety through mutex locks.

The `db_set_seed` function allows setting the seed for the pseudo-random number generator used to generate keys, facilitating reproducibility during testing or debugging. The example usage in the `main` function demonstrates inserting and retrieving records from the database.']

