        records[i].offset = prng->generate(prng, 0, 1000); // Example range
        records[i].key = prng->generate(prng, -100, 100);
        records[i].rec.value = prng->generate(prng, 0, 1000);
        int fieldLength = prng->generate(prng, minLength, maxLength);
        for (int j = 0; j < fieldLength; ++j) {
            records[i].rec.field[j] = charSet[prng->generate(prng, 0, strlen(charSet))];
        }
        records[i].rec.field[fieldLength] = '\0'; // Null-terminate the string
        records[i].timestamp = time(NULL); // Current system time

        if (i > 0 && records[i].timestamp <= records[i - 1].timestamp) {
