        return NULL; // Handle invalid input gracefully
    }

    record* records = (record*)aligned_alloc(16, count * sizeof(record)); // Align to 16 bytes for performance
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < count; ++i) {
        records[i].key = min_key + rand() % (max_key - min_key + 1);
        records[i].offset = i * sizeof(record); // Example offset calculation
