record* generate_records(int seed, int max_key, size_t num_records) {
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        // Handle memory allocation failure
        errno = ENOMEM;
        return NULL;
    }

    // Seed the CSPRNG
    srand(seed);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % (max_key + 1);
        records[i].offset = (long *)malloc(sizeof(long));
        if (!records[i].offset) {
            // Handle memory allocation failure
            errno = ENOMEM;
            goto cleanup;

        }
        *(records[i].offset) = rand(); // Use CSPRNG for random offset values
    }

    return records;

cleanup:
    // Free previously allocated offsets
    for (size_t i = 0; i < i; ++i) {
        free(records[i].offset);
    }
    free(records);

    errno = ENOMEM;
    return NULL;
}

// Example usage in a system with thread-safe mechanisms
void manage_records(record **records, int seed, int max_key, size_t num_records) {
