    if (*records == NULL) {
        // Handle error
        perror("Failed to allocate records");
        return;
    }

    // Use the records in a thread-safe manner

    // Free allocated memory
    for (size_t i = 0; i < num_records; ++i) {
        free((*records)[i].offset);
    }
    free(*records);
}
