    for (size_t i = 0; i < max_value; ++i) {
        records[i].value = rand() % max_value; // Generate a random value within the range
        records[i].data[0] = '\0'; // Initialize data array to null terminator
    }

    return records;
}

void free_records(record* records, size_t max_value) {
    for (size_t i = 0; i < max_value; ++i) {
        records[i].data[0] = '\0'; // Clear the data array
    }
