record* allocate_arrays(long** offsets, int** keys, record** records, size_t count, int min_value, int max_value) {
    // Initialize PRNG
    srand(time(NULL));

    *offsets = (long*)malloc(count * sizeof(long));
    *keys = (int*)malloc(count * sizeof(int));
    *records = (record*)malloc(count * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        // Initialize offset
        (*offsets)[i] = rand() % (long)count;

        // Initialize key with a pseudo-random value in the specified range
        (*keys)[i] = min_value + rand() % (max_value - min_value + 1);

        // Initialize record data and value
        for (int j = 0; j < MAX_RECORD_LENGTH; ++j) {
            (*records)[i].data[j] = (char)(rand() % 256);
        }
        (*records)[i].value = rand() % (max_value - min_value + 1);
    }

    return *records;
}

void free_arrays(long* offsets, int* keys, record* records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}

