#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000000

typedef struct {
    int transaction_id;
    long amount;
    time_t timestamp;
} Transaction;

struct PRNGState {
    unsigned int state;
};

void initPRNG(struct PRNGState *state, unsigned int seed) {
    state->state = seed ^ (time(NULL) << 16);
}

unsigned int nextRandom(struct PRNGState *state) {
    state->state = state->state * 1103515245 + 12345;
    return state->state >> 16;
}

void populateTransactions(Transaction *transactions, struct PRNGState *prng_state) {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i].transaction_id = i + 1;
        transactions[i].amount = nextRandom(prng_state) % 901 + 100; // 100 to 1000
        transactions[i].timestamp = time(NULL);
    }
}

void *threadFunc(void *arg) {
    struct PRNGState prng_state;
    initPRNG(&prng_state, (unsigned int)pthread_self());

    Transaction *transactions = malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    if (!transactions) {
        perror("Failed to allocate transactions");
        return NULL;
    }

    populateTransactions(transactions, &prng_state);

    // Process transactions...

    free(transactions);
    return NULL;
}

int main() {
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, threadFunc, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```

