    unsigned int* ids = malloc(NUM_TRANSACTIONS * sizeof(unsigned int));
    transaction* txs = malloc(NUM_TRANSACTIONS * sizeof(transaction));
    char** descriptions = malloc(NUM_TRANSACTIONS * sizeof(char*));

    if (offsets == NULL || ids == NULL || txs == NULL || descriptions == NULL) {
        // Handle memory allocation failure
        return 1;
