record* initialize_records(int size, int min_value, int max_value, FILE* log_file) {
    if (size <= 0 || min_value > max_value) {
        fprintf(log_file, "Error: Invalid input parameters.\n");
        return NULL;
    }

    const int chunk_size = 1024; // Define a manageable chunk size
    record* records = malloc(chunk_size * sizeof(record));
    if (records == NULL) {
        fprintf(log_file, "Warning: Out of memory. Attempting alternative allocation strategies.\n");
        // Implement alternative allocation strategies here
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG for non-cryptographic purposes

    for (int i = 0; i < size; ++i) {
        if (i % chunk_size == 0) {
            // Reallocate memory in chunks to manage large datasets efficiently
            record* temp = realloc(records, (i / chunk_size + 1) * chunk_size * sizeof(record));
            if (temp == NULL) {
                fprintf(log_file, "Warning: Out of memory. Attempting alternative allocation strategies.\n");
                // Implement alternative allocation strategies here
                free(records);
                return NULL;
            }
            records = temp;
