#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(int)

typedef struct {
    int *data;
    size_t count;
    size_t capacity;
} RecordArray;

RecordArray *create_record_array(size_t initial_capacity) {
    RecordArray *array = (RecordArray *)malloc(sizeof(RecordArray));
    array->data = (int *)calloc(initial_capacity, RECORD_SIZE);
    array->count = 0;
    array->capacity = initial_capacity;
    return array;
}

void add_record(RecordArray *array, int value) {
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * RECORD_SIZE);
    }
    array->data[array->count++] = value;
}

void update_record(RecordArray *array, size_t index, int value) {
    if (index < array->count) {
        array->data[index] = value;
    }
}

void remove_record(RecordArray *array, size_t index) {
    if (index < array->count - 1) {
        memmove(array->data + index, array->data + index + 1, (array->count - index - 1) * RECORD_SIZE);
    }
    array->count--;
}

void delete_record_array(RecordArray *array) {
    free(array->data);
    free(array);
}

int pseudo_random(int min, int max) {
    static unsigned seed = 0;
    if (seed == 0) {
        seed = time(NULL);
    }
    return rand_r(&seed) % (max - min + 1) + min;
}

void initialize_records(RecordArray *array, int range_min, int range_max) {
    for (size_t i = 0; i < array->count; i++) {
        add_record(array, pseudo_random(range_min, range_max));
    }
}

