float* read_numbers(int* count) {
    *count = 0;
    float* numbers = (float*)malloc(sizeof(float) * MAX_ITEMS);
    if (!numbers) {
        log_message("Failed to allocate memory for numbers array.");
        return NULL;
    }

    while (*count < MAX_ITEMS && scanf("%f", &numbers[*count]) == 1) {
        (*count)++;
    }

    if (*count == 0) {
        free(numbers);
        log_message("No numbers provided. Freeing allocated memory.");
        numbers = NULL;
    }

    return numbers;
}

float calculate_average(float* numbers, int count) {
    float sum = 0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

Item* initialize_items(int num_items) {
    Item* items = (Item*)malloc(sizeof(Item) * num_items);
    if (!items) {
        log_message("Failed to allocate memory for items array.");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_items; i++) {
        items[i].timestamp = time(NULL) + rand() % 1000; // Simulate timestamp
        items[i].score = ((float)rand()) / RAND_MAX * 100.0f; // Generate random score
    }

    return items;
}

void free_items(Item* items, int num_items) {
    if (items) {
        free(items);
        log_message("Items memory freed.");
    }
}

int main() {
    int num_items = 500;
    Item* items = initialize_items(num_items);
    if (!items) {
        return EXIT_FAILURE;
    }

    int count;
    float* numbers = read_numbers(&count);
    if (!numbers) {
        free_items(items, num_items);
        return EXIT_FAILURE;
    }

    float average = calculate_average(numbers, count);
    printf("Average of numbers: %f\n", average);

    free(numbers);
    free_items(items, num_items);

    log_message("All memory freed and resources closed.");
    return EXIT_SUCCESS;
}
