record* create_records(int size) {
    return (record*)calloc(size, sizeof(record));
}

void free_records(record* records) {
    free(records);
}

unsigned long xorshift32(unsigned long *x) {
    unsigned long num = (*x ^= (*x << 13u) ^ (*x >> 7u) ^ (*x << 17u));
    return (num & 0xFFFFFFFF);
}

void populate_records(record* records, int size) {
    unsigned long seed = time(NULL);
    for(int i = 0; i < size; i++) {
        records[i].value = xorshift32(&seed);
    }
}

int compare_records(const void *a, const void *b) {
    return ((record*)a)->value - ((record*)b)->value;
}

void sort_records(record* records, int size) {
    qsort(records, size, sizeof(record), compare_records);
}

int main() {
    int long_size, int_size;

    printf("Enter the size of the 'long' offset array: ");
    scanf("%d", &long_size);

    printf("Enter the size of the 'int' key array: ");
    scanf("%d", &int_size);

    record* records = create_records(int_size);
    if(records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    populate_records(records, int_size);
    sort_records(records, int_size);

    printf("Sorted Records:\n");
    for(int i = 0; i < int_size; i++) {
        printf("%d\n", records[i].value);
    }

    free_records(records);
    return 0;
}
