    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            // Clean up allocated records before returning
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->key = i + 1; // Example key assignment
        records[i]->offset = i * 100L; // Example offset assignment

        int dataSize = rand() % (maxDataRange - minDataRange + 1) + minDataRange;
        records[i]->data = malloc(dataSize);
        if (!records[i]->data) {
            perror("Failed to allocate memory for record data");
            // Clean up allocated records before returning
            for (int j = 0; j <= i; ++j) {
                free(records[j]->data);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        for (int j = 0; j < dataSize; ++j) {
            records[i]->data[j] = 'a' + rand() % 26; // Fill with pseudo-random characters
        }
    }

    return records;
}

void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        if (records[i]->data) {
            free(records[i]->data);
        }
        free(records[i]);
    }
    free(records);
}

int main() {
    const int numRecords = 1000;
    const int minDataRange = 5;
    const int maxDataRange = 20;

    Record** records = initializeRecords(numRecords, minDataRange, maxDataRange);

    if (records) {
        // Use the records
        freeRecords(records, numRecords);
    }

    return 0;
}
