typedef struct {
    char *username;
    char *email;
    char *session_token;
    long *offset_values;
    int *keys;
    int offset_count;
} UserRecord;

// Custom PRNG function
unsigned long custom_prng(unsigned long seed) {
    return (seed * 134775813) + 1;
}

void generate_session_token(UserRecord *user, unsigned long seed, int token_length) {
    char *token = (char *)malloc((token_length + 1) * sizeof(char));
    for (int i = 0; i < token_length; i++) {
        token[i] = 'A' + custom_prng(seed + i) % 26;
    }
    token[token_length] = '\0';
    free(user->session_token);
    user->session_token = token;
}

void update_user_record(UserRecord *user, const char *new_username, const char *new_email) {
    free(user->username);
    user->username = strdup(new_username);
    free(user->email);
    user->email = strdup(new_email);
    generate_session_token(user, custom_prng((unsigned long)new_username), 32); // Example token length
}

void init_user_record(UserRecord *user, const char *initial_username, const char *initial_email) {
    user->username = strdup(initial_username);
    user->email = strdup(initial_email);
    user->session_token = NULL;
    user->offset_values = NULL;
    user->keys = NULL;
    user->offset_count = 0;
}

void destroy_user_record(UserRecord *user) {
    free(user->username);
    free(user->email);
    free(user->session_token);
    if (user->offset_values != NULL) {
        free(user->offset_values);
    }
    if (user->keys != NULL) {
        free(user->keys);
    }
}

// Example usage
int main() {
    UserRecord user;
    init_user_record(&user, "john_doe", "john@example.com");

    update_user_record(&user, "jane_doe", "jane@example.com");
    printf("Updated Username: %s\n", user.username);
    printf("Session Token: %s\n", user.session_token);

    destroy_user_record(&user);
    return 0;
}
