void initialize_arrays(long start_time, long end_time) {
    long *timestamps = (long *)malloc(MAX_EVENTS * sizeof(long));
    int *priorities = (int *)calloc(MAX_EVENTS, sizeof(int));
    Event *events = (Event *)malloc(MAX_EVENTS * sizeof(Event));

    if (!timestamps || !priorities || !events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Initialize random seed

    int priority_set[] = {1, 2, 3, 4}; // Example priority set
    size_t priority_count = sizeof(priority_set) / sizeof(priority_set[0]);

    for (size_t i = 0; i < MAX_EVENTS; ++i) {
        timestamps[i] = start_time + rand() % ((end_time - start_time) + 1);
        priorities[i] = priority_set[rand() % priority_count];
        snprintf(events[i].message, sizeof(events[i].message), "Event-%zu", i);

        events[i].timestamp = timestamps[i];
        events[i].priority = priorities[i];
    }

    // Use the arrays here (e.g., pass them to other functions)

    free(timestamps);
    free(priorities);
    free(events);
}

int main() {
    long start_time = time(NULL) - 86400; // 24 hours ago
    long end_time = time(NULL);

    initialize_arrays(start_time, end_time);

    return 0;
}
