#include <time.h>

typedef struct {
    time_t timestamp;
} Timestamp;

typedef struct {
    unsigned long transactionID;
    char clientIP[16];
    char httpMethod[8];
    char urlPath[256];
    char queryParams[256];
    int responseStatusCode;
    Timestamp timestamps[];
} RequestLogEntry;

unsigned long generateTransactionID(unsigned long clientIP, time_t currentTime) {
    // Simple PRNG for demonstration purposes
    return (clientIP * 1007 + currentTime) % 1000000000;
}

RequestLogEntry* createRequestLogEntry(char* clientIP, char* httpMethod, char* urlPath, char* queryParams, int responseStatusCode, int numTimestamps) {
    RequestLogEntry* entry = (RequestLogEntry*)malloc(sizeof(RequestLogEntry) + sizeof(Timestamp) * numTimestamps);
    if (entry == NULL) {
        return NULL; // Handle memory allocation failure
    }

    entry->transactionID = generateTransactionID(*(unsigned long*)&clientIP, time(NULL));
    snprintf(entry->clientIP, 16, "%s", clientIP);
    snprintf(entry->httpMethod, 8, "%s", httpMethod);
    snprintf(entry->urlPath, 256, "%s", urlPath);
    snprintf(entry->queryParams, 256, "%s", queryParams);
    entry->responseStatusCode = responseStatusCode;

    for (int i = 0; i < numTimestamps; i++) {
        entry->timestamps[i].timestamp = time(NULL) + rand() % 100;
    }

    return entry;
}

void freeRequestLogEntry(RequestLogEntry* entry) {
    if (entry != NULL) {
        free(entry);
    }
}

int main() {
    srand(time(NULL));

    RequestLogEntry* logEntry = createRequestLogEntry("192.168.1.1", "GET", "/", "?param=value", 200, 5);
    if (logEntry != NULL) {
        printf("Transaction ID: %lu\n", logEntry->transactionID);
        printf("Client IP: %s\n", logEntry->clientIP);
        printf("HTTP Method: %s\n", logEntry->httpMethod);
        printf("URL Path: %s\n", logEntry->urlPath);
        printf("Query Params: %s\n", logEntry->queryParams);
        printf("Response Status Code: %d\n", logEntry->responseStatusCode);

        for (int i = 0; i < 5; i++) {
            printf("Timestamp %d: %ld\n", i, logEntry->timestamps[i].timestamp);
        }

        freeRequestLogEntry(logEntry);
    } else {
        printf("Failed to create request log entry.\n");
    }

    return 0;
}
