Record* manage_dynamic_memory(long offset_count, int key_count, unsigned long seed) {
    if (offset_count <= 0 || key_count <= 0) {
        return NULL; // Invalid input
    }

    Record* records = malloc(key_count * sizeof(Record));
    if (!records) {
        return NULL; // Insufficient memory
    }

    srand(seed); // Initialize PRNG

    for (int i = 0; i < key_count; i++) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
        records[i].timestamp = time(NULL);
        records[i].status = 'A'; // Example status
    }

    return records;
}

int main() {
    unsigned long seed = time(NULL); // Current time as seed for reproducibility
    Record* my_records = manage_dynamic_memory(10, 5, seed);

    if (my_records) {
        for (int i = 0; i < 5; i++) {
            printf("Record %d: Value=%d, Timestamp=%ld, Status='%c'\n", 
                   i, my_records[i].value, my_records[i].timestamp, my_records[i].status);
        }
        free(my_records); // Clean up
    } else {
        printf("Failed to allocate memory or invalid input.\n");
    }

    return 0;
}
