#define MAX_MESSAGE_LENGTH 256

typedef struct {
    long timestamp;
    int priority;
    char message[MAX_MESSAGE_LENGTH];
    int flag;
} event;

event* create_event_array(int size, long min_timestamp, long max_timestamp) {
    if (size <= 0 || min_timestamp > max_timestamp) {
        return NULL;
    }

    event* events = malloc(size * sizeof(event));
    if (!events) {
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < size; ++i) {
        events[i].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
        events[i].priority = rand() % 10; // Assuming priority range is 0 to 9
        snprintf(events[i].message, MAX_MESSAGE_LENGTH, "Event %d", i);
        events[i].flag = rand() % 2; // Assuming flag can be either 0 or 1
    }

    return events;
}

void log_events(event* events, int size) {
    if (!events || size <= 0) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        printf("Timestamp: %ld, Priority: %d, Message: %s, Flag: %d\n",
               events[i].timestamp, events[i].priority, events[i].message, events[i].flag);
    }
}

void free_event_array(event* events) {
    if (events) {
        free(events);
    }
}

int main() {
    int num_events = 10;
    long min_timestamp = 1633072800; // Example timestamp for January 1, 2021
    long max_timestamp = 1664595200; // Example timestamp for December 31, 2022

    event* events = create_event_array(num_events, min_timestamp, max_timestamp);
    if (events) {
        log_events(events, num_events);
        free_event_array(events);
    } else {
        fprintf(stderr, "Failed to allocate memory for events.\n");
    }

    return 0;
}
