    if (!array || size <= 0) return;

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void read_from_stdin_and_find_largest() {
    int *array = NULL;
    int size = 0, capacity = 10, value;

    while (scanf("%d", &value) != EOF) {
        if (size >= capacity) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(int));
        }
        array[size++] = value;
    }

    find_largest_integer(array, size);
    free(array);
}
