void process_temperatures(float *temperatures, int count) {
    float sum = 0.0;
    float min_temp = temperatures[0];
    float max_temp = temperatures[0];

    for (int i = 0; i < count; ++i) {
        printf("Enter temperature reading %d: ", i + 1);
        scanf("%f", &temperatures[i]);
        sum += temperatures[i];
        if (temperatures[i] < min_temp) min_temp = temperatures[i];
        if (temperatures[i] > max_temp) max_temp = temperatures[i];
    }

    printf("Average Temperature: %.2f\n", sum / count);
    printf("Minimum Temperature: %.2f\n", min_temp);
    printf("Maximum Temperature: %.2f\n", max_temp);
}

