// Define the sensorData structure
typedef struct {
    int timestamp;
    double value;
    char status;
} sensorData;

// Function to generate pseudo-random values within a specified range using a non-cryptographic PRNG
int generatePRN(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to initialize the sensor data arrays and populate them with random values
sensorData* initSensorData(long numSensors) {
    srand(time(NULL)); // Seed the PRNG
    sensorData* sensorArray = (sensorData*)malloc(numSensors * sizeof(sensorData));
    if (!sensorArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    for (long i = 0; i < numSensors; ++i) {
        sensorArray[i].timestamp = generatePRN(1, 365); // Timestamp between 1 and 365
        sensorArray[i].value = ((double)generatePRN(1, 1000)) / 100.0; // Sensor reading between 1.0 and 10.0
        sensorArray[i].status = (sensorArray[i].value > 5.0) ? 'V' : 'I'; // Status based on value
    }
    return sensorArray;
}

// Function to read valid integers from standard input
int readValidInt() {
    int num;
    while (1) {
        printf("Enter an integer: ");
        if (scanf("%d", &num) == 1) {
            break;
        } else {
            printf("Invalid input. Please enter a valid integer.\n");
            while (getchar() != '\n'); // Clear the input buffer
        }
    }
    return num;
}

// Function to compute the average of all valid sensor readings
double calculateAverage(sensorData* sensorArray, long numSensors) {
    double sum = 0.0;
    int count = 0;
    for (long i = 0; i < numSensors; ++i) {
        if (sensorArray[i].status == 'V') {
            sum += sensorArray[i].value;
            ++count;
        }
    }
    return (count > 0) ? (sum / count) : 0.0;
}

