    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

event* initialize_events(int num_events) {
    event* events = (event*)safe_malloc(num_events * sizeof(event));
    srand(time(NULL));

    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = time(NULL) - rand() % (24 * 3600);
        events[i].priority = rand() % 5 + 1;
        snprintf(events[i].message, sizeof(events[i].message), "Event %d", i);
    }

    return events;
}

void find_largest_float(float* arr, int size) {
