time_t* read_and_validate_timestamps(int* num_timestamps) {
    time_t* timestamps = safe_malloc(sizeof(time_t) * MAX_EVENTS);
    char line[256];
    *num_timestamps = 0;

    while (fgets(line, sizeof(line), stdin)) {
        struct tm tm;
        if (strptime(line, "%Y-%m-%d %H:%M:%S", &tm)) {
            timestamps[*num_timestamps] = mktime(&tm);
            (*num_timestamps)++;
        } else {
            fprintf(stderr, "Invalid timestamp format\n");
        }
    }

    return timestamps;
}

double calculate_average_time_interval(time_t* timestamps, int num_timestamps) {
    if (num_timestamps < 2) {
        printf("Not enough timestamps for interval calculation\n");
        return -1;
    }

    double total = 0;
    for (int i = 1; i < num_timestamps; i++) {
        total += difftime(timestamps[i], timestamps[i-1]);
    }

    return total / (num_timestamps - 1);
}

