    for (int i = 0; i < size; i++) {
        uf[i] = i;
    }
    return uf;
}

void* createLongArr(int size) {
    return (long*)malloc(size * sizeof(long));
}

void freeAll(void** pointers, int count) {
    for (int i = 0; i < count; i++) {
        if (pointers[i]) {
            free(pointers[i]);
            pointers[i] = NULL;
        }
    }
}

// Union-Find operations
int find(int* uf, int x) {
    if (uf[x] != x) {
        uf[x] = find(uf, uf[x]); // Path compression
    }
    return uf[x];
}

void unionSets(int* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        uf[rootX] = rootY;
    }
}

