#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
} record;

union find {
    int parent;
    int rank;
};

void union_find_init(union find *uf, int size) {
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

int find(union find *uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void union_op(union find *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

int max_value(int *array, int size) {
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void log_message(const char *message, ...) {
    // Implement your logging mechanism here
    printf("%s\n", message);
}

record* init_records(int count, int min_val, int max_val) {
    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    srand(time(0)); // Initialize PRNG
    for (int i = 0; i < count; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    return records;
}

void free_records(record *records, int count) {
    if (records) {
        free(records);
    }
}

int main() {
    int count;
    printf("Enter the number of elements: ");
    scanf("%d", &count);

    record *records = init_records(count, 1, 100); // Initialize records with random values between 1 and 100
    if (!records) {
        return EXIT_FAILURE;
    }

    int input_count;
    printf("Enter the number of integers to read: ");
    scanf("%d", &input_count);

    int *input_array = (int *)malloc(input_count * sizeof(int));
    if (!input_array) {
        log_message("Memory allocation failed for input array.");
        free_records(records, count);
        return EXIT_FAILURE;
    }

    printf("Enter the integers: ");
    for (int i = 0; i < input_count; ++i) {
        scanf("%d", &input_array[i]);
    }

    int max_val = max_value(input_array, input_count);
    printf("The largest integer is: %d\n", max_val);

    union find uf[input_count];
    union_find_init(uf, input_count);

    for (int i = 0; i < input_count - 1; ++i) {
        clock_t start_time = clock();
        if (find(uf, input_array[i]) != find(uf, input_array[i + 1])) {
            union_op(uf, input_array[i], input_array[i + 1]);
        }
        clock_t end_time = clock();

        double duration = (double)(end_time - start_time) / CLOCKS_PER_SEC;
        printf("Time taken for disjoint check: %.4f ms\n", duration * 1000);
    }

    free(input_array);
    free_records(records, count);

    return EXIT_SUCCESS;
}
