#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    Record** records;
} Metadata;

// Custom PRNG state structure
typedef struct {
    unsigned long seed;
} PRNGState;

// Initialize PRNG with a seed
PRNGState* prng_init(unsigned long seed) {
    PRNGState* state = (PRNGState*)malloc(sizeof(PRNGState));
    if (!state) return NULL;
    state->seed = seed;
    return state;
}

// Custom PRNG function using XORShift algorithm for high performance
unsigned long prng_next(PRNGState* state) {
    unsigned long x = state->seed;
    x ^= x << 13;
    x ^= x >> 7;
    state->seed = x ^ (x >> 17);
    return x;
}

// Generate random integer within a specified range
int generate_random_int(PRNGState* prng, int min, int max) {
    unsigned long range = (unsigned long)(max - min + 1);
    unsigned long mod = (range == (unsigned long)-1) ? range : range * range;
    unsigned long res;

    do {
        res = prng_next(prng) % mod;
    } while (res >= range);

    return (int)(min + res);
}

// Allocate memory for arrays and initialize records
void allocate_memory(int num_records, long* offsets, int* keys, Record** records, Metadata** metadata, PRNGState* prng) {
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *records = (Record**)malloc(num_records * sizeof(Record*));
    *metadata = (Metadata*)malloc(sizeof(Metadata));

    if (!(*offsets) || !(*keys) || !(*records) || !(*metadata)) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    (*metadata)->records = (Record**)malloc(num_records * sizeof(Record*));
    if (!(*metadata)->records) {
        printf("Metadata memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records with random integers
    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (Record*)malloc(sizeof(Record));
        (*keys)[i] = generate_random_int(prng, 1, 100); // Example range
        (*records)[i]->value = generate_random_int(prng, -1000, 1000); // Example range
        (*offsets)[i] = i * sizeof(Record);
        (*metadata)->records[i] = (*records)[i];
    }
}

// Free allocated memory
void free_memory(int num_records, long* offsets, int* keys, Record** records, Metadata* metadata) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
    for (int i = 0; i < num_records; i++) {
        free(metadata->records[i]);
    }
    free(metadata->records);
    free(metadata);
}

int main() {
    int num_records = 100;
    long* offsets;
    int* keys;
    Record** records;
    Metadata* metadata;
    PRNGState* prng;

    srand(time(NULL)); // Seed for the initial PRNG state
    prng = prng_init(rand());

    allocate_memory(num_records, &offsets, &keys, &records, &metadata, prng);

    // Example usage: Access a record
    printf("Record 0 value: %d\n", records[0]->value);

    free_memory(num_records, offsets, keys, records, metadata);
    prng_free(prng); // Assuming prng_free is defined to properly clean up PRNG state

    return 0;
}
```

