Record* create_record(int data_field, const char* variable_length_data) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->data_field = data_field;
    record->variable_length_data = strdup(variable_length_data);
    if (!record->variable_length_data) {
        free(record);
        return NULL;
    }

    return record;
}

void destroy_record(Record* record) {
    if (record) {
        free(record->variable_length_data);
        free(record);
    }
}

