        data[i].timestamp = time(NULL);
        data[i].key = malloc(10 * sizeof(char));
        sprintf(data[i].key, "Key%d", i);
        data[i].record = malloc(sizeof(void*));
        data[i].input = (float)(rand() % 100) / 100.0;
        data[i].stringPtrs = malloc(2 * sizeof(char*));
        for (int j = 0; j < 2; j++) {
            data[i].stringPtrs[j] = malloc(50 * sizeof(char));
            sprintf(data[i].stringPtrs[j], "String%d_%d", i, j);
        }
    }

    // Initialize Union-Find structure
    uf.size = 10;
    uf.parent = malloc(uf.size * sizeof(int));
    uf.rank = malloc(uf.size * sizeof(int));
    for (int i = 0; i < uf.size; i++) {
        uf.parent[i] = i;
        uf.rank[i] = 0;
    }

    // Process data and update Union-Find structure
    for (int i = 0; i < 10; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        while (uf.parent[a] != a) a = uf.parent[a];
        while (uf.parent[b] != b) b = uf.parent[b];
        if (a != b) {
            if (uf.rank[a] < uf.rank[b]) {
                uf.parent[a] = b;
            } else if (uf.rank[a] > uf.rank[b]) {
                uf.parent[b] = a;
            } else {
                uf.parent[a] = b;
                uf.rank[b]++;
            }
        }
    }

    // Read floating-point numbers and find smallest
    float* arr = malloc(10 * sizeof(float));
    for (int i = 0; i < 10; i++) {
