#include <string.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
    char* strValue;
} Record;

// Function to initialize an array of records
void initRecords(Record** records, size_t count) {
    const char* stringList[] = {"apple", "banana", "cherry"};
    size_t listSize = sizeof(stringList) / sizeof(stringList[0]);

    *records = (Record*)malloc(count * sizeof(Record));
    if (*records == NULL) {
        // Log error
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        // Initialize fields with random values and strings
        (*records)[i].offset = rand();
        (*records)[i].key = rand() % 1000; // Assuming key range [0, 999]
        (*records)[i].value = (double)(rand() % 1000) / 10.0; // Assuming value range [0.0, 99.9]

        // Allocate memory for the string and copy a random string from the list
        (*records)[i].strValue = (char*)malloc(6 * sizeof(char)); // Size of "banana" + null terminator
        if ((*records)[i].strValue == NULL) {
            // Log error
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            continue;
        }
        strcpy((*records)[i].strValue, stringList[rand() % listSize]);
    }

    printf("Records initialized successfully\n");
}

// Function to free the allocated memory
void freeRecords(Record* records, size_t count) {
    if (records == NULL) return;

    for (size_t i = 0; i < count; ++i) {
        free(records[i].strValue);
    }
    free(records);
}

int main() {
    const size_t recordCount = 10;
    Record* records;

    initRecords(&records, recordCount);

    // Use the records...

