#define MAX_ID 10000
#define NUM_TRANSACTIONS 5000

typedef struct {
    int id;
    int status_code;
    char descriptor[256];
} Transaction;

void generate_random_transaction(Transaction *transaction) {
    transaction->id = rand() % MAX_ID;
    transaction->status_code = rand() % 100; // Assuming status codes range from 0 to 99
    for (int i = 0; i < 255; i++) {
        transaction->descriptor[i] = 'a' + rand() % ('z' - 'a' + 1);
    }
    transaction->descriptor[255] = '\0';
}

void log_event(const char *message) {
    printf("LOG: %s\n", message);
}

void initialize_transactions(Transaction **transactions, int num_transactions) {
    if (num_transactions <= 0) {
        log_event("Error: Invalid number of transactions");
        return;
    }

    *transactions = malloc(num_transactions * sizeof(Transaction));
    if (*transactions == NULL) {
        log_event("Error: Memory allocation failed");
        return;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_transactions; i++) {
        generate_random_transaction(&(*transactions)[i]);
        printf("Transaction %d - ID: %d, Status: %d, Descriptor: %s\n", 
               i + 1, (*transactions)[i].id, (*transactions)[i].status_code, 
               (*transactions)[i].descriptor);
    }
}

void free_transactions(Transaction *transactions) {
    if (transactions != NULL) {
        free(transactions);
    }
}

int main() {
    Transaction *transactions = NULL;

    initialize_transactions(&transactions, NUM_TRANSACTIONS);

    // Perform further operations with transactions...

    free_transactions(transactions);

    return 0;
}
