record* create_records(long *offsets, int *keys, size_t count) {
    record *records = malloc(count * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (size_t i = 0; i < count; ++i) {
