    }

    return records;
}

int find_largest(int *array, size_t count) {
    int largest = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void process_input() {
    int input_numbers[MAX_RECORDS];
    size_t count = 0;

    printf("Enter integers separated by spaces: ");
    while (scanf("%d", &input_numbers[count]) == 1 && count < MAX_RECORDS) {
        ++count;
    }

    if (count == 0) {
        fprintf(stderr, "No input provided.\n");
        return;
    }

    int largest = find_largest(input_numbers, count);
    printf("The largest number is: %d\n", largest);
