    printf("Enter number of strings: ");
    scanf("%zu", string_count);
    *string_array = (char **)malloc(*string_count * sizeof(char *));

    for (size_t i = 0; i < *int_count; ++i) {
        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &(*int_array)[i]);
    }

    for (size_t i = 0; i < *string_count; ++i) {
        (*string_array)[i] = (char *)malloc(MAX_STRING_LENGTH * sizeof(char));
        printf("Enter string %zu: ", i + 1);
        scanf("%255s", (*string_array)[i]);
    }
}

void free_input(int *int_array, char **string_array, size_t int_count, size_t string_count) {
    free(int_array);
    for (size_t i = 0; i < string_count; ++i) {
        free(string_array[i]);
    }
    free(string_array);
}

