    scanf("%zu", &record_count);

    long *offsets = allocate_offset_array(record_count);
    int *keys = allocate_key_array(record_count);
    record *records = allocate_record_array(record_count);

    initialize_records(records, record_count, 1, 1000, time(NULL));

    printf("Largest integer: %d\n", find_largest_integer(keys, record_count));

    size_t int_count, string_count;
    char **strings = NULL;
    read_input(&keys, &strings, &int_count, &string_count);

    printf("Longest string length: %d\n", find_longest_string(strings, string_count));

    free_records(records, record_count);
    free_keys(keys);
    free_offsets(offsets);
    free_input(keys, strings, int_count, string_count);

    return 0;
}
