DetailedRecord* initializeRecords(int size, PRNG *prng, const char *charSet, int minLength, int maxLength) {
    if (size <= 0 || prng == NULL || charSet == NULL || minLength < 1 || minLength > maxLength || maxLength > 10) {
        return NULL;
    }

    DetailedRecord* records = malloc(size * sizeof(DetailedRecord));
    if (records == NULL) {
        return NULL;
