    long offsets[size];
    int keys[size];

    for (int i = 0; i < size; i++) {
        offsets[i] = prng->generateLong(prng);
        keys[i] = prng->generateInt(prng, minValue, maxValue);

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].record.value = prng->generateInt(prng, recordMinValue, recordMaxValue);
        records[i].eventTimestamp = time(NULL);

        int fieldLength = prng->generateInt(prng, minLength, maxLength);
        for (int j = 0; j < fieldLength; j++) {
            records[i].record.field[j] = charSet[prng->generateInt(prng, 0, strlen(charSet) - 1)];
        }
        records[i].record.field[fieldLength] = '\0';
    }

    return records;
}
