#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_RECORDS 100000

typedef struct {
    int value;
} Record;

Record* allocate_and_init_pipeline(int num_records, int min_value, int max_value) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        return NULL;
    }

    Record *pipeline = malloc(num_records * sizeof(Record));
    if (!pipeline) {
        perror("Failed to allocate memory for pipeline.");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; ++i) {
        int random_value = rand() % (max_value - min_value + 1) + min_value;
        pipeline[i].value = random_value;
    }

    return pipeline;
}

void serialize_pipeline(Record *pipeline, int num_records, FILE *output_file) {
    if (!pipeline || !output_file) {
        fprintf(stderr, "Error: Invalid input parameters for serialization.\n");
        return;
    }

    fwrite(pipeline, sizeof(Record), num_records, output_file);
}

int deserialize_pipeline(Record **pipeline, FILE *input_file, int *num_records) {
    if (!input_file || !num_records) {
        fprintf(stderr, "Error: Invalid input parameters for deserialization.\n");
        return -1;
    }

    fseek(input_file, 0, SEEK_END);
    long file_size = ftell(input_file);
    fseek(input_file, 0, SEEK_SET);

    *num_records = file_size / sizeof(Record);
    if (*num_records <= 0) {
        fprintf(stderr, "Error: Invalid file size for deserialization.\n");
        return -1;
    }

    *pipeline = realloc(*pipeline, *num_records * sizeof(Record));
    if (!*pipeline) {
        perror("Failed to allocate memory for deserialized pipeline.");
        return -1;
    }

    fread(*pipeline, sizeof(Record), *num_records, input_file);

    return 0;
}

void free_pipeline(Record *pipeline) {
    if (pipeline) {
        free(pipeline);
    }
}
```

