#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
    char* str;
} Record;

// Custom pseudo-random number generator using the Mersenne Twister algorithm
unsigned int mt[624];
int index = 624;

void initPRNG(unsigned int seed) {
    mt[0] = seed;
    for (int i = 1; i < 624; ++i) {
        mt[i] = (1812736953UL * (mt[i - 1] ^ (mt[i - 1] >> 30)) + i) & 0xFFFFFFFFUL;
    }
}

unsigned int genPRNG() {
    if (index >= 624) {
        for (int i = 0; i < 227; ++i) {
            unsigned int y = (mt[i] & 0x80000000UL) | (mt[(i + 1) % 624] & 0x7FFFFFFFUL);
            mt[i] = mt[(i + 397) % 624] ^ (y >> 1);
            if (y & 1) {
                mt[i] ^= 0x9908B0DFUL;
            }
        }
        for (int i = 227; i < 623; ++i) {
            unsigned int y = (mt[i] & 0x80000000UL) | (mt[(i + 1) % 624] & 0x7FFFFFFFUL);
            mt[i] = mt[(i - 227) % 624] ^ (y >> 1);
            if (y & 1) {
                mt[i] ^= 0x9908B0DFUL;
            }
        }
        unsigned int y = (mt[623] & 0x80000000UL) | (mt[0] & 0x7FFFFFFFUL);
        mt[623] = mt[396] ^ (y >> 1);
        if (y & 1) {
            mt[623] ^= 0x9908B0DFUL;
        }
        index = 0;
    }

    unsigned int y = mt[index++];
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9D2C5680UL;
    y ^= (y << 15) & 0xEFC60000UL;
    y ^= (y >> 18);

    return y;
}

void initRecords(Record* records, int count, unsigned int seed) {
    initPRNG(seed);
    char alphabet[] = "abcdefghijklmnopqrstuvwxyz";
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        records[i].key = i;
        records[i].offset = genPRNG() % 1000000L;
        int strLength = genPRNG() % 20 + 5; // Random length between 5 and 24
        records[i].str = (char*)malloc((strLength + 1) * sizeof(char));
        for (int j = 0; j < strLength; ++j) {
            records[i].str[j] = alphabet[genPRNG() % 26];
        }
        records[i].str[strLength] = '\0';
    }
}

void freeRecords(Record* records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i].str);
    }
}

int main() {
    Record records[MAX_RECORDS];
    initRecords(records, MAX_RECORDS, time(NULL));

    // Print records for demonstration
    for (int i = 0; i < MAX_RECORDS; ++i) {
        printf("Record %d: Key=%d, Offset=%ld, Str=%s\n", i, records[i].key, records[i].offset, records[i].str);
    }

    freeRecords(records, MAX_RECORDS);

    return 0;
}
```

**PRNG Choice and Rationale**: The Mersenne Twister algorithm is chosen for this task because it provides a good balance between performance and randomness quality. It has a period of \(2^{19937} - 1\) and generates high-quality pseudo-random numbers, making it suitable for applications requiring both speed and robustness in generating random data. The choice also allows for easy integration with other components that might need to generate random numbers independently.']

