        records[i].rec.value = prng(1000); // Example PRNG usage

        int length = minLength + prng(maxLength - minLength + 1); // Random string length within the specified range
        for (int j = 0; j < length; j++) {
            int index = prng(strlen(charSet));
            records[i].rec.field[j] = charSet[index];
        }
        records[i].rec.field[length] = '\0';

        records[i].eventTimestamp = time(NULL);
