    for (int i = 0; i < size; ++i) {
        records[i].offset = prng->generateLong(prng, 0, INT_MAX);
        records[i].key = prng->generateInt(prng, 0, INT_MAX);
        records[i].record.value = prng->generateInt(prng, -100, 100);

        int length = prng->generateInt(prng, minLength, maxLength);
        for (int j = 0; j < length; ++j) {
            records[i].record.field[j] = charSet[prng->generateInt(prng, 0, strlen(charSet))];
        }
        records[i].record.field[length] = '\0';

        records[i].eventTimestamp = currentTime + i;
    }

    return records;
