#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t size;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    collection->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    if (!collection->offsets || !collection->keys) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;

    srand(time(NULL)); // Seed for random number generation

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->offsets);
        free(collection->keys);
        free(collection);
    }
}

int add_record(RecordCollection *collection, Record record) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * GROWTH_FACTOR;
        long *new_offsets = realloc(collection->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(collection->keys, new_capacity * sizeof(int));

        if (!new_offsets || !new_keys) {
            return -1; // Realloc failed
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->capacity = new_capacity;
    }

    collection->offsets[collection->size] = (long)record.value;
    collection->keys[collection->size] = record.value;
    collection->size++;

    return 0; // Success
}

void serialize_record_collection(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&collection->size, sizeof(size_t), 1, file);
    fwrite(collection->offsets, sizeof(long), collection->size, file);
    fwrite(collection->keys, sizeof(int), collection->size, file);

    fclose(file);
}

void deserialize_record_collection(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    if (new_size > collection->capacity) {
        long *new_offsets = realloc(collection->offsets, new_size * sizeof(long));
        int *new_keys = realloc(collection->keys, new_size * sizeof(int));

        if (!new_offsets || !new_keys) {
            fclose(file);
            return; // Realloc failed
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->capacity = new_size;
    }

    fread(collection->offsets, sizeof(long), new_size, file);
    fread(collection->keys, sizeof(int), new_size, file);

    collection->size = new_size;

    fclose(file);
}
