#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <openssl/rand.h>

typedef struct {
    int value;
} record;

int initialize_arrays(size_t size, long** offsets, int** keys, record** records) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; i++) {
        (*offsets)[i] = rand() % (RAND_MAX / 2); // Generate a random long offset
        (*keys)[i] = rand() % 1000; // Generate a random int key

        // Initialize records with cryptographically secure values
        if (!RAND_bytes((unsigned char*)&(*records)[i].value, sizeof((*records)[i].value))) {
            perror("PRNG seeding failed");
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
    }

    // Periodically reseed PRNG with entropy from the system
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        unsigned char buf[sizeof(ts.tv_sec) + sizeof(ts.tv_nsec)];
        memcpy(buf, &ts.tv_sec, sizeof(ts.tv_sec));
        memcpy(buf + sizeof(ts.tv_sec), &ts.tv_nsec, sizeof(ts.tv_nsec));
        if (!RAND_add(buf, sizeof(buf), 1)) {
            perror("PRNG reseeding failed");
        }
    } else {
        perror("Failed to get current time for PRNG reseeding");
    }

    return 0;
}

int main() {
    size_t size = 1000; // Example size
    long* offsets;
    int* keys;
    record* records;

    if (initialize_arrays(size, &offsets, &keys, &records) == 0) {
        printf("Arrays initialized successfully.\n");

        // Free allocated memory
        free(offsets);
        free(keys);
        free(records);
    }

    return 0;
}
