#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_USERS 1000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* users[MAX_USERS];
int user_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* create_user(int key, int value) {
    pthread_mutex_lock(&mutex);
    if (user_count >= MAX_USERS) {
        pthread_mutex_unlock(&mutex);
        return "{\"status\":\"failure\",\"message\":\"Maximum users reached\"}";
    }
    Record* user = malloc(sizeof(Record));
    user->offset = rand();
    user->key = key;
    user->value = value;
    users[user_count++] = user;
    pthread_mutex_unlock(&mutex);
    return "{\"status\":\"success\",\"message\":\"User created successfully\"}";
}

char* update_user(int key, int new_value) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < user_count; i++) {
        if (users[i]->key == key) {
            users[i]->value = new_value;
            pthread_mutex_unlock(&mutex);
            return "{\"status\":\"success\",\"message\":\"User updated successfully\"}";
        }
    }
    pthread_mutex_unlock(&mutex);
    return "{\"status\":\"failure\",\"message\":\"User not found\"}";
}

char* delete_user(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < user_count; i++) {
        if (users[i]->key == key) {
            free(users[i]);
            memmove(&users[i], &users[i+1], sizeof(Record*) * (user_count - i - 1));
            user_count--;
            pthread_mutex_unlock(&mutex);
            return "{\"status\":\"success\",\"message\":\"User deleted successfully\"}";
        }
    }
    pthread_mutex_unlock(&mutex);
    return "{\"status\":\"failure\",\"message\":\"User not found\"}";
}

void* manage_user_accounts(void* arg) {
    int operation = *(int*)arg;
    switch (operation) {
        case 1: // Create user
            printf("%s\n", create_user(rand(), rand()));
            break;
        case 2: // Update user
            printf("%s\n", update_user(rand() % MAX_USERS, rand()));
            break;
        case 3: // Delete user
            printf("%s\n", delete_user(rand() % MAX_USERS));
            break;
    }
    free(arg);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* operation = malloc(sizeof(int));
        *operation = rand() % 3 + 1;
        pthread_create(&threads[i], NULL, manage_user_accounts, operation);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
