#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define DEFAULT_CAPACITY 10
#define MIN_RANDOM 1
#define MAX_RANDOM 100

typedef struct {
    int value;
} record;

record* create_records(int *size, int initial_capacity);
void destroy_records(record **records, int *size);
int add_record(record **records, int *size, int capacity);
void serialize_records(const record *records, int size, const char *filename);
int deserialize_records(record **records, int *size, const char *filename);

record* create_records(int *size, int initial_capacity) {
    record *records = malloc(initial_capacity * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    *size = 0;
    return records;
}

void destroy_records(record **records, int *size) {
    free(*records);
    *records = NULL;
    *size = 0;
}

int add_record(record **records, int *size, int capacity) {
    if (*size >= capacity) {
        record *new_records = realloc(*records, (capacity + 10) * sizeof(record));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed.\n");
            return -1;
        }
        *records = new_records;
        capacity += 10;
    }
    (*records)[*size].value = rand() % (MAX_RANDOM - MIN_RANDOM + 1) + MIN_RANDOM;
    (*size)++;
    return 0;
}

void serialize_records(const record *records, int size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing.");
        return;
    }

    // Write records to file
    fwrite(records, sizeof(record), size, file);

    // Calculate checksum and write it
    unsigned int checksum = 0;
    for (int i = 0; i < size; i++) {
        checksum += records[i].value;
    }
    fwrite(&checksum, sizeof(unsigned int), 1, file);

    fclose(file);
}

int deserialize_records(record **records, int *size, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file for reading.");
        return -1;
    }

    // Read records from file
    *size = fread(*records, sizeof(record), DEFAULT_CAPACITY, file);
    if (*size < 0) {
        fclose(file);
        fprintf(stderr, "Error reading from file.\n");
        return -1;
    }

    // Calculate checksum and read it
    unsigned int stored_checksum, calculated_checksum = 0;
    fread(&stored_checksum, sizeof(unsigned int), 1, file);

    for (int i = 0; i < *size; i++) {
        calculated_checksum += (*records)[i].value;
    }

    if (calculated_checksum != stored_checksum) {
        fclose(file);
        fprintf(stderr, "Checksum validation failed.\n");
        return -1;
    }

    fclose(file);
    return 0;
}

int main() {
    srand(time(NULL));
    record *records = create_records(&record_count, DEFAULT_CAPACITY);

    for (int i = 0; add_record(&records, &record_count, DEFAULT_CAPACITY) == 0 && i < 25; i++);

    serialize_records(records, record_count, "data.bin");

    destroy_records(&records, &record_count);
    return 0;
}
