#include <time.h>

typedef struct {
    time_t timestamp;
    double amount;
    int id;
} Transaction;

Transaction* create_transaction_array(size_t initial_size) {
    return (Transaction*)malloc(initial_size * sizeof(Transaction));
}

void free_transaction_array(Transaction* transactions, size_t size) {
    free(transactions);
}

int generate_unique_id() {
    static int last_id = 0;
    last_id++;
    if (last_id == INT_MAX) {
        last_id = 1; // Reset to avoid overflow
    }
    return last_id;
}

void serialize_transactions(Transaction* transactions, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(transactions, sizeof(Transaction), size, file);
    fclose(file);
}

void deserialize_transactions(Transaction** transactions_ptr, size_t* size_ptr, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        *transactions_ptr = NULL;
        *size_ptr = 0;
        return;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *transactions_ptr = (Transaction*)malloc(size);
    if (!*transactions_ptr) {
        perror("Failed to allocate memory for deserialized transactions");
        fclose(file);
        return;
    }

    if (fread(*transactions_ptr, sizeof(Transaction), size / sizeof(Transaction), file) != size / sizeof(Transaction)) {
        perror("Failed to read all data from file");
        free(*transactions_ptr);
        *transactions_ptr = NULL;
        *size_ptr = 0;
    } else {
        *size_ptr = size / sizeof(Transaction);
    }

    fclose(file);
}

int main() {
    Transaction* transactions = create_transaction_array(100);
    if (!transactions) {
        fprintf(stderr, "Failed to allocate initial memory for transactions\n");
        return EXIT_FAILURE;
    }

    // Populate transactions array with data
    for (size_t i = 0; i < 100; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (double)RAND_MAX * 1000.0; // Random amount between 0 and 1000
        transactions[i].id = generate_unique_id();
    }

    serialize_transactions(transactions, 100, "transactions.bin");

    Transaction* deserialized_transactions;
    size_t deserialized_size;
    deserialize_transactions(&deserialized_transactions, &deserialized_size, "transactions.bin");

    if (deserialized_transactions) {
        // Process deserialized transactions
        free_transaction_array(deserialized_transactions, deserialized_size);
    }

    free_transaction_array(transactions, 100);

    return EXIT_SUCCESS;
}
```

This code provides a basic framework for managing and serializing transaction data. It includes functions to create and free an array of `Transaction` structures, generate unique identifiers using a simple counter (with a reset mechanism), serialize transactions to a binary file, and deserialize them back into memory. The main function demonstrates creating a set of transactions, serializing them, deserializing them, and cleaning up allocated memory.']

