log_entry* initialize_log_entries(int num_entries) {
    if (num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Error: Maximum number of entries exceeded.\n");
        return NULL;
    }

    log_entry* entries = (log_entry*)malloc(num_entries * sizeof(log_entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed for log entries.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    char buffer[20];

    for (int i = 0; i < num_entries; ++i) {
        entries[i].value = rand() % 1000; // Pseudo-random value between 0 and 999

        strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", localtime(&entries[i].timestamp));
        sprintf(entries[i].str, "entry_%s", buffer);

        entries[i].str = (char*)realloc(entries[i].str, strlen(buffer) + 1);
        if (!entries[i].str) {
            fprintf(stderr, "Memory allocation failed for string in log entry %d.\n", i);
            free_log_entries(entries, num_entries); // Free allocated memory before returning NULL
            return NULL;
        }
    }

    return entries;
}

void free_log_entries(log_entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].str);
    }
    free(entries);
}

