#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_USERS 1000
#define CACHE_SIZE 500

typedef struct {
    int key;
    int value;
} User;

User users[MAX_USERS];
int user_count = 0;
int cache[CACHE_SIZE][2]; // [key, value]
int cache_size = 0;

void init_users() {
    srand(time(NULL));
}

int generate_unique_key() {
    while (1) {
        int key = rand();
        int found = 0;
        for (int i = 0; i < user_count; i++) {
            if (users[i].key == key) {
                found = 1;
                break;
            }
        }
        if (!found) return key;
    }
}

void create_user(int value) {
    int key = generate_unique_key();
    users[user_count].key = key;
    users[user_count++].value = value;
    // Cache the new user
    cache[cache_size][0] = key;
    cache[cache_size++][1] = value;
}

void update_user(int key, int value) {
    for (int i = 0; i < user_count; i++) {
        if (users[i].key == key) {
            users[i].value = value;
            // Update cache
            for (int j = 0; j < cache_size; j++) {
                if (cache[j][0] == key) {
                    cache[j][1] = value;
                    return;
                }
            }
        }
    }
}

void delete_user(int key) {
    for (int i = 0; i < user_count; i++) {
        if (users[i].key == key) {
            memmove(&users[i], &users[i + 1], (user_count - i - 1) * sizeof(User));
            user_count--;
            // Invalidate cache
            for (int j = 0; j < cache_size; j++) {
                if (cache[j][0] == key) {
                    memmove(&cache[j], &cache[j + 1], (cache_size - j - 1) * sizeof(int[2]));
                    cache_size--;
                    break;
                }
            }
        }
    }
}

int get_user_value(int key) {
    // Check cache first
    for (int i = 0; i < cache_size; i++) {
        if (cache[i][0] == key) return cache[i][1];
    }
    // If not in cache, check main memory
    for (int i = 0; i < user_count; i++) {
        if (users[i].key == key) return users[i].value;
    }
    return -1; // User not found
}

void validate_input(int key, int value) {
    if (key < 0 || value < 0) {
        printf("Invalid input: Key and value must be non-negative integers.\n");
        exit(1);
    }
}

int main() {
    init_users();
    create_user(10);
    update_user(1, 20);
    printf("User value for key 1: %d\n", get_user_value(1));
    delete_user(1);
    return 0;
}
```

