typedef struct {
    double value;
    char* message;
    float performance_metric;
} Data;

typedef struct {
    int value;
    char* status_message;
} Record;

// Helper function to find the smallest floating-point number
double find_smallest(double* arr, int size) {
    if (size <= 0) return -1.0; // Return an error value for invalid input
    double min = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

void perform_task() {
    long* seed_values = (long*)malloc(30 * sizeof(long));
    int* indices = (int*)malloc(30 * sizeof(int));
    Data* data_structures = (Data*)malloc(30 * sizeof(Data));
    double* input_numbers = NULL;
    int num_input_numbers = 0;

    // Initialize arrays and structures
    for (int i = 0; i < 30; i++) {
        seed_values[i] = rand();
        indices[i] = i;
        data_structures[i].value = (double)i * 1.1;
        data_structures[i].message = (char*)malloc(20 * sizeof(char));
        snprintf(data_structures[i].message, 20, "Message %d", i);
        data_structures[i].performance_metric = (float)(i + 0.5);
    }

    // Read floating-point numbers from standard input
    double num;
    while (scanf("%lf", &num) != EOF) {
        input_numbers = realloc(input_numbers, sizeof(double) * (num_input_numbers + 1));
        if (!input_numbers) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        input_numbers[num_input_numbers++] = num;
    }

    // Find and print the smallest floating-point number
    double smallest_num = find_smallest(input_numbers, num_input_numbers);
    printf("Smallest number: %f\n", smallest_num);

    // Clean up dynamically allocated memory
    free(seed_values);
    free(indices);
    for (int i = 0; i < 30; i++) {
        free(data_structures[i].message);
    }
    free(data_structures);
    if (input_numbers) {
        free(input_numbers);
    }
}

int main() {
    srand(time(NULL));
    perform_task();
    return 0;
}
