void initializeSensorData(long* offsetArray, int* keyArray, sensorRecord** records, size_t count, int rangeMin, int rangeMax) {
    if (count <= 0 || rangeMin > rangeMax) {
        fprintf(stderr, "Invalid input values.\n");
        return;
    }

    srand(time(NULL)); // Seed for PRNG

    // Allocate memory for arrays
    offsetArray = (long*)malloc(count * sizeof(long));
    keyArray = (int*)malloc(count * sizeof(int));
    records = (sensorRecord**)malloc(count * sizeof(sensorRecord*));

    if (offsetArray == NULL || keyArray == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < count; ++i) {
        offsetArray[i] = rand(); // Using rand() for non-cryptographic PRNG

        keyArray[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;

        records[i] = (sensorRecord*)malloc(sizeof(sensorRecord));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %zu.\n", i);
            return;
        }

        records[i]->timestamp = time(NULL);
        records[i]->statusCode = rand() % 100; // Simulating sensor status code
        records[i]->sensorReading = (double)(rand() % 1000) / 10.0; // Simulating sensor reading
    }
