            // Free previously allocated tokens and sessions
            for (int j = 0; j < i; ++j) {
                free(sessions[j].token);
            }
            free(sessions);
            return NULL;
        }

        // Generate a random token using PRNG
        snprintf(sessions[i].token, 33, "%08x%08x", rand(), rand());
    }

    return sessions;
}

void free_session_array(session* sessions, int size) {
    for (int i = 0; i < size; ++i) {
        free(sessions[i].token);
    }
    free(sessions);
}

