#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    char* data;
    long offset;
    int key;
    time_t timestamp;
} record;

int initialize_records(record** records, size_t num_records, size_t max_data_len) {
    *records = (record*)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        log_error("Memory allocation failed for records");
        return -1;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        free(*records);
        log_error("Memory allocation failed for offsets");
        return -1;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        free(*records);
        log_error("Memory allocation failed for keys");
        return -1;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
        (*records)[i].timestamp = time(NULL);

        size_t data_len = rand() % max_data_len + 1;
        (*records)[i].data = (char*)malloc(data_len * sizeof(char));
        if ((*records)[i].data == NULL) {
            log_error("Memory allocation failed for record data");
            // Clean up previously allocated resources
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].data);
            }
            pthread_mutex_destroy(&lock);
            free(keys);
            free(offsets);
            free(*records);
            return -1;
        }

        // Initialize the data string with random characters
        for (size_t j = 0; j < data_len; ++j) {
            (*records)[i].data[j] = 'a' + rand() % 26;
        }
    }

    pthread_mutex_destroy(&lock);
    free(offsets);
    free(keys);

    log_info("Records initialized successfully");
    return 0;
}
