    printf("Largest integer: %d\n", largestInt);

    free(intValues);

    // Assume setupRemoteConnection and handleData manage the Java Channel.
    setupRemoteConnection();
    for (long i = 0; i < numRecords; i++) {
        handleData(records[i]);
    }
    closeRemoteConnection();
}

