// Function to find the largest floating-point number in an array
float find_largest(float* arr, int size) {
    if (size <= 0) {
        fprintf(stderr, "Array is empty or invalid\n");
        return -1.0f;
    }
    float max_val = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
