// Function to calculate the average time interval between consecutive timestamps
double avg_time_interval(time_t* timestamps, int count) {
    if (count <= 1) {
        fprintf(stderr, "Not enough timestamps for an interval\n");
        return -1.0;
    }
    double total_interval = difftime(timestamps[1], timestamps[0]);
    for (int i = 2; i < count; i++) {
        total_interval += difftime(timestamps[i], timestamps[i-1]);
    }
