#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define MAX_EVENTS 1000
#define MAX_DESCRIPTION 256

typedef struct {
    long timestamp;
    int event_id;
    char description[MAX_DESCRIPTION];
} Event;

Event* init_events(int num_events) {
    Event *events = malloc(num_events * sizeof(Event));
    if (events == NULL) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    // Initialize PRNG
    srand(time(NULL));

    for (int i = 0; i < num_events; ++i) {
        events[i].timestamp = rand() % (1000 * 60 * 60 * 24); // Random timestamp in last day
        events[i].event_id = rand() % 1000; // Random event ID between 0 and 999

        snprintf(events[i].description, MAX_DESCRIPTION, "Event %d", i);
    }

    return events;
}

void log_event_init(int result) {
    if (result == -1) {
        fprintf(stderr, "Error initializing events\n");
    } else {
        printf("Events initialized successfully\n");
    }
}

int connect_to_server(const char *ip, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, ip, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to connect to server");
        close(sock);
        return -1;
    }

    printf("Connected to server\n");
    return sock;
}

void log_server_connection(int result) {
    if (result == -1) {
        fprintf(stderr, "Error connecting to server\n");
    } else {
        printf("Server connection successful\n");
    }
}

int find_max_event_id(int *event_ids, int num_events) {
    if (num_events <= 0) return -1;

    int max_id = event_ids[0];
    for (int i = 1; i < num_events; ++i) {
        if (event_ids[i] > max_id) {
            max_id = event_ids[i];
        }
    }

    return max_id;
}

void log_max_event_id(int max_id, int num_events) {
    if (max_id == -1) {
        fprintf(stderr, "Error finding maximum event ID\n");
    } else {
        printf("Maximum event ID: %d (Found in %d events)\n", max_id, num_events);
    }
}

int main() {
    int num_events = MAX_EVENTS;
    Event *events = init_events(num_events);
    log_event_init(events == NULL ? -1 : 0);

    if (events != NULL) {
        int server_sock = connect_to_server("127.0.0.1", 8080);
        log_server_connection(server_sock);

        // Close socket
        close(server_sock);

        // Free events memory
        free(events);
    }

    return 0;
}
