['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    char* event_description;
} Record;

typedef struct memory_pool {
    void** pool;
    size_t size;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

Record* create_records(int count, MemoryPool* pool) {
    if (count <= 0) {
        printf("Error: Count must be greater than zero.\n");
        return NULL;
    }

    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].offset = rand();
        records[i].key = rand();

        size_t desc_length = rand() % 100 + 1;
        records[i].event_description = malloc(desc_length * sizeof(char));
        if (!records[i].event_description) {
            perror("Failed to allocate memory for event description.");
            // Clean up previously allocated records
            for (int j = 0; j < i; j++) {
                free(records[j].event_description);
            }
            free(records);
            return NULL;
        }

        // Generate unique random string for event description
        for (size_t j = 0; j < desc_length - 1; j++) {
            records[i].event_description[j] = 'a' + rand() % 26;
        }
        records[i].event_description[desc_length - 1] = '\0';

        // Add record to memory pool
        pthread_mutex_lock(&pool->mutex);
        if (pool->used >= pool->size) {
            size_t new_size = pool->size == 0 ? 1 : pool->size * 2;
            pool->pool = realloc(pool->pool, new_size * sizeof(void*));
            if (!pool->pool) {
                perror("Failed to resize memory pool.");
                pthread_mutex_unlock(&pool->mutex);
                // Clean up previously allocated records and descriptions
                for (int j = 0; j <= i; j++) {
                    free(records[j].event_description);
                }
                free(records);
                return NULL;
            }
            pool->size = new_size;
        }
        pool->pool[pool->used++] = records + i;
        pthread_mutex_unlock(&pool->mutex);
    }

    return records;
}

void destroy_records(Record* records, int count, MemoryPool* pool) {
    for (int i = 0; i < count; i++) {
        free(records[i].event_description);
    }
    free(records);

    // Clear memory pool
    pthread_mutex_lock(&pool->mutex);
    pool->used = 0;
    pthread_mutex_unlock(&pool->mutex);
}

void init_memory_pool(MemoryPool* pool, size_t initial_size) {
    pool->pool = malloc(initial_size * sizeof(void*));
    if (!pool->pool) {
        perror("Failed to initialize memory pool.");
        return;
    }
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->used; i++) {
        Record* record = pool->pool[i];
        free(record->event_description);
    }
    free(pool->pool);
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 1024);

    int count = 5;
    Record* records = create_records(count, &pool);
    if (records) {
        // Use records...
        destroy_records(records, count, &pool);
    }

    destroy_memory_pool(&pool);
    return 0;
}
```

This code provides a basic implementation of the described task. It includes functions to create and destroy records with memory pooling, as well as initialization and destruction of the memory pool itself. Note that error handling is simplified for brevity; in a production environment, more detailed error checking would be necessary.

For additional functionality such as thread-safe concurrent access, efficient hash table implementation for duplicate event description validation, and optimization strategies, further development would be required based on specific requirements and constraints.']

