int generate_transaction_ids(long *offsets, int *keys, record **records, int num_records, long min_id, long max_id) {
    if (num_records <= 0 || min_id >= max_id) {
        fprintf(stderr, "Invalid input range or number of records.\n");
        return -1;
    }

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_id - min_id + 1) + min_id;
        keys[i] = rand() % (max_id - min_id + 1) + min_id;

        if (!RAND_bytes((unsigned char *)&records[i]->transaction_id, sizeof(records[i]->transaction_id))) {
            fprintf(stderr, "Failed to generate a secure random number.\n");
            return -1;
        }
    }

    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (records[i]->transaction_id == records[j]->transaction_id) {
                fprintf(stderr, "Collision detected in transaction IDs.\n");
                return -1;
            }
        }
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
