Transaction* create_transactions(int count) {
    Transaction* transactions = (Transaction*)malloc(count * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize PRNG
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].transaction_id = rand();
        transactions[i].exchange_rate = ((float)rand() / RAND_MAX) * 1.5 + 0.5;
    }

    return transactions;
}

void read_currency_codes(int** codes, int* count) {
    printf("Enter the number of currency codes: ");
    scanf("%d", count);

    *codes = (int*)malloc(*count * sizeof(int));
    if (*codes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    printf("Enter %d currency codes:\n", *count);
    for (int i = 0; i < *count; ++i) {
        scanf("%d", &(*codes)[i]);
    }
}

float calculate_average_exchange_rate(Transaction* transactions, int count, int* currency_codes, int code_count) {
    float sum = 0.0;
    int valid_codes = 0;

    for (int i = 0; i < count; ++i) {
        for (int j = 0; j < code_count; ++j) {
            if (transactions[i].transaction_id == currency_codes[j]) {
                sum += transactions[i].exchange_rate;
                valid_codes++;
                break;
            }
        }
    }

    return valid_codes > 0 ? sum / valid_codes : 0.0;
}

