// Union-Find data structure implementation
typedef struct {
    int *parent;
    int *rank;
} UnionFind;

void init_union_find(UnionFind *uf, int n) {
    uf->parent = (int *)malloc(n * sizeof(int));
    uf->rank = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int main() {
    long *seed_values = (long *)malloc(12 * sizeof(long));
    int *indices = (int *)malloc(12 * sizeof(int));
    double *data = (double *)malloc(12 * sizeof(double));

    if (!seed_values || !indices || !data) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    // Initialize seed values, indices, and data
    for (int i = 0; i < 12; i++) {
        seed_values[i] = time(NULL);
        indices[i] = rand() % 100;
        data[i] = ((double)rand() / RAND_MAX) * 100.0;
    }

    double *input_numbers = NULL;
    int input_count = 0;

    // Read floating-point numbers from standard input
    while (scanf("%lf", &input_numbers[input_count]) != EOF) {
        input_count++;
        input_numbers = (double *)realloc(input_numbers, (input_count + 1) * sizeof(double));
    }

    double smallest_number = find_smallest(input_numbers, input_count);
    printf("Smallest number: %f\n", smallest_number);

    // Free allocated memory
    free(seed_values);
    free(indices);
    free(data);
    free(input_numbers);

    return EXIT_SUCCESS;
}
