#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define NUM_SEEDS 6

typedef struct {
    float value;
} Data;

typedef struct {
    unsigned long seed[NUM_SEEDS];
    unsigned int indices[NUM_SEEDS];
    Data data[NUM_SEEDS];
    float *input_numbers;
    int *random_numbers;
    unsigned long *unique_ids;
    pthread_mutex_t queue_lock;
    pthread_cond_t queue_not_empty;
    pthread_cond_t queue_full;
    struct QueueNode *front, *rear;
} SharedData;

typedef struct QueueNode {
    char command[256];
    struct QueueNode *next;
} QueueNode;

void enqueue(SharedData *sd, const char *command) {
    QueueNode *new_node = (QueueNode *)malloc(sizeof(QueueNode));
    strcpy(new_node->command, command);
    new_node->next = NULL;
    if (sd->front == NULL) {
        sd->front = sd->rear = new_node;
    } else {
        sd->rear->next = new_node;
        sd->rear = new_node;
    }
}

void *process_queue(void *arg) {
    SharedData *sd = (SharedData *)arg;
    while (1) {
        pthread_mutex_lock(&sd->queue_lock);
        while (sd->front == NULL) {
            pthread_cond_wait(&sd->queue_not_empty, &sd->queue_lock);
        }
        QueueNode *current = sd->front;
        if (sd->front == sd->rear) {
            sd->front = sd->rear = NULL;
        } else {
            sd->front = current->next;
        }
        pthread_mutex_unlock(&sd->queue_lock);

        // Process the command
        printf("Processing: %s\n", current->command);
        free(current);
    }
}

void initialize_data(SharedData *sd) {
    srand(time(NULL));
    for (int i = 0; i < NUM_SEEDS; i++) {
        sd->seed[i] = rand();
        sd->indices[i] = rand() % 100;
        sd->data[i].value = (float)(rand() % 100) / 100.0f;
    }

    int num_numbers;
    printf("Enter the number of floating-point numbers: ");
    scanf("%d", &num_numbers);
    sd->input_numbers = (float *)malloc(num_numbers * sizeof(float));
    for (int i = 0; i < num_numbers; i++) {
        scanf("%f", &sd->input_numbers[i]);
    }

    sd->random_numbers = (int *)malloc(100 * sizeof(int));
    for (int i = 0; i < 100; i++) {
        sd->random_numbers[i] = rand() % 100;
    }

    FILE *fp = fopen("data.csv", "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }
    unsigned long id;
    while (fscanf(fp, "%lu,", &id) == 1) {
        // Assuming no duplicate IDs
        sd->unique_ids[id] = id;
    }
    fclose(fp);

    pthread_mutex_init(&sd->queue_lock, NULL);
    pthread_cond_init(&sd->queue_not_empty, NULL);
    pthread_cond_init(&sd->queue_full, NULL);

    sd->front = sd->rear = NULL;

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, process_queue, sd);
    }

    // Enqueue commands
    enqueue(sd, "Write to file");
    enqueue(sd, "Generate random numbers");

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }
}

int find_smallest_number(float *numbers, int count) {
    if (count <= 0) return -1;
    float smallest = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] < smallest) {
            smallest = numbers[i];
        }
    }
    return smallest;
}

int main() {
    SharedData sd;
    initialize_data(&sd);
    int smallest_number = find_smallest_number(sd.input_numbers, 5);
    printf("Smallest number: %d\n", smallest_number);

    pthread_mutex_destroy(&sd.queue_lock);
    pthread_cond_destroy(&sd.queue_not_empty);
    pthread_cond_destroy(&sd.queue_full);
    free(sd.input_numbers);
    free(sd.random_numbers);

    return 0;
}
