#define MAX_SESSIONS 10000

typedef struct {
    long timestamp;
    int id;
    char* buffer;
    int expiration_time;
    float priority_level;
    int status_code;
} Session;

Session** create_session_pool() {
    Session** pool = (Session**)malloc(MAX_SESSIONS * sizeof(Session*));
    if (!pool) return NULL;

    srand(time(NULL)); // Seed PRNG

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        pool[i] = (Session*)malloc(sizeof(Session));
        if (!pool[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(pool[j]);
            free(pool);
            return NULL;
        }

        pool[i]->timestamp = time(NULL);
        pool[i]->id = i + 1;
        pool[i]->buffer = (char*)malloc(1024 * sizeof(char)); // Example buffer size
        if (!pool[i]->buffer) {
            for (int j = 0; j <= i; ++j) free(pool[j]->buffer);
            free(pool);
            return NULL;
        }
        pool[i]->expiration_time = rand() % 3600 + 1; // Random expiration time between 1 and 3600 seconds
        pool[i]->priority_level = ((float)(rand() % 100)) / 100.0; // Random priority level between 0 and 1
        pool[i]->status_code = rand() % 5 + 1; // Random status code between 1 and 5
    }

    return pool;
}

void destroy_session_pool(Session** pool) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        free(pool[i]->buffer);
        free(pool[i]);
    }
    free(pool);
}
