record* create_records(int num_records, int offset_range_start, int offset_range_end, int key_range_start, int key_range_end) {
    if (num_records > MAX_RECORDS) {
        printf("Error: Exceeds maximum number of records.\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        int offset = generate_random(offset_range_start, offset_range_end);
        records[i].key = generate_random(key_range_start, key_range_end);

        char* value = (char*)malloc(20 * sizeof(char)); // Assuming a maximum string length of 19 characters
        if (!value) {
            printf("Error: Memory allocation failed for record %d.\n", i);
            // Free previously allocated records and return NULL
            for (int j = 0; j < i; j++) {
                free(records[j].value);
            }
            free(records);
            return NULL;
        }
        snprintf(value, 20, "%d", generate_random(0, 999));
        records[i].value = value;
    }

    printf("Allocated memory: %zu bytes for %d records.\n", num_records * sizeof(record), num_records);
