        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];

        if (!records[i].offset_ptr || !records[i].key_ptr) {
            error_flag = 1; // Memory allocation failed
            break;
        }

        offsets[i] = i * 10; // Example offset calculation
        keys[i] = i * 5;   // Example key calculation
    }

    if (error_flag) {
        free(records);
        records = NULL;
    } else {
        for (int i = 0; i < NUM_RECORDS; ++i) {
            records[i].error_flag = error_flag;
        }
    }

