    time_t timestamp;
    int id;
    SensorData data;
    struct SensorNode* next;
} SensorNode;

// Function to initialize PRNG with a seed
void init_prng(unsigned long seed) {
    srand(seed);
}

// Non-cryptographically secure PRNG function
unsigned int prng() {
    return rand();
}

// Function to validate PRNG output range
int is_valid_prng_output(unsigned int value, unsigned int min, unsigned int max) {
    return value >= min && value <= max;
}

// Function for dynamic memory allocation and initialization
void* allocate_and_init(int type, size_t size, unsigned long seed) {
    void* ptr = NULL;
    init_prng(seed);

    switch (type) {
        case 1: // Array of double
            ptr = malloc(size * sizeof(double));
            if (!ptr) {
                perror("Memory allocation failed for array of doubles");
                return NULL;
            }
            for (size_t i = 0; i < size; i++) {
                ((double*)ptr)[i] = prng() / (RAND_MAX + 1.0);
            }
            break;
        case 2: // Array of char
            ptr = malloc(size * sizeof(char));
            if (!ptr) {
                perror("Memory allocation failed for array of chars");
                return NULL;
            }
            for (size_t i = 0; i < size; i++) {
                ((char*)ptr)[i] = 'a' + prng() % 26;
            }
            break;
        case 3: // Array of SensorData
            ptr = malloc(size * sizeof(SensorData));
            if (!ptr) {
                perror("Memory allocation failed for array of SensorData");
                return NULL;
            }
            for (size_t i = 0; i < size; i++) {
                ((SensorData*)ptr)[i].temperature = prng() / (RAND_MAX + 1.0);
                ((SensorData*)ptr)[i].humidity = prng() / (RAND_MAX + 1.0);
                ((SensorData*)ptr)[i].pressure = prng() / (RAND_MAX + 1.0);
            }
            break;
        case 4: // Linked list of SensorNode
            ptr = malloc(sizeof(SensorNode));
            if (!ptr) {
                perror("Memory allocation failed for linked list of SensorNode");
                return NULL;
            }
            ((SensorNode*)ptr)->timestamp = time(NULL);
            ((SensorNode*)ptr)->id = prng();
            ((SensorNode*)ptr)->data.temperature = prng() / (RAND_MAX + 1.0);
            ((SensorNode*)ptr)->data.humidity = prng() / (RAND_MAX + 1.0);
            ((SensorNode*)ptr)->data.pressure = prng() / (RAND_MAX + 1.0);
            ((SensorNode*)ptr)->next = NULL;
            break;
        default:
            fprintf(stderr, "Unknown type for allocation\n");
            return NULL;
    }

    if (!is_valid_prng_output(((char*)ptr)[size - 1], 0, 255)) {
        fprintf(stderr, "Invalid PRNG output detected\n");
        free(ptr);
        return NULL;
    }

    pthread_mutex_t* lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!lock) {
        perror("Memory allocation failed for mutex");
        free(ptr);
        return NULL;
    }
    pthread_mutex_init(lock, NULL);

    ptr = realloc(ptr, size * sizeof(char) + sizeof(void*));
    ((void**)ptr)[size] = lock;

    return ptr;
}

// Function to free allocated memory
void free_memory(void* ptr) {
    if (ptr) {
        void** ptr_with_lock = (void**)ptr;
        pthread_mutex_t* lock = (pthread_mutex_t*)ptr_with_lock[size];
        pthread_mutex_destroy(lock);
        free(lock);
        free(ptr_with_lock);
    }
}
