// Example hash function using djb2 algorithm
int hash_function(long key) {
    unsigned long hash = 5381;
    while (key) {
        hash = ((hash << 5) + hash) + (key & 0xFF); /* hash * 33 + c */
        key >>= 8;
    }
    return hash % INT_MAX; // Ensure result is within int range
}

