int validateRecords(record* records, long* offsets, int keys[], int num_records, long min_offset, long max_offset) {
    // Validate unique keys and offsets
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (keys[i] == keys[j]) return -1; // Duplicate key found
            if ((offsets[i] < min_offset || offsets[i] > max_offset) || (offsets[j] < min_offset || offsets[j] > max_offset)) return -2; // Offset out of range
        }
    }
    return 0; // Validation passed
}

int generateRecords(record** records, long** offsets, int keys[], int num_records, long min_offset, long max_offset) {
    *records = (record*)malloc(num_records * sizeof(record));
    *offsets = (long*)malloc(num_records * sizeof(long));
    if (*records == NULL || *offsets == NULL) return -1; // Memory allocation failed

    srand(time(NULL)); // Seed for pseudo-random number generator
    int seed = rand();
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand_r((unsigned int*)&seed); // Generate unique key
        (*records)[i].value = rand(); // Generate random record value
        do {
            *offsets[i] = min_offset + (long)(rand() / (RAND_MAX / (max_offset - min_offset + 1)));
        } while ((*offsets[i] < min_offset) || (*offsets[i] > max_offset)); // Ensure offset is within valid range
    }

    int status = validateRecords(*records, *offsets, keys, num_records, min_offset, max_offset);
    if (status != 0) {
        free(*records);
        free(*offsets);
        return status; // Validation failed
    }

    return 0; // Generation and validation successful
}

// Example usage in main or another function
int main() {
    int num_records = 1000;
    long min_offset = 0, max_offset = 9999;
