import java.util.HashSet;

public class RecordProcessor {

    public int calculateDisjointPairs(int[] array) {
        HashSet<Integer> elements = new HashSet<>();
        for (int num : array) {
            if (!elements.add(num)) return 0; // Duplicate found, not disjoint
        }

        // Number of disjoint pairs is n-1 where n is the number of unique elements
        return elements.size() - 1;
    }

    public static void main(String[] args) {
        RecordProcessor processor = new RecordProcessor();
        int[] array = {1, 2, 3, 4, 5};
        System.out.println("Number of disjoint pairs: " + processor.calculateDisjointPairs(array));
    }
}
```

