#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Custom pseudo-random number generator function
unsigned long customPRNG(unsigned long seed) {
    seed = seed * 1664525 + 1013904223;
    return seed & 0xFFFFFFFF; // Ensure 32-bit output
}

record* initializeData(long offsetCount, int keyCount) {
    unsigned long seed = time(NULL); // Seed the PRNG with current time
    record *records = (record *)malloc(sizeof(record) * keyCount);
    if (records == NULL) {
        return NULL; // Handle memory allocation failure gracefully
    }

    for (int i = 0; i < keyCount; ++i) {
        records[i].value = customPRNG(seed ^ i); // Use PRNG to set record value
    }

    long *offsets = (long *)malloc(sizeof(long) * offsetCount);
    if (offsets == NULL) {
        free(records); // Free previously allocated memory before returning NULL
        return NULL; // Handle memory allocation failure gracefully
    }

    int *keys = (int *)malloc(sizeof(int) * keyCount);
    if (keys == NULL) {
        free(offsets);
        free(records);
        return NULL; // Handle memory allocation failure gracefully
    }

    for (long i = 0; i < offsetCount; ++i) {
        offsets[i] = i * 10; // Initialize offsets array
    }

    for (int i = 0; i < keyCount; ++i) {
        keys[i] = i + 1; // Initialize keys array
    }

    // Bounds checking example
    if ((size_t)i >= keyCount || (size_t)i >= offsetCount) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Prevent buffer overflow
    }

    // Return pointer to the array of records
    return records;
}
```

### Notes:
1. **PRNG Function**: The `customPRNG` function is a simple linear congruential generator (LCG) which is known for its simplicity and good statistical properties.
2. **Memory Allocation**: Memory allocation failures are handled gracefully by checking if the pointers returned by `malloc` are `NULL`. If an error occurs, previously allocated memory is freed before returning `NULL`.
3. **Bounds Checking**: Example bounds checking is provided to prevent buffer overflows when accessing arrays.
4. **Random Number Generation**: The PRNG seed is initialized with the current time using `time(NULL)`, ensuring that each run of the program generates a different sequence of pseudo-random numbers.
5. **Return Value**: The function returns a pointer to the array of records if all allocations are successful, otherwise it returns `NULL`.

This code snippet is designed to be maintainable and scalable, allowing for future modifications or enhancements without introducing significant downtime.']

