    int *seeds;
    size_t seed_count;
} PRNGState;

PRNGState prng_state;

void init_prng() {
    prng_state.seed_count = 10;
    prng_state.seeds = (int *)malloc(prng_state.seed_count * sizeof(int));
    srand(time(NULL));
    for (size_t i = 0; i < prng_state.seed_count; ++i) {
        prng_state.seeds[i] = rand();
    }
}

void destroy_prng() {
    free(prng_state.seeds);
    pthread_mutex_destroy(&prng_state.lock);
}

int get_random_seed(int range) {
    pthread_mutex_lock(&prng_state.lock);
    int seed_index = rand() % prng_state.seed_count;
    int random_value = prng_state.seeds[seed_index] % (range + 1);
    pthread_mutex_unlock(&prng_state.lock);
    return random_value;
}

double find_smallest(double *values, size_t count) {
    double smallest = values[0];
    for (size_t i = 1; i < count; ++i) {
        if (values[i] < smallest) {
            smallest = values[i];
        }
    }
    return smallest;
}

void handle_input() {
    double values[MAX_RECORDS];
    size_t count = 0;

    while (scanf("%lf", &values[count]) == 1 && count < MAX_RECORDS) {
        ++count;
    }

    if (count > 0) {
        double smallest = find_smallest(values, count);
        printf("Smallest value: %f\n", smallest);
    } else {
        printf("No values provided.\n");
    }
}

void *analytics_thread(void *arg) {
    handle_input();
    return NULL;
}

int main() {
    pthread_t threads[10];
    init_prng();

    for (size_t i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, analytics_thread, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_prng();
    return EXIT_SUCCESS;
}
