};

enum Status generate_records(long **offsets, int **keys, Record **records, int num_records, long min_offset, long max_offset) {
    *offsets = (long *)malloc(num_records * sizeof(long));
    *keys = (int *)malloc(num_records * sizeof(int));
    *records = (Record *)malloc(num_records * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return STATUS_MEM_ERROR;
    }

    srand((unsigned int)((long)time(NULL) ^ (long)getpid() ^ arc4random()));

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = min_offset + rand() % (max_offset - min_offset + 1);
        (*keys)[i] = rand();

        if (i > 0 && (*keys)[i] == (*keys)[i-1]) {
            free(*offsets);
            free(*keys);
            free(*records);
            return STATUS_INVALID_RECORDS;
