### Java Method

```java
import java.util.*;

public class UnionFind {
    private int[] parent;

    public UnionFind(int size) {
        this.parent = new int[size];
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    public boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return false; // Already in the same set
        }

        parent[rootX] = rootY;
        return true;
    }
}

public class RecordProcessor {
    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);
        Set<Integer> seenKeys = new HashSet<>();

        for (int i = 0; i < array.length - 1; ++i) {
            if (!seenKeys.add(array[i])) {
                continue; // Duplicate key, skip
            }

            for (int j = i + 1; j < array.length; ++j) {
                if (!seenKeys.contains(array[j])) {
                    uf.union(i, j);
                }
            }
        }

        int disjointPairs = 0;
        for (int i = 0; i < array.length; ++i) {
            if (uf.find(i) == i) {
                disjointPairs++;
            }
        }

        return disjointPairs;
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5}; // Example input
        int disjointPairs = countDisjointPairs(array);
        System.out.println("Number of disjoint pairs: " + disjointPairs);
    }
}
```

