    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void resize_collection(RecordCollection* collection, size_t new_capacity) {
    if (new_capacity <= collection->capacity) return;

    Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) return;

    collection->records = new_records;
    collection->capacity = new_capacity;
}

void add_record(RecordCollection* collection, long offset) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) resize_collection(collection, collection->capacity * 2);
    collection->records[collection->size].key = random() % 100; // Simplified for example
    collection->records[collection->size].offset = offset;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
}

