typedef struct {
    char *session_id;
    time_t expiration_time;
} SessionInfo;

typedef struct {
    SessionInfo **sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* session_manager_init(size_t initial_capacity) {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->sessions = malloc(initial_capacity * sizeof(SessionInfo *));
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->sessions || pthread_mutex_init(&manager->lock, NULL)) {
        free(manager);
        return NULL;
    }

    return manager;
}

void session_manager_free(SessionManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->sessions[i]->session_id);
        free(manager->sessions[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager->sessions);
    free(manager);
}

int session_manager_add(SessionManager *manager, const char *session_id, time_t expiration_time) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        SessionInfo **new_sessions = realloc(manager->sessions, manager->capacity * 2 * sizeof(SessionInfo *));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->sessions = new_sessions;
        manager->capacity *= 2;
    }

    manager->sessions[manager->size] = malloc(sizeof(SessionInfo));
    if (!manager->sessions[manager->size]) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->sessions[manager->size]->session_id = strdup(session_id);
    if (!manager->sessions[manager->size]->session_id) {
        free(manager->sessions[manager->size]);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->sessions[manager->size]->expiration_time = expiration_time;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int session_manager_remove(SessionManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i]->session_id, session_id) == 0) {
            free(manager->sessions[i]->session_id);
            free(manager->sessions[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Additional functions for managing session IDs and expiration times can be added here
