    if (!offsets) return NULL;

    // Allocate memory for int keys array
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize arrays with random values and offsets
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand(); // Random offset
        keys[i] = rand() % 1000; // Random key between 0 and 999
    }

    // Return a pointer to the first element of the keys array
    return (void*)keys;
}

// Function to free allocated memory
void freeArrays(void* ptr) {
    if (ptr) {
        // Assuming keys array is passed, free it and offsets array
        int* keys = (int*)ptr;
        long* offsets = (long*)((char*)keys - sizeof(long*) * keys);
        free(offsets);
        free(keys);
    }
}

