RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;
    collection->keys = malloc(initial_capacity * sizeof(int));
    collection->offsets = malloc(initial_capacity * sizeof(long));
    if (collection->keys == NULL || collection->offsets == NULL) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void resize_record_collection(RecordCollection **collection, size_t new_capacity) {
    RecordCollection *new_col = realloc(*collection, sizeof(RecordCollection));
    if (new_col == NULL) return; // Handle error
    new_col->keys = realloc(new_col->keys, new_capacity * sizeof(int));
    new_col->offsets = realloc(new_col->offsets, new_capacity * sizeof(long));
    if (new_col->keys == NULL || new_col->offsets == NULL) {
        free(new_col);
        return; // Handle error
    }
    new_col->capacity = new_capacity;
    *collection = new_col;
}

void destroy_record_collection(RecordCollection *collection) {
    free(collection->keys);
    free(collection->offsets);
    free(collection);
}

int add_record(RecordCollection *collection, int key, long offset) {
    if (collection->size == collection->capacity) {
        resize_record_collection(&collection, collection->capacity * 2);
    }
    collection->keys[collection->size] = key;
    collection->offsets[collection->size] = offset;
    collection->size++;
    return 0; // Return success
}

int get_record(RecordCollection *collection, int key, long *offset) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->keys[i] == key) {
            *offset = collection->offsets[i];
            return 1; // Return success
        }
    }
    return 0; // Record not found
}
