// Define the event structure
typedef struct {
    long timestamp;
    int identifier;
    long value;
} Event;

// Define the record structure
typedef struct {
    int data;
} Record;

// Function to generate a pseudo-random number using XORShift algorithm
long xorshift32(long *state) {
    long x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return (*state = x);
}

void initializeArrays(int numRecords, int minValue, int maxValue, Event **events, int **keys, int **identifiers, Record **records) {
    // Seed the PRNG with current time
    srand(time(NULL));

    // Allocate memory for arrays
    *events = (Event *)malloc(numRecords * sizeof(Event));
    *keys = (int *)malloc(numRecords * sizeof(int));
    *identifiers = (int *)malloc(numRecords * sizeof(int));
    *records = (Record *)malloc(numRecords * sizeof(Record));

    // Initialize the PRNG state
    long prngState = time(NULL);

    // Populate arrays with random values
    for (int i = 0; i < numRecords; i++) {
        (*keys)[i] = xorshift32(&prngState) % numRecords;
        (*identifiers)[i] = xorshift32(&prngState) % 1000 + 1; // Identifier within a range of 1 to 1000
        (*records)[i].data = xorshift32(&prngState) % (maxValue - minValue + 1) + minValue;

        // Generate pseudo-random 'long' value for each event
        long longValue;
        do {
            longValue = xorshift32(&prngState);
        } while ((*events)[i].value == longValue); // Ensure uniqueness
        (*events)[i].value = longValue;

        // Set timestamp (current time in seconds)
        (*events)[i].timestamp = time(NULL);
    }
}

int main() {
    int numRecords = 1000;
    Event *events;
    int *keys, *identifiers;
    Record *records;

    initializeArrays(numRecords, 100, 500, &events, &keys, &identifiers, &records);

    // Free allocated memory
    free(events);
    free(keys);
    free(identifiers);
    free(records);

    return 0;
}
