#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t count;
    pthread_mutex_t lock;
} ArrayManager;

uint32_t xorshift32(uint32_t *state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return (*state = x);
}

void init_prng_state(uint32_t *state, uint64_t seed) {
    *state = (uint32_t)(seed ^ (seed >> 32));
}

int generate_random_number(uint32_t *state, int min, int max) {
    const uint32_t range = (uint32_t)(max - min + 1);
    if (range == 0 || range > UINT32_MAX) return -1; // Invalid range
    uint32_t rand_val = xorshift32(state) % range;
    return (int)(rand_val + min);
}

void validate_entropy(ArrayManager *manager, int min, int max, size_t threshold) {
    int count[min - max + 1];
    for (size_t i = 0; i < manager->count; ++i) {
        count[manager->records[i]->value - min]++;
    }
    for (int i = 0; i <= range; ++i) {
        if (count[i] < threshold) {
            // Retry generation or handle insufficient entropy
            return;
        }
    }
}

void initialize_arrays(ArrayManager *manager, size_t count, int min, int max, uint64_t seed) {
    manager->count = count;
    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = (long *)malloc(count * sizeof(long));
    manager->keys = (int *)malloc(count * sizeof(int));
    manager->records = (Record **)malloc(count * sizeof(Record *));

    uint32_t prng_state;
    init_prng_state(&prng_state, seed);

    for (size_t i = 0; i < count; ++i) {
        while (1) {
            manager->keys[i] = generate_random_number(&prng_state, min, max);
            validate_entropy(manager, min, max, count / range);
            if (manager->keys[i] != -1) break;
        }
        manager->records[i] = (Record *)malloc(sizeof(Record));
        manager->records[i]->value = manager->keys[i];

        // Lock before modifying shared data
        pthread_mutex_lock(&manager->lock);
        manager->offsets[i] = i * sizeof(long); // Simplified for example
        pthread_mutex_unlock(&manager->lock);
    }
}

void free_arrays(ArrayManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}
