// Function to generate a random string
void generate_random_string(char** str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    *str = malloc(length + 1);
    if (*str == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (size_t i = 0; i < length; ++i) {
        (*str)[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    (*str)[length] = '\0';
}

// Thread-safe function to dynamically allocate memory for transactions
transaction* allocate_transactions(size_t num_transactions, size_t user_id_length) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG once per program execution

    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].amount = ((double)(rand()) / RAND_MAX) * 1000.0; // Random amount between 0 and 1000
        transactions[i].timestamp = time(NULL);
        generate_random_string(&transactions[i].user_id, user_id_length);
    }

    pthread_mutex_unlock(&mutex);
    return transactions;
}

// Example usage
int main() {
    size_t num_transactions = 10;
    size_t user_id_length = 8;

    transaction* transactions = allocate_transactions(num_transactions, user_id_length);
    if (transactions != NULL) {
        for (size_t i = 0; i < num_transactions; ++i) {
            printf("Transaction %zu: Amount=%f, Timestamp=%lu, User ID=%s\n", i, transactions[i].amount,
                   transactions[i].timestamp, transactions[i].user_id);
            free(transactions[i].user_id); // Free each user ID string
        }
        free(transactions); // Free the transaction array
    }

    return 0;
}
