#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void initialize_arrays(long **offsets, int **keys, record **records, int num_records) {
    *offsets = (long *)malloc(num_records * sizeof(long));
    *keys = (int *)malloc(num_records * sizeof(int));
    *records = (record *)malloc(num_records * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed PRNG
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = rand() % 1000L;
        (*keys)[i] = rand();
        (*records)[i].value = rand();
    }
}

void log_message(const char *message) {
    printf("%s\n", message);
}

int find_largest(int *array, int size) {
    if (size == 0) return -1; // Handle empty array
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

double calculate_average(int *array, int size) {
    if (size == 0) return 0.0; // Handle empty array
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return (double)sum / size;
}

void check_duplicates(int *array, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (array[i] == array[j]) {
                printf("Duplicate found: %d\n", array[i]);
                return;
            }
        }
    }
    printf("No duplicates.\n");
}

void read_and_process_input() {
    int input[MAX_RECORDS];
    int count = 0;

    while (scanf("%d", &input[count++]) == 1 && count < MAX_RECORDS);

    if (count == 0) {
        log_message("No valid input received.");
        return;
    }

    log_message("Input processed successfully.");

    int largest = find_largest(input, count);
    printf("Largest number: %d\n", largest);

    double average = calculate_average(input, count);
    printf("Average: %.2f\n", average);

    check_duplicates(input, count);
}

int main() {
    long *offsets;
    int *keys;
    record *records;

    initialize_arrays(&offsets, &keys, &records, MAX_RECORDS);
    log_message("Arrays initialized successfully.");

    read_and_process_input();

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
