long generate_random_long(long min, long max) {
    // Non-cryptographic pseudo-random number generation
    return min + (rand() % (max - min + 1));
}

void initialize_arrays() {
    long *offsets = malloc(ARRAY_SIZE * sizeof(long));
    int *keys = malloc(ARRAY_SIZE * sizeof(int));
    data_entry *entries = malloc(ARRAY_SIZE * sizeof(data_entry));
    double *timestamps = malloc(ARRAY_SIZE * sizeof(double));
    record *records = malloc(ARRAY_SIZE * sizeof(record));

    if (!offsets || !keys || !entries || !timestamps || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed PRNG for consistency across runs

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        offsets[i] = generate_random_long(0, 1000000L);
        keys[i] = rand() % 100;
        entries[i].value = generate_random_long(-1000000L, 1000000L);
        entries[i].status_flag = (rand() % 2) == 0 ? 1 : -1; // Randomly set to 1 or -1
        timestamps[i] = (double)time(NULL); // Current timestamp
        records[i].value = rand() % 1000;
    }

    // Log initialization process
    printf("Initialization complete with no errors\n");

    // Free allocated memory
    free(offsets);
    free(keys);
    free(entries);
    free(timestamps);
    free(records);
}

int main() {
    initialize_arrays();
    return 0;
}
