        return NULL;
    }

    if ((numRecords * sizeof(Record) + numRecords * sizeof(double)) > memoryThreshold) {
        free(records);
        free(probabilities);
        *error = ERROR_CODE;
        return NULL;
    }

    // Generate unique probabilities using a more robust PRNG
    for (int i = 0; i < numRecords; ++i) {
        probabilities[i] = ((double)i + 1.0) / (numRecords + 1.0);
    }

    // Assign the probabilities to records
    for (int i = 0; i < numRecords; ++i) {
        records[i].key = i;
        records[i].offset = i * 1024;
        records[i].probability = probabilities[i];
    }

    free(probabilities);
    *error = 0;
    return records;
}

void freeRecords(Record* records, int count) {
    free(records);
}
