    for (int i = 0; i < RANDOM_NUMBER_ARRAY_SIZE; i++) {
        random_number_array[i] = ((double)rand() / RAND_MAX);
    }
}

void reseed_prng_with_timestamp(long timestamp_array[], int seed_array[]) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    for (int i = 0; i < SEED_ARRAY_SIZE; i++) {
        seed_array[i] = rand();
        srand(seed_array[i]);
    }

    for (int i = 0; i < TIMESTAMP_ARRAY_SIZE; i++) {
        timestamp_array[i] = tv.tv_sec;
        gettimeofday(&tv, NULL);
    }
}

