    srand(time(NULL)); // Seed the PRNG for consistent randomness across runs

    long* offsets = (long*)malloc(MAX_SESSIONS * sizeof(long));
    if (!offsets) return NULL; // Handle memory allocation failure

    int* session_keys = (int*)malloc(MAX_SESSIONS * sizeof(int));
    if (!session_keys) {
        free(offsets); // Clean up previous allocation
        return NULL;
    }

    session* sessions = (session*)malloc(MAX_SESSIONS * sizeof(session));
    if (!sessions) {
        free(session_keys);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        offsets[i] = rand() % RECORD_OFFSET_RANGE;
        session_keys[i] = rand() % SESSION_KEY_RANGE;
        sessions[i].session_key = session_keys[i];
        sessions[i].offset = offsets[i];
        sessions[i].expiration = time(NULL) + 3600; // Set expiration to 1 hour from now
    }

    return sessions;
}

void free_session_management(session* sessions, int* session_keys, long* offsets) {
    if (sessions) free(sessions);
    if (session_keys) free(session_keys);
    if (offsets) free(offsets);
}
