#define MAX_RECORDS 1000000

typedef struct {
    int value;
} record;

int initialize_records(long* offsets, int* keys, record** records, int range) {
    srand(time(NULL));

    *records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        return -1;
    }

    offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        free(*records);
        return -2;
    }

    keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*records);
        free(offsets);
        return -3;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*records)[i].value = rand() % range;
        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }

    return MAX_RECORDS;
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    int initialized_records;

    clock_t start_time, end_time;
    double cpu_time_used;

    // Measure memory usage before
    printf("Memory used before: %zu bytes\n", sizeof(offsets) + sizeof(keys));

    start_time = clock();
    initialized_records = initialize_records(&offsets, &keys, &records, 100);
    end_time = clock();

    cpu_time_used = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    if (initialized_records >= 0) {
        printf("Successfully initialized %d records in %.2f seconds\n", initialized_records, cpu_time_used);

        // Free allocated memory
        free(records);
        free(offsets);
        free(keys);
    } else {
        printf("Failed to initialize records\n");
    }

    return 0;
}
