#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    long* pointer;
} Record;

void seed_prng() {
    static pthread_mutex_t seed_lock = PTHREAD_MUTEX_INITIALIZER;
    static time_t last_seed = 0;

    time_t current_time = time(NULL);
    if (current_time != last_seed) {
        pthread_mutex_lock(&seed_lock);
        if (current_time != last_seed) {
            srand(current_time);
            last_seed = current_time;
        }
        pthread_mutex_unlock(&seed_lock);
    }
}

Record* create_records(long offset_size, int key_size, int value_range_min, int value_range_max, size_t num_records) {
    if (offset_size < 0 || key_size < 0 || value_range_min > value_range_max || !num_records)
        return NULL;

    seed_prng();

    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    Record* records = malloc(num_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        records[i].pointer = malloc(sizeof(long));
        if (!records[i].pointer) {
            // Cleanup on failure
            for (size_t j = 0; j < i; ++j)
                free(records[j].pointer);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    return records;
}

void free_records(Record* records, size_t num_records) {
    if (!records)
        return;

    for (size_t i = 0; i < num_records; ++i)
        free(records[i].pointer);

    free(records);
}
```

This code snippet provides a function `create_records` that dynamically allocates memory for three arrays and initializes them according to the specified requirements. It includes error handling for invalid input parameters, seed management for the PRNG, and thread-safe seeding using a mutex. The records are allocated in a way that each record contains an integer value within a given range and a pointer to a long. Memory is freed properly upon function exit to prevent leaks.']

