#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

void init_record_collection(RecordCollection *collection) {
    memset(collection, 0, sizeof(*collection));
    pthread_mutex_init(&collection->lock, NULL);
}

int add_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Key already exists
        }
    }
    if (collection->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Collection is full
    }
    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    ++collection->count;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int generate_unique_key(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    int key;
    do {
        if (!RAND_bytes((unsigned char*)&key, sizeof(key))) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to generate a key
        }
    } while (add_record(collection, key, 0) == -1);
    pthread_mutex_unlock(&collection->lock);
    return key;
}

void log_message(const char *message, int level) {
    if (level <= LOG_LEVEL) {
        printf("%s\n", message);
    }
}

int load_records_from_source(RecordCollection *collection, const char *source_path, int max_threads) {
    // Simulate loading records from a source
    for (int i = 0; i < max_threads; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, (void*)load_records_thread, collection) != 0) {
            log_message("Failed to create thread", LOG_ERROR);
            return -1;
        }
    }
    for (int i = 0; i < max_threads; ++i) {
        pthread_join(thread, NULL);
    }
    return 0;
}

void* load_records_thread(void *arg) {
    RecordCollection *collection = (RecordCollection*)arg;
    // Simulate loading records and adding them to the collection
    for (int i = 0; i < 100; ++i) {
        int key = generate_unique_key(collection);
        if (key == -1) {
            log_message("Failed to generate unique key", LOG_ERROR);
            return NULL;
        }
        long offset = rand(); // Simulate offset
        add_record(collection, key, offset);
    }
    return NULL;
}

int main() {
    RecordCollection collection;
    init_record_collection(&collection);

    if (load_records_from_source(&collection, "source.txt", 4) != 0) {
        log_message("Failed to load records from source", LOG_ERROR);
        return -1;
    }

    log_message("Records loaded successfully", LOG_INFO);
    return 0;
}
