} record;

record* create_records(size_t size, int key_min, int key_max, time_t ts_min, time_t ts_max) {
    if (size == 0 || key_min >= key_max || ts_min >= ts_max) {
        return NULL; // Handle invalid input parameters
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the CSPRNG

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = rand() % 1000L; // Generate a random offset within a specified range
        records[i].key = rand() % (key_max - key_min + 1) + key_min; // Generate a random key within the given range
        time(&records[i].last_updated); // Set timestamp to current time

        size_t id_length = rand() % 20 + 5; // Random length for unique ID between 5 and 24 characters
        records[i].unique_id = malloc((id_length + 1) * sizeof(char));
        if (!records[i].unique_id) {
            free(records); // Free previously allocated memory on error
            return NULL;
        }

        // Generate a unique identifier (this is a placeholder, replace with actual implementation)
        for (size_t j = 0; j < id_length; ++j) {
            records[i].unique_id[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        records[i].unique_id[id_length] = '\0';
    }

    return records;
}

void free_records(record* records, size_t size) {
    if (!records) {
        return; // Nothing to free
    }

    for (size_t i = 0; i < size; ++i) {
        free(records[i].unique_id); // Free dynamically allocated string
    }
    free(records); // Free the array of records
}
