typedef struct {
    long* offsets;
    int* keys;
    int** records;
    long*** record_pointers;
    time_t* timestamps;
    char* output_buffer;
} DataPipeline;

DataPipeline* create_data_pipeline(size_t num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL;
    }

    DataPipeline* pipeline = malloc(sizeof(DataPipeline));
    if (!pipeline) {
        return NULL;
    }

    pipeline->offsets = malloc(num_records * sizeof(long));
    pipeline->keys = malloc(num_records * sizeof(int));
    pipeline->records = malloc(num_records * sizeof(int*));
    pipeline->record_pointers = malloc(num_records * sizeof(long**));
    pipeline->timestamps = malloc(num_records * sizeof(time_t));
    pipeline->output_buffer = malloc(1024 * 1024); // Assuming buffer size of 1MB

    if (!pipeline->offsets || !pipeline->keys || !pipeline->records || 
        !pipeline->record_pointers || !pipeline->timestamps || !pipeline->output_buffer) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline->record_pointers);
        free(pipeline->timestamps);
        free(pipeline->output_buffer);
        free(pipeline);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        pipeline->offsets[i] = rand();
        pipeline->keys[i] = rand() % (max_value - min_value + 1) + min_value;
        pipeline->records[i] = malloc(sizeof(int));
        *pipeline->records[i] = rand() % (max_value - min_value + 1) + min_value;
        pipeline->record_pointers[i] = &pipeline->records[i];
        pipeline->timestamps[i] = time(NULL);
    }

    return pipeline;
}

void destroy_data_pipeline(DataPipeline* pipeline, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(pipeline->records[i]);
    }
    free(pipeline->offsets);
    free(pipeline->keys);
    free(pipeline->records);
    free(pipeline->record_pointers);
    free(pipeline->timestamps);
    free(pipeline->output_buffer);
    free(pipeline);
}
