    cprng->min = min;
    cprng->max = max;
    return cprng;
}

void destroyCSPRNG(CSPRNG* cprng) {
    free(cprng);
}

unsigned long generateRandomIntInclusive(CSPRNG* cprng) {
    return (random() % (cprng->max - cprng->min + 1)) + cprng->min;
}

unsigned long generateRandomIntExclusive(CSPRNG* cprng) {
    return random() % (cprng->max - cprng->min) + cprng->min;
}

void populateRecords(Record** records, unsigned long count, CSPRNG* cprng) {
    for (unsigned long i = 0; i < count; ++i) {
        records[i]->value = generateRandomIntInclusive(cprng);
    }
}

