int generateKey(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

record* initializeRecords(long* offsets, int* keys, int numRecords, int minValue, int maxValue) {
    record* records = malloc(numRecords * RECORD_SIZE);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = generateOffset(0, numRecords - 1);
        keys[i] = generateKey(minValue, maxValue);
        records[i].value = generateKey(minValue, maxValue);
    }

    return records;
}

void verifyIntegrity(long* offsets, int* keys, record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (offsets[i] >= numRecords || keys[i] < 0) {
            fprintf(stderr, "Integrity check failed at index %d\n", i);
            return;
        }
    }
}

void logOperation(const char* operation) {
    printf("%s\n", operation);
}

record* decryptMessage(record* records, int recordSize, const char* encryptedMessage, size_t encryptedLength, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Decryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    record* decryptedRecord = malloc(recordSize);
    if (!decryptedRecord) {
        fprintf(stderr, "Memory allocation failed for decrypted record\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int len1, len2;
    if (1 != EVP_DecryptUpdate(ctx, (unsigned char*)decryptedRecord, &len1, (const unsigned char*)encryptedMessage, encryptedLength)) {
        fprintf(stderr, "Decryption update failed\n");
        free(decryptedRecord);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_DecryptFinal_ex(ctx, (unsigned char*)decryptedRecord + len1, &len2)) {
        fprintf(stderr, "Decryption finalization failed\n");
        free(decryptedRecord);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int totalLen = len1 + len2;
    if (totalLen != recordSize) {
        fprintf(stderr, "Decrypted message size mismatch\n");
        free(decryptedRecord);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);
    logOperation("Message decrypted successfully");
    return decryptedRecord;
}

