#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct Record {
    int key;
    time_t timestamp;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct Database {
    Node* head;
    pthread_mutex_t lock;
} Database;

Database* db_init() {
    Database* db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;
    db->head = NULL;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void db_insert(Database* db, Record record) {
    pthread_mutex_lock(&db->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&db->lock);
        return;
    }
    new_node->data = record;
    new_node->next = db->head;
    db->head = new_node;
    pthread_mutex_unlock(&db->lock);
}

int db_delete(Database* db, int key) {
    pthread_mutex_lock(&db->lock);
    Node* current = db->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.key == key) {
            if (prev == NULL) db->head = current->next;
            else prev->next = current->next;
            free(current);
            pthread_mutex_unlock(&db->lock);
            return 1;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&db->lock);
    return 0;
}

Record* db_retrieve(Database* db, int key) {
    pthread_mutex_lock(&db->lock);
    Node* current = db->head;
    while (current != NULL) {
        if (current->data.key == key) {
            Record* record = (Record*)malloc(sizeof(Record));
            if (!record) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&db->lock);
                return NULL;
            }
            *record = current->data;
            pthread_mutex_unlock(&db->lock);
            return record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&db->lock);
    return NULL;
}

void db_free(Database* db) {
    Node* current = db->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int main() {
    Database* db = db_init();
    if (!db) return 1;

    Record record;
    record.key = rand(); // This should be replaced with a proper PRNG seeding and key generation
    record.timestamp = time(NULL);
    record.offset = 0;

    db_insert(db, record);

    Record* retrieved_record = db_retrieve(db, record.key);
    if (retrieved_record) {
        printf("Retrieved record: Key=%d, Timestamp=%ld, Offset=%ld\n", 
               retrieved_record->key, retrieved_record->timestamp, retrieved_record->offset);
        free(retrieved_record);
    }

    db_delete(db, record.key);

    db_free(db);
    return 0;
}
```

