#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

// Define record structure
typedef union {
    int value;
    struct timespec timestamp;
} record_union;

typedef struct {
    long offset;
    int key;
    record_union data;
} record;

// Function to initialize arrays and records
int init_arrays(long *offsets, int *keys, record **records, int count, int range_start, int range_end) {
    // Seed PRNG with hardware entropy if available
    if (rand_r((unsigned int *)time(NULL)) == 0) {
        FILE *urandom = fopen("/dev/urandom", "rb");
        if (urandom != NULL) {
            unsigned int seed;
            fread(&seed, sizeof(seed), 1, urandom);
            fclose(urandom);
            srand(seed);
        }
    }

    // Allocate memory
    for (int i = 0; i < count; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            return -1;
        }
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
        // Initialize data with a random value within the specified range
        records[i]->data.value = rand() % (range_end - range_start + 1) + range_start;
    }

    return 0;
}

// Helper function to find and print the largest integer in an array
void find_and_print_largest(int *array, int size) {
    if (size > 0) {
        int max = array[0];
        for (int i = 1; i < size; i++) {
            if (array[i] > max) {
                max = array[i];
            }
        }
        printf("Largest integer: %d\n", max);
    } else {
        printf("Array is empty.\n");
    }
}

// Simulate network latency
void simulate_latency(int dataset_size, int latency_factor) {
    if (latency_factor > 0) {
        sleep(dataset_size / latency_factor); // Introduce delay based on data size and factor
    }
}

int main() {
    int count = 100; // Number of elements in arrays/records
    long *offsets = malloc(count * sizeof(long));
    int *keys = malloc(count * sizeof(int));
    record **records = (record **)malloc(count * sizeof(record *));

    if (init_arrays(offsets, keys, records, count, 100, 1000) != 0) {
        // Handle error
        free(offsets);
        free(keys);
        for (int i = 0; i < count; i++) {
            free(records[i]);
        }
        free(records);
        return -1;
    }

    int input_array[count];
    printf("Enter %d integers: ", count);
    for (int i = 0; i < count; i++) {
        scanf("%d", &input_array[i]);
    }

    find_and_print_largest(input_array, count);

    // Simulate network latency
    simulate_latency(count, 10); // Adjust latency factor as needed

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}
