event* createEventArrayThreadSafe(int size, int minID, int maxID) {
    pthread_mutex_lock(&mutex);
    event *events = malloc(size * sizeof(event));
    if (events == NULL) {
        // Log error: Memory allocation failed
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        events[i].id = rand() % (maxID - minID + 1) + minID;
        events[i].latency = ((double)rand()) / RAND_MAX; // Random double between 0 and 1
        int descLength = rand() % 20 + 1; // Random length for description
        events[i].description = (char *)malloc(descLength * sizeof(char));
        if (events[i].description == NULL) {
            // Log warning: Memory allocation failed for event description
            free(events);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        for (int j = 0; j < descLength - 1; j++) {
            events[i].description[j] = 'a' + rand() % 26; // Random lowercase letter
        }
        events[i].description[descLength - 1] = '\0';
    }

    pthread_mutex_unlock(&mutex);
    return events;
}

