#include <stdlib.h>
#include <time.h>
#include "log.h" // Assume this header provides logging functions

typedef struct kv_pair {
    int key;
    double value;
    struct kv_pair *next;
} kv_pair;

typedef struct record {
    long offset;
    int key;
    double probability;
    kv_pair *kv_list;
} record;

record* initialize_records(int num_records, long range_start, long range_end) {
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        log_error("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed the pseudo-random number generator
    double total_probability = 0.0;

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % (range_end - range_start + 1) + range_start;
        records[i].key = rand() % num_records;
        records[i].probability = ((double)(rand()) / RAND_MAX);
        total_probability += records[i].probability;
    }

    // Normalize probabilities to sum up to 1
    for (int i = 0; i < num_records - 1; i++) {
        records[i].probability /= total_probability;
    }
    records[num_records - 1].probability = 1.0 - (total_probability - records[num_records - 2].probability);

    // Initialize linked lists
    for (int i = 0; i < num_records; i++) {
        records[i].kv_list = NULL;
        for (int j = 0; j < 5; j++) { // Example: Each record has 5 key-value pairs
            kv_pair *pair = malloc(sizeof(kv_pair));
            if (pair == NULL) {
                log_error("Failed to allocate memory for a kv_pair");
                // Clean up previously allocated records and their linked lists
                for (int k = 0; k < i; k++) {
                    free_list(records[k].kv_list);
                }
                free(records);
                return NULL;
            }
            pair->key = rand() % num_records;
            pair->value = ((double)(rand()) / RAND_MAX);
            pair->next = records[i].kv_list;
            records[i].kv_list = pair;
        }
    }

    log_info("Records initialized successfully");
    return records;
}

void free_list(kv_pair *list) {
    kv_pair *current = list;
    while (current != NULL) {
        kv_pair *temp = current;
        current = current->next;
        free(temp);
    }
}
