    for (int i = 0; i < 4; i++) {
        (*keys)[i] = rand();
        (*values)[i] = ((double)rand() / RAND_MAX) * 100.0;
        asprintf(&(*userIDs)[i], "user%d", i);
        (*records)[i].value = (*values)[i];
        (*records)[i].userID = (*userIDs)[i];
    }
}

// Function to find and print the maximum value and corresponding user ID
void find_max_value(double* values, char** userIDs) {
    double max_value = -1.0;
    int index = -1;

    for (int i = 0; i < 4; i++) {
        if (values[i] > max_value) {
            max_value = values[i];
            index = i;
        }
    }

    printf("Maximum value: %f, Corresponding user ID: %s\n", max_value, userIDs[index]);
}

