    int* keys;
    double* values;
    char** userIDs;
    Record* records;

    // Initialize arrays and records
    init_arrays_and_records(&keys, &values, &userIDs, &records);

    // Find and print the maximum value and corresponding user ID
    find_max_value(values, userIDs);

