record* init_records(int num_records, long* offsets, int* keys) {
    // Allocate memory for records
    record* recs = malloc(num_records * sizeof(record));
    if (recs == NULL) {
        // Log error: Memory allocation failed
        return NULL;
    }

    // Initialize non-cryptographic PRNG
    srand(time(NULL));

    // Populate records with random values
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 1000; // Example range: 0 to 999
        recs[i].key = keys[i];
        recs[i].weight = (float)rand() / RAND_MAX; // Normalize between 0 and 1
    }

    return recs;
}

// Function to find and print the largest integer in an array
int find_largest(int* arr, int size) {
    if (size <= 0) {
        // Log warning: Empty array or invalid size
        return -1; // Assuming -1 as an error code for this example
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

int main() {
    int num_records = 1000000; // Example number of records
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));

    record* recs = init_records(num_records, offsets, keys);
    if (recs == NULL) {
        printf("Failed to initialize records.\n");
        return 1;
    }

    // Example array of integers
    int arr[] = {3, 5, 1, 2, 4};
    int size = sizeof(arr) / sizeof(arr[0]);
    int largest = find_largest(arr, size);
    printf("Largest integer: %d\n", largest);

    free(recs);
    free(offsets);
    free(keys);

    return 0;
}
