void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

record* initialize_records(int range, int count) {
    record* records = (record*)safe_malloc(count * sizeof(record));
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % range + 1;
    }
    return records;
}

void check_disjoint_pairs(int* array, int size) {
    clock_t start, end;
    double cpu_time_used;

    start = clock();
    // Perform disjoint set operations here
    end = clock();
    cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Disjoint pairs check took %.3f seconds\n", cpu_time_used);
}

int main() {
    long* offsets = (long*)safe_malloc(4 * sizeof(long));
    int* keys = (int*)safe_malloc(MAX_RECORDS * sizeof(int));
    record* records = initialize_records(100, MAX_RECORDS);
    int* input_array = (int*)safe_malloc(MAX_RECORDS * sizeof(int));

    // Initialize offsets and keys here
    check_disjoint_pairs(input_array, MAX_RECORDS);

    free(offsets);
    free(keys);
    free(records);
    free(input_array);

