#include <time.h>

#define MAX_SENSORS 100

typedef struct {
    time_t timestamp;
    int index;
    float measurement;
} sensorData;

typedef struct {
    long offset;
} offset;

typedef struct {
    int key;
    record *data; // Assuming 'record' is a user-defined type
} keyRecord;

typedef struct Node {
    int value;
    struct Node *next;
} ListNode;

// Function to initialize sensor data with pseudo-random values
void initSensorData(sensorData *sensor, int index) {
    sensor->timestamp = time(NULL);
    sensor->index = index;
    sensor->measurement = (float)rand() / RAND_MAX; // Simplified PRNG for demonstration
}

// Function to find the largest integer in a list and calculate its average
void processList(ListNode **head) {
    ListNode *current = *head;
    int max_value = INT_MIN;
    int sum = 0;
    int count = 0;

    while (current != NULL) {
        if (current->value > max_value) {
            max_value = current->value;
        }
        sum += current->value;
        count++;
        current = current->next;
    }

    if (count > 0) {
        float average = (float)sum / count;
        printf("Largest Value: %d, Average: %.2f\n", max_value, average);
    } else {
        printf("No values in the list.\n");
    }
}

// Function to clean up allocated memory
void cleanup(sensorData *sensor, offset *off, keyRecord *keyRec, ListNode **head) {
    free(sensor);
    free(off);
    free(keyRec->data);

    // Free linked list
    ListNode *current = *head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL)); // Seed PRNG

    sensorData *sensor = malloc(sizeof(sensorData));
    offset *off = malloc(sizeof(offset));
    keyRecord *keyRec = malloc(sizeof(keyRecord));

    if (sensor == NULL || off == NULL || keyRec == NULL) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    initSensorData(sensor, 0);
    printf("Sensor Data: Timestamp=%ld, Index=%d, Measurement=%.2f\n", sensor->timestamp, sensor->index, sensor->measurement);

    // Simulate linked list creation for demonstration
    ListNode *head = NULL;
    ListNode *tail = NULL;

    for (int i = 0; i < 10; i++) {
        ListNode *newNode = malloc(sizeof(ListNode));
        if (newNode == NULL) {
            perror("Memory allocation failed");
            cleanup(sensor, off, keyRec, &head);
            return EXIT_FAILURE;
        }
        newNode->value = rand() % 100;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    processList(&head);

    cleanup(sensor, off, keyRec, &head);

    return EXIT_SUCCESS;
}
