    if (entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG for non-cryptographic purposes

    for (int i = 0; i < num_entries; i++) {
        entries[i].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp + 1);
        entries[i].event_type = rand() % 10 + 1; // Example valid event types
        entries[i].message = (char*)malloc(256 * sizeof(char));
        if (entries[i].message == NULL) {
            fprintf(stderr, "Memory allocation for message failed\n");
            free_log_entries(entries, i);
            return NULL;
        }
        snprintf(entries[i].message, 256, "Event %d at time %ld", entries[i].event_type, entries[i].timestamp);
    }

    return entries;
}

// Function to free allocated memory
void free_log_entries(log_entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(entries[i].message);
    }
    free(entries);
}

