            if (entries[i].event_type == event_type) {
                printf("Event %d at time %ld\n", entries[i].event_type, entries[i].timestamp);
                valid_count++;
            }
        }
    }

    free_log_entries(entries, num_entries);

    return EXIT_SUCCESS;
}
