} userSession;

int generateUniqueID(userSession *sessions, int count) {
    // Use a simple PRNG to generate unique IDs for demonstration purposes
    static int lastID = 0;
    return ++lastID;
}

void initializeSessions(userSession **sessions, int count, void (*logFunction)(const char *)) {
    *sessions = (userSession *)malloc(count * sizeof(userSession));
    if (*sessions == NULL) {
        logFunction("Failed to allocate memory for sessions.");
        exit(1);
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < count; ++i) {
        (*sessions)[i].sessionID = generateUniqueID(*sessions, i);
        (*sessions)[i].status = 'A'; // Active status
        logFunction("Session initialized with ID: %d", (*sessions)[i].sessionID);
    }
}

int readUniqueIntegers(int *array, int size) {
    int count = 0;
    while (count < size && scanf("%d", &array[count]) == 1) {
        for (int i = 0; i < count; ++i) {
            if (array[i] == array[count]) {
                printf("Duplicate detected, please enter a unique integer.\n");
                break;
            }
        }
        if (count >= size) {
            printf("Too many unique integers entered.\n");
            break;
        }
        ++count;
    }
    return count;
}

int findLargestInteger(int *array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void logMessage(const char *message) {
    printf("%s\n", message);
}

int main() {
    int count = 5;
    userSession *sessions;
    initializeSessions(&sessions, count, logMessage);

    int uniqueIntegers[10];
    int uniqueCount = readUniqueIntegers(uniqueIntegers, sizeof(uniqueIntegers) / sizeof(int));

    if (uniqueCount > 0) {
        int largest = findLargestInteger(uniqueIntegers, uniqueCount);
        printf("The largest integer is: %d\n", largest);
    }

    free(sessions);
    return 0;
}
