#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char buffer[1024];
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    char identifier[256];
} BatchRecord;

typedef struct {
    BatchRecord** batches;
    size_t batch_count;
    size_t max_records_per_batch;
} DynamicDataStructure;

DynamicDataStructure* create_dynamic_data_structure(size_t batch_count, size_t max_records_per_batch, unsigned int prng_seed) {
    DynamicDataStructure* dds = malloc(sizeof(DynamicDataStructure));
    if (dds == NULL) {
        return NULL;
    }

    dds->batch_count = batch_count;
    dds->max_records_per_batch = max_records_per_batch;

    dds->batches = malloc(batch_count * sizeof(BatchRecord*));
    if (dds->batches == NULL) {
        free(dds);
        return NULL;
    }

    srand(prng_seed);

    for (size_t i = 0; i < batch_count; ++i) {
        dds->batches[i] = malloc(max_records_per_batch * sizeof(BatchRecord));
        if (dds->batches[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free(dds->batches[j]);
            }
            free(dds->batches);
            free(dds);
            return NULL;
        }

        for (size_t j = 0; j < max_records_per_batch; ++j) {
            dds->batches[i][j].offset = j * batch_count + i;
            dds->batches[i][j].key = j;

            // Initialize record with random value
            dds->batches[i][j].record.value = rand() % 1000; // Example range

            // Generate unique identifier
            snprintf(dds->batches[i][j].identifier, sizeof(dds->batches[i][j].identifier), "key%d_%zu", j, i);

            // Populate buffer with unique string identifier
            strncpy(dds->batches[i][j].record.buffer, dds->batches[i][j].identifier, sizeof(dds->batches[i][j].record.buffer) - 1);
        }
    }

    return dds;
}

void destroy_dynamic_data_structure(DynamicDataStructure* dds) {
    for (size_t i = 0; i < dds->batch_count; ++i) {
        free(dds->batches[i]);
    }
    free(dds->batches);
    free(dds);
}
