#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int value;
    time_t timestamp;
    unsigned char status_flag;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DataProcessor;

void prng_init() {
    srand(time(NULL));
}

int prng_generate(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DataProcessor* dp_create(size_t initial_capacity) {
    DataProcessor *dp = (DataProcessor*)malloc(sizeof(DataProcessor));
    if (dp == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    dp->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (dp->records == NULL) {
        free(dp);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    dp->capacity = initial_capacity;
    dp->count = 0;
    pthread_mutex_init(&dp->mutex, NULL);
    prng_init();
    return dp;
}

void dp_add_record(DataProcessor *dp) {
    pthread_mutex_lock(&dp->mutex);
    if (dp->count == dp->capacity) {
        Record *new_records = (Record*)realloc(dp->records, dp->capacity * 2 * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&dp->mutex);
            return;
        }
        dp->records = new_records;
        dp->capacity *= 2;
    }
    Record *new_record = &dp->records[dp->count];
    new_record->key = prng_generate(1, 1000);
    new_record->offset = prng_generate(0, 1000000);
    new_record->value = prng_generate(0, 99999);
    time(&new_record->timestamp);
    new_record->status_flag = (unsigned char)prng_generate(0, 255);
    dp->count++;
    pthread_mutex_unlock(&dp->mutex);
}

void dp_destroy(DataProcessor *dp) {
    pthread_mutex_lock(&dp->mutex);
    free(dp->records);
    pthread_mutex_unlock(&dp->mutex);
    pthread_mutex_destroy(&dp->mutex);
    free(dp);
}

int main() {
    DataProcessor *dp = dp_create(100);
    if (dp != NULL) {
        for (size_t i = 0; i < 200; i++) {
            dp_add_record(dp);
        }
        dp_destroy(dp);
    }
    return 0;
}
