void initialize_arrays(long **offsets, int **keys, Record **records, char **buffer, Record ***hash_table, int size) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (Record *)malloc(size * sizeof(Record));
    *buffer = (char *)malloc(size * sizeof(char));
    *hash_table = (Record **)malloc(size * sizeof(Record *));

    for (int i = 0; i < size; ++i) {
        (*offsets)[i] = rand() % size;
        (*keys)[i] = rand() % size;
        (*records)[i].value1 = rand() % size;
        (*records)[i].value2 = rand() % size;
        (*hash_table)[i] = NULL;
    }
}

void free_memory(long *offsets, int *keys, Record *records, char *buffer, Record **hash_table, int size) {
    free(offsets);
    free(keys);
    free(records);
    free(buffer);

    for (int i = 0; i < size; ++i) {
        while ((*hash_table)[i] != NULL) {
            Record *temp = (*hash_table)[i];
            (*hash_table)[i] = (*hash_table)[i]->next;
            free(temp);
        }
    }

    free(hash_table);
}

