#include <time.h>
#include <limits.h>

typedef struct {
    int value;
} record;

long* generateOffsets(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* generateKeys(int size, long offsetRange) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(generateOffsets(size));
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % offsetRange;
    }
    return keys;
}

record* initializeRecords(int size, int keyRange) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(generateOffsets(size));
        free(generateKeys(size, 0));
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % keyRange;
    }
    return records;
}

void logInitialization(int size, int offsetRange, int keyRange) {
    printf("Initializing with size: %d, offset range: %ld, key range: %d\n", size, offsetRange, keyRange);
}

int readAndValidateIntegers(int* validInts, int maxSize, int minVal, int maxVal) {
    int count = 0;
    char buffer[128];
    printf("Enter integers (range %d-%d), separated by spaces: ", minVal, maxVal);
    fgets(buffer, sizeof(buffer), stdin);
    char* token = strtok(buffer, " ");
    while (token && count < maxSize) {
        int value = atoi(token);
        if (value >= minVal && value <= maxVal) {
            validInts[count++] = value;
        }
        token = strtok(NULL, " ");
    }
    return count;
}

int findLargestInteger(int* array, int size) {
    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char** argv) {
    int size = 1000; // Example size
    long offsetRange = 1000000;
    int keyRange = 1000;

    logInitialization(size, offsetRange, keyRange);

    long* offsets = generateOffsets(size);
    int* keys = generateKeys(size, offsetRange);
    record* records = initializeRecords(size, keyRange);

    int validIntegers[size];
    int count = readAndValidateIntegers(validIntegers, size, 100, 999);

    if (count > 0) {
        printf("Largest integer: %d\n", findLargestInteger(validIntegers, count));
    } else {
        printf("No valid integers entered.\n");
    }

    cleanup(offsets, keys, records);
    return 0;
}
