typedef struct {
    time_t timestamp;
    int transactionID;
    double amount;
} Transaction;

void initializeTransactions(Transaction *transactions, int count) {
    srand(time(NULL)); // Seed the PRNG with the current time for better randomness

    for (int i = 0; i < count; i++) {
        transactions[i].timestamp = time(NULL); // Use current time as timestamp
        transactions[i].transactionID = rand() % 10000 + 1; // Random ID in range [1, 10000]
        transactions[i].amount = (double)(rand() % 100) / 2.0; // Random amount between 0 and 50
    }
}

int validateTransactionID(int id, Transaction *transactions, int count) {
    for (int i = 0; i < count; i++) {
        if (transactions[i].transactionID == id) {
            return i; // Return the index of the valid transaction
        }
    }
    return -1; // ID not found
}

double calculateTotalAmount(int *ids, int count, Transaction *transactions, int transactionsCount) {
    double total = 0.0;
    for (int i = 0; i < count; i++) {
        int index = validateTransactionID(ids[i], transactions, transactionsCount);
        if (index != -1) {
            total += transactions[index].amount;
        }
    }
    return total;
}

int main() {
    int transactionCount = 1000; // Number of transactions
    Transaction *transactions = (Transaction *)malloc(transactionCount * sizeof(Transaction));
    initializeTransactions(transactions, transactionCount);

    int ids[] = {2345, 6789, 1234}; // Example transaction IDs to validate
    int idCount = sizeof(ids) / sizeof(ids[0]);
    double totalAmount = calculateTotalAmount(ids, idCount, transactions, transactionCount);
    printf("Total Amount: %.2f\n", totalAmount);

    free(transactions); // Free the allocated memory
    return 0;
}
