    int key;
    union {
        int value;
    };
} Record;

typedef struct union_find_node {
    int parent;
    int rank;
} UnionFindNode;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int initialize_arrays(long** offsets, int** keys, Record** records, UnionFindNode** nodes, int num_elements) {
    *offsets = (long*)safe_malloc(num_elements * sizeof(long));
    *keys = (int*)safe_malloc(num_elements * sizeof(int));
    *records = (Record*)safe_malloc(num_elements * sizeof(Record));
    *nodes = (UnionFindNode*)safe_malloc(num_elements * sizeof(UnionFindNode));

    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100;
        (*records)[i].offset = (*offsets)[i];
        (*records)[i].key = (*keys)[i];
        (*records)[i].value = rand();
        (*nodes)[i].parent = i;
        (*nodes)[i].rank = 0;
    }

    return 0;
}

int find_largest(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void read_and_print_largest() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);
    int* array = (int*)safe_malloc(size * sizeof(int));

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    int largest = find_largest(array, size);
    printf("The largest integer is: %d\n", largest);

    free(array);
}

void union_find_init(UnionFindNode* nodes, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        nodes[i].parent = i;
        nodes[i].rank = 0;
    }
}

int find(UnionFindNode* nodes, int x) {
    if (nodes[x].parent != x) {
        nodes[x].parent = find(nodes, nodes[x].parent);
    }
    return nodes[x].parent;
}

void union_(UnionFindNode* nodes, int x, int y) {
    int rootX = find(nodes, x);
    int rootY = find(nodes, y);

    if (nodes[rootX].rank > nodes[rootY].rank) {
        nodes[rootY].parent = rootX;
    } else if (nodes[rootX].rank < nodes[rootY].rank) {
        nodes[rootX].parent = rootY;
    } else {
        nodes[rootY].parent = rootX;
        nodes[rootX].rank++;
    }
}

void close_channel() {
    // Implement channel closure logic here
}

int main() {
    int num_elements = 1000; // Example number of elements
    long* offsets;
    int* keys;
    Record* records;
    UnionFindNode* nodes;

    initialize_arrays(&offsets, &keys, &records, &nodes, num_elements);
    read_and_print_largest();
    union_find_init(nodes, num_elements);

    for (int i = 0; i < num_elements - 1; i++) {
        union_(nodes, i, i + 1);
        int root_i = find(nodes, i);
        int root_j = find(nodes, i + 1);
        printf("Pair %d and %d are in the same set: %s\n", i, i + 1, (root_i == root_j) ? "Yes" : "No");
    }

    close_channel();

    free(offsets);
    free(keys);
    free(records);
    free(nodes);

    return 0;
}
