long find_max(int* array, int length) {
    if (length == 0) {
        fprintf(stderr, "Input list is empty\n");
        return -1;
    }
    long max = array[0];
    for (int i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

