DataStructure* initialize_data_structure(size_t initial_capacity) {
    DataStructure *ds = malloc(sizeof(DataStructure));
    if (ds == NULL) {
        log_message("Failed to allocate memory for data structure");
        return NULL;
    }

    ds->offsets = malloc(initial_capacity * sizeof(int));
    ds->keys = malloc(initial_capacity * sizeof(char *));
    ds->records = malloc(initial_capacity * sizeof(Record *));
    ds->count = 0;
    ds->capacity = initial_capacity;

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        log_message("Failed to allocate memory for data structure arrays");
        free(ds);
        return NULL;
    }

    // Initialize PRNG seed and other setup code here

