}

void free_data_structure(DataStructure *ds) {
    if (ds != NULL) {
        for (size_t i = 0; i < ds->count; ++i) {
            free(ds->keys[i]);
        }
        free(ds->offsets);
        free(ds->keys);
        for (size_t i = 0; i < ds->count; ++i) {
            free(ds->records[i]);
        }
        free(ds->records);
        free(ds);
    }
