void initializeArrays(int size) {
    long *longSeed = (long *)malloc(size * sizeof(long));
    int *intIndices = (int *)malloc(size * sizeof(int));
    Data *dataStructures = (Data *)malloc(size * sizeof(Data));
    double *inputNumbers = (double *)malloc(size * sizeof(double));
    int *prngArray = (int *)malloc(size * sizeof(int));

    if (longSeed == NULL || intIndices == NULL || dataStructures == NULL || inputNumbers == NULL || prngArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize pseudo-random values and perform operations
    for (int i = 0; i < size; i++) {
        longSeed[i] = time(NULL) % 1000 + i;
        intIndices[i] = rand() % 100;
        dataStructures[i].value = ((double)rand() / RAND_MAX) * 100.0;

        // Read floating-point numbers from standard input
        printf("Enter a floating-point number: ");
        scanf("%lf", &inputNumbers[i]);

        // Generate non-cryptographic PRNG values
        prngArray[i] = (int)((time(NULL) + i) % 100);
    }

    // Find and print the smallest floating-point number
    double minNumber = inputNumbers[0];
    for (int i = 1; i < size; i++) {
        if (inputNumbers[i] < minNumber) {
            minNumber = inputNumbers[i];
        }
    }
    printf("The smallest floating-point number is: %f\n", minNumber);

    // Free allocated memory
    free(longSeed);
    free(intIndices);
    free(dataStructures);
    free(inputNumbers);
    free(prngArray);
}

int main() {
