    int value;
};

// Function to initialize the vectors with pseudo-random values
void initialize_vectors(std::vector<long>& offsets, std::vector<int>& keys, int size) {
    srand(time(0)); // Seed the random number generator
    for (int i = 0; i < size; ++i) {
        offsets.push_back(rand() % 1000); // Generate random offset values
        keys.push_back(rand() % 100);    // Generate random key values
    }
}

// Helper function to find the largest integer in a vector
int find_largest(const std::vector<int>& vec) {
    return *std::max_element(vec.begin(), vec.end());
}

// Function to insert a string into a forward list after the first occurrence of a specified string
void insert_after(std::forward_list<std::string>& lst, const std::string& search, const std::string& insert) {
    auto prev = lst.before_begin();
    for (auto it = lst.begin(); it != lst.end(); ++it) {
        if (*it == search) {
            lst.insert_after(prev, insert);
            return;
        }
        prev = it;
    }
    lst.push_back(insert); // Append to the end if not found
}

// Helper function to find and print the largest integer in an array
int find_largest_array(const int* arr, size_t size) {
    return *std::max_element(arr, arr + size);
}
