#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    char* identifier;
} record;

void log_message(const char* message) {
    // External logging mechanism integration
    printf("LOG: %s\n", message);
}

long find_largest_long(long* array, int size) {
    long max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

record* initialize_records(int num_keys, const char** identifiers, long* offsets) {
    record* records = (record*)malloc(num_keys * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = offsets[i];
        records[i].key = rand();
        records[i].identifier = strdup(identifiers[i]);
        if (!records[i].identifier) {
            log_message("Memory allocation failed for identifier.");
            free_records(records, i);
            return NULL;
        }
    }

    return records;
}

void print_largest_integer(int* integers, int size) {
    int max = find_largest_long((long*)integers, size);
    printf("Largest Integer: %d\n", max);
}

void print_largest_identifier(record* records, long* offsets, int num_records) {
    long largest_offset = find_largest_long(offsets, num_records);
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == largest_offset) {
            printf("Largest Offset Identifier: %s\n", records[i].identifier);
            break;
        }
    }
}

void check_data_integrity(record* records, int num_records) {
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (strcmp(records[i].identifier, records[j].identifier) == 0) {
                log_message("Data integrity warning: Duplicate identifier found.");
                break;
            }
        }
    }
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].identifier);
    }
    free(records);
}

int main() {
    int num_keys;
    printf("Enter the number of keys: ");
    scanf("%d", &num_keys);

    long* offsets = (long*)malloc(num_keys * sizeof(long));
    char** identifiers = (char**)malloc(num_keys * sizeof(char*));

    printf("Enter offsets and identifiers:\n");
    for (int i = 0; i < num_keys; i++) {
        scanf("%ld %s", &offsets[i], identifiers[i] = (char*)malloc(100));
    }

    record* records = initialize_records(num_keys, (const char**)identifiers, offsets);
    if (!records) {
        return 1;
    }

    int* integers = (int*)malloc(num_keys * sizeof(int));
    printf("Enter integers:\n");
    for (int i = 0; i < num_keys; i++) {
        scanf("%d", &integers[i]);
    }

    print_largest_integer(integers, num_keys);
    print_largest_identifier(records, offsets, num_keys);
    check_data_integrity(records, num_keys);

    free(offsets);
    for (int i = 0; i < num_keys; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free_records(records, num_keys);
    free(integers);

    return 0;
}
