#define NUM_ELEMENTS 10

typedef struct {
    int value;
    char* status_message;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    double timestamp;
    int vertex_id;
    double weight;
    char* node_label;
    char* metadata;
    int path_sequence[NUM_ELEMENTS];
    char* algorithm_params;
} GraphData;

GraphData* initialize_graph_data() {
    GraphData* graph_data = (GraphData*)malloc(NUM_ELEMENTS * sizeof(GraphData));
    if (!graph_data) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize arrays and populate with random data
    srand(time(NULL));  // Seed the PRNG

    for (int i = 0; i < NUM_ELEMENTS; i++) {
        graph_data[i].offset = rand();
        graph_data[i].key = rand() % 1000;
        graph_data[i].record.value = rand() % 100;
        graph_data[i].record.status_message = (char*)malloc(256);
        snprintf(graph_data[i].record.status_message, 256, "Status %d", i);
        graph_data[i].timestamp = (double)rand() / RAND_MAX * time(NULL);
        graph_data[i].vertex_id = rand() % 100;
        graph_data[i].weight = (double)rand() / RAND_MAX * 100.0;
        graph_data[i].node_label = (char*)malloc(256);
        snprintf(graph_data[i].node_label, 256, "Label %d", i);
        graph_data[i].metadata = (char*)malloc(256);
        snprintf(graph_data[i].metadata, 256, "Metadata %d", i);

        for (int j = 0; j < NUM_ELEMENTS; j++) {
            graph_data[i].path_sequence[j] = rand() % 10;
        }

        graph_data[i].algorithm_params = (char*)malloc(256);
        snprintf(graph_data[i].algorithm_params, 256, "Params %d", i);
    }

    return graph_data;
}

void free_graph_data(GraphData* graph_data) {
    if (!graph_data) {
        return;
    }

    for (int i = 0; i < NUM_ELEMENTS; i++) {
        free(graph_data[i].record.status_message);
        free(graph_data[i].node_label);
        free(graph_data[i].metadata);
        free(graph_data[i].algorithm_params);
    }

    free(graph_data);
}

int main() {
    GraphData* graph_data = initialize_graph_data();
    if (graph_data) {
        // Process the graph data
        free_graph_data(graph_data);
    }
    return 0;
}
