#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    int event_type;
} record;

typedef struct {
    int *parent;
    int *rank;
} uf_set;

void init_union_find(uf_set *set, int n) {
    set->parent = malloc(n * sizeof(int));
    set->rank = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        set->parent[i] = i;
        set->rank[i] = 0;
    }
}

int find(uf_set *set, int i) {
    if (set->parent[i] != i)
        set->parent[i] = find(set, set->parent[i]);
    return set->parent[i];
}

void union_sets(uf_set *set, int x, int y) {
    int rootX = find(set, x);
    int rootY = find(set, y);

    if (rootX != rootY) {
        if (set->rank[rootX] > set->rank[rootY])
            set->parent[rootY] = rootX;
        else if (set->rank[rootX] < set->rank[rootY])
            set->parent[rootX] = rootY;
        else {
            set->parent[rootY] = rootX;
            set->rank[rootX]++;
        }
    }
}

void free_union_find(uf_set *set) {
    free(set->parent);
    free(set->rank);
}

double calculate_average_rate(int start, int end) {
    // Simulate event rate calculation for demonstration purposes
    return (end - start) / 10.0; // Assuming a base rate of 10 events per second
}

void process_records() {
    record *records = NULL;
    int count = 0;
    long min_timestamp = LONG_MAX, max_timestamp = LONG_MIN;

    while (1) {
        record new_record;
        if (scanf("%ld %d", &new_record.timestamp, &new_record.event_type) != 2)
            break;

        if (new_record.timestamp < min_timestamp)
            min_timestamp = new_record.timestamp;
        if (new_record.timestamp > max_timestamp)
            max_timestamp = new_record.timestamp;

        records = realloc(records, (count + 1) * sizeof(record));
        records[count++] = new_record;
    }

    int interval_count = max_timestamp - min_timestamp + 1;
    uf_set set;
    init_union_find(&set, count);

    clock_t start_time, end_time;
    double total_time = 0.0;

    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (records[i].timestamp == records[j].timestamp) {
                start_time = clock();
                union_sets(&set, i, j);
                end_time = clock();
                total_time += (double)(end_time - start_time) / CLOCKS_PER_SEC;
            }
        }
    }

    free_union_find(&set);

    for (int i = 0; i < count; ++i) {
        int root = find(&set, i);
        if (records[root].timestamp == records[i].timestamp)
            printf("Interval %ld-%ld: Average rate = %.2f\n", min_timestamp + root, max_timestamp - root, calculate_average_rate(min_timestamp + root, max_timestamp - root));
    }

    free(records);
}

int main() {
    process_records();
    return 0;
}
