void allocateMemory(int n, int m, int p, int q) {
    long** offsetArrays = (long**)malloc(n * sizeof(long*));
    if (offsetArrays == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset arrays\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the keys array
    int* keys = (int*)malloc(m * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for keys array\n");
        free(offsetArrays);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for record arrays
    Record** recordArrays = (Record**)malloc(p * sizeof(Record*));
    if (recordArrays == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record arrays\n");
        free(keys);
        free(offsetArrays);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for metadata pointers
    void*** metadataPointers = (void***)malloc(q * sizeof(void**));
    if (metadataPointers == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for metadata pointers\n");
        free(recordArrays);
        free(keys);
        free(offsetArrays);
        exit(EXIT_FAILURE);
    }

    // Initialize record structures with pseudo-random values
    srand(time(NULL));
    for (int i = 0; i < p; i++) {
        Record* records = (Record*)malloc(m * sizeof(Record));
        if (records == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for records\n");
            for (int j = 0; j < i; j++) {
                free(recordArrays[j]);
            }
            free(metadataPointers);
            free(keys);
            free(offsetArrays);
            exit(EXIT_FAILURE);
        }
        recordArrays[i] = records;
        for (int j = 0; j < m; j++) {
            records[j].value = rand() % 100; // Pseudo-random value
        }
    }

    // Free allocated memory
    free(recordArrays);
    free(keys);
    free(offsetArrays);
    free(metadataPointers);
}

int main() {
    int n, m, p, q;
    printf("Enter the number of offset arrays: ");
    scanf("%d", &n);
    printf("Enter the number of keys: ");
    scanf("%d", &m);
    printf("Enter the number of record arrays: ");
    scanf("%d", &p);
    printf("Enter the number of metadata pointers: ");
    scanf("%d", &q);

    allocateMemory(n, m, p, q);

    return 0;
}
