// Union-Find data structure implementation (simplified version)
typedef struct {
    int* parent;
    int size;
} UFSet;

UFSet* uf_init(int n) {
    UFSet* set = malloc(sizeof(UFSet));
    set->parent = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        set->parent[i] = i;
    }
    set->size = n;
    return set;
}

void uf_make_set(UFSet* set, int x) {
    set->parent[x] = x;
}

int uf_find(UFSet* set, int x) {
    if (set->parent[x] != x) {
        set->parent[x] = uf_find(set, set->parent[x]);
    }
    return set->parent[x];
}

void uf_union(UFSet* set, int x, int y) {
    int rootX = uf_find(set, x);
    int rootY = uf_find(set, y);
    if (rootX != rootY) {
        set->parent[rootY] = rootX;
    }
}

// Function to generate pseudo-random values
int prng(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Function to initialize arrays and structures
void init_data_structures() {
    srand(time(NULL));

    // Allocate memory for long offset values
    long* offsets = malloc(5 * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    // Allocate memory for int keys
    int* keys = malloc(5 * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for record structures
    Record* records1 = malloc(2 * sizeof(Record));
    Record* records2 = malloc(2 * sizeof(Record));
    if (!records1 || !records2) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Allocate memory for char strings
    char** ids = malloc(5 * sizeof(char*));
    if (!ids) {
        fprintf(stderr, "Memory allocation failed for IDs\n");
        free(offsets);
        free(keys);
        free(records1);
        free(records2);
        return;
    }

    // Initialize arrays with pseudo-random values
    for (int i = 0; i < 5; i++) {
        offsets[i] = prng(0, 1000);
        keys[i] = prng(0, 100);
        ids[i] = malloc(20 * sizeof(char));
        sprintf(ids[i], "ID%ld", offsets[i]);
    }

    // Initialize record structures
    for (int i = 0; i < 2; i++) {
        records1[i].value = prng(0, 10);
        records2[i].value = prng(0, 10);
    }

    // Union-Find data structure example
    UFSet* uf = uf_init(5);
    uf_make_set(uf, 0);
    uf_make_set(uf, 1);
    uf_union(uf, 0, 1);

    printf("Number of milliseconds taken for union: %ld\n", clock());

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records1);
    free(records2);
    for (int i = 0; i < 5; i++) {
        free(ids[i]);
    }
    free(uf->parent);
    free(uf);

    printf("Initialization complete.\n");
}

int main() {
    init_data_structures();
    return 0;
}
