#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_RANDOM_VALUE 256

typedef struct {
    int value;
    char indicator;
    size_t length;
} record;

record* allocate_records(int num_records, unsigned long seed) {
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        return NULL;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % MAX_RANDOM_VALUE;
        records[i].indicator = 'A' + (rand() % 26);
        records[i].length = rand() % 100;
    }

    return records;
}

