void calculateStatistics(float* data, size_t count) {
    // Implement mean, median, and standard deviation calculation
    float sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
    }
    float mean = sum / count;

    // Sort the array for median calculation
    qsort(data, count, sizeof(float), (int (*)(const void*, const void*))compareFloats);
    float median;
    if (count % 2 == 0) {
        median = (data[count / 2 - 1] + data[count / 2]) / 2;
    } else {
        median = data[count / 2];
    }

    // Calculate standard deviation
    float varianceSum = 0;
    for (size_t i = 0; i < count; ++i) {
        varianceSum += pow(data[i] - mean, 2);
    }
    float stdDeviation = sqrt(varianceSum / count);

    printf("Mean: %f\n", mean);
    printf("Median: %f\n", median);
    printf("Standard Deviation: %f\n", stdDeviation);
}

int compareFloats(const void* a, const void* b) {
    return (*(float*)a - *(float*)b);
}
