record* create_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL;
    }

    size_t total_size = sizeof(long) * num_records + sizeof(record) * num_records;
    if (total_size > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory allocation exceeds maximum limit.\n");
        return NULL;
    }

    record* records = (record*)malloc(total_size);
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    long* offsets = (long*)((char*)records + sizeof(record) * num_records);

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        free(records);
    }
}

