#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int generateRandom(int min, int max, int *last) {
    static int seed = 0;
    if (seed == 0) {
        seed = time(NULL);
        srand(seed);
    }
    int randomValue;
    do {
        randomValue = rand() % (max - min + 1) + min;
    } while (randomValue == *last);
    *last = randomValue;
    return randomValue;
}

void manageMemory(long **offsets, int **keys, record **records, size_t offsetSize, size_t keySize, size_t recordSize) {
    *offsets = malloc(offsetSize * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(1);
    }

    *keys = malloc(keySize * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        exit(1);
    }

    *records = malloc(recordSize * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        exit(1);
    }

    // Initialize offsets
    for (size_t i = 0; i < offsetSize; ++i) {
        (*offsets)[i] = i * 100;
    }

    // Initialize keys and records
    int lastRandom = -1;
    for (size_t i = 0; i < recordSize; ++i) {
        (*records)[i].value = generateRandom(0, 100000, &lastRandom);
    }
}

void freeMemory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const size_t offsetSize = 10000;
    const size_t keySize = 5000;
    const size_t recordSize = 2000;

    long *offsets;
    int *keys;
    record *records;

    manageMemory(&offsets, &keys, &records, offsetSize, keySize, recordSize);

    // Use the allocated arrays and structures here

    freeMemory(offsets, keys, records);

    return 0;
}
