typedef struct string_node {
    char *str;
    struct string_node *next;
} string_node;

typedef struct string_list {
    string_node *head;
    string_node *tail;
} string_list;

string_list* create_string_list() {
    string_list *list = (string_list*)malloc(sizeof(string_list));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    return list;
}

void add_to_string_list(string_list *list, const char *str) {
    string_node *new_node = (string_node*)malloc(sizeof(string_node));
    if (!new_node) return;
    new_node->str = strdup(str);
    new_node->next = NULL;

    if (list->tail) list->tail->next = new_node;
    else list->head = new_node;

    list->tail = new_node;
}

int find_largest_integer(int *array, int size) {
    if (size <= 0) return -1; // Handle edge case for empty or invalid input
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void free_string_list(string_list *list) {
    string_node *current, *next;
    current = list->head;

    while (current != NULL) {
        next = current->next;
        free(current->str);
        free(current);
        current = next;
    }

    free(list);
}
