#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define the union-find data structure
typedef struct {
    int *parent;
    int *rank;
    int size;
} UnionFind;

// Function to initialize the union-find data structure
void initUnionFind(UnionFind *uf, int n) {
    uf->parent = (int *)malloc(n * sizeof(int));
    uf->rank = (int *)calloc(n, sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
    }
}

// Function to find the root of an element
int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

// Function to union two sets
void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

// Function to initialize arrays and records
void initArrays(int numArrays, long *offsets, int *keys, Record **records) {
    for (int i = 0; i < numArrays; i++) {
        offsets[i] = (long)(rand() % 1000);
        keys[i] = rand() % 100;
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->value = rand() % 1000;
    }
}

// Function to free allocated memory
void freeArrays(int numArrays, long *offsets, int *keys, Record **records) {
    for (int i = 0; i < numArrays; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

// Function to find the largest integer in an array
int findLargest(int *array, int size) {
    if (size == 0) return -1;
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

// Main function
int main() {
    srand(time(0));

    // Example usage
    int numArrays = 5;
    long *offsets = (long *)malloc(numArrays * sizeof(long));
    int *keys = (int *)malloc(numArrays * sizeof(int));
    Record **records = (Record **)malloc(numArrays * sizeof(Record *));

    initArrays(numArrays, offsets, keys, records);

    // Union-Find example
    UnionFind uf;
    initUnionFind(&uf, numArrays);
    unionSets(&uf, 0, 1);
    unionSets(&uf, 2, 3);

    int largest = findLargest(offsets, numArrays);
    printf("Largest offset: %ld\n", largest);

    freeArrays(numArrays, offsets, keys, records);
    freeUnionFind(&uf);

    return 0;
}

// Function to free union-find data structure
void freeUnionFind(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
}
