} uf_set;

// Function to initialize the Union-Find structure
void init_uf(uf_set *ufs, int size) {
    ufs->parent = malloc(size * sizeof(int));
    if (ufs->parent == NULL) {
        perror("Memory allocation failed");
        return;
    }
    for (int i = 0; i < size; i++) {
        ufs->parent[i] = i;
    }
}

// Function to find the root of a set
int find(uf_set *ufs, int x) {
    if (ufs->parent[x] != x) {
        ufs->parent[x] = find(ufs, ufs->parent[x]);
    }
    return ufs->parent[x];
}

// Mock function for disjointness check using Union-Find
int are_disjoint(uf_set *ufs, int a, int b) {
    return find(ufs, a) != find(ufs, b);
}

// Function to perform disjointness checks and measure time
void check_disjointness(uf_set *ufs, int size, int num_checks) {
    clock_t start_time = clock();
    for (int i = 0; i < num_checks; i++) {
        int a = rand() % size;
        int b = rand() % size;
        printf("Disjoint(%d, %d): %s\n", a, b, are_disjoint(ufs, a, b) ? "Yes" : "No");
    }
    clock_t end_time = clock();
    double time_taken = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("Time taken for disjointness checks: %.2f ms\n", time_taken * 1000);
