#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct Record {
    int key;
    long offset;
    char* string;
    int randomValue;
} Record;

// Custom PRNG function using Linear Congruential Generator (LCG)
unsigned int lcg(unsigned int seed) {
    return (seed * 1664525 + 1013904223) % 4294967296;
}

// Function to initialize the dynamic list of records
Record* initRecords(int numRecords, long offsetRangeMin, long offsetRangeMax,
                    int keyRangeMin, int keyRangeMax, const char* stringCharset,
                    int stringLengthMin, int stringLengthMax, unsigned int seed) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) return NULL;

    unsigned int lcgSeed = seed;
    for (int i = 0; i < numRecords; i++) {
        // Initialize record key
        records[i].key = keyRangeMin + lcg(lcgSeed++) % (keyRangeMax - keyRangeMin + 1);

        // Initialize record offset
        records[i].offset = offsetRangeMin + lcg(lcgSeed++) % (offsetRangeMax - offsetRangeMin + 1);

        // Generate unique string
        int length = stringLengthMin + lcg(lcgSeed++) % (stringLengthMax - stringLengthMin + 1);
        char* newString = (char*)malloc((length + 1) * sizeof(char));
        if (!newString) {
            for (int j = 0; j < i; j++) free(records[j].string);
            free(records);
            return NULL;
        }
        for (int j = 0; j < length; j++) {
            newString[j] = stringCharset[lcg(lcgSeed++) % strlen(stringCharset)];
        }
        newString[length] = '\0';
        records[i].string = newString;

        // Initialize random value
        records[i].randomValue = keyRangeMin + lcg(lcgSeed++) % (keyRangeMax - keyRangeMin + 1);
    }

    return records;
}

// Example usage
int main() {
    srand(time(NULL));
    const char* charset = "abcdefghijklmnopqrstuvwxyz0123456789";
    Record* records = initRecords(10, 0, 1000000, 1, 100, charset, 5, 10, time(NULL));

    if (records) {
        for (int i = 0; i < 10; i++) {
            printf("Record %d: Key=%d, Offset=%ld, String='%s', RandomValue=%d\n",
                   i, records[i].key, records[i].offset, records[i].string, records[i].randomValue);
        }
        for (int i = 0; i < 10; i++) free(records[i].string);
        free(records);
    }

    return 0;
}
```

