#define MAX_EVENT_CODES 100
#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    time_t timestamp;
    int buffer_identifier;
    int event_code;
} event_log;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    int size;
} dynamic_buffer;

dynamic_buffer* init_dynamic_buffer(int initial_size, int seed) {
    dynamic_buffer *buf = (dynamic_buffer*) malloc(sizeof(dynamic_buffer));
    if (!buf) {
        fprintf(stderr, "Memory allocation failed for buffer initialization.\n");
        return NULL;
    }

    buf->offsets = (long*) calloc(initial_size, sizeof(long));
    buf->keys = (int*) calloc(initial_size, sizeof(int));
    buf->records = (record**) malloc(initial_size * sizeof(record*));

    if (!buf->offsets || !buf->keys || !buf->records) {
        fprintf(stderr, "Memory allocation failed for buffer components.\n");
        free(buf->offsets);
        free(buf->keys);
        free(buf->records);
        free(buf);
        return NULL;
    }

    buf->size = initial_size;

    srand(seed);
    for (int i = 0; i < initial_size; i++) {
        buf->records[i] = (record*) malloc(sizeof(record));
        if (!buf->records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            // Free previously allocated records and components
            for (int j = 0; j < i; j++) {
                free(buf->records[j]);
            }
            free(buf->offsets);
            free(buf->keys);
            free(buf->records);
            free(buf);
            return NULL;
        }
        buf->records[i]->value = rand() % MAX_EVENT_CODES;
    }

    return buf;
}

void destroy_dynamic_buffer(dynamic_buffer *buf) {
    for (int i = 0; i < buf->size; i++) {
        free(buf->records[i]);
    }
    free(buf->offsets);
    free(buf->keys);
    free(buf->records);
    free(buf);
}

