    if (!records) {
        return NULL; // Handle allocation failure
    }

    for (size_t i = 0; i < numRecords; ++i) {
        records[i].key = generateRandomInt(1, 100); // Key in range 1 to 100

        records[i].length = generateRandomInt(5, maxMessageSize); // Message length between 5 and maxMessageSize
        records[i].message = (char *)malloc(records[i].length * sizeof(char));
        if (!records[i].message) {
            for (size_t j = 0; j < i; ++j) {
                free(records[j].message);
            }
            free(records);
            return NULL; // Handle allocation failure
        }

        fillMessage(records[i].message, records[i].length);
