```rust
use reqwest::{Client, RequestBuilder};
use std::collections::HashSet;
use tokio::net::TcpStream;

fn create_client(allow_insecure: bool) -> Client {
    if allow_insecure {
        let mut builder = reqwest::ClientBuilder::new();
        builder.dangerously_ignore_ssl(true);
        builder.build().unwrap()
    } else {
        reqwest::Client::new()
    }
}

async fn fetch_urls(urls: &[&str]) -> Vec<RequestBuilder> {
    urls.iter()
        .map(|url| create_client(false).get(url))
        .collect()
}

fn read_urls_from_file(file_path: &str) -> Result<Vec<&str>, std::io::Error> {
    let file_content = std::fs::read_to_string(file_path)?;
    Ok(file_content.lines().collect())
}

async fn process_requests(urls: Vec<&str>) -> Result<(), reqwest::Error> {
    let mut handles = vec![];
    for url in urls {
        let client = create_client(false);
        let builder = client.get(url);
        let handle = tokio::spawn(async move {
            match builder.send().await {
                Ok(response) => {
                    log_info(&format!("Request to {} successful", url));
                    response
                },
                Err(e) => {
                    log_error(&format!("Failed to request {}: {}", url, e));
                    return;
                }
            };
        });
        handles.push(handle);
    }

    for handle in handles {
        if let Err(e) = handle.await {
            log_error(&format!("Error processing request: {}", e));
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let urls = read_urls_from_file("urls.txt")?;
    let requests = fetch_urls(&urls);
    process_requests(requests).await?;
    Ok(())
}
