#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

long* allocate_offset_array(size_t size) {
    long* offset_array = (long*)malloc(size * sizeof(long));
    if (!offset_array) {
        perror("Failed to allocate memory for offset array");
        exit(EXIT_FAILURE);
    }
    return offset_array;
}

int* allocate_key_array(size_t size) {
    int* key_array = (int*)malloc(size * sizeof(int));
    if (!key_array) {
        perror("Failed to allocate memory for key array");
        free(offset_array);
        exit(EXIT_FAILURE);
    }
    return key_array;
}

record** allocate_record_array(size_t size) {
    record** record_array = (record**)malloc(size * sizeof(record*));
    if (!record_array) {
        perror("Failed to allocate memory for record array");
        free(key_array);
        free(offset_array);
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; ++i) {
        record_array[i] = (record*)malloc(sizeof(record));
        if (!record_array[i]) {
            perror("Failed to allocate memory for record");
            for (size_t j = 0; j < i; ++j) {
                free(record_array[j]);
            }
            free(record_array);
            free(key_array);
            free(offset_array);
            exit(EXIT_FAILURE);
        }
    }
    return record_array;
}

void initialize_arrays(long* offset_array, int* key_array, record** record_array, size_t size, long seed) {
    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        offset_array[i] = rand() % 1000L;
        key_array[i] = rand() % 1000;
        record_array[i]->value = rand() % 1000;
    }
}

int find_largest_int(int* array, size_t size) {
    if (size == 0) {
        fprintf(stderr, "Empty input stream\n");
        return INT_MIN;
    }
    int max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

record** initialize_random_records(size_t size, long seed, int range_min, int range_max) {
    srand(seed);
    record** record_array = allocate_record_array(size);
    for (size_t i = 0; i < size; ++i) {
        record_array[i]->value = rand() % (range_max - range_min + 1) + range_min;
    }
    return record_array;
}

int read_integers_from_file(const char* filename, int** array, size_t* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    *size = 0;
    int value;
    while (fscanf(file, "%d", &value) == 1) {
        (*size)++;
    }
    fclose(file);

    *array = (int*)malloc((*size) * sizeof(int));
    if (!*array) {
        perror("Failed to allocate memory for integer array");
        return -1;
    }

    file = fopen(filename, "r");
    if (!file) {
        perror("Failed to reopen file");
        free(*array);
        return -1;
    }
    size_t read_count = fread(*array, sizeof(int), *size, file);
    fclose(file);

    if (read_count != *size) {
        fprintf(stderr, "Error reading from file\n");
        free(*array);
        return -1;
    }

    return 0;
}

int main() {
    size_t size = 1000;
    long seed = time(NULL);
    int* integers;
    size_t integer_count;

    if (read_integers_from_file("input.txt", &integers, &integer_count) != 0) {
        free(integers);
        return EXIT_FAILURE;
    }

    long* offset_array = allocate_offset_array(size);
    int* key_array = allocate_key_array(size);
    record** record_array = allocate_record_array(size);

    initialize_arrays(offset_array, key_array, record_array, size, seed);

    int largest_value = find_largest_int(integers, integer_count);
    printf("Largest value: %d\n", largest_value);

    record** random_records = initialize_random_records(size, seed, 1, 1000);

    for (size_t i = 0; i < size; ++i) {
        free(record_array[i]);
        free(random_records[i]);
    }
    free(offset_array);
    free(key_array);
    free(record_array);
