    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* initialize_records(int count) {
    record* records = (record*)allocate_memory(count * sizeof(record));
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }
    return records;
}

void find_max(int* arr, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

void union_find(int* arr, int count) {
    union FindData* data = (union FindData*)allocate_memory(count * sizeof(union FindData));
    for (int i = 0; i < count; i++) {
        data[i].parent = i;
        data[i].rank = 0;
    }

    // Example of finding disjoint pairs
    for (int i = 0; i < count - 1; i++) {
        int t1 = arr[i];
        int t2 = arr[i + 1];
        clock_t start = clock();
        while (t1 != data[t1].parent) {
            t1 = data[t1].parent;
        }
        while (t2 != data[t2].parent) {
            t2 = data[t2].parent;
        }

        if (t1 == t2) {
            printf("Pair %d and %d are disjoint\n", arr[i], arr[i + 1]);
        } else {
            printf("Pair %d and %d are not disjoint\n", arr[i], arr[i + 1]);
        }
        clock_t end = clock();
        double time_taken = ((double) (end - start)) / CLOCKS_PER_SEC;
        printf("Time taken for pair %d: %f milliseconds\n", i, time_taken * 1000);
    }

    free(data);
}

int main() {
    int count = 5; // Example size
    record* records = initialize_records(count);
    int* input_arr = (int*)allocate_memory(count * sizeof(int));

    for (int i = 0; i < count; i++) {
        input_arr[i] = rand() % 1000;
    }

    find_max(input_arr, count);
    union_find(input_arr, count);

    free(records);
    free(input_arr);

    return 0;
}
