record* allocate_and_init_records(int num_records, int seed) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % num_records;
        records[i].value = rand();
    }

    return records;
