record* get_record_by_key(record* records, int num_records, int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }
    fprintf(stderr, "Record with key %d not found\n", key);
    return NULL;
}

void update_record_by_key(record* records, int num_records, int key, int new_value) {
    record* rec = get_record_by_key(records, num_records, key);
    if (rec != NULL) {
        rec->value = new_value;
    }
}

void free_records(record* records) {
    free(records);
}
