#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initialize_arrays(size_t offset_size, size_t key_size, size_t record_size, int min_random, int max_random) {
    // Allocate memory for arrays
    long *offsets = (long *)calloc(offset_size, sizeof(long));
    if (offsets == NULL) {
        return NULL;
    }

    int *keys = (int *)calloc(key_size, sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return NULL;
    }

    record *records = (record *)malloc(record_size * sizeof(record));
    if (records == NULL) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize offsets and keys with zero
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = 0;
    }
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = 0;
    }

    // Seed the non-cryptographic PRNG
    srand(time(NULL));

    // Populate records with random numbers within the specified range
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % (max_random - min_random + 1) + min_random;
    }

    return records;
}
```

**Explanation of the code:**
- The function `initialize_arrays` is designed to allocate and initialize memory for three arrays as per the requirements.
- Memory allocation is done using `calloc` and `malloc`, ensuring that the allocated blocks are initialized to zero or non-zero as specified.
- A non-cryptographic PRNG (`srand` followed by `rand`) is used to generate random numbers within a specified range. This choice balances performance with predictability, which is suitable for many applications but should be reconsidered if absolute unpredictability is required.
- Error handling is included to manage cases where memory allocation fails.
- The function returns pointers to the allocated arrays, making it easy to use in larger systems while ensuring proper memory management.

**Limitations:**
- The non-cryptographic PRNG used here may produce predictable sequences under certain conditions, which could be a concern if cryptographic security is paramount.
- This implementation assumes that the input sizes (`offset_size`, `key_size`, and `record_size`) are reasonable and do not lead to excessive memory usage or performance issues.']

