int initializeArrays(int size, void* (*prng)(void), const char* charSet, int minLength, int maxLength, long** offsetArray, int** keyArray, record** recordArray) {
    if (size <= 0 || prng == NULL || charSet == NULL || minLength < 1 || maxLength > 10 || minLength > maxLength) {
        return -1; // Invalid input parameters
    }

    *offsetArray = malloc(size * sizeof(long));
    *keyArray = malloc(size * sizeof(int));
    *recordArray = malloc(size * sizeof(record));

    if (*offsetArray == NULL || *keyArray == NULL || *recordArray == NULL) {
        free(*offsetArray);
        free(*keyArray);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        (*offsetArray)[i] = *(long(*)())prng(); // Cast to long pointer and dereference
        (*keyArray)[i] = *(int(*)())prng();

        int recordType = rand() % 2; // Randomly decide between int and string
        if (recordType == 0) {
            (*recordArray)[i].intValue = rand(); // Random integer value
        } else {
            int length = minLength + rand() % (maxLength - minLength + 1); // Random length between minLength and maxLength
            for (int j = 0; j < length; j++) {
                (*recordArray)[i].stringValue[j] = charSet[rand() % strlen(charSet)]; // Random character from the set
            }
            (*recordArray)[i].stringValue[length] = '\0'; // Null-terminate the string
        }
    }

    return 0; // Success
}
