#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

unsigned long linear_congruential_generator(unsigned long seed, unsigned long max_value) {
    const unsigned long a = 1664525;
    const unsigned long c = 1013904223;
    seed = (a * seed + c) % ((unsigned long)-1);
    return seed % max_value + 1;
}

void initialize_arrays(long** offsets, int** keys, record** records, unsigned long num_elements, unsigned long seed, unsigned long max_value) {
    if (num_elements <= 0 || max_value < 1) {
        fprintf(stderr, "Invalid input: num_elements must be greater than zero and max_value must be at least one.\n");
        return;
    }

    *offsets = (long*)malloc(num_elements * sizeof(long));
    *keys = (int*)malloc(num_elements * sizeof(int));
    *records = (record*)malloc(num_elements * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    srand(seed);

    for (unsigned long i = 0; i < num_elements; ++i) {
        (*offsets)[i] = i * sizeof(long);
        (*keys)[i] = rand();
        (*records)[i].value = linear_congruential_generator(seed + i, max_value);
    }
}

int main() {
    unsigned long seed = time(NULL);
    unsigned long max_value = 100;
    unsigned long num_elements = 10;

    long* offsets;
    int* keys;
    record* records;

    initialize_arrays(&offsets, &keys, &records, num_elements, seed, max_value);

    if (offsets != NULL && keys != NULL && records != NULL) {
        for (unsigned long i = 0; i < num_elements; ++i) {
            printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i].value);
        }

        free(offsets);
        free(keys);
        free(records);
    }

    return 0;
}
